const MET_PARAGRAPHS = [
 {"num":1,"section":"proleg","aa":null,"ed":null,"text":"metaphysica est scientia primorum in humana cognitione principiorum.","glosses":[],"marks":[]},
 {"num":2,"section":"proleg","aa":null,"ed":null,"text":"Ad metaphysicam referuntur ontologia, cosmologia, psychologia, et theologia naturalis.","glosses":[],"marks":[]},
 {"num":3,"section":"proleg","aa":null,"ed":2,"text":"metaphysica naturalis est cognitio rerum in metaphysica occurrentium solo usu acquisita, cui accedere artificialem §. 1 definitam utile est: 1) Ob evolutionem conceptuum. 2) Ob determinationem conceptionemque primarum propositionum. 3) Ob continuationem certitudinemque probationum, e.c.","glosses":[],"marks":[],"aaEnd":24},
 {"num":4,"section":"parsi-proleg","aa":24,"ed":null,"text":"Ontologia@@1@@ (ontosophia, metaphysica, cf. §. 1, metaphysica universalis, architectonica, philosophia prima,) est scientia praedicatorum entis generaliorum.","glosses":["Die Grund-Wissenschaft"],"marks":["*"]},
 {"num":5,"section":"parsi-proleg","aa":24,"ed":null,"text":"Entis praedicata generaliora sunt prima cognitionis humanae principia, ergo ontologia refertur, §. 2, cum ratione ad metaphysicam, §. 1, 4.","glosses":[],"marks":[]},
 {"num":6,"section":"parsi-proleg","aa":24,"ed":null,"text":"Ontologia continet praedicata entis, §. 4, I) interna 1) universalia, quae sunt in singulis, 2) disiunctiva, quorum alterutrum est in singulis; II) relativa.","glosses":[],"marks":[]},
 {"num":7,"section":"parsi-capi-seci","aa":24,"ed":null,"text":"Nihil negativum, cf. §. 54, irrepraesentabile, impossibile, repugnans, (absurdum, cf. §. 13,) contradictionem involvens, implicans, contradictorium, est A et non-A, seu, praedicatorum contradictoriorum nullum est subiectum, seu, nihil est, et non est. 0 = A + non-A. Haec propositio dicitur principium contradictionis, et absolute primum.","glosses":[],"marks":[]},
 {"num":8,"section":"parsi-capi-seci","aa":24,"ed":null,"text":"Nonnihil est aliquid@@1@@: repraesentabile, quicquid non involvit contradictionem, quicquid non est A et non-A, est possibile@@2@@, §. 7.","glosses":["Etwas","Möglich"],"marks":["*","**"]},
 {"num":9,"section":"parsi-capi-seci","aa":24,"ed":null,"text":"A et non-A non est aliquid, §. 8, hinc est nihil et contradictorium, §. 7, s. subiectum implicans nulla habet praedicata, sive, quicquid est et non est, nihil est. A + non-A = 0.","glosses":[],"marks":[]},
 {"num":10,"section":"parsi-capi-seci","aa":24,"ed":4,"text":"Omne possibile est aut A, aut non-A, aut neutrum, §. 8, iam neutrum est nihilum, quia esset utrumque, §. 9. Ergo omne possibile aut est A, aut non-A, seu, omni subiecto ex omnibus praedicatis contradictoriis alterutrum convenit. Haec praepositio dicitur principium exclusi tertii, seu medii, inter duo contradictoria.","glosses":[],"marks":[],"aaEnd":25,"flags":[{"w":"praepositio","r":"propositio","y":"The same formula reads »Haec propositio dicitur« at §. 7 and §. 11."}]},
 {"num":11,"section":"parsi-capi-seci","aa":25,"ed":null,"text":"Omne possibile A est A, seu, quicquid est, illud est, seu, omne subiectum est praedicatum sui. Si negas: quoddam possibile A est non-A, §. 10, hinc A et non-A, seu nihil, §. 7, quod impossibile, §. 9. Haec propositio dicitur principium positionis, seu, identitatis.","glosses":[],"marks":[]},
 {"num":12,"section":"parsi-capi-seci","aa":25,"ed":null,"text":"Posito impossibili oritur contradictio@@1@@. Quod non tantum videtur, sed et est, verum@@2@@, quod tantum videtur, non est, apparens@@3@@ dicitur. Hinc orta contradictio vel vera est, vel apparens.","glosses":["Entsteht ein Widerspruch","Wahr","nur scheinend"],"marks":["*","**","***"]},
 {"num":13,"section":"parsi-capi-seci","aa":25,"ed":5,"text":"Posito A et non-A oritur contradictio, §. 9, 12. Posito A et B, quo posito ponitur non-A, ponitur impossibile, §. 9, hinc oritur contradictio, §. 12, prior patens@@1@@ (directa, immediata et explicita), posterior latens@@2@@ (indirecta, cryptica, mediata et implicita) vocatur. In quo vera contradictio patet, absurdum@@3@@ est (absonum).","glosses":["Ein offenbarer","Ein versteckter Widerspruch","offenbar falsch"],"marks":["*","**","***"],"aaEnd":27},
 {"num":14,"section":"parsi-capi-seci","aa":27,"ed":null,"text":"Ratio@@1@@, cf. §. 640, (condicio, hypothesis,) est id, ex quo cognoscibile est, cur aliquid sit. Quod rationem habet, seu, cuius aliquid est ratio, rationatum@@2@@ eius dicitur, et ab eo dependens@@3@@. Praedicatum, quo aliquid vel ratio, vel rationatum est, vel utrumque, nexus@@4@@ est.","glosses":["ein Grund","seine Folge, das in ihm gegründete","das von ihm abhängende","der Zusammenhang, die Verknüpfung"],"marks":["*","**","***","****"]},
 {"num":15,"section":"parsi-capi-seci","aa":27,"ed":null,"text":"Quod spectatur, sed non in nexu cum iis, quae extra illud ponuntur, spectatur in se@@1@@. Quod nec in se quidem spectandum repraesentabile est, est impossibile in se@@2@@, (intrinsecus, simpliciter, absolute, per se). Quod in se spectatum est possibile, est possibile in se@@3@@ (intrinsecus, absolute, per se, simpliciter).","glosses":["wird an und vor sich betrachtet","an und vor sich, innerlich, schlechterdings unmöglich","an und vor sich, innerlich, unbedingt möglich"],"marks":["*","**","***"],"aaEnd":29},
 {"num":16,"section":"parsi-capi-seci","aa":29,"ed":6,"text":"Quod in nexu etiam cum aliquibus, quae extra illud ponuntur, tamen est possibile, est possibile hypothetice@@1@@ (respective, relative, extrinsecus, per aliud, et secundum quid).","glosses":["bedingt, äusserlich möglich"],"marks":["*"],"aaEnd":30},
 {"num":17,"section":"parsi-capi-seci","aa":30,"ed":null,"text":"Quod non, nisi in aliquo nexu cum iis, quae extra illud ponuntur, est impossibile, est impossibile hypothetice@@1@@ (respective, relative, extrinsecus, per aliud, et secundum quid).","glosses":["bedingt, äusserlich, in einem gewissen Zusammenhange unmöglich"],"marks":["*"]},
 {"num":18,"section":"parsi-capi-seci","aa":30,"ed":null,"text":"Nullum absolute impossibile est hypothetice possibile, §. 15, 16. Ergo nullum hypothetice possibile est absolute impossibile. Omne hypothetice impossibile et possibile est in se possibile, §. 17, 15. Ergo absolute impossibilia nec hypothetice possibilia sunt, nec impossibilia. Quoddam absolute possibile est hypothetice impossibile.","glosses":[],"marks":[]},
 {"num":19,"section":"parsi-capi-secii","aa":30,"ed":7,"text":"Possibile in nexu i.e. in quo nexus est, cui nexus convenit, connexum@@1@@ (rationale) est, in nexu impossibile est irrationale@@2@@ (inconnexum, incohaerens). Hinc irrationalia vel sunt in se, vel hypothetice impossibilia, §. 15, 17.","glosses":["zusammenhängend, verknüpft","ungereimt"],"marks":["*","**"]},
 {"num":20,"section":"parsi-capi-secii","aa":30,"ed":null,"text":"Omne possibile aut habet rationem, aut minus, §. 10, Si habet rationem, aliquid est eius ratio, §. 8. Si non habet, nihil est eius ratio, §. 7. Ergo omnis possibilis ratio aut nihil est, aut aliquid, §. 10. Si nihil foret ratio alicuius possibilis, foret ex nihilo cognoscibile, cur illud sit, §. 14, hinc ipsum nihilum repraesentabile et aliquid, §. 8, nihil aliquid, §. 14, 8. Hinc quoddam possibile impossibile, §. 7, 8, q.a., §. 9. Ergo omnis possibilis aliquid est ratio, s. omne possibile est rationatum, s. nihil est sine ratione, seu, posito aliquo, ponitur aliquid eius ratio. Haec propositio dicitur principium rationis, quam colligas etiam ex §. 265, 279, partim abstrahendo, partim vitando circulum.","glosses":[],"marks":[],"aaEnd":31},
 {"num":21,"section":"parsi-capi-secii","aa":31,"ed":null,"text":"Ratio singulorum in aliquo est ratio eius sufficiens@@1@@ (completa, totalis), aliquorum tantum in eodem ratio est ratio eius insufficiens@@2@@ (incompleta, partialis).","glosses":["der zureichende Grund","der unzulängliche"],"marks":["*","**"]},
 {"num":22,"section":"parsi-capi-secii","aa":31,"ed":8,"text":"Nihil est sine ratione sufficiente, seu, posito aliquo, ponitur aliquid eius ratio sufficiens. Singula in omni possibili habent rationem, §. 20, hinc omne possibile rationem sufficientem, §. 21. Haec propositio dicitur principium rationis sufficientis (convenientiae).","glosses":[],"marks":[]},
 {"num":23,"section":"parsi-capi-secii","aa":31,"ed":null,"text":"Omne possibile est ratio, seu nihil est sine rationato, nihil sine corollario et auctoramento, nihil omnino sterile, otiosum et infecundum, seu posito aliquo ponitur aliquid rationatum eius. Nam omne possibile aut habet rationatum, aut minus, §. 10. Si habet, est aliquid rationatum eius, §. 8, si non habet, nihil est eius rationatum, §. 7. Ergo omnis possibilis rationatum aut nihil est, aut aliquid, §. 10. Si nihil esset rationatum possibilis alicuius, posset ex hoc cognosci, §. 14, hinc esset aliquid, §. 8, adeoque quoddam possibile impossibile, §. 7, 8, q.a., §. 9. Haec propositio dicatur principium rationati.","glosses":[],"marks":[]},
 {"num":24,"section":"parsi-capi-secii","aa":31,"ed":9,"text":"Omne possibile est ratio et rationatum, §. 20, 23, hinc nexu duplici, §. 14, connexum et rationale, §. 19, tam a priori quam a posteriori cognoscibile. Haec propositio dicatur principium utrimque connexorum (a parte ante, et a parte post).","glosses":[],"marks":[]},
 {"num":25,"section":"parsi-capi-secii","aa":31,"ed":null,"text":"Ratio A rationis B, est ratio rationati C. Ex ratione του B cognosci potest, cur C sit, §. 23, hinc A est ratio του C, §. 14.","glosses":[],"marks":[],"aaEnd":32},
 {"num":26,"section":"parsi-capi-secii","aa":32,"ed":null,"text":"Rationatum C rationati B, est rationatum rationis A, §. 25, 14.","glosses":[],"marks":[]},
 {"num":27,"section":"parsi-capi-secii","aa":32,"ed":null,"text":"Ratio A alicuius B, a quo dependet C, est huius C ratio mediata@@1@@ (ulterior, remota), ratio non mediata est immediata@@2@@ (proxima).","glosses":["mittelbarer und entfernter","unmittelbarer und nächster Grund"],"marks":["*","**"]},
 {"num":28,"section":"parsi-capi-secii","aa":32,"ed":null,"text":"Ratio secundum quid@@1@@ (intermedia,) dicitur, quae habet adhuc ulteriorem, quae non habet, simpliciter talis@@2@@ (ultima). Rationes et rationata alicuius vel spectantur, etiam ut rationes et rationata inter se, subordinata@@3@@, vel minus, coordinata@@4@@.","glosses":["der Zwischen-Grund","der letzte Grund","untereinander","neben einander stehende Gründe und Folgen"],"marks":["*","**","***","****"]},
 {"num":29,"section":"parsi-capi-secii","aa":32,"ed":10,"text":"Posito rationato, ponitur eius ratio aliqua, § 20, 14, et sufficiens, §. 22, seu a rationato ad rationem, et sufficientem, V. C.","glosses":[],"marks":[],"aaEnd":33},
 {"num":30,"section":"parsi-capi-secii","aa":33,"ed":null,"text":"Posita ratione, hinc et sufficiente, §. 21, ponitur rationatum, §. 23, seu a ratione, et sufficiente, ad rationatum V. C.","glosses":[],"marks":[]},
 {"num":31,"section":"parsi-capi-secii","aa":33,"ed":null,"text":"Sublata ratione, et sufficiente, tollitur aliquid rationatum, quia posito hoc, poneretur et illa, §. 29.","glosses":[],"marks":[]},
 {"num":32,"section":"parsi-capi-secii","aa":33,"ed":null,"text":"Sublato rationato tollitur ratio eius, et sufficiens, quia hac posita, poneretur et illud, §. 30.","glosses":[],"marks":[]},
 {"num":33,"section":"parsi-capi-secii","aa":33,"ed":null,"text":"A et B connexa tertio C sunt connexa inter se, A est connexum cum C connexo cum B, est ergo in A, de quo cognosci potest ex B, cur sit, hinc A et B sunt connexa, §. 19.","glosses":[],"marks":[],"aaEnd":34},
 {"num":34,"section":"parsi-capi-seciii","aa":34,"ed":11,"text":"Quod aut ponitur esse A, aut ponitur non esse A, determinatur@@1@@. Quod vero tantum ponitur esse aut A, aut non A, est indeterminatum@@2@@. Seu, si de subiecto respectu praedicatorum contradictoriorum nil ponitur, nisi alterutrum ex illis ipsi convenire, subiectum illud respectu horum praedicatorum est indeterminatum; determinatur autem, si alterutrum in subiecto ponitur. Quod determinari potest, est determinabile@@3@@. De quo ergo aut poni potest, illud esse A, aut, illud esse non A, illud est determinabile.","glosses":["bestimmt","unbestimmt","bestimmlich"],"marks":["*","*","***"]},
 {"num":35,"section":"parsi-capi-seciii","aa":34,"ed":null,"text":"Ratio determinandi est determinans@@1@@. Omnis ergo ratio, sufficiens sufficienter, insufficiens insufficienter, determinat, §. 34, 21. Hinc posito determinante, ponitur determinatum, §. 30, et v.v., §. 29. Sublato determinato, tollitur determinans, §. 32, et v.v., §. 31.","glosses":["das bestimmende"],"marks":["*"]},
 {"num":36,"section":"parsi-capi-seciii","aa":34,"ed":12,"text":"Quae determinando ponuntur in aliquo (notae et praedicata), sunt determinationes@@1@@, altera positiva, et affirmativa, §. 34, 10, quae si vere sit, est realitas, altera negativa, §. 34, 10, quae si vere sit, est negatio@@2@@. Negatio apparens est realitas cryptica, realitas apparens est vanitas@@3@@.","glosses":["Bestimmungen","Verneinungen","Eitelkeit"],"marks":["*","**","***"]},
 {"num":37,"section":"parsi-capi-seciii","aa":34,"ed":null,"text":"Determinationes possibilis aut sunt in eo repraesentabiles, etiamsi nondum spectetur in nexu, absolutae@@1@@, aut tunc demum, quando spectatur in nexu, §. 10, respectivae@@2@@ (assumptivae). Determinationes possibilium respectivae sunt respectus@@3@@ (habitudines, τα προσ τι, relationes latius dictae, vel ad extra, vel ad intra). Respectus possibilium in iisdem in se spectatis non repraesentabiles sunt relationes@@4@@ (strictius dictae, ad extra). Relationes possibilium sunt eorundem determinationes externae@@5@@ (relativae, ad extra, extrinsecae), reliquae omnes, internae@@6@@.","glosses":["dem möglichen an und vor sich betrachtet schon","beziehungs-weise zukommende Bestimmungen","Beziehungen","Verhältnisse","äussre","innre Bestimmungen"],"marks":["*","**","***","****","*****","******"],"aaEnd":35},
 {"num":38,"section":"parsi-capi-seciii","aa":35,"ed":null,"text":"Si in A sunt, quae in B, A et B sunt eadem@@1@@. Non eadem sunt diversa@@2@@ (alia).","glosses":["einerlei","verschieden"],"marks":["*","**"],"aaEnd":36},
 {"num":39,"section":"parsi-capi-seciii","aa":36,"ed":13,"text":"Determinationes possibilis internae, aut sunt internarum reliquarum rationes in internis simpliciter tales, aut minus, §. 10. Illae sunt primae (principes), sive essentialia@@1@@.","glosses":["die ersten oder wesentlichen Bestimmungen"],"marks":["*"]},
 {"num":40,"section":"parsi-capi-seciii","aa":36,"ed":null,"text":"Complexus essentialium in possibili, seu possibilitas eius interna est essentia@@1@@ (esse rei, ratio formalis, natura, cf. §. 430, quidditas, forma, formale totius, ουσια τινοτισ, substantia, cf. §. 191, conceptus entis primus).","glosses":["das Wesen"],"marks":["*"]},
 {"num":41,"section":"parsi-capi-seciii","aa":36,"ed":null,"text":"Determinationes possibilis internae, rationata essentiae, sunt affectiones@@1@@.","glosses":["innere folgende Bestimmungen"],"marks":["*"]},
 {"num":42,"section":"parsi-capi-seciii","aa":36,"ed":null,"text":"Determinatio interna, quae non est essentiale, est rationatum essentiae, §. 39, 40, hinc affectio, §. 41.","glosses":[],"marks":[]},
 {"num":43,"section":"parsi-capi-seciii","aa":36,"ed":null,"text":"Posita in possibili essentia ponuntur affectiones, §. 41, 30.","glosses":[],"marks":[],"aaEnd":37},
 {"num":44,"section":"parsi-capi-seciii","aa":37,"ed":null,"text":"Positis in possibili affectionibus ponitur essentia aliqua, §. 41, 29.","glosses":[],"marks":[]},
 {"num":45,"section":"parsi-capi-seciii","aa":37,"ed":14,"text":"Sublata essentia tolluntur aliquae affectiones, §. 41, 31.","glosses":[],"marks":[]},
 {"num":46,"section":"parsi-capi-seciii","aa":37,"ed":null,"text":"Sublatis affectionibus tollitur essentia, §. 41, 32.","glosses":[],"marks":[]},
 {"num":47,"section":"parsi-capi-seciii","aa":37,"ed":null,"text":"Omnes determinationes internae possibilis sunt inter se connexae, singulae cum singulis. Affectiones enim connectuntur singulae cum essentialibus, §. 39, haec cum essentia, §. 40, 14. Hinc singulae determinationes cum singulis, §. 33.","glosses":[],"marks":[]},
 {"num":48,"section":"parsi-capi-seciii","aa":37,"ed":null,"text":"Nexus (harmonia) universalis@@1@@ est, qui est in singulis.","glosses":["ein allgemeiner Zusammenhang"],"marks":["*"]},
 {"num":49,"section":"parsi-capi-seciii","aa":37,"ed":null,"text":"In determinationibus possibilis internis est nexus universalis §. 47, 48.","glosses":[],"marks":[]},
 {"num":50,"section":"parsi-capi-seciii","aa":37,"ed":null,"text":"Affectiones habent rationem in essentia, §. 41, hinc aut sufficientem, aut minus, §. 21, 10. Illae sunt attributa@@1@@, hae modi@@2@@ (accidentia praedicabilia, s. logica, cf. §. 191, adiuncta, praedicata secundaria).","glosses":["Eigenschaften","Zufälligkeiten"],"marks":["*","*"]},
 {"num":51,"section":"parsi-capi-seciii","aa":37,"ed":15,"text":"Attributa rationem sufficientem habent aut in omnibus essentialibus, aut in aliquibus tantum, §. 50, 10. Illa propria@@1@@ sunt, haec communia@@2@@.","glosses":["besondre","gemeine"],"marks":["*","**"]},
 {"num":52,"section":"parsi-capi-seciii","aa":37,"ed":null,"text":"Omnis possibilium determinatio aut est essentiale, §. 39, aut attributum, aut modus, §. 42, aut relatio, §. 37.","glosses":[],"marks":[],"aaEnd":38},
 {"num":53,"section":"parsi-capi-seciii","aa":38,"ed":null,"text":"Omne possibile determinatum est, qua possibilitatem, §. 34, 8, hinc in se possibile, qua possibilitatem internam, §. 15, quae cum sit essentia, §. 40, omne possibile habet essentiam, determinatum, qua essentiam. Ergo omnimode indeterminatum nihil est, §. 7.","glosses":[],"marks":[]},
 {"num":54,"section":"parsi-capi-seciii","aa":38,"ed":null,"text":"Possibile praeter essentiam, §. 53, aut est determinatum, qua omnes affectiones etiam in ipso compossibiles, aut minus, §. 34, 10. Illud est actuale@@1@@, hoc non ens (nihil, cf. §. 7) privativum (mere possibile)@@2@@ vocatur.","glosses":["wirklich","das bloss mögliche, ein mögliches Nichts"],"marks":["*","**"]},
 {"num":55,"section":"parsi-capi-seciii","aa":38,"ed":16,"text":"Exsistentia@@1@@ (actus, cf. §. 210, actualitas) est complexus affectionum in aliquo compossibilium, i.e. complementum essentiae sive possibilitatis internae, quatenus haec tantum, ut complexus determinationum spectatur, §. 40.","glosses":["Wirklichkeit"],"marks":["*"]},
 {"num":56,"section":"parsi-capi-seciii","aa":38,"ed":null,"text":"Omnis determinatio possibilis interna aut pertinet ad essentiam eius, aut ad exsistentiam, §. 55, 42.","glosses":[],"marks":[]},
 {"num":57,"section":"parsi-capi-seciii","aa":38,"ed":null,"text":"Omne actuale est interne possibile, §. 54, seu posita exsistentia ponitur interna possibilitas, §. 55, 40, ab esse ad posse V. C.","glosses":[],"marks":[]},
 {"num":58,"section":"parsi-capi-seciii","aa":38,"ed":null,"text":"Nullum interne impossibile est actuale, §. 57, sublata possibilitate interna, tollitur actualitas, §. 55, 40, seu a non posse ad non esse V. C.","glosses":[],"marks":[]},
 {"num":59,"section":"parsi-capi-seciii","aa":38,"ed":null,"text":"Quoddam possibile non est actuale, §. 54, seu posita possibilitate quadam tamen tolli potest actualitas, seu a quodam posse ad esse N. V. C.","glosses":[],"marks":[],"aaEnd":39},
 {"num":60,"section":"parsi-capi-seciii","aa":39,"ed":17,"text":"Quoddam non actuale est possibile, §. 59, sublata actualitate non omnis tollitur possibilitas, seu a non esse ad omnino non posse N. V. C.","glosses":[],"marks":[]},
 {"num":61,"section":"parsi-capi-seciii","aa":39,"ed":null,"text":"Possibile, qua exsistentiam, determinabile est ens@@1@@.","glosses":["ein Ding"],"marks":["*"],"aaEnd":40},
 {"num":62,"section":"parsi-capi-seciii","aa":40,"ed":null,"text":"Non ens@@1@@ (negativum, cf. §. 54) esset possibile, qua exsistentiam, non determinabile. §. 61. At hoc impossibile, §. 10, et, si videtur esse ens, est ens fictum@@2@@ (rationis ratiocinantis, cf. §. 647).","glosses":["ein Unding","ein erdichtetes Ding"],"marks":["*","**"]},
 {"num":63,"section":"parsi-capi-seciii","aa":40,"ed":null,"text":"Omne ens est possibile, §. 61, rationem, §. 20, sufficientem habet, §. 22, et rationatum, §. 23, hinc dupliciter connexum est, §. 24, habet essentiam, §. 53, et essentialia, §. 40, hinc affectiones, §. 43, in universali nexu, §. 49. Omnes entis determinationes aut sunt essentialia, aut attributa, aut modi, aut relationes, §. 52. Posito ente, ponitur essentia eius, hinc essentialia omnia. Sublata essentia, tollitur ens. Sublato essentiali, tollitur essentia, hinc ens ipsum, §. 53, 40. Omnis denique determinatio entis interna aut pertinet ad essentiam eius, aut ad exsistentiam, §. 56.","glosses":[],"marks":[]},
 {"num":64,"section":"parsi-capi-seciii","aa":40,"ed":18,"text":"Per essentiam attributa entis sufficienter determinantur, §. 35, 50, hinc posita essentia ponuntur attributa, §. 35. Ergo posito ente ponuntur attributa eius, §. 63, sublato attributo tollitur essentia et ens, §. 35, 63.","glosses":[],"marks":[],"aaEnd":41},
 {"num":65,"section":"parsi-capi-seciii","aa":41,"ed":null,"text":"Modi entis per essentiam non sufficienter determinantur, §. 50, 35, hinc non determinantur, qua exsistentiam, § 55. Ens ergo, qua modos actuales, per essentiam est indeterminatum, §. 34, 54, i.e. modi possunt abesse et adesse salva rei essentia.","glosses":[],"marks":[]},
 {"num":66,"section":"parsi-capi-seciii","aa":41,"ed":null,"text":"Exsistentia non repugnat essentiae, sed est realitas, §. 36, cum ea compossibilis, §. 50, 55.","glosses":[],"marks":[]},
 {"num":67,"section":"parsi-capi-seciii","aa":41,"ed":19,"text":"Cognitio diversitatis est distinctio@@1@@, et ratio distinctionis in distinguendo discrimen (differentia, character, character distinctivus latius dictus, cf. §. 350, nota, nota characteristica)@@2@@. Iam omnis determinatio entis est id, ex quo cognosci potest, ens illud nec indeterminatum, nec alio modo determinatum esse, §. 36, 34. Ergo omnis determinatio est discrimen entis, §. 38, 14.","glosses":["Unterscheidung","Unterscheid, Merkmal, Kennezeichen, Unterscheidungs-Zeichen"],"marks":["*","**"]},
 {"num":68,"section":"parsi-capi-seciii","aa":41,"ed":null,"text":"Discrimina entis sunt vel externa seu relativa, vel interna, §. 67, 37, et haec vel essentialia, quae pertinent ad essentiam, vel accidentalia, quae ad exsistentiam, §. 56, vel absoluta, vel respectiva, §. 37.","glosses":[],"marks":[]},
 {"num":69,"section":"parsi-capi-seciii","aa":41,"ed":null,"text":"Discrimina interna possunt repraesentari in ente in se spectato, §. 68, 37, hinc quomodocumque cognosci, seu dari@@1@@. Data vel possumus etiam (sine compraesentia) sine assumpto alio, sine relatione ad aliud, concipere@@2@@ et intelligere, i.e. distincte cognoscere, vel non possumus. Illa sunt qualitates@@3@@, haec quantitates@@4@@.","glosses":["angegeben werden","begreifen und verstehn","Beschaffenheiten","Grössen"],"marks":["*","**","***","****"]},
 {"num":70,"section":"parsi-capi-seciii","aa":41,"ed":20,"text":"Qua qualitatem eadem sunt similia @@1@@, qua quantitatem, aequalia = @@2@@, qua utramque, congruentia _ @@3@@.Qua qualitatem diversa, dissimilia @@4@@, qua quantitatem, inaequalia @@5@@, qua utramque diversa, discongruentia @@6@@.","glosses":["ähnlich","gleich","gleichartig","unähnlich","ungleich","ungleichartig"],"marks":["*","**","***","****","*****","******"],"aaEnd":42},
 {"num":71,"section":"parsi-capi-seciii","aa":42,"ed":null,"text":"Mere similia non sunt congruentia, hinc quantitate differunt, §. 70, hinc quantitas est discrimen internum mere similium.","glosses":[],"marks":[],"aaEnd":43},
 {"num":72,"section":"parsi-capi-seciiii","aa":43,"ed":null,"text":"Determinationes entis separantur@@1@@, si ex simul positis quaedam tolluntur. Hinc inseparabiles@@2@@ sunt, quarum simul positarum nulla potest tolli.","glosses":["werden getrennt","unzertrennlich"],"marks":["*","**"]},
 {"num":73,"section":"parsi-capi-seciiii","aa":43,"ed":21,"text":"Posito ente ponitur essentia, §. 63, ergo complexus essentialium, §. 40, hinc posito ente simul ponuntur essentialia omnia, et ita quidem, ut nullum possit tolli, §. 63, 40. Ergo essentialia entis sunt per se inseparabilia, §. 72, 15. Unum@@1@@ est, cuius determinationes sunt inseparabiles, et transcendentaliter@@2@@ quidem, cuius determinationes sunt per se inseparabiles. Ergo omne ens est unum transcendentale.","glosses":["Eins","wesentlich eins"],"marks":["*","**"]},
 {"num":74,"section":"parsi-capi-seciiii","aa":43,"ed":null,"text":"A unum et B unum e.c. partim eadem, partim diversa sunt multa@@1@@. Quicquid cogitemus, aut sunt multa, aut non multa, §. 10. Prior determinatio est multitudo (pluralitas)@@2@@, posterior unitas categorica@@3@@.","glosses":["Viele","die Vielheit, Mehrheit","die Einheit"],"marks":["*","**","***"]},
 {"num":75,"section":"parsi-capi-seciiii","aa":43,"ed":null,"text":"Determinationes entis singulae sunt una, §. 73, partim eadem, dum sunt determinationes eiusdem entis, partim diversa, §. 38, hinc multa, §. 74. Potest ergo multitudo dari in ente in se spectato, §. 69, et est eius discrimen internum, §. 37, quod tamen intelligere non possumus, nisi uno alio assumpto, §. 74, 38, hinc multitudo est quantitas, §. 69.","glosses":[],"marks":[],"aaEnd":44},
 {"num":76,"section":"parsi-capi-seciiii","aa":44,"ed":null,"text":"Inseparabilitas determinationum cum sit impossibilitas separationis, §. 72, est vel absoluta, vel hypothetica, §. 15, 16. Hinc unitas est vel absoluta, vel hypothetica, §. 73.","glosses":[],"marks":[]},
 {"num":77,"section":"parsi-capi-seciiii","aa":44,"ed":22,"text":"Quicquid est, quod multa non sunt, est unicum (unum exclusive tale)@@1@@.","glosses":["Einzig"],"marks":["*"]},
 {"num":78,"section":"parsi-capi-secv","aa":44,"ed":null,"text":"Si multa iuxta vel post se invicem ponuntur, coniunguntur@@1@@. Coniunctio plurium vel est eadem, vel diversa, §. 10, 38. Si prior, est coordinatio@@2@@, et eius identitas ordo@@3@@. Ordinis scientia olim erat musica latius dicta.","glosses":["verbunden werden","zusammenordnen","Ordnung"],"marks":["*","**","***"]},
 {"num":79,"section":"parsi-capi-secv","aa":44,"ed":null,"text":"Diversitas in coniunctione plurium est confusio (inordinatio)@@1@@. Coniunctio inseparabilium est unitio@@2@@.","glosses":["Unordnung und Verwirrung","Vereinigung"],"marks":["*","**"]},
 {"num":80,"section":"parsi-capi-secv","aa":44,"ed":23,"text":"Omnis determinatio habet rationem, §. 20, 36, quaeque ex aliqua determinata ratione cognosci potest, rationi dicitur conformis (conveniens, consentiens)@@1@@.","glosses":["dem Grunde gemäss, übereinstimmig und zukommend"],"marks":["*"]},
 {"num":81,"section":"parsi-capi-secv","aa":44,"ed":null,"text":"Si posito A tollitur B, A et B opposita sunt@@1@@.","glosses":["entgegen gesetzt, mit einander streitend"],"marks":["*"],"aaEnd":45},
 {"num":82,"section":"parsi-capi-secv","aa":45,"ed":null,"text":"Determinatio opposita illi, quae rationi conformis est, est rationi contraria (difformis, disconveniens) seu defectus@@1@@.","glosses":["Mangel"],"marks":["*"]},
 {"num":83,"section":"parsi-capi-secv","aa":45,"ed":null,"text":"Propositis enuntians determinationem rationi conformem est norma (regula@@1@@, lex), immo latius, repraesentatio determinationis rationi conformis.","glosses":["Richtschnur, Gesetz"],"marks":["*"]},
 {"num":84,"section":"parsi-capi-secv","aa":45,"ed":null,"text":"Ubicumque determinationes, ibi leges, §. 83, 80.","glosses":[],"marks":[]},
 {"num":85,"section":"parsi-capi-secv","aa":45,"ed":null,"text":"Respectus entis ex coniunctione eius cum aliis determinatus est positus@@1@@. Ubi ergo positus, ibi leges, §. 84, 37.","glosses":["Stelle"],"marks":["*"]},
 {"num":86,"section":"parsi-capi-secv","aa":45,"ed":24,"text":"Coniunctione determinatur positus, hinc sunt in coniunctione leges, §. 85, in eadem eaedem, §. 38. Ergo in ordine coniunguntur plura eidem rationi conformiter, §. 83, 78. Quod est in A et B, ipsis commune@@1@@ est. Quod est in A, non in B, est, respectu B, τῳ A proprium@@2@@, ergo in ordine sunt regulae communes.","glosses":["Gemein","Eigen"],"marks":["*","**"]},
 {"num":87,"section":"parsi-capi-secv","aa":45,"ed":null,"text":"In coniunctione diversa diversae sunt leges, §. 86, 38. Ergo in confusione non sunt leges communes, §. 79, 86.","glosses":[],"marks":[]},
 {"num":88,"section":"parsi-capi-secv","aa":45,"ed":null,"text":"Ordinis si regula fuerit unica, simplex@@1@@, si plures, ordo compositus@@2@@ vocatur.","glosses":["Eine einfache","zusammengesetzte Ordnung"],"marks":["*","**"]},
 {"num":89,"section":"parsi-capi-secvi","aa":45,"ed":25,"text":"Veritas metaphysica@@1@@ (realis, obiectiva, materialis) est ordo plurium in uno, veritas in essentialibus et attributis entis, transcendentalis@@2@@.","glosses":["die metaphysische Wahrheit","die nothwendige metaphysische Wahrheit"],"marks":["*","**"]},
 {"num":90,"section":"parsi-capi-secvi","aa":45,"ed":null,"text":"Cum omnis entis determinationes coniungantur, essentiales secundum principium contradictionis, §. 40, 7, et accidentales, attributa secundum principium contradictionis, §. 64, 7, et rationis, §. 20, et sufficientis, §. 22, 50, modi secundum principium contradictionis, §. 65, 7, et rationis, §. 42, 20, essentialia et affectiones secundum principium rationati, §. 23, 41, hinc regulas communes, §. 83, 86, omne ens est verum transcendentaliter, § 89.","glosses":[],"marks":[],"aaEnd":46},
 {"num":91,"section":"parsi-capi-secvi","aa":46,"ed":null,"text":"Confusio veritati transcendentali opposita esset somnium obiective sumptum@@1@@ (cf. §. 593). Somniorum aggregatum esset mundus fabulosus@@2@@ (cf. §. 354).","glosses":["ein Traum, das geträumte","das Land der Wünsche"],"marks":["*","**"]},
 {"num":92,"section":"parsi-capi-secvi","aa":46,"ed":26,"text":"Principia (cf. §. 307, 311) catholica@@1@@ (universalia) sunt singulis entibus communia. Metaphysice vera determinantur principiis catholicis, §. 7, 20, 22, 23, convenienter, §. 90, 80, et, quae determinantur his principiis conformiter, sunt methaphysice vera, §. 89. Hinc veritas methaphysica potest definiri per convenientiam entis cum principiis catholicis.","glosses":["allgemeine Grund-Sätze"],"marks":["*"],"flags":[{"w":"methaphysice","r":"metaphysice","y":"Spelt »metaphysic-« everywhere else in the volume."},{"w":"methaphysica","r":"metaphysica","y":"Spelt »metaphysic-« everywhere else in the volume."}]},
 {"num":93,"section":"parsi-capi-secvi","aa":46,"ed":null,"text":"Certitudo obiectiva@@1@@ (cf. §. 531) est apperceptibilitas veritatis in ente. Iam omnis entis veritas est clare cognoscibilis, §. 90, 8. Ergo omne ens est obiective certum.","glosses":["Gewissheit der Dinge"],"marks":["*"]},
 {"num":94,"section":"parsi-capi-secvii","aa":46,"ed":null,"text":"Si plura simul sumpta unius rationem sufficientem constituunt, consentiunt@@1@@. Consensus ipse est perfectio@@2@@, et unum, in quod consentitur, ratio perfectionis determinans (focus perfectionis)@@3@@.","glosses":["übereinstimmen","Vollkommenheit","Grund oder Brennpunkt der Vollkommenheit"],"marks":["*","**","***"]},
 {"num":95,"section":"parsi-capi-secvii","aa":46,"ed":27,"text":"In perfectione plura eidem rationi conformiter determinantur, §. 94, 80, ergo est in perfectione ordo, §. 78, et communes perfectionis regulae, §. 86.","glosses":[],"marks":[],"aaEnd":47},
 {"num":96,"section":"parsi-capi-secvii","aa":47,"ed":null,"text":"Ratio perfectionis determinans si fuerit unica, simplex@@1@@, si plures, composita tunc est perfectio@@2@@, §. 88, 95.","glosses":["eine einfache","eine zusammengesetzte"],"marks":["*","**"]},
 {"num":97,"section":"parsi-capi-secvii","aa":47,"ed":null,"text":"Regulae oppositae collidi@@1@@ dicuntur, et defectus ex regulis perfectionis collidentibus exceptio@@2@@, prout normae vel vera vel apparente tantum oppositione colliduntur, §. 81, vel vera, vel apparens, §. 12.","glosses":["mit einander streitende Richtschnuren","Ausnahme"],"marks":["*","**"]},
 {"num":98,"section":"parsi-capi-secvii","aa":47,"ed":null,"text":"Consensus essentialium est perfectio (essentialis) transcendentalis@@1@@, affectionum accidentalis@@2@@, utraque interna@@3@@. Consensus relationum est perfectio externa@@4@@.","glosses":["wesentliche","innre ausserwesentliche","innre","äussre"],"marks":["*","**","***","****"]},
 {"num":99,"section":"parsi-capi-secvii","aa":47,"ed":28,"text":"Essentialia omnis entis consentiunt ad essentiam eius, §. 63, 40, et attributa, §. 50, 94. Ergo omne ens est perfectum transcendentaliter.","glosses":[],"marks":[]},
 {"num":100,"section":"parsi-capi-secvii","aa":47,"ed":null,"text":"Bonum@@1@@ est, quo posito ponitur perfectio. Ergo omne ens est bonum transcendentaliter, §. 99.","glosses":["gut"],"marks":["*"],"aaEnd":48},
 {"num":101,"section":"parsi-capii-seci","aa":48,"ed":null,"text":"Necessarium@@1@@ est, cuius oppositum est impossibile, non necessarium est contingens@@2@@.","glosses":["nothwendig","zufällig"],"marks":["*","**"]},
 {"num":102,"section":"parsi-capii-seci","aa":48,"ed":29,"text":"Cuius oppositum in se impossibile est, est illud necessarium in se@@1@@ (metaphysice, intrinsecus, absolute, geometrice, logice). Cuius oppositum est extrinsecus tantum impossibile, est necessarium hypothetice@@2@@ (secundum quid). Entis determinatio, qua necessarium est, est eius necessitas@@3@@. Ergo necessitas est vel absoluta@@4@@ (consequentis), vel hypothetica@@5@@ (consequentiae), illa, qua aliquid est in et per se, haec, qua aliquid est hypothetice tantum necessarium.","glosses":["an sich, schlechterdings, unbedingt, nothwendig","bedingt nothwendig","Nothwendigkeit","die schlechterdings so genannte (unbedingte)","die bedingte"],"marks":["*","**","***","****","*****"]},
 {"num":103,"section":"parsi-capii-seci","aa":48,"ed":null,"text":"Possibilitas oppositum involvit, §. 81, 7, hinc possibilitas entis est determinatio eius necessaria, §. 101, intrinseca intrinsecus, extrinseca extrinsecus, §. 102.","glosses":[],"marks":[]},
 {"num":104,"section":"parsi-capii-seci","aa":48,"ed":30,"text":"Cuius oppositum absolute possibile est, est contingens in se@@1@@ (per se, intrinsecus), cuius oppositum est etiam hypothetice possibile, est et extrinsecus contingens@@2@@ (hypothetice). Entis determinatio, qua contingens est, est eius contingentia@@3@@. Ergo contingentia est vel absoluta@@4@@, qua aliquid est saltim in et per se, vel hypothetica@@5@@, qua aliquid est hypothetice contingens.","glosses":["an sich, schlechterdings (unbedingt)","auch bedingt und äusserlich zufällig","Zufälligkeit","die unbedingte, schlechterdings so genannte","die bedingte"],"marks":["*","**","***","****","*****"],"aaEnd":49},
 {"num":105,"section":"parsi-capii-seci","aa":49,"ed":null,"text":"Nullum absolute necessarium est ullo modo contingens, §. 102, 104. Ergo quicquid ullo modo contingens est, non est absolute necessarium. Omne hypothetice necessarium est in et per se contingens, §. 18. Ergo quoddam in et per se contingens est hypothetice necessarium. Omne hypothetice contingens est et in se, §. 104.","glosses":[],"marks":[]},
 {"num":106,"section":"parsi-capii-seci","aa":49,"ed":null,"text":"Essentiae rerum sunt in iis absolute necessariae, §. 40, 103.","glosses":[],"marks":[]},
 {"num":107,"section":"parsi-capii-seci","aa":49,"ed":null,"text":"Sublatis essentialibus et attributis tollitur essentia, §. 63, 64, hinc ponitur impossibilitas entis interna, §. 81, 40. Sunt ergo tam essentialia, quam attributa absolute necessariae entis determinationes, §. 103.","glosses":[],"marks":[]},
 {"num":108,"section":"parsi-capii-seci","aa":49,"ed":31,"text":"Modorum oppositum est in ente absolute possibile, §. 65, 81, hinc modi sunt determinationes entis in se contingentes, §. 104. Ergo non absolute necessariae, §. 105. Absolute necessariarum in ente determinationum oppositum est in eodem absolute impossibile, §. 102. Ergo ipsae sunt in ente absolute possibiles, §. 81, hinc in eodem in se spectato repraesentabiles, §. 15. Relationes autem non sunt in ente in se spectato repraesentabiles, §. 37. Ergo nullae relationes entis sunt absolute necessariae, omnes contingentes, §. 101.","glosses":[],"marks":[]},
 {"num":109,"section":"parsi-capii-seci","aa":49,"ed":null,"text":"Cum exsistentiae oppositum in aliquo sit possibile, §. 54, 55, exsistentia aut erit absolute necessaria, aut in se contingens, §. 102, 10. Ens, cuius exsistentia est absolute necessaria, est ens necessarium@@1@@, cuius exsistentia est intrinsecus contingens, est ens contingens@@2@@.","glosses":["das nothwendige Ding","ein zufälliges Ding"],"marks":["*","**"],"aaEnd":50},
 {"num":110,"section":"parsi-capii-seci","aa":50,"ed":null,"text":"Omnes entis necessarii determinationes internae sunt absolute necessariae. Pertinent enim aut ad essentiam, aut ad exsistentiam, §. 56. Tam haec, quam illa est in ente necessario absolute necessaria, §. 109, 106.","glosses":[],"marks":[]},
 {"num":111,"section":"parsi-capii-seci","aa":50,"ed":32,"text":"In ente necessario non sunt modi, §. 110, 108. Ergo cui modi insunt, est ens contingens, §. 109.","glosses":[],"marks":[]},
 {"num":112,"section":"parsi-capii-seci","aa":50,"ed":null,"text":"Omne ens contingens habet modos. Pone enim alicui enti contingenti nullos modos inesse, omnes affectiones eius sunt absolute necessariae, §. 52, 107, hinc et exsistentia eius absolute necessaria est, §. 55, q.a., §. 109.","glosses":[],"marks":[]},
 {"num":113,"section":"parsi-capii-seci","aa":50,"ed":null,"text":"Determinationes unius sunt inseparabiles, §. 73, hinc cuiuslibet oppositum impossibile, §. 72, 81, sunt ergo determinationes unius necessariae, §. 101, et absolute quidem absolute unius, hypothetice hypothetice unius, §. 102, 76. Unita sunt necessario coniuncta, §. 79, vel in se, vel hypothetice, §. 102.","glosses":[],"marks":[]},
 {"num":114,"section":"parsi-capii-seci","aa":50,"ed":33,"text":"Necessaria sunt unico tantum modo ac ratione determinabilia. Nam sunt aut A, aut non-A. Tertius modus, tertia ratio determinabilitatis impossibilis est, §. 10. Iam pone necessarium esse determinabile per A; non-A est huius determinationis oppositum, §. 81, hinc impossibile, §. 101. Non sunt ergo plures determinabilitatis modi ac rationes, praeter A unicum, §. 77. Unico tantum modo ac ratione determinabilia sint A, oppositum eorum esset non-A, §. 81, sed hoc impossibile est, §. 77. Sint non-A, oppositum eorum esset A, §. 81, sed hoc impossibile est, §. 77. Tertium non datur, §. 10. Ergo unico tantum modo ac ratione determinabilium oppositum est impossibile, adeoque ipsa necessaria sunt, §. 102. Contingentia non sunt necessaria, hinc nec sunt unico tantum modo ac ratione determinabilia, nec pluribus ac duobus, §. 10. Sunt ergo duplici modo determinabilia. Duplici modo ac ratione determinabilia non sunt necessaria, hinc contingentia, §. 102. Possunt itaque definiri 1) necessarium, per unico tantum, 2) contingens, per duplici modo determinabile, 3) necessitas per unicitatem, 4) contingentia per duplicitatem determinabilitatis.","glosses":[],"marks":[],"aaEnd":51},
 {"num":115,"section":"parsi-capii-seci","aa":51,"ed":null,"text":"Unum hypothetice tale habet determinationes in se separabiles, §. 76, 18, hinc unitas eius est intrinsecus contingens, §. 104.","glosses":[],"marks":[]},
 {"num":116,"section":"parsi-capii-seci","aa":51,"ed":null,"text":"Unitas transcendentalis est absolute necessaria, §. 73, 102, hinc nullum eius est oppositum, §. 102, 15.","glosses":[],"marks":[]},
 {"num":117,"section":"parsi-capii-seci","aa":51,"ed":34,"text":"Ordinis opposita cum sint confusio, §. 79, 78, et non facta coniunctio, §. 78, 81, ordo absolute necessarius est in per se necessario coniunctis et quidem eodem modo, §. 102. Ubicumque ergo non est absolute necessaria tam coniunctio, quam coniunctionis identitas, ibi est ordo in se contingens, §. 104.","glosses":[],"marks":[]},
 {"num":118,"section":"parsi-capii-seci","aa":51,"ed":null,"text":"Veritas transcendentalis est ordo in essentialibus et attributis, §. 89, hinc necessario per se coniunctis, §. 78, 107, et quidem eodem modo, §. 7, 22, hinc veritas transcendentalis est absolute necessaria, §. 117, et nullum habet oppositum, §. 102, 15.","glosses":[],"marks":[]},
 {"num":119,"section":"parsi-capii-seci","aa":51,"ed":null,"text":"Ordo plurium in uno, quorum non coniunctio aut confusio est interne possibilis in ente, est veritas in se contingens, §. 117, 89.","glosses":[],"marks":[],"aaEnd":52},
 {"num":120,"section":"parsi-capii-seci","aa":52,"ed":null,"text":"Somnium obiective sumptum et mundus fabulosus sunt nonentia, §. 118, 91, et si videantur entia, sunt entia ficta, §. 62.","glosses":[],"marks":[]},
 {"num":121,"section":"parsi-capii-seci","aa":52,"ed":35,"text":"Perfectionis oppositum est imperfectio@@1@@, et quidem 1) non consensus simplex, si in pluribus simul sumptis quaedam non sunt rationes unius: haec est imperfectio privative dicta, 2) dissensus, si in pluribus simul sumptis quaedam consentiunt ad unum, quaedam ad oppositum eius: haec est imperfectio contrarie dicta, §. 81, 94.","glosses":["Unvollkommenheit"],"marks":["*"]},
 {"num":122,"section":"parsi-capii-seci","aa":52,"ed":null,"text":"Perfectio eorum, quorum non consensus, hinc et dissensus est in se impossibilis, est absolute necessaria, §. 121, 102. At perfectio in iis, quae non consentire aut etiam dissentire est in se possibile, est in se contingens, §. 104, 121.","glosses":[],"marks":[]},
 {"num":123,"section":"parsi-capii-seci","aa":52,"ed":null,"text":"Perfectio transcendentalis est absolute necessaria, §. 122, 94, hinc nullam habet oppositam imperfectionem, §. 121, 102.","glosses":[],"marks":[]},
 {"num":124,"section":"parsi-capii-secii","aa":52,"ed":null,"text":"Succedunt@@1@@ sibi (successiva sibi sunt), quorum unum post aliud exsistit. Determinatio entium, qua sibi successiva sunt, est eorum successio@@2@@.","glosses":["Folgen aufeinander","die Folge"],"marks":["*","**"]},
 {"num":125,"section":"parsi-capii-secii","aa":52,"ed":36,"text":"Cuius determinationes sibi succedunt, mutatur@@1@@: hinc mutabile@@2@@ (variabile) est, cuius determinationes sibi possunt succedere; cuius determinationes sibi non possunt succedere, est immutabile@@3@@ (fixum, invariabile, constans). Ipsa autem determinationum in ente successio, est eius, et simul determinationum eius, mutatio@@4@@.","glosses":["wird verändert","veränderlich","unveränderlich","Veränderung"],"marks":["*","**","***","****"],"aaEnd":53},
 {"num":126,"section":"parsi-capii-secii","aa":53,"ed":null,"text":"Mutatio entis vel est interna@@1@@ internorum, vel externa@@2@@ seu relativa relationum, §. 125, 37.","glosses":["eine innre","äussre Veränderung"],"marks":["*","**"]},
 {"num":127,"section":"parsi-capii-secii","aa":53,"ed":null,"text":"Mutabilitas@@1@@ entis, s. possibilitas mutationum in eodem, vel est absoluta, §. 125, 15, vel hypothetica, §. 125, 16. Immutabilitas@@2@@ entis, s. impossibilitas mutationum in eodem, vel est absoluta, §. 125, 15, vel hypothetica, §. 125, 17.","glosses":["Veränderlichkeit","Unveränderlichkeit"],"marks":["*","**"]},
 {"num":128,"section":"parsi-capii-secii","aa":53,"ed":37,"text":"Nullum per se immutabile est hypothetice mutabile. Ergo nullum hypothetice mutabile est absolute immutabile. Omne hypothetice immutabile est in se mutabile. Omne hypothetice mutabile est in se mutabile. Ergo absolute immutabilia nec sunt hypothetice mutabilia, nec immutabilia. Quoddam absolute mutabile est hypothetice immutabile, §. 127, 18.","glosses":[],"marks":[]},
 {"num":129,"section":"parsi-capii-secii","aa":53,"ed":null,"text":"Mutabilium determinationes sibi possunt succedere, §. 125, hinc mutabilia sunt pluribus modis determinabilia, §. 74, 34. Necessaria non sunt pluribus modis determinabilia, §. 114. Ergo necessaria sunt immutabilia, §. 125.","glosses":[],"marks":[]},
 {"num":130,"section":"parsi-capii-secii","aa":53,"ed":null,"text":"Absolute necessaria sunt absolute immutabilia, hypothetice necessaria sunt hypothetice immutabilia, §. 129, 127.","glosses":[],"marks":[]},
 {"num":131,"section":"parsi-capii-secii","aa":53,"ed":null,"text":"Nullum mutabile est necessarium, §. 129, hinc omne mutabile est contingens, §. 101, et in se quidem mutabile est in se contingens, hypothetice mutabile est hypothetice contingens, §. 104, 127.","glosses":[],"marks":[]},
 {"num":132,"section":"parsi-capii-secii","aa":53,"ed":38,"text":"Essentiae rerum, §. 106, essentialia et attributa, §. 107, exsistentia entis necessarii, §. 109, omnes eius determinationes internae, §. 110, unitas, §. 116, veritas, §. 118, et perfectio, transcendentales, §. 123, sunt absolute et interne immutabiles, §. 130, 126.","glosses":[],"marks":[]},
 {"num":133,"section":"parsi-capii-secii","aa":53,"ed":null,"text":"Modi entis sibi in eo in se spectato possunt succedere, §. 124, 65, hinc et ipsi, et ens, cui insunt, sunt absolute mutabilia, §. 125, 127. Iam omne ens contingens habet modos, §. 112. Ergo omne ens contingens est absolute et interne mutabile, §. 126. Relationes entis sunt intrinsecus contingentes, §. 108. Ergo possunt sibi in eo in se spectato succedere, §. 124, 104. Hinc sunt in omni ente absolute mutabiles, §. 127. Omne ens, qua omnes suas relationes, est mutabile, §. 125.","glosses":[],"marks":[],"aaEnd":54},
 {"num":134,"section":"parsi-capii-secii","aa":54,"ed":null,"text":"Essentia non est mutabilis, §. 132, hinc omne ens contingens mutabile est, qua exsistentiam, §. 133, 56. Hinc exsistentia entis contingentis est mutabilis, §. 125, nec est adeo essentiale, nec attributum, §. 132, interna tamen determinatio, §. 55, ergo modus, §. 52. Cuius exsistentia modus est, eius exsistentia est absolute mutabilis, §. 133, hinc et intrinsecus contingens, §. 131. Ergo cuius exsistentia modus est, est ens contingens, §. 109. Potest hinc ens contingens definiri per ens, cuius exsistentia modus est.","glosses":[],"marks":[]},
 {"num":135,"section":"parsi-capii-seciii","aa":54,"ed":null,"text":"Negatione posita realitas tollitur, §. 36, 10. Hinc negationes et realitates sunt sibi invicem oppositae, §. 81. Tam realitates ipsae, quam entia, quibus insunt, entia realia@@1@@ seu positiva dicuntur. Negationes autem entia negativa@@2@@.","glosses":["etwas bejahendes","etwas verneinendes"],"marks":["*","**"]},
 {"num":136,"section":"parsi-capii-seciii","aa":54,"ed":null,"text":"Ens mere negativum esset, cui nulla inesset realitas, hinc nec possibilitas, §. 8, nec rationalitas, §. 19, nec actualitas, §. 55, nec unitas, §. 73, nec veritas, §. 89, nec perfectio, §. 94, realitates, §. 36. Ergo ens mere negativum est non ens, et, si videtur ens, est ens fictum, §. 62. Cum ergo omni enti quaedam insit realitas, omne ens est reale, §. 135.","glosses":[],"marks":[],"aaEnd":55},
 {"num":137,"section":"parsi-capii-seciii","aa":55,"ed":40,"text":"Omne ens cum sit reale, §. 136, aut nulla ipsi inerit negatio, aut quaedam cum realitatibus eius una inerit, §. 10, et haec quidem aut absolute necessaria, aut in se contingens, §. 102, 104. Prior est negatio stricte dicta@@1@@ (ens negativum stricte dictum). Posterior est privatio@@2@@ seu ens privativum. Essentialia et attributa negativa sunt negationes stricte dictae, §. 106, 107, modi negativi sunt privationes, §. 108.","glosses":["eine Verneinung in engerer Bedeutung","eine Beraubung"],"marks":["*","**"]},
 {"num":138,"section":"parsi-capii-seciii","aa":55,"ed":null,"text":"Nullae privationes sunt in ente absolute necessariae, §. 137, 105, hinc internae non sunt essentialia, nec attributa, §. 107. Ergo modi, §. 52. Ens itaque necessarium non habet privationes internas, §. 111, et cui insunt, est ens contingens, §. 111.","glosses":[],"marks":[]},
 {"num":139,"section":"parsi-capii-seciii","aa":55,"ed":null,"text":"Ens negativum, qua tale, non est positivum, §. 135, at, si consentiret, qua negatio, ad unam realitatem, esset realitas, §. 94, 36, hinc ens negativum, qua tale, non consentit in ente reali, cui inest, §. 137, ad unam realitatem.","glosses":[],"marks":[]},
 {"num":140,"section":"parsi-capii-seciii","aa":55,"ed":null,"text":"Realitates, qua tales, non consentiunt, nisi ad realitates. Rationatum enim merarum realitatum esse est realitas, §. 36, 14.","glosses":[],"marks":[]},
 {"num":141,"section":"parsi-capii-seciii","aa":55,"ed":null,"text":"Omne ens est perfectum, §. 99, et reale, §. 137, hinc eius perfectio, qua talis, est consensus realitatum ad unam, §. 94, 140.","glosses":[],"marks":[]},
 {"num":142,"section":"parsi-capii-seciii","aa":55,"ed":41,"text":"Positis in ente negationibus ponitur non consensus, §. 141, 139, hinc imperfectio, §. 121, hinc positis in ente negationibus stricte dictis, ponitur imperfectio absolute necessaria, §. 137.","glosses":[],"marks":[],"aaEnd":56},
 {"num":143,"section":"parsi-capii-seciii","aa":56,"ed":null,"text":"Imperfectio entis absolute necessaria, aut est attributum eius, aut essentiale, §. 107, 108, at, quia in realitatibus non est ratio sufficiens negationum, §. 139, non est in entis attributis imperfectio, in cuius non sit etiam essentialibus, §. 50, nec est in essentialibus entis imperfectio, in cuius non esset etiam affectionibus, §. 23.","glosses":[],"marks":[]},
 {"num":144,"section":"parsi-capii-seciii","aa":56,"ed":null,"text":"Positis in ente privationibus ponitur imperfectio, §. 142, at in se contingens, §. 138.","glosses":[],"marks":[]},
 {"num":145,"section":"parsi-capii-seciii","aa":56,"ed":null,"text":"Non est perfectio essentialis sine accidentali, §. 98, 140, nec accidentalis sine essentiali, §. 98, non est imperfectio essentialis sine accidentali, nec accidentalis sine essentiali, §. 143, 98, nec sunt perfectio et imperfectio essentialis opposita, §. 81, 142.","glosses":[],"marks":[]},
 {"num":146,"section":"parsi-capii-seciii","aa":56,"ed":42,"text":"Quo posito ponitur imperfectio, malum@@1@@ est, hinc negationes sunt malum, §. 142, eaeque vel stricte dictae, malum metaphysicum@@2@@, quo posito ponitur imperfectio absolute necessaria, §. 142, vel privationes, malum contingens@@3@@ (physicum late dictum, cf. §. 788), quo posito ponitur imperfectio in se contingens, §. 144.","glosses":["Das Übel, Böse","das schlechterdings nothwendige","das zufällige"],"marks":["*","**","***"]},
 {"num":147,"section":"parsi-capii-seciii","aa":56,"ed":null,"text":"Positis entis realitatibus ponitur eius perfectio, §. 141, hinc realitates sunt bona, §. 100, et absolute quidem necessariae, bonum metaphysicum@@1@@, in se contingentes, bonum contingens@@2@@ (physicum late dictum, cf. §. 787).","glosses":["das schlechterdings nothwendige","das zufällige Gute"],"marks":["*","**"],"aaEnd":57},
 {"num":148,"section":"parsi-capii-seciiii","aa":57,"ed":43,"text":"Complexus omnium determinationum in ente compossibilium est omnimoda eius determinatio@@1@@. Hinc ens aut est omnimode determinatum, aut minus, §. 10. Illud est singulare@@2@@ (individuum), hoc universale@@3@@. Utrumque respectu omnium minus determinatorum, quae in se continet, inferius@@4@@ dicitur, illa respectu huius, superiora@@5@@.","glosses":["durchgängige, völlige, vollständige Bestimmung","einzeln","allgemeine","das untere, niedrigere, tiefere, bestimmtere","die obern, höheren, allgemeinern, unbestimmtern"],"marks":["*","**","***","****","*****"]},
 {"num":149,"section":"parsi-capii-seciiii","aa":57,"ed":null,"text":"Ens universale spectatum in suo inferiori, et singulare spectatum, qua alia etiam sua praedicata, praeter certum universale, spectatur in concreto@@1@@ et tunc concretum@@2@@ dicitur. Ens universale quod attenditur quidem, non tamen in inferiori suo, et singulare, in quo tamen certum tantum eius superius attenditur, spectatur in abstracto@@3@@, et tunc abstractum@@4@@ dicitur. Universale in concreto est universale physicum@@5@@ (in multis, in re), universale in abstracto est logicum@@6@@ (post multa, post rem).","glosses":["in mehrerer Bestimmung betrachtet","unabgesondert","nur in gewisser Bestimmung betrachtet","abgesondert","das allgemeine im bestimmtern","das allgemeine im denkenden"],"marks":["*","**","***","****","*****","******"]},
 {"num":150,"section":"parsi-capii-seciiii","aa":57,"ed":44,"text":"Universale in solis individuis in concreto repraesentabile, seu, quod sola individua sub se continet, est species@@1@@, quod etiam in universalibus in concreto repraesentabile est, seu, quod universalia etiam sub se continet, est genus@@2@@, et horum infimum@@3@@ quod in nullo genere est, s. quod nullum genus sub se continet, summum@@4@@ in quo nullum genus s. quod sub nullo genere continetur, subalterna@@5@@ denique vocantur, quae non sunt summa.","glosses":["Art, Gattung","Geschlecht","das Unterste","das Oberste","untergeordnete, oder Untergeschlechte"],"marks":["*","**","***","****","*****"]},
 {"num":151,"section":"parsi-capii-seciiii","aa":57,"ed":null,"text":"Determinationes inferioris entis, indeterminatae in eius superiore sunt illius differentia@@1@@. Hinc differentia generica@@2@@ est complexus determinationum in genere determinatarum, indeterminatarum in eius superiori. Differentia specifica@@3@@ est complexus determinationum speciei indeterminatarum in genere eius infimo. Differentia numerica@@4@@ (haecceitas, principium individuationis) est complexus determinationum individui indeterminatarum in specie, §. 148.","glosses":["die genauere Bestimmung","eines Geschlechtes","einer Art","eines jeden einzeln"],"marks":["*","**","***","****"]},
 {"num":152,"section":"parsi-capii-seciiii","aa":57,"ed":null,"text":"Singularia sunt interne prorsus determinata, §. 148, hinc actualia, §. 54.","glosses":[],"marks":[],"aaEnd":58},
 {"num":153,"section":"parsi-capii-seciiii","aa":58,"ed":45,"text":"Cum in inferiori sit superius, §. 149, 148, est in individuo species, genus infimum, subalterna, summum, in specie genera, in genere infimo et subalterno superiora, in inferioribus omnibus summum, §. 150.","glosses":[],"marks":[]},
 {"num":154,"section":"parsi-capii-seciiii","aa":58,"ed":null,"text":"Determinationes generis summi sunt in inferioribus eius, §. 148, i.e. generibus subalternis, infimo, speciebus et individuis; determinationes generis subalterni sunt in inferioribus eius generibus, speciebus, et individuis; determinationes generis infimi sunt in speciebus et individuis; determinationes speciei sunt in individuis, §. 153, 35, i.e. determinationes superioris sunt in eius inferiori, seu positivae fuerint seu negativae, §. 36. Haec propositio dicitur dictum de O. et N.","glosses":[],"marks":[]},
 {"num":155,"section":"parsi-capii-secv","aa":58,"ed":46,"text":"Unum prorsus idem cum multis simul sumptis est totum@@1@@, et multa simul sumpta prorsus eadem cum toto sunt partes@@2@@ eius. Quae cum data parte simul sumenda sunt, ut sit prorsus eadem cum toto, sunt eius compartes, seu complementa ad totum@@3@@ (supplementa).","glosses":["das Ganze","Theile","Ergänzungen"],"marks":["*","**","***"]},
 {"num":156,"section":"parsi-capii-secv","aa":58,"ed":null,"text":"Quaelibet pars simul sumpta cum suis complementis ad totum est pars actualis@@1@@, cum aliis simul sumpta est pars potentialis@@2@@.","glosses":["ein wirklicher","ein möglicher Theil"],"marks":["*","**"]},
 {"num":157,"section":"parsi-capii-secv","aa":58,"ed":null,"text":"Totum est prorsus idem cum suis partibus actualibus, §. 155, 156, hinc et aequale, et simile et congruens, §. 70.","glosses":[],"marks":[],"aaEnd":59},
 {"num":158,"section":"parsi-capii-secv","aa":59,"ed":null,"text":"Ens, cuius essentia est pars alterius, est ens incompletum@@1@@, cuius essentia non est pars alterius, est ens completum@@2@@.","glosses":["ein unvollständiges","ein vollständiges Ding"],"marks":["*","**"]},
 {"num":159,"section":"parsi-capii-secv","aa":59,"ed":47,"text":"Multitudo partium est magnitudo@@1@@ (absoluta, cf. §. 161) seu quantitas, §. 75, continua. Multitudo totorum est numerus@@2@@ (absolutus, cf. 161) seu quantitas, §. 75, discreta. Si tota, quorum est numerus, iterum spectentur, ut partes, numerusest fractus@@3@@ (fractio, minutia), sin minus, numerus est integer@@4@@.","glosses":["die Grösse des Ganzen","eine Zahl","ein Bruch","eine ganze Zahl"],"marks":["*","**","***","****"]},
 {"num":160,"section":"parsi-capii-secv","aa":59,"ed":null,"text":"Cuius pars toti aequalis est, maius > est@@1@@, totum parti aequale minus < est@@2@@.","glosses":["das grössere","das kleinere"],"marks":["*","**"],"aaEnd":60},
 {"num":161,"section":"parsi-capii-secv","aa":60,"ed":null,"text":"Minimum@@1@@ est solo nihilo maius, seu, quo minus impossibile est, maximum@@2@@ est, solo nihilo minus, seu, quo maius impossibile est. Multitudo maior est multitudo comparativa@@3@@, Cf. §. 74, minor, paucitas@@4@@. Magnitudo maior est magnitudo comparativa@@5@@, cf. §. 159, minor, parvitas@@6@@. Numerus maior est comparativus, cf. §. 159, minor, raritas°°). °°) Seltenheit.","glosses":["das kleinste","das grösseste","eine Menge","Wenigkeit","eine Grösse des Ganzen und Zahl, auch in der Vergleichung","Kleinigkeit"],"marks":["*","**","***","****","*****","******"]},
 {"num":162,"section":"parsi-capii-secv","aa":60,"ed":48,"text":"Mutari in minus est minui@@1@@, mutari in maius augeri@@2@@. Quicquid ergo potest augeri vel minui, est mutabile, §. 125, et quidem, qua quantitatem, §. 160, 70, hinc interne, §. 126, 69.","glosses":["vermindert","vermehrt werden"],"marks":["*","**"],"aaEnd":61},
 {"num":163,"section":"parsi-capii-secv","aa":61,"ed":null,"text":"Essentiae rerum, essentialia et attributa, omnes entis necessarii determinationes internae, unitas in entibus, veritas, et perfectio, transcendentales augeri vel minui intrinsecus nequeunt, §. 162, 132.","glosses":[],"marks":[]},
 {"num":164,"section":"parsi-capii-secv","aa":61,"ed":null,"text":"Determinatio entis interna, quae potest augeri vel minui, modus est, §. 163, 52, et in quo talis occurrit determinatio interna, quae in ipso potest augeri vel minui, illud est ens contingens, §. 111.","glosses":[],"marks":[]},
 {"num":165,"section":"parsi-capii-secvi","aa":61,"ed":null,"text":"Possibilitas minima est non repugnantia minimorum paucissimorum, §. 161, 8. Quo ergo plura, quo maiora sunt compossibilia, hoc maior est possibilitas, §. 160, donec maxima sit, ubi plurima maxima sunt compossibilia, §. 161. Hinc omnis possibilitas entis hypothetica maior est eiusdem possibilitate intrinseca, §. 16, 15.","glosses":[],"marks":[]},
 {"num":166,"section":"parsi-capii-secvi","aa":61,"ed":49,"text":"Ratio minima est, quae unicum minimum rationatum habet, §. 161. Quo ergo plura, quo maiora rationata habet, hoc maior est, §. 160, donec maxima fiat maxima plurima rationata habens, §. 161. Magnitudo rationis ex numero rationatorum est fecunditas@@1@@, ex magnitudine eorum pondus@@2@@ (gravitas, dignitas, nobilitas).","glosses":["Fruchtbarkeit","Wichtigkeit"],"marks":["*","**"]},
 {"num":167,"section":"parsi-capii-secvi","aa":61,"ed":null,"text":"Nexus minimus est unicae rationis minimae, §. 166, 14. Quo ergo plures, quo maiores rationes, hoc maior nexus, §. 160, donec fiat maximus plurimarum maximarum rationum, §. 161, i.e. fecundissimarum et gravissimarum, §. 166. Nexus maior est harmonia.","glosses":[],"marks":[],"aaEnd":62},
 {"num":168,"section":"parsi-capii-secvi","aa":62,"ed":null,"text":"Possibilitas hypothetica minima est, qua ens unicum minimum in minimo nexu gaudet, §. 16, 161. Quo ergo plura, quo maiora, quo maiore in nexu possibilia sunt, hoc maior est possibilitas hypothetica §. 160, donec maxima sit, ubi plurima maxima in maximo nexu possibilia sunt, §. 161, i.e. fecundissimarum gravissimarumque rationum rationata fecundissima, gravissima, §. 167.","glosses":[],"marks":[]},
 {"num":169,"section":"parsi-capii-secvi","aa":62,"ed":50,"text":"Ratio sufficiens est rationum fecundissima, §. 166, 21, in sufficientibus tamen minima est, quae unico minimo rationato sufficit, §. 166, 161. Quo ergo pluribus, quo maioribus rationatis sufficit, hoc maior est, §. 160, donec sit maxima, plurimis maximis rationatis sufficiens, §. 161, eademque fecundissima et nobilissima, §. 166.","glosses":[],"marks":[]},
 {"num":170,"section":"parsi-capii-secvi","aa":62,"ed":null,"text":"Ratio ulterior propiore maior est, §. 166, 27, hinc sufficiens simpliciter talis maior omnibus secundum quid sufficientibus, §. 169, 28.","glosses":[],"marks":[]},
 {"num":171,"section":"parsi-capii-secvi","aa":62,"ed":null,"text":"Essentia minima est, complexus paucissimorum minimorum essentialium, §. 40, 161. Quo plura, quo maiora sunt essentialia, hoc est maior, §. 160, donec maxima sit, complexus plurimorum maximorum essentialium, §. 161.","glosses":[],"marks":[]},
 {"num":172,"section":"parsi-capii-secvi","aa":62,"ed":null,"text":"Nexus universalis minimus est, ubi singula aut sunt rationes minimae, aut earum rationata, §. 48, 167. Quo ergo aut maiores rationes, aut maiorum rationum rationata, aut utrumque fiunt singula, hoc maior est nexus universalis, §. 160, donec sit maximus, ubi singula maximae rationes sunt, §. 161, i.e. fecundissimae gravissimaeque, §. 166.","glosses":[],"marks":[]},
 {"num":173,"section":"parsi-capii-secvi","aa":62,"ed":51,"text":"Unitas minima est, si paucissimae minimae determinationes unici minimi sint inseparabiles, §. 73, 161. Quo ergo plures, quo maiores determinationes, quo plurium, quo maiorum sunt inseparabiles, hoc unitas maior est, §. 160, donec sit maxima, ubi plurimae maximae determinationes plurimorum maximorumque sunt inseparabiles, §. 161. Unicitas minima est, qua unum minimum a paucissimis minimis unico minimo discrimine differt, §. 77, 161. Quo ergo maius, a quo pluribus, quo maioribus, quo plures, quo maiores per differentias distinguitur, hoc maior est unicitas, §. 160, donec sit maxima, qua maximum ob omnibus, maximis etiam in suo genere, per plurimas maximas differentias distinguitur, §. 161.","glosses":[],"marks":[]},
 {"num":174,"section":"parsi-capii-secvi","aa":62,"ed":null,"text":"Identitas minima est, si unica minima determinatio sit paucissimis minimis communis, §. 38, 161. Hinc quo plures, quo maiores determinationes, quo pluribus, quo maioribus sunt communes, hoc maior est identitas, §. 160, donec sit maxima, plurimarum maximarumque determinationum in plurimis maximis communio, §. 161.","glosses":[],"marks":[],"aaEnd":63},
 {"num":175,"section":"parsi-capii-secvi","aa":63,"ed":52,"text":"Ordo minimus est minima in coniunctione identitas, §. 78, 161. Ergo quo maior est coniunctionis identitas, hoc maior fit ordo, §. 160, 174, donec sit maximus, ubi maxima coniunctionis identitas, §. 161, i.e. ubi plurima maxima, toties, tantumque coniunguntur eodem modo, quoties, quantumque possunt, §. 174. Unitio minima est paucissimorum minimorum minime necessaria coniunctio, §. 79, 113, 161. Quo ergo plura coniunguntur, hoc est extensive maior, quo maiora, quo maiori necessitate coniunguntur, hoc est intensive maior unitio, donec plurimorum coniunctio necessaria sit extensive, vel duorum tantum, triumve, sed maximorum et maxime necessaria, quae potest esse inter ea, sit intensive maxima unitio.","glosses":[],"marks":[]},
 {"num":176,"section":"parsi-capii-secvi","aa":63,"ed":null,"text":"Determinationis ex ratione cognoscibilitas cum sit conformitas eius cum ratione@@1@@, §. 80, haec conformitas erit minima, si determinatio ex minima ratione tantum cognoscibilis, §. 161, 166, in minima cognitionis possibilitate, §. 165. Quo maior ratio, ex qua cognoscenda determinatio, quo magis possibilis haec cognitio, hoc maior conformitas determinationis cum ratione, §. 160, donec sit maxima ex maxima ratione maxime cognoscibilis, §. 161.","glosses":["die Übereinstimmung einer Bestimmung mit ihrem Grunde"],"marks":["*"]},
 {"num":177,"section":"parsi-capii-secvi","aa":63,"ed":null,"text":"Determinatio rationi sufficienti, fecundiori, graviori conformis, §. 166, 169, hinc ulteriori et simpliciter tali, §. 170, maiorem habet conformitatem, quam insufficienti, minus fecundae, minusque gravi, §. 166, 169, propiori aut secundum quid sufficienti, §. 170, tantum conformis, §. 176.","glosses":[],"marks":[]},
 {"num":178,"section":"parsi-capii-secvi","aa":63,"ed":53,"text":"Defectus minimus est oppositus determinationi minimae conformitatis cum ratione, §. 82, 161, hinc eo maior est, quo maior in opposito eius conformitas, §. 160, 176, donec sit maximus, oppositus determinationi, in qua maxima conformitas, §. 176, 161.","glosses":[],"marks":[]},
 {"num":179,"section":"parsi-capii-secvi","aa":63,"ed":null,"text":"Defectus rationi sufficienti, fecundiori, graviori, ulteriori et simpliciter tali contrarius maior est contrario rationi insufficienti, minus fecundae, minus gravi, propiori et sufficienti secundum quid tantum, §. 178, 177.","glosses":[],"marks":[]},
 {"num":180,"section":"parsi-capii-secvi","aa":63,"ed":null,"text":"Magnitudo conformitatis cum ratione in determinatione, quam lex enuntiat, est robur legis@@1@@. Lex enuntians determinationem conformitatis cum ratione comparative magnae est fortis@@2@@, parvae debilis@@3@@ est. Hinc lex maxime debilis seu minimi roboris est, quae enuntiat determinationem minimae conformitatis cum ratione, §. 161, 176. Quo maior conformitas cum ratione determinationi a lege enuntiatae, hoc lex est fortior, §. 160, donec fortissima sit enuntians determinationem, in qua maxima conformitas, §. 161.","glosses":["Stärke der Richtschnur","ein starkes","schwaches Gesetz"],"marks":["*","**","***"],"aaEnd":64},
 {"num":181,"section":"parsi-capii-secvi","aa":64,"ed":54,"text":"Lex enuntians determinationem rationi sufficienti, fecundiori, graviori, ulteriori, cuius rationatum sit, seu cui subordinetur comparanda propior, et simpliciter tali conformem fortior est, quam lex debilior enuntians determinationem rationi insufficienti, minus fecundae, minus gravi, propiori, quae subordinetur illi, cum qua comparatur, ulteriori, et secundum quid sufficienti tantum conformem, §. 180, 177.","glosses":[],"marks":[]},
 {"num":182,"section":"parsi-capii-secvi","aa":64,"ed":null,"text":"Lex enuntians determinationem rationi sufficienti ulteriori conformem superior@@1@@, propiori conformem enuntians inferior@@2@@ dicitur. Ergo leges superiores fortiores sunt inferioribus, et summa lex est fortissima, §. 181.","glosses":["eine höhere","niedrigere Richtschnur"],"marks":["*","**"]},
 {"num":183,"section":"parsi-capii-secvi","aa":64,"ed":null,"text":"Ordo maximus plurimas regulas communes habet, §. 175, 86, hinc est maxime compositus, §. 88, adeoque ordo simplex, quantuscumque sit, non tamen est maximus, §. 175, 88.","glosses":[],"marks":[],"aaEnd":65},
 {"num":184,"section":"parsi-capii-secvi","aa":65,"ed":55,"text":"Veritas metaphysica minima est ordo plurium in uno minimus, §. 175, 89, seu minima cum principiis catholicis conformitas, §. 176, 92. Quo ergo plura in ente, quo maiora, secundum quo plures, quo fortiores regulas coniuncta sunt, hoc maior est in illo veritas, §. 175, 180, donec sit maxima, ubi plurima maxima, fortissimis (principiorum catholicorum, §. 182) regulis convenientissima deprehenduntur, §. 160, 161.","glosses":[],"marks":[]},
 {"num":185,"section":"parsi-capii-secvi","aa":65,"ed":null,"text":"Perfectio minima est consensus paucissimorum minimorum ad unum minimum unicus minimus, §. 94, 161, hinc quo plura, quo maiora, in quo plura, in quo maiora, quo pluries, quo magis consentiunt, hoc maior est perfectio, §. 160, donec sit maxima plurimorum maximorum maximus consensus ad unum, §. 161, 169. At summa perfectio cum adeo sit maxime composita, §. 183, 96, simplex perfectio, quantacumque sit, non tamen est maxima, §. 96.","glosses":[],"marks":[]},
 {"num":186,"section":"parsi-capii-secvi","aa":65,"ed":56,"text":"Exceptio minima est a maxime debili perfectionis regula ob fortissimam facta, §. 178, 97. Ergo quo fortior est regula perfectionis, a qua, quo debilior, ob quam excipitur, hoc maior est exceptio, §. 160, donec sit maxima a fortissima, hinc summa perfectionis regula, §. 182, ob maxime debilem legem excipiens, §. 161. Si collidantur ratio perfectionis sufficiens et insufficiens, exceptio a sufficiente maior, ab insufficiente minor est. Si collidantur fecundior et minus fecunda, exceptio a fecundiori maior, a minus fecunda minor est. Si collidantur ratio perfectionis gravior et minus gravis, exceptio a graviori maior, a minus gravi minor est. Si collidantur ulterior et ipsi subordinanda propior, exceptio ab ulteriori maior, a propiori minor est. Si collidantur ratio simpliciter sufficiens et talis secundum quid, exceptio a simpliciter tali maior, a tali secundum quid, minor est, §. 181. Si collidantur regula perfectionis superior et inferior, exceptio a superiori maior, ab inferiori minor est, §. 182. Hinc exceptio summae perfectionis legi contraria, i.e. quae fit a summa perfectionis regula ob minimam, i.e. minimae conformis, est maxima, §. 187, 182.","glosses":[],"marks":[]},
 {"num":187,"section":"parsi-capii-secvi","aa":65,"ed":null,"text":"Bonum minimum est, quo posito ponitur minima perfectio, §. 100, 161. Quo maior est perfectio posito bono ponenda, hoc maius est bonum, §. 160, donec optimum@@1@@ sit, quo posito ponitur summa perfectio, §. 161.","glosses":["das Beste"],"marks":["*"]},
 {"num":188,"section":"parsi-capii-secvi","aa":65,"ed":null,"text":"Minime contingens est, cuius oppositum est minime possibile, §. 104, 161. Quo maior ergo possibilitas unius oppositorum, hoc maior alterius contingentia, §. 160. Maxima contingentia est illius, cuius oppositum habet maximam possibilitatem, §. 161.","glosses":[],"marks":[],"aaEnd":66},
 {"num":189,"section":"parsi-capii-secvi","aa":66,"ed":57,"text":"Quo maior est determinationum hypothetice unius separabilitas, hoc maior est huius unitatis contingentia, §. 115, 188. Quo magis tam non coniunctio, quam confusio est possibilis, hoc oppositus ordo magis est contingens, §. 117, 188. Quo magis non coniunctio vel confusio quorundam entis variorum possibilis est, hoc veritas eius opposita magis est contingens, §. 119, 188. Quo magis imperfectio possibilis est, hoc magis opposita perfectio contingens est, §. 122, 188.","glosses":[],"marks":[]},
 {"num":190,"section":"parsi-capii-secvi","aa":66,"ed":58,"text":"Minima mutatio est unici minimi in unico minimo successio, §. 161, 125. Ergo quo plura, quo maiora, in quo pluribus, quo maioribus succedunt, hoc maior est mutatio, §. 160, donec sit maxima, plurimorum maximorum in pluribus maximis successio. Minima minimae mutationis in ente possibilitas est eius mutabilitas minima, §. 161, 127. Ergo quo magis possibilis, quo maior in ente mutatio, hoc est eius maior mutabilitas, donec sit maxima, maxima maximae mutationis possibilitas, §. 161. Realitas in ente minima est summa paucitas et parvitas in eodem determinationum vere positivarum, §. 135, 161. Quo harum plures, quo maiores habet, hoc est realius. Realissimum ergo est, in quo maximae plurimae realitates, §. 161, 36. Hae absolute necessariae sunt summum bonum, s. optimum metaphysicum@@1@@, §. 137, 147, in se contingentes summum bonum contingens@@2@@ (physicum late dictum).","glosses":["das nothwendige höchste Gut","das zufällige höchste Gut"],"marks":["*","**"],"aaEnd":67},
 {"num":191,"section":"parsi-capii-secvii","aa":67,"ed":null,"text":"Ens vel non potest exsistere, nisi ut determinatio alterius (in alio), vel potest, §. 10. Prius accidens@@1@@ (praedicamentale s. physicum, cf. §. 50, cuius esse est inesse, συμβεβηκοσ), posterius est substantia@@2@@ (ens per se subsistens, forma, ἐντελεχεια οὐσια ὑποστασισ ἐνεργεια), quod potest exsistere, licet non sit in alio, licet non sit determinatio alterius.","glosses":["ein nur in andern","ein vor sich bestehendes Ding"],"marks":["*","**"]},
 {"num":192,"section":"parsi-capii-secvii","aa":67,"ed":null,"text":"Exsistentia accidentis, qua talis, est inhaerentia@@1@@, exsistentia substantiae, qua talis, est subsistentia@@2@@.","glosses":["das nur in andern","das vor sich bestehn"],"marks":["*","**"]},
 {"num":193,"section":"parsi-capii-secvii","aa":67,"ed":null,"text":"Accidentia si videntur per se subsistentia, sunt phaenomena substantiata@@1@@.","glosses":["das vor sich zu bestehn scheinende"],"marks":["*"]},
 {"num":194,"section":"parsi-capii-secvii","aa":67,"ed":59,"text":"Accidentianon exsistere possunt, nisi in aliis. Iam non sunt diversa ab accidentibus, nisi substantiae, §. 191. Ergo accidentia non exsistere possunt, nisi in substantiis, seu non exsistunt extra suas substantias, §. 58.","glosses":[],"marks":[]},
 {"num":195,"section":"parsi-capii-secvii","aa":67,"ed":null,"text":"Essentialia, attributa, modi, relationes accidentia, §. 191, 52, non exsistere possunt, nisi in substantiis, §. 194.","glosses":[],"marks":[]},
 {"num":196,"section":"parsi-capii-secvii","aa":67,"ed":null,"text":"Id in substantia, cui inhaerere possunt accidentia, s. substantia, quatenus est subiectum (cf. §. 344) id, cui accidentia inhaerere possunt, substantiale vocatur, nec accidentia exsistunt extra substantiale, §. 194.","glosses":[],"marks":[]},
 {"num":197,"section":"parsi-capii-secvii","aa":67,"ed":null,"text":"Si substantiae inhaerent accidentia, est aliquid inhaerentiae ratio, §. 20, s. vis latius dicta@@1@@ (efficacia, energia, activitas, cf. §. 216), et sufficiens, §. 22. Hoc est vis (strictius dicta@@2@@, et brevitatis causa nonnumquam simpliciter).","glosses":["eine Kraft in weiterer","eine Kraft in engerer Bedeutung"],"marks":["*","**"],"aaEnd":68},
 {"num":198,"section":"parsi-capii-secvii","aa":68,"ed":60,"text":"Vis strictius dicta aut est substantia, aut accidens, §. 191. Iam non est accidens, eorum omnium cum sit ratio sufficiens, §. 197. Ergo est substantia, et quatenus ipsi inhaerere possunt accidentia, ut subiecto, substantiale, §. 196.","glosses":[],"marks":[]},
 {"num":199,"section":"parsi-capii-secvii","aa":68,"ed":null,"text":"Omnis substantia est substantiali, §. 191, 196, hinc vi praedita, §. 198, est substantiale, §. 196, 191, hinc vis tam latius, quam strictius dicta, §. 198, 197.","glosses":[],"marks":[]},
 {"num":200,"section":"parsi-capii-secvii","aa":68,"ed":null,"text":"Substantiae si videntur accidentia, sint substantiae praedicatae, singulares sunt supposita@@1@@.","glosses":["einzle vor sich bestehende Dinge"],"marks":["*"]},
 {"num":201,"section":"parsi-capii-secvii","aa":68,"ed":null,"text":"Phaenomenis substantiatis vis tribuitur, §. 199, 193, et sunt etiam vires latius dictae, aut viribus latius dictis praedita, §. 197, 23. Quod si vero strictius dicta vis tribuitur accidentibus, sunt ea phaenomena substantiata, §. 198, 193.","glosses":[],"marks":[]},
 {"num":202,"section":"parsi-capii-secvii","aa":68,"ed":61,"text":"Omnis substantia habet essentialia et attributa absolute necessario, §. 107, hinc omnis substantia habet accidentia, §. 191, 195. Sed modos vel habet, vel non habet, §. 10. Quae modos habet, est ens contingens, quae non habet, ens necessarium, §. 111. Ergo substantia vel est necessaria vel contingens. Substantiae contingentis subsistentia modus est, §. 134, 192.","glosses":[],"marks":[]},
 {"num":203,"section":"parsi-capii-secvii","aa":68,"ed":null,"text":"Vis minima unici tantum minimi inhaerentis accidentis est ratio, §. 197, 166. Quo ergo plurium, quo maiorum inhaerentium accidentium ratio est, hoc maior est, donec sit maxima plurimorum maximorum inhaerentium accidentium, §. 197, 166.","glosses":[],"marks":[]},
 {"num":204,"section":"parsi-capii-secvii","aa":68,"ed":null,"text":"Scientia virium est dynamica tam philosophica, quam mathematica, dynameometria.","glosses":[],"marks":[],"aaEnd":69},
 {"num":205,"section":"parsi-capii-secviii","aa":69,"ed":62,"text":"Suppositum contingens est determinatum, qua modos et relationes, §. 184, 200. Hinc coexsistunt in eo fixa, seu, intrinsecus immutabilia, §. 107, 132, cum mutabilibus, §. 133. Eiusmodi coexsistentia status@@1@@ est. Ergo suppositum contingens habet statum. Status unitorum est unio@@2@@.","glosses":["Zustand","Einigkeit"],"marks":["*","**"]},
 {"num":206,"section":"parsi-capii-secviii","aa":69,"ed":null,"text":"Coexsistentia modorum cum fixis est status internus@@1@@, hinc suppositum contingens habet statum internum, §. 205.","glosses":["der innre Zustand"],"marks":["*"]},
 {"num":207,"section":"parsi-capii-secviii","aa":69,"ed":null,"text":"Relationes substantiae sunt in ea intrinsecus mutabiles, §. 133. Ergo fixis coexsistentes dant statum, §. 205, qui externus dicitur@@1@@.","glosses":["der äussre Zustand"],"marks":["*"]},
 {"num":208,"section":"parsi-capii-secviii","aa":69,"ed":null,"text":"Mutato modo mutatur status internus, §. 125, 200, mutata relatione, mutatur status externus, §. 125, 207. Iam modi et relationes sunt mutabiles, §. 133. 207. Ergo in substantia contingenti mutationes status sunt possibiles. §. 206, 207.","glosses":[],"marks":[]},
 {"num":209,"section":"parsi-capii-secviii","aa":69,"ed":63,"text":"Mutatio modi est modificatio@@1@@. Ergo modificatio est mutatio status interni, §. 208, et substantia contingens est modificabilis, §. 128. Mutatio relationis variatio est@@2@@.","glosses":["eine innre","eine äussre Veränderung"],"marks":["*","**"],"aaEnd":70},
 {"num":210,"section":"parsi-capii-secviii","aa":70,"ed":null,"text":"Mutationes status sunt accidentia, §. 191, hinc non exsistere possunt, nisi in substantiis, §. 194, et quidem posita vi, etiam strictius dicta, §. 197, 22. Vis illa mutationis, aut in genere inhaerentis accidentis, ratio sufficiens, §. 197, vel est substantiale, quod mutatur, aut in genere, cui accidens inhaeret, vel vis ab eo diversa, §. 10, 38. Si prius est, substantia, cuius status mutatur, vel in genere, cui accidens inhaeret, agit@@1@@; si posterius est, substantia, cuius status mutatur, vel in genere, cui accidens inhaeret, patitur. Hinc actio@@2@@ (actus, operatio) est mutatio status, et in genere actuatio accidentis in substantia, per vim ipsius: passio@@3@@ mutatio status, et in genere actuatio accidentis in substantia, per vim alienam.","glosses":["thun, handeln","Handlung","Leiden"],"marks":["*","**","***"]},
 {"num":211,"section":"parsi-capii-secviii","aa":70,"ed":null,"text":"Substantia in substantiam extra se agens in eam influit, adeo influxus@@1@@ (actio transiens) est actio substantiae in substantiam extra se. Actio, quae non est influens, est immanens.","glosses":["Einfluss"],"marks":["*"],"aaEnd":71},
 {"num":212,"section":"parsi-capii-secviii","aa":71,"ed":64,"text":"Si passio illius substantiae, in quam altera influit, simul est ipsius patientis actio, passio et influxus dicuntur ideales. Si vero passio non est patientis actio, passio et influxus dicuntur reales.","glosses":[],"marks":[]},
 {"num":213,"section":"parsi-capii-secviii","aa":71,"ed":null,"text":"Actio patientis in agens est reactio@@1@@ et mutua substantiarum actio et reactio conflictus@@2@@.","glosses":["Gegenwirkung","Streit"],"marks":["*","**"]},
 {"num":214,"section":"parsi-capii-secviii","aa":71,"ed":null,"text":"Actio et passio reactioque minimae sunt, per quas non nisi unicum minimum accidens actuatur, §. 161, 210. Quo ergo plura, quo maiora accidentia actuantur, hoc maior actio, passio, reactio, §. 160, 213, donec sint maximae, ubi plurima maxima actuantur accidentia, §. 161, 210.","glosses":[],"marks":[]},
 {"num":215,"section":"parsi-capii-secviii","aa":71,"ed":null,"text":"Actio et passio simplex@@1@@ dicitur, quae non est totum aliarum, quae est, composita@@2@@; et quo pluribus partialibus constat, hoc magis est composita, §. 160. Hinc actio et passio maxima est maxime composita, §. 214, 161.","glosses":["ein einfaches","ein zusammengesetztes Thun und Leiden"],"marks":["*","**"],"aaEnd":72},
 {"num":216,"section":"parsi-capii-secviii","aa":72,"ed":65,"text":"Omnis substantia exsistens agit, §. 210, 199, hinc habet possibilitatem agendi seu facultatem@@1@@ (potentiam activam, vim, cf. §. 197), §. 57, si patitur, habet possibilitatem patiendi, i.e. (potentiam passivam, capacitatem) receptivitatem@@2@@. §. 57.","glosses":["Vermögen","Fähigkeit, Empfänglichkeit"],"marks":["*","**"]},
 {"num":217,"section":"parsi-capii-secviii","aa":72,"ed":null,"text":"Facultas et receptivitas influxuum realium reales, idealium ideales, actionum simplicium simplices@@1@@, compositarum compositae@@2@@ sunt.","glosses":["einfache","zusammengesetzte Vermögen und Fähigkeiten"],"marks":["*","**"],"aaEnd":74},
 {"num":218,"section":"parsi-capii-secviii","aa":74,"ed":null,"text":"Facultates et receptivitates vel absolutae sunt, §. 216, 15, vel hypotheticae, §. 16. Hae quidem semper maiores illis, §. 105, 216.","glosses":[],"marks":[]},
 {"num":219,"section":"parsi-capii-secviii","aa":74,"ed":null,"text":"Facultas hypothetica minima esset, qua unica tantum actio in minimo nexu substantiae possibilis esset, §. 216, 161. Quo plures, quo maiores actiones, quo maiori in nexu sunt substantiae possibiles, hoc maior est facultas hypothetica, §. 168, 160. Maior facultas hypothetica est habitus@@1@@ (promptitudo, dexteritas).","glosses":["Fertigkeit"],"marks":["*"]},
 {"num":220,"section":"parsi-capii-secviii","aa":74,"ed":66,"text":"Posita facultate et receptivitate cum non ponatur actio vel passio, §. 216, 259, ponatur tamen posita vi strictius dicta, §. 210, 30, haec erit complementum facultatis ad actum, i.e. quod accedit ad facultatem, ut exsistat actio. Hinc data certa vis strictius dicta ad datam certam actionem vel sufficit, vel minus, §. 21, 210, prior viva@@1@@, posterior mortua@@2@@ sollicitatio dicitur.","glosses":["eine lebendige","eine todte Kraft"],"marks":["*","**"]},
 {"num":221,"section":"parsi-capii-secviii","aa":74,"ed":null,"text":"Impedimentum@@1@@ (obstaculum) est oppositum accidentis inhaerentiae, hinc et oppositum mutationibus est impedimentum, §. 210.","glosses":["Hinderniss"],"marks":["*"],"aaEnd":75},
 {"num":222,"section":"parsi-capii-secviii","aa":75,"ed":null,"text":"Resistentia@@1@@ est impedimentum actionis. Cumque oppositum inhaerentiae accidentium et mutationum sit accidens, §. 191, 81, impedimenta resistentiaeque rationem habent in vi sufficientem, §. 197, 27. Posito impedimento ponitur vis impediens: posita resistentia ponitur vis resistens, §. 22.","glosses":["Wiederstand"],"marks":["*"]},
 {"num":223,"section":"parsi-capii-secviii","aa":75,"ed":67,"text":"Substantia in substantiam propius influens illi praesens@@1@@ est, et proxime praesentes sibi invicem substantiae, se contingunt, sunt contigua@@2@@, ut adeo sit praesentia@@3@@ influxus propior, et immediata praesentia mutua, s. immediatus conflictus, contactus@@4@@. Quatenus aliquid in aliud non influit, nec ab eo patitur, propius, absens@@5@@ ab illo dicitur.","glosses":["gegenwärtig, zugegen","sich einander berühren","Gegenwart","Berührung","abwesend"],"marks":["*","**","***","****","*****"],"aaEnd":77},
 {"num":224,"section":"parsi-capii-secviiii","aa":77,"ed":null,"text":"Ens compositum (stricte et simpliciter dictum)@@1@@ est totum partium extra partes, ens non compositum simplex (simpliciter et rigorose dictum)@@2@@ est. Ens compositum latius dictum@@3@@ est quicquid partes habet, et simplex comparative@@4@@ minus compositum.","glosses":["ein zusammengesetztes Ding in enger Bedeutung","einfach in genauer Bedeutung","zusammengesetzt in weiterer Bedeutung","einfach in Vergleichung"],"marks":["*","**","***","****"]},
 {"num":225,"section":"parsi-capii-secviiii","aa":77,"ed":68,"text":"Partes compositorum vel singulae et simul sumptae sunt accidentia, vel aliquae compositorum partes sunt substantiae, §. 10, 191. Si prius est, ens compositum est accidens, §. 224, 155. Posterius est ens compositum strictius dictum (reale)@@1@@.","glosses":["ein zusammengesetztes Ding in engerer Bedeutung"],"marks":["*"]},
 {"num":226,"section":"parsi-capii-secviiii","aa":77,"ed":null,"text":"Pone extra se invicem posita nullo modo totum constituere, seu componi@@1@@, posse: compositum erit intrinsecus impossibile, §. 224, 15. Modus ergo compositionis est internae impossibilitatis oppositum in compositis, §. 81, i.e. interna possibilitas et compositorum essentia, §. 40.","glosses":["zusammengesetzt werden"],"marks":["*"]},
 {"num":227,"section":"parsi-capii-secviiii","aa":77,"ed":null,"text":"Ortus@@1@@ est mutatio ex non exsistente in exsistens. Mutatio ex exsistenti in non exsistens est interitus@@2@@. Hinc entis necessarii et substantiae necessariae ortus et interitus est absolute impossibilis, §. 132, 202.","glosses":["das Entstehn","der Untergang"],"marks":["*","**"]},
 {"num":228,"section":"parsi-capii-secviiii","aa":77,"ed":69,"text":"Ortus ex nihilo@@1@@ est ortus eius, cuius nulla pars ipsi praeexsistit, et annihilatio@@2@@ interitus eius, cuius nulla pars exsistit superstes. Entis et substantiae necessariae ortus ex nihilo et annihilatio est absolute impossibilis, §. 227.","glosses":["das aus nichts entstehn","Vernichtung"],"marks":["*","**"]},
 {"num":229,"section":"parsi-capii-secviiii","aa":77,"ed":null,"text":"Ortus et ortus ex nihilo, interitus et annihilatio non possunt exsistere, nisi in substantiis, §. 227, 228, quia sunt accidentia, §. 210, sed non in necessaria, §. 227, 228. Ergo in contingentibus, §. 202.","glosses":[],"marks":[],"aaEnd":78},
 {"num":230,"section":"parsi-capii-secx","aa":78,"ed":null,"text":"Substantia vel est simplex, vel composita, §. 224. Prior monas (atomus, perfecta unitas) dicitur.","glosses":[],"marks":[]},
 {"num":231,"section":"parsi-capii-secx","aa":78,"ed":null,"text":"Substantiae compositae pars omnis est vel substantiale vel accidens. Accidentia non sunt extra substantiale, §. 196. Ergo substantiae compositae substantialia sunt extra se posita, §. 124.","glosses":[],"marks":[]},
 {"num":232,"section":"parsi-capii-secx","aa":78,"ed":70,"text":"Substantia composita habet vires, hinc substantias extra se positas pro partibus, §. 231, 198, hinc est ens compositum strictius dictum, §. 225.","glosses":[],"marks":[]},
 {"num":233,"section":"parsi-capii-secx","aa":78,"ed":null,"text":"Substantia composita non potest exsistere, nisi ut complexus substantiarum aliarum extra se invicem positarum, §. 232, 155, certoque modo compositarum, §. 226. Ergo non potest exsistere, nisi ut determinatio aliorum, §. 36, 38. Ergo est accidens, §. 191, et, si videtur per se subsistere, ipsique vis tribuitur, est phaenomenon substantiatum, §. 193, 201.","glosses":[],"marks":[]},
 {"num":234,"section":"parsi-capii-secx","aa":78,"ed":null,"text":"Omnis substantia monas est, §. 233, 230, ens compositum strictius dictum non est monas, §. 225. Ergo phaenomenon substantiatum, §. 193, 201.","glosses":[],"marks":[]},
 {"num":235,"section":"parsi-capii-secx","aa":78,"ed":null,"text":"Compositum strictius dictum monadibus constat, §. 225, 234.","glosses":[],"marks":[],"aaEnd":79},
 {"num":236,"section":"parsi-capii-secx","aa":79,"ed":71,"text":"Monas non oriri potest, nisi ex nihilo. Partes enim eius sunt substantiale et accidentia ipsi inhaerentia, §. 196. Substantiale non praeexsistit substantiae; eo enim exsistente exsistit vis, hinc substantia, §. 198. Accidentium nullum praeexsistit suae substantiae, §. 194. Ergo oriundae monados nulla pars praeexsistit, hinc non oriri potest, nisi ex nihilo, §. 228.","glosses":[],"marks":[]},
 {"num":237,"section":"parsi-capii-secx","aa":79,"ed":null,"text":"Substantiali superstite, nondum interiit substantia, §. 198, accidens vero nullum suae substantiae superstes est, §. 194. Ergo monas non potest interire, nisi per annihilationem, §. 228, 196.","glosses":[],"marks":[]},
 {"num":238,"section":"parsi-capii-secx","aa":79,"ed":null,"text":"Coniuncta iuxta se posita sunt simultanea@@1@@, post se posita successiva@@2@@. Totum simultaneorum est ens simultaneum, successivorum ens successivum.","glosses":["neben einander seiende","aufeinanderfolgende"],"marks":["*","**"]},
 {"num":239,"section":"parsi-capii-secx","aa":79,"ed":null,"text":"Ordo simultaneorum extra se invicem positorum est spatium@@1@@, successivorum tempus@@2@@.","glosses":["Raum","Zeit"],"marks":["*","**"]},
 {"num":240,"section":"parsi-capii-secx","aa":79,"ed":72,"text":"Positis simultaneis extra se, ponitur spatium. Posito spatio extra se invicem ponuntur simultanea. Positis successivis, ponitur tempus, et posito tempore ponuntur diversa, §. 74, sibi succedentia, §. 239, 78.","glosses":[],"marks":[]},
 {"num":241,"section":"parsi-capii-secx","aa":79,"ed":null,"text":"In quo spatium est, extensum@@1@@ est, et spatium vel locum replere (esse in spatio, vel loco, repletive scilicet) dicitur. Iam in omni composito stricte dicto spatium est, §. 240, 224. Ergo omne compositum stricte dictum extensum est et spatium replet. Omne extensum habet partes extra partes simultaneas, §. 240, hinc compositum est, §. 224.","glosses":["ausgedehnt"],"marks":["*"]},
 {"num":242,"section":"parsi-capii-secx","aa":79,"ed":null,"text":"Monas non extensa est, nec spatium replet, §. 241, 230. At totum monadum, §. 235, est extensum, §. 241.","glosses":[],"marks":[]},
 {"num":243,"section":"parsi-capii-secx","aa":79,"ed":null,"text":"Omne compositum habet magnitudinem, §. 159, 224. Magnitudo compositi stricte et strictius dicti est quantitativa@@1@@. Hinc monas non habet magnitudinem quantitativam, §. 230.","glosses":["ausgedehnte Grösse"],"marks":["*"]},
 {"num":244,"section":"parsi-capii-secx","aa":79,"ed":73,"text":"Divisio physica@@1@@ est imminutio magnitudinis quantitativae. Sicut individui impossibilis est divisio logica, §. 148, ita indivisibile@@2@@ est, cuius impossibilis est divisio physica. Ergo indivisibilitas est vel absoluta vel hypothetica, §. 15, 17. Nullum absolute indivisibile est hypothetice divisibile. Quoddam absolute divisibile est hypothetice indivisibile, §. 18. Hinc monas est indivisibilis, §. 243, et quidem per se, §. 15.","glosses":["Zerlegung, Theilung","untheilbar"],"marks":["*","**"],"aaEnd":80},
 {"num":245,"section":"parsi-capii-secx","aa":80,"ed":null,"text":"Composita non possunt exsistere, nisi ut determinationes aliorum, §. 225, 233. Iam non sunt alia, praeter composita, quam simplicia, §. 224, 38. Ergo exsistente composito exsistunt monades, §. 230, 233.","glosses":[],"marks":[]},
 {"num":246,"section":"parsi-capii-secxi","aa":80,"ed":null,"text":"Quantitas qualitatis est gradus@@1@@ (quantitas virtutis). Hinc gradum non nisi alio assumpto intelligere possumus, §. 69.","glosses":["eine Stufe, Staffel"],"marks":["*"]},
 {"num":247,"section":"parsi-capii-secxi","aa":80,"ed":74,"text":"Gradus infimus seu minimus est, quo minor impossibilis, quo maior impossibilis, maximus est, §. 246, 161. Gradus maiores sunt plurium minimorum tota, §. 155, 160. Hinc ab affirmato gradu maiore ad affirmandum minorem, a negato gradu minore ad negandum gradum maiorem valet consequentia, §. 157. In quovis gradu maiore est multitudo graduum, quae intensio@@1@@ dicitur, §. 159. Haec si augetur, qualitas, cuius gradus est, intenditur@@2@@, si minuitur, qualitas, cuius gradus est, remittitur@@3@@.","glosses":["das höhere","zunehmen, stärker, angestrengt","schwächer werden, nachlassen, abnehmen"],"marks":["*","**","***"]},
 {"num":248,"section":"parsi-capii-secxi","aa":80,"ed":75,"text":"Ens reale esse est qualitas, §. 69, omni enti conveniens, §. 136. Cumque in omni ente sit certus realitatum numerus, §. 136, 159, omne ens habet certum realitatis gradum, §. 246, 159. Hinc vel erit maximus, vel non maximus, §. 10, 247. Cumque gradus realitatis, quo maior possibilis est, seu non maximus, §. 247, limes@@1@@ (terminus, cf. §. 350, finis, cf. §. 341) dicatur, limitem autem habens finitum@@2@@ (cf. §. 341, limitatum), non habens limitem infinitum@@3@@ (reale, illimitatum) erit. Ens ergo gradum realitatis maximum habens s. realissimum, §. 190, est infinitum, finita reliqua omnia. Finitum, cuius limites determinare vel non possumus, vel non placet, est indefinitum@@4@@ (infinitum imaginarium, mathematice tale).","glosses":["der Schranken","endlich, eingeschränkt","uneingeschränkt","mathematisch unendlich, unendlichscheinend"],"marks":["*","**","***","****"],"aaEnd":81},
 {"num":249,"section":"parsi-capii-secxi","aa":81,"ed":null,"text":"Finita habent limitem, hinc gradum, §. 248, ergo quantitatem, §. 246, hinc omnium finitorum possibilis est cognitio philosophica et mathematica, §. 93, 22. limes dati finiti, citra quem plus ultra in eodem per eius essentiam impossibile est, est essentialis@@1@@. Mathesis non extensorum intensorum@@2@@ est, §. 247.","glosses":["der wesentliche Schranken","Wissenschaft unausgedehnter Grössen"],"marks":["*","**"]},
 {"num":250,"section":"parsi-capii-secxi","aa":81,"ed":null,"text":"In omni finito quaedam realitas tollenda est, §. 248, 247. Ergo quaedam ponenda negatio, §. 135, 81, adeoque imperfectio, §. 142, tam essentialis, quam accidentalis, §. 143, hinc absolute necessaria, §. 107, negatio, §. 36, stricte dicta, §. 137, malum metaphysicum, §. 146.","glosses":[],"marks":[]},
 {"num":251,"section":"parsi-capii-secxi","aa":81,"ed":76,"text":"Infiniti gradus realitatis maximus est absolute necessarius, §. 248, 102, hinc absolute immutabilis, §. 130.","glosses":[],"marks":[]},
 {"num":252,"section":"parsi-capii-secxi","aa":81,"ed":null,"text":"Si ens infinitum esset interne mutabile, determinationes, quae aliis succederent, mutarent realitatis gradum, §. 246, 125. At hic interne immutabilis est, §. 251. Ergo ens infinitum est interne immutabile.","glosses":[],"marks":[]},
 {"num":253,"section":"parsi-capii-secxi","aa":81,"ed":null,"text":"Interne immutabile est, qua determinationes internas, actu quicquid esse potest, §. 125. Ergo ens infinitum, qua determinationes internas, est actu, quicquid esse potest, §. 252.","glosses":[],"marks":[],"aaEnd":82},
 {"num":254,"section":"parsi-capii-secxi","aa":82,"ed":null,"text":"Quod non est actu, qua determinationes internas, quicquid esse potest, est ens finitum, §. 253, 248.","glosses":[],"marks":[]},
 {"num":255,"section":"parsi-capii-secxi","aa":82,"ed":null,"text":"Interne mutabile est ens finitum, §. 252, 126. Ergo omne ens contingens est finitum, §. 133, licet esse possit multis rationibus indefinitum et mathematice infinitum, §. 248.","glosses":[],"marks":[]},
 {"num":256,"section":"parsi-capii-secxi","aa":82,"ed":null,"text":"Ens infinitum est ens necessarium, §. 255, 109.","glosses":[],"marks":[]},
 {"num":257,"section":"parsi-capii-secxi","aa":82,"ed":77,"text":"Quod habet gradum realitatis, quo maior possibilis est, eius qualitas quaedam, §. 248, hinc interna determinatio intendi potest, §. 247, 69, hinc mutari, §. 247, 162. Ergo ens finitum est interne mutabile, §. 248, 126, hinc non est ens necessarium, §. 132, eius exsistentia modus est, §. 134, et ipsum ens contingens, §. 109.","glosses":[],"marks":[]},
 {"num":258,"section":"parsi-capii-secxi","aa":82,"ed":null,"text":"Ens necessarium est infinitum, §. 257, 248.","glosses":[],"marks":[]},
 {"num":259,"section":"parsi-capii-secxi","aa":82,"ed":null,"text":"Quod est actu, qua determinationes internas, quicquid esse potest, est ens necessarium, §. 132, ergo infinitum, §. 258. Hinc definiri potest ens infinitum per ens, quod actu est, qua determinationes internas, quicquid esse potest, §. 253.","glosses":[],"marks":[]},
 {"num":260,"section":"parsi-capii-secxi","aa":82,"ed":78,"text":"Ens contingens non est actu, qua determinationes internas, quicquid esse potest, §. 133. Ens finitum est ens contingens, §. 257. Ergo ens finitum definiri potest per ens, quod non est actu, qua determinationes internas, quicquid esse potest, §. 254. Quod et hinc patet, quia contradictorie oppositorum uno definito affirmative, alterum iisdem notis, sed negativis, definiri potest, §. 81, 248.","glosses":[],"marks":[]},
 {"num":261,"section":"parsi-capii-secxi","aa":82,"ed":null,"text":"Infinitudo est realitas, §. 36, cuius ratio est gradus realitatis maximus, §. 248, 14, finitudo seu limitatio est negatio, §. 36, cuius ratio limes est, §. 248, 14.","glosses":[],"marks":[]},
 {"num":262,"section":"parsi-capii-secxi","aa":82,"ed":null,"text":"Modi et relationes entis vel sunt realitates, vel negationes, §. 36, hinc iis in ente finito mutatis mutatur limes eius, §. 248. Iam omnis mutatio entis finiti est mutatio modi aut relationis, §. 52, 132. Ergo omnis mutatio entis finiti est mutatio limitum eius, hinc et limitationis, §. 261, 30.","glosses":[],"marks":[]},
 {"num":263,"section":"parsi-capii-secxi","aa":82,"ed":null,"text":"Ens finitum habet modos, §. 257, 112. Hi vel realitates sunt, vel negationes, §. 36. Utrarumque oppositum est in ente finito absolute possibile, §. 108. Hinc privationes sunt in omni ente finito absolute possibiles, §. 137. Hinc et imperfectio et malum contingens, §. 144, 146 (physicum late dictum).","glosses":[],"marks":[],"aaEnd":83},
 {"num":264,"section":"parsi-capii-secxi","aa":83,"ed":79,"text":"Omne ens finitum partim malum, partim bonum est, §. 147, 137, et omni finito bonum malumque contingens est intrinsecus possibile, §. 147, 263.","glosses":[],"marks":[]},
 {"num":265,"section":"parsi-capiii-seci","aa":83,"ed":null,"text":"Similitudo minima est in duobus, in quibus unica minima qualitas est communis, §. 174, 70. Iam vero in omnibus entibus quaedam qualitates communes sunt, §. 8-100. Ergo omnia entia sibi sunt in aliquo gradu similia, §. 246. Est hinc in entibus similitudo quaedam adeoque identitas universalis, §. 70. Quo plures, quo maiores qualitates, quo pluribus sunt communes, hoc maior est similitudo, §. 174, 70. Aequalitas minima est in duobus, in quibus unica minima quantitas est communis, quo ergo plures, in quo pluribus, quo maiores quantitates communes sunt, hoc maior est aequalitas, §. 174, 70.","glosses":[],"marks":[]},
 {"num":266,"section":"parsi-capiii-seci","aa":83,"ed":80,"text":"Congruentia minima est similitudo et aequalitas minima, quoque illae simul maiores, hoc maior est congruentia, §. 265, 70. Identitas, similitudo, aequalitas, congruentia essentialium essentiales@@1@@, essentialium et attributorum necessariae@@2@@, modorum contingentes, affectionum accidentales@@3@@ vocantur.","glosses":["wesentliche","nothwendige","zufallige"],"marks":["*","**","***"]},
 {"num":267,"section":"parsi-capiii-seci","aa":83,"ed":null,"text":"Identitas et diversitas, qua singula praedicata, est totalis@@1@@, qua quaedam, partialis@@2@@. Ergo similitudo, aequalitas, congruentia, sunt vel totales, vel partiales, §. 70.","glosses":["völlig, gänzlich","zum Theil statt findend"],"marks":["*","**"],"aaEnd":84},
 {"num":268,"section":"parsi-capiii-seci","aa":84,"ed":null,"text":"Cum sit omnium entium similitudo partialis, §. 265, non sunt entia totaliter diversa, §. 267. Hanc propositionem dicamus principium negatae totalis dissimilitudinis et diversitatis.","glosses":[],"marks":[]},
 {"num":269,"section":"parsi-capiii-seci","aa":84,"ed":81,"text":"Identitas totalis singularium est numerica. Impossibilia sunt duo extra se singularia prorsus seu totaliter eadem. Cum enim ponantur duo, ponuntur multa, hinc partim eadem, partim diversa, §. 74. Ergo non sunt totaliter eadem, §. 267. Quae sunt totaliter eadem singularia, sunt eadem numero, nec partim eadem, partim diversa, §. 267. Hinc non sunt multa, nec duo, §. 74. Haec propositio dicitur principium (identitatis) indiscernibilium late sumptum, aut negatae totalis identitatis.","glosses":[],"marks":[],"aaEnd":85},
 {"num":270,"section":"parsi-capiii-seci","aa":85,"ed":null,"text":"Impossibilia sunt plura extra se actualia totaliter congruentia. Dum enim extra se invicem exsisterent, sua et propria cuilibet exsistentia conveniret, §. 86, ab exsistentia alterius diversa, §. 38, hinc aut attributum, aut modus, saltim unicus, §. 77, in altero esset, qui non esset in altero, §. 38, 55, adeoque aut qualitas, aut quantitas, §. 69, nec essent hinc ambo totaliter congruentia, §. 70, 267. Totaliter congruentia, qua omnia discrimina interna, sunt eadem, §. 267, 70, hinc exsistentia unius non est diversa ab exsistentia alterius, §. 70, ergo non exsistunt extra se invicem. Haec propositio sit principium negatae totalis congruentiae.","glosses":[],"marks":[]},
 {"num":271,"section":"parsi-capiii-seci","aa":85,"ed":82,"text":"Impossibilia sunt plura extra se invicem actualia totaliter similia. Aut enim essent etiam totaliter aequalia, aut minus. Si prius, essent totaliter congruentia, §. 70, 267, q.a., §. 270. Si non essent totaliter aequalia, esset in uno quantitas, quae non esset in altero, §. 70, 38. Haec haberet rationem sufficientem, §. 22. Hinc esset in totaliter similium uno qualitas, quae non esset in altero, §. 69, 14, q.a., §. 70, 267. Haec propositio est principium (identitatis) indiscernibilium stricte sumptum, aut negatae totalis similitudinis.","glosses":[],"marks":[]},
 {"num":272,"section":"parsi-capiii-seci","aa":85,"ed":null,"text":"Impossibilia sunt plura extra se invicem actualia totaliter aequalia. Aut enim erunt simul totaliter similia, aut partialiter tantum, §. 265. Si prius, essent totaliter congruentia, §. 70, 267, q.a., §. 270. Si partialiter tantum essent similia, esset qualitas in uno, quae non esset in altero, §. 267, 70, hinc in utroque non esset idem totaliter realitatis gradus, §. 248, adeoque quaedam quantitas unius non esset quantitas alterius, §. 246, ergo nec essent totaliter aequalia, §. 267, 70. Haec propositio sit principium negatae totalis aequalitatis.","glosses":[],"marks":[]},
 {"num":273,"section":"parsi-capiii-seci","aa":85,"ed":null,"text":"Omnia extra se invicem actualia sunt partialiter diversa, §. 268, discongruentia, §. 270, 70, dissimilia, §. 271, inaequalia, §. 272.","glosses":[],"marks":[]},
 {"num":274,"section":"parsi-capiii-seci","aa":85,"ed":83,"text":"Eadem A et C eidem tertio B, sunt eadem inter se. Quae enim sunt in B, sunt in A, §. 38. Quae sunt in C, sunt in B, §. 38. Ergo quae sunt in C, sunt in A. Hinc A et C sunt eadem, §. 38.","glosses":[],"marks":[]},
 {"num":275,"section":"parsi-capiii-seci","aa":85,"ed":null,"text":"Congruentia, similia, aequalia eidem tertio sunt congruentia, similia, aequalia inter se, §. 70, 274.","glosses":[],"marks":[]},
 {"num":276,"section":"parsi-capiii-seci","aa":85,"ed":null,"text":"Posita eadem, congruenti, simili, aequali ratione sufficiente, ponitur idem, congruens, simile, aequale rationatum, et vice versa, §. 38, 70.","glosses":[],"marks":[],"aaEnd":86},
 {"num":277,"section":"parsi-capiii-seci","aa":86,"ed":null,"text":"Posita eadem essentia, ponuntur eadem attributa, et vice versa, §. 276, 50.","glosses":[],"marks":[]},
 {"num":278,"section":"parsi-capiii-seci","aa":86,"ed":null,"text":"Posita diversa, discongruenti, dissimili, inaequali ratione sufficiente, ponitur diversum, dissimile, discongruens, inaequale rationatum, et vice versa, hinc posita diversa essentia, ponuntur diversa attributa, et vice versa, §. 277, 276.","glosses":[],"marks":[]},
 {"num":279,"section":"parsi-capiii-seci","aa":86,"ed":84,"text":"Identitas, diversitas, §. 38, congruentia, discongruentia, similitudo, dissimilitudo, aequalitas, inaequalitas, §. 70, extra se invicem actualium in nullo eorum repraesentabiles sunt, nisi spectetur in nexu cum iis, quae extra illud ponuntur, §. 14, hinc sunt relationes, §. 37. Inter quae ergo intercedit, ea sunt connexa, §. 14, 19. Iam intercedit inter singula extra se invicem actualia, §. 265-273. Ergo singula actualia sunt connexa, §. 47. Hinc in omnibus actualibus nexus, immo harmonia est universalis, §. 48, 167.","glosses":[],"marks":[]},
 {"num":280,"section":"parsi-capiii-secii","aa":86,"ed":null,"text":"Extensio cum sit qualitas compositi entis, qua spatium replet, §. 69, 241, et spatium possit esse maius et minus, §. 239, 175, in extenso possibilis est gradus extensionis, §. 246, i.e. figura. Hinc monas non admittit, at totum monadum admittit figuram, §. 242. Compositum extensionis maioris est spatiosum@@1@@, minoris angustum@@2@@.","glosses":["räumlich","eng"],"marks":["*","**"]},
 {"num":281,"section":"parsi-capiii-secii","aa":86,"ed":null,"text":"Positus simultanei extra alia actualis eius locus@@1@@ est, successivi positus est aetas@@2@@.","glosses":["Ort","Alter"],"marks":["*","**"],"aaEnd":87},
 {"num":282,"section":"parsi-capiii-secii","aa":87,"ed":85,"text":"Simultanei cuiuslibet locus ex coniunctione cum diversis extra illud actualibus determinatur, §. 85, 281. Hinc diversus est a loco coexsistentium, §. 38. Ergo simultanea sibi invicem extra se posita non sunt in eodem loco, §. 281. Successivi cuiuslibet aetas ex coniunctione eius cum actualibus ante et post illud positis determinatur, §. 85, 78, hinc diversa est ab eorum aetate, §. 38. Hinc successiva sibi invicem non possunt esse in eadem aetate.","glosses":[],"marks":[]},
 {"num":283,"section":"parsi-capiii-secii","aa":87,"ed":null,"text":"Mutatio loci motus@@1@@ est, hinc omnis motus est mutatio relationis, §. 281, 85, et minimus esset, si unici minimi unicus tantum positus erga unicum minimum extra ipsum actuale mutaretur, §. 161, hinc eo maior est, quo plures, quo plurium, quo maiorum positus erga quo plura, quo maiora extra mobilia mutantur. Quae non moventur, quiescunt@@2@@, et absentia motus quies@@3@@ est.","glosses":["Bewegung","ruhen","Ruhe"],"marks":["*","**","***"]},
 {"num":284,"section":"parsi-capiii-secii","aa":87,"ed":86,"text":"Coordinata se mutuo contingentia sunt contigua@@1@@, non contigua distant@@2@@. Locus inter se distantium situs@@3@@ est. Actio s. influxus immediatus et proximus in distans est impossibilis in et per se, §. 223, 15.","glosses":["zunächst an einander","von einander abstehend","Lage"],"marks":["*","**","***"],"aaEnd":88},
 {"num":285,"section":"parsi-capiii-secii","aa":88,"ed":null,"text":"Ens simultaneum et successivum partium contiguarum est continuum@@1@@, at ens simultaneum et successivum partium inter se distantium est interruptum@@2@@.","glosses":["stetig, ununterbrochen, in einem fortgehend","unterbrochen"],"marks":["*","**"]},
 {"num":286,"section":"parsi-capiii-secii","aa":88,"ed":null,"text":"Partes extensi extra se positae vel simplices sunt, vel compositae, §. 224. Priores quatenus extensae non sunt, §. 242, puncta vocantur. Series punctorum punctis distantibus interpositorum continua est linea.","glosses":[],"marks":[]},
 {"num":287,"section":"parsi-capiii-secii","aa":88,"ed":null,"text":"Extensio lineae ex numero punctorum, quibus constat, determinatur, §. 241, 286, et in qua datis distantibus paucissima interponuntur, est haec linea inter ista brevissima@@1@@. Linea inter data puncta brevissima est recta@@2@@, non recta, curva@@3@@ est.","glosses":["die kürzeste","grade","krumm"],"marks":["*","**","***"]},
 {"num":288,"section":"parsi-capiii-secii","aa":88,"ed":87,"text":"Linea recta inter distantia est eorum distantia@@1@@, quoque haec maior est, hoc magis distantia inter se distant, §. 287, 284. Quod si maior fuerit distantia, distantia sunt remotiora@@2@@, si minor, propiora@@3@@.","glosses":["Entfernung","entfernter","näher"],"marks":["*","**","***"]},
 {"num":289,"section":"parsi-capiii-secii","aa":88,"ed":null,"text":"Series linearum lineis distantibus interpositarum continua est superficies@@1@@. Extensio superficiei ex numero linearum, quibus constat, determinatur, §. 241, 175, eaque inter datas lineas distantes brevissima, est superficies plana@@2@@, non plana curva@@3@@ est (gibba). Series superficierum superficiebus distantibus interpositarum continua est mathematice solidum@@4@@ (corpus, cf. §. 296, mathematicum).","glosses":["Fläche","ebene","gebogene","das der dreifachen Ausmessung fähige"],"marks":["*","**","***","****"],"aaEnd":89},
 {"num":290,"section":"parsi-capiii-secii","aa":89,"ed":88,"text":"Extensio in linea sola possibilis est longitudo@@1@@, quae ad longitudinem accedit in superficie est latitudo@@2@@, quae ad extensionem superficierum in mathematice solidis accedit, est (altitudo) seu profunditas@@3@@.","glosses":["Länge","Breite","Dicke, Höhe, Tiefe"],"marks":["*","**","***"],"aaEnd":90},
 {"num":291,"section":"parsi-capiii-secii","aa":90,"ed":null,"text":"Si ex quantitate pro una assumpta aliam homogeneam, seu similem, intelligimus, hanc mensuratam@@1@@ ex illa mensura@@2@@ metimur@@3@@, et ipsa haec actio dicitur dimensio@@4@@.","glosses":["das gemessene","das Maass","messen","Ausmessung"],"marks":["*","**","***","****"]},
 {"num":292,"section":"parsi-capiii-secii","aa":90,"ed":null,"text":"Linea tantum admittit extensionis unicam dimensionem, §. 291, 287, superficies duplicem, §. 291, 289, mathematice solidum triplicem, §. 280, 246.","glosses":[],"marks":[],"aaEnd":91},
 {"num":293,"section":"parsi-capiii-secii","aa":91,"ed":null,"text":"Spatii partes cum sint in simultaneis extra se positis, §. 239, 155, sunt simultaneae, et spatium adeo est ens simultaneum, §. 238.","glosses":[],"marks":[]},
 {"num":294,"section":"parsi-capiii-secii","aa":91,"ed":89,"text":"Motus cum sit accidens, §. 283, non exsistere potest, nisi in substantiis, et quidem posita vi, §. 210, quae vis motrix@@1@@ dicitur. Cumque quies sit impedimentum motus, §. 221, 283, posita quiete ponitur vis motui resistens, §. 222, quae vis inertiae@@2@@ (antitypia, ignavia, vis insita) vocatur.","glosses":["bewegende Kraft","Kraft der Trägheit, widerstehende Kraft"],"marks":["*","**"],"aaEnd":92},
 {"num":295,"section":"parsi-capiii-secii","aa":92,"ed":null,"text":"Extensum, cui vis inertiae tribuitur, est materia, cf. §. 344, et phaenomenon substantiatum, §. 234, 201. Materia, cui haec sola vis tribuitur, est prima, cf. §. 423 (mere passiva).","glosses":[],"marks":[]},
 {"num":296,"section":"parsi-capiii-secii","aa":92,"ed":null,"text":"Materia, cui vis motrix tribuitur, est corpus physicum (cf. §. 289, materia secunda, cf. §. 295) et phaenomenon substantiatum, §. 295, 201.","glosses":[],"marks":[]},
 {"num":297,"section":"parsi-capiii-seciii","aa":92,"ed":null,"text":"Tempus cogitationis de ipso simultaneum praesens@@1@@ est, cui praesens succedit, praeteritum@@2@@, praesentis successivum futurum@@3@@.","glosses":["die gegenwärtige","vergangene","zukünftige Zeit"],"marks":["*","**","***"]},
 {"num":298,"section":"parsi-capiii-seciii","aa":92,"ed":90,"text":"Actualia temporis praesentis sunt exsistentia@@1@@ (tempore praesentia, entia actu). Actualia temporis praeteriti, si non sint simul entia actu, s. si non amplius exsistant, sunt praeterita@@2@@ (res facti). Actualia temporis futuri sunt futura@@3@@, eaque, si non sint simul entia actu, sunt entia in potentia@@4@@.","glosses":["das jetzt daseiende","das vergangene","das zukünftige","das noch werden soll"],"marks":["*","**","***","****"]},
 {"num":299,"section":"parsi-capiii-seciii","aa":92,"ed":null,"text":"Exsistentiae continuatio est duratio@@1@@. In quo possibilis est duratio, perdurabile@@2@@ dicitur. Actuale vero non perdurabile instantaneum@@3@@ (momentaneum). Perdurabile durationis maioris est diuturnum@@4@@ (stabile, constans, perpetuum, aeternum), minoris est breve@@5@@ (fluxum, transitorium, inconstans).","glosses":["die Dauer","einer Dauer fähig","keiner Dauer fähig","dauerhaft","von kurzer Dauer"],"marks":["*","**","***","****","*****"],"aaEnd":93},
 {"num":300,"section":"parsi-capiii-seciii","aa":93,"ed":91,"text":"Tempus momentanei simultaneum instans (momentum) dicitur@@1@@. Successivum aliorum posterius@@2@@, cuius alia successiva sunt, prius@@3@@, omnibus prius, primum@@4@@, omnibus posterius, postremum@@5@@ est.","glosses":["ein Augenblick","das spätere","das frühere","das erste","das letzte der Zeit nach"],"marks":["*","**","***","****","*****"]},
 {"num":301,"section":"parsi-capiii-seciii","aa":93,"ed":null,"text":"Mutatio entis in praesens est initium@@1@@, in praeteritum finis@@2@@. Unitio est unionis initium, §. 79, 205, initium contactus ictus@@3@@ est.","glosses":["Anfang","Ende","Stoss"],"marks":["*","**","***"]},
 {"num":302,"section":"parsi-capiii-seciii","aa":93,"ed":null,"text":"Aeternitas@@1@@ (rigorose dicta, cf. §. 299) est duratio sine initio et fine. Duratio sine fine tantum est aeviternitas@@2@@, et omni tempori simultanea sempiternitas@@3@@.","glosses":["die Ewigkeit","das nur ohne Ende","das zu aller Zeit sein"],"marks":["*","**","***"]},
 {"num":303,"section":"parsi-capiii-seciii","aa":93,"ed":null,"text":"Exsistentiam continuans sine initio est simultaneum omni praeterito tempori et praesenti, §. 301, 297, eandem continuaturum sine fine erit simultaneum omni futuro tempori, §. 301, 297. Ergo omne aeternum sempiternum est, §. 302.","glosses":[],"marks":[]},
 {"num":304,"section":"parsi-capiii-seciii","aa":93,"ed":92,"text":"Ens in potentia vel rationem exsistentiae sufficientem proximam habet in entibus actu, vel minus, §. 27, 10. Prius est ens in potentia proxima@@1@@, posterius ens in potentia remota@@2@@.","glosses":["das sogleich","das einmal werden soll"],"marks":["*","**"]},
 {"num":305,"section":"parsi-capiii-seciii","aa":93,"ed":null,"text":"Ens actu, dum durat, non potest non durare, §. 9, 7, hinc exsistit necessario, §. 299, 101, s. quicquid est, dum est, est necessario.","glosses":[],"marks":[]},
 {"num":306,"section":"parsi-capiii-seciii","aa":93,"ed":null,"text":"Quae locum et aetatem sibi mutuo determinant, sunt connexa, §. 281, 85. Hinc simultanea connexa sunt, qua spatium, successiva, qua tempus, §. 238, 239. Iam vero singula actualia extra se invicem posita sunt vel simultanea, vel successiva, §. 238, 298. Ergo inter singula actualia intercedit nexus et harmonia universalis, §. 48, 167.","glosses":[],"marks":[],"aaEnd":94},
 {"num":307,"section":"parsi-capiii-seciiii","aa":94,"ed":93,"text":"Quod continet rationem alterius, eius est principium@@1@@. Dependens a principio principiatum@@2@@ est. Principium exsistentiae est causa@@3@@, principiatum causae causatum@@4@@. Quod non potest exsistere, nisi ut causatum alterius extra se positi, est ens ab alio@@5@@ (dependens), quod potest etiam exsistere, licet non sit causatum alterius extra se positi, est ens a se@@6@@ (independens).","glosses":["die Quelle","das abgeleitete","die Ursach","das verursachte","abhängend","selbstständig"],"marks":["*","**","***","****","*****","******"]},
 {"num":308,"section":"parsi-capiii-seciiii","aa":94,"ed":null,"text":"Entis contingentis, hinc et finiti, exsistentia modus est, §. 134, 257. Hinc non sufficienter determinatur per entis contingentis et finiti essentiam, §. 65. Ergo nec per eius attributa, §. 64, 25. Ergo in internis entis contingentis et finiti determinationibus non est eius exsistentiae ratio sufficiens, §. 52. At necessaria est tamen enti contingenti et finito ad exsistendum, §. 22, 101. Ergo extra ens contingens et finitum ratio exsistentiae eius sufficiens ut sit, necesse est, quam quae continent cum causae sint, §. 307, ens finitum et contingens non potest exsistere, nisi ut causatum extra se positi, i.e. est ens ab alio, §. 307.","glosses":[],"marks":[]},
 {"num":309,"section":"parsi-capiii-seciiii","aa":94,"ed":94,"text":"Ens a se non est contingens, nec finitum, §. 308, 307, hinc necessarium, §. 109, et infinitum, §. 258.","glosses":[],"marks":[]},
 {"num":310,"section":"parsi-capiii-seciiii","aa":94,"ed":null,"text":"Ens necessarium et infinitum, §. 258, potest exsistere, licet non sit causatum alterius extra se positi, §. 109, 102, ergo est ens a se et independens, §. 307.","glosses":[],"marks":[]},
 {"num":311,"section":"parsi-capiii-seciiii","aa":94,"ed":null,"text":"Principium possibilitatis principium essendi@@1@@ (compositionis), causa principium fiendi@@2@@ (generationis), principium cognitionis principium cognoscendi@@3@@ dicitur, idque si nec plura, nec pauciora inde cognosci possunt, quam datum principiatum, illi principiato adaequatum@@4@@ dicitur. Essentia est principium essendi et cognoscendi modorum, §. 65, 50.","glosses":["Quelle der Möglichkeit","Quelle der Wirklichkeit","Erkenntniss-Quelle","hinlänglich-eigen"],"marks":["*","**","***","****"],"aaEnd":95},
 {"num":312,"section":"parsi-capiii-seciiii","aa":95,"ed":null,"text":"Relatorum principium terminus relationis@@1@@, dependens vero subiectum relationis@@2@@ dicitur. Quorumque potest unum alterius fieri terminus relationis, sunt correlata@@3@@.","glosses":["der Grund","der Gegenstand der Verhältniss","beziehen sich wechselweise auf einander"],"marks":["*","**","***"]},
 {"num":313,"section":"parsi-capiii-seciiii","aa":95,"ed":95,"text":"Inter causam et causatum nexus est, §. 307, 14, qui causalis@@1@@ dicitur, et, quatenus causae tribuitur, causalitas@@2@@, quatenus causato, dependentia@@3@@.","glosses":["Zusammenhang der Ursachen","das Verursachen","verursacht sein, oder werden, die Abhänglichkeit"],"marks":["*","**","***"]},
 {"num":314,"section":"parsi-capiii-seciiii","aa":95,"ed":null,"text":"Causae plures unius eiusdemque causati sunt concausae@@1@@, et ad causatum concurrere@@2@@ dicuntur. Causa, quae non habet concausam, est solitaria@@3@@. Concausarum ea, quae maximam rationem causati inter reliquas continet, est principalis (primaria)@@4@@. Concausae causae principalis sunt (minus principales) secundariae@@5@@. Omnes concausae connectuntur inter se, §. 313, 33.","glosses":["Mitursachen","zusammenkommen","die einzige Ursach","die Haupt-Ursach","Neben-Ursachen"],"marks":["*","**","***","****","*****"]},
 {"num":315,"section":"parsi-capiii-seciiii","aa":95,"ed":96,"text":"Concausarum una vel est causa alterius, vel minus, §. 10. In casu priore concausae sunt subordinatae@@1@@, in posteriori coordinatae@@2@@. Subordinatarum omnium causa prima@@3@@, reliquae secundae@@4@@ sunt.","glosses":["unter einander","bei und neben einander geordnete Ursachen","die erste","Unter-Ursachen"],"marks":["*","**","***","****"]},
 {"num":316,"section":"parsi-capiii-seciiii","aa":95,"ed":null,"text":"In concausis subordinatis aut in causa propiori idem dependebit a causa ulteriori, a quo causatum propioris pendet, aut aliud quid, §. 315, 27. Si prius, concausae subordinantur essentialiter@@1@@, si posterius, accidentaliter@@2@@.","glosses":["so sind die Mitursachen in einerlei","in verschiedenen Stücken untereinander geordnet"],"marks":["*","**"],"aaEnd":96},
 {"num":317,"section":"parsi-capiii-seciiii","aa":96,"ed":null,"text":"Causa causae essentialiter sibi subordinatae est etiam causa causati, §. 316, 25.","glosses":[],"marks":[]},
 {"num":318,"section":"parsi-capiii-seciiii","aa":96,"ed":null,"text":"Causa vel est sufficiens vel insufficiens, §. 307, 21, et ista vel secundum quid, vel simpliciter talis, §. 28. Causa vel est mediata, a qua datum causatum per aliam dependet, vel immediata, a qua datum causatum, sed non per aliam, dependet, §. 27.","glosses":[],"marks":[],"aaEnd":97},
 {"num":319,"section":"parsi-capiii-secv","aa":97,"ed":null,"text":"Causa realitatis per actionem est efficiens@@1@@, negationis vero deficiens@@2@@. Causa tam efficiens, quam deficiens agunt, hinc sunt substantiae, §. 210, adeoque accidentia spectata, ut causae efficientes, sunt phaenomena substantiata, §. 201, 200. Causae efficientis deficientisve causata sunt effectus@@3@@.","glosses":["eine wirkende","fehlende Ursach","Wirkung"],"marks":["*","**","***"]},
 {"num":320,"section":"parsi-capiii-secv","aa":97,"ed":null,"text":"Causa efficiens et deficiens vel est mediata, quae per aliam causam efficientem deficientemve, vel immediata, quae effectum, sed non per aliam causam efficientem deficientemve, actuat. Causa efficiens et deficiens alteri efficienti et deficienti coordinata eius socia@@1@@ dicitur, et si altera sive socia una ad datum effectum insufficiens fuerit, socia altera vocatur auxiliaris@@2@@.","glosses":["vergesellschaftete Ursachen","eine helfende Ursach"],"marks":["*","**"]},
 {"num":321,"section":"parsi-capiii-secv","aa":97,"ed":98,"text":"Auxilium@@1@@ est complementum ad effectum causae sociae insufficientis. Causam auxiliarem esse est iuvare@@2@@. Ergo iuvans non est causa solitaria, §. 320, et causa solitaria non iuvat, §. 314.","glosses":["Hülfe","helfen"],"marks":["*","**"]},
 {"num":322,"section":"parsi-capiii-secv","aa":97,"ed":null,"text":"Causa efficiens deficiensve minus principalis efficienti deficientive subordinata instrumentalis@@1@@ (administra, et ministerialis) est.","glosses":["ein Werkzeug"],"marks":["*"]},
 {"num":323,"section":"parsi-capiii-secv","aa":97,"ed":99,"text":"Actio singularis cum effectu suo eventus@@1@@ dicitur. Relatio eventus est circumstantia@@2@@. Complexus relationum ad eventum concurrentium occasio@@3@@, eiusque causa causa occasionalis est@@4@@. Paucissimarum minimarum circumstantiarum minimus ad eventum datum consensus est occasio minima, §. 161. Quo plures, quo maiores circumstantiae, quo magis ad eum consentiunt, hoc maior est occasio, §. 160, donec sit maxima plurimarum maximarum circumstantiarum ad datum eventum consensus maximus, §. 161. Occasio maior respectu loci opportunitas, eiusque oppositum inopportunitas, respectu temporis tempestivitas, eiusque oppositum intempestivitas est@@5@@.","glosses":["ein Vorfall, eine Begebenheit","ein Umstand","die Gelegenheit","eine gelegentliche Ursach","bequemre und unbequemre Zeiten und Orte"],"marks":["*","**","***","****","*****"]},
 {"num":324,"section":"parsi-capiii-secv","aa":97,"ed":null,"text":"Si minima circumstantia sit in eventu A, quae non est in eventu B, eventus A et B non sunt totaliter iidem, §. 267, 323, hinc partialiter diversi, §. 267, i.e. minima circumstantia variat rem externe.","glosses":[],"marks":[]},
 {"num":325,"section":"parsi-capiii-secv","aa":97,"ed":null,"text":"Sint eventus A et B interne in aliquo gradu iidem, et spectentur in diversissimis circumstantiis, diversitas inde pendens non est, nisi in relationibus, §. 323, hinc externa, §. 37. Ergo interna eventuum identitas diversitate circumstantiarum, loci, aetatis, §. 281, 85, e.c. nec augetur, nec minuitur, §. 162, i.e. Locus et tempus non variant rem interne.","glosses":[],"marks":[]},
 {"num":326,"section":"parsi-capiii-secv","aa":97,"ed":null,"text":"Posito principio, ponitur principiatum, §. 307, 30. Posita causa, ponitur causatum, §. 311. Posita causa efficiente et deficiente, ponitur effectus, §. 319, posita causa occasionali, ponitur occasio, §. 323, et v.v., §. 29.","glosses":[],"marks":[],"aaEnd":98},
 {"num":327,"section":"parsi-capiii-secv","aa":98,"ed":100,"text":"Posito eodem, simili, aequali, congruenti principio, hinc causis, §. 307, efficientibus, deficientibus, §. 319, occasionalibus, §. 323, ponuntur eadem, similia, aequalia, congruentia principiata, §. 276, 307, causata, effectus, occasiones, et v.v.","glosses":[],"marks":[]},
 {"num":328,"section":"parsi-capiii-secv","aa":98,"ed":null,"text":"Sublato principio, hinc causa, §. 307, efficiente, deficiente, §. 319, et occasionali, §. 223, tollitur principiatum, causatum, effectus, occasio, §. 307, 31, et v.v., §. 32.","glosses":[],"marks":[]},
 {"num":329,"section":"parsi-capiii-secv","aa":98,"ed":null,"text":"Omnis effectus causae deficienti vel efficienti similis est, §. 265, i.e. qualis causa, talis effectus, §. 70. Effectus causae efficienti vel similis, qua differentiam utriusque specificam, vel minus, §. 10. Prior effectus univocus@@1@@, posterior aequivocus@@2@@ dicitur.","glosses":["eine Wirkung von einerlei","von verschiedener Art"],"marks":["*","**"]},
 {"num":330,"section":"parsi-capiii-secv","aa":98,"ed":101,"text":"Effectus in data actione rationem exsistentiae proximam habens est effectus eius immediatus@@1@@ (proximus, et continuus, cf. §. 285). Mediati@@2@@ (remoti) sunt, qui ulteriorem tantum rationem exsistentiae suae in data actione habent. Effectus actionis omnes in omni intensione sumpti sunt effectus plenus@@3@@. Minus plenus@@4@@ est vel quidam tantum, vel in minori gradu spectatus.","glosses":["unmittelbare","mittelbare","völlige","Wirkung, die nicht völlig ist"],"marks":["*","**","***","****"]},
 {"num":331,"section":"parsi-capiii-secv","aa":98,"ed":null,"text":"Effectus plenus tantus est, quanta actio, per quam actuatur, §. 330, 214, hinc actioni aequalis est, §. 70. Iam actio tanta, quanta vis viva, per quam actuatur, §. 220, 166, hinc actio viribus vivis, a quibus actuatur, aequalis est, §. 70. Ergo actio causae efficientis aequalis est viribus eius vivis, §. 319. Hinc effectus plenus aequalis (proportionatus) est viribus causae efficientis vivis, §. 275.","glosses":[],"marks":[]},
 {"num":332,"section":"parsi-capiii-secv","aa":98,"ed":null,"text":"Nobilitas seu dignitas alicuius effectus causae alicui efficienti essentialiter subordinandi ad huius effectum plenum pertinet, §. 330, 317, 166. Ergo effectus non est nobilior sua causa efficiente, cui essentialiter subordiantur, §. 331, 160.","glosses":[],"marks":[]},
 {"num":333,"section":"parsi-capiii-secv","aa":98,"ed":102,"text":"Ex effectu qualitates, §. 329, et quantitates, §. 331, hinc determinationes causae cognosci possunt, §. 70, 67. Ergo effectus est principium cognoscendi causam, §. 311, i.e. effectus testatur de causa.","glosses":[],"marks":[],"aaEnd":99},
 {"num":334,"section":"parsi-capiii-secv","aa":99,"ed":null,"text":"Omne ens contingens et finitum est ens ab alio, §. 308. Ergo exsistenti exsistentia non inhaeret per vim ipsi propriam, §. 307, hinc vis aliena extra finitum et contingens reale posita est ratio sufficiens inhaerentis enti finito et contingenti reali exsistentiae, §. 210. Ergo substantia extra ipsum posita in illud agit exsistentiam influendo, §. 211. Hinc omne ens contingens et finitum reale est effectus, §. 319, et habet causam efficientem, §. 326.","glosses":[],"marks":[]},
 {"num":335,"section":"parsi-capiii-secv","aa":99,"ed":null,"text":"Nexus causalis inter causam efficientem, deficientem et effectum effectivus dicitur@@1@@. Hinc causae sociae connectuntur nexu effectivo, §. 320, 314.","glosses":["Zusammenhang der Ursachen und Wirkungen"],"marks":["*"]},
 {"num":336,"section":"parsi-capiii-secvi","aa":99,"ed":103,"text":"Utile@@1@@ est alteri bonum, non bonum alteri inutile@@2@@, alteri malum noxium@@3@@ est. Hinc utilitas@@4@@ est bonitas respectiva, §. 37, quae si tribuitur rei, cui alterum prodesse potest, passiva@@5@@, si illi, quod prodesse potest, activa@@6@@ dici potest.","glosses":["nützlich, nutzbar","unnütz","schädlich","Nutzbarkeit","des, dem genutzt werden kann","die thätige Nutzbarkeit"],"marks":["*","**","***","****","*****","******"]},
 {"num":337,"section":"parsi-capiii-secvi","aa":99,"ed":null,"text":"Utilitas minima est, qua unicum minimum in altero unico minimo ponit unicam minimam perfectionem, §. 336, 161, hinc augetur, quo plura, quo maiora, in quo pluribus, quo maioribus, quo plures, quo maiores perfectiones ponunt §. 187. Gradus utilitatis valor@@1@@, et iudicium de valore pretium@@2@@ (aestimatio) dicitur. Hinc aestimatio cum pretio vel vera, vel apparens s. imaginaria est, §. 12.","glosses":["Werth","Preis, Achtung, Schätzung, Würdigung"],"marks":["*","**"],"aaEnd":100},
 {"num":338,"section":"parsi-capiii-secvi","aa":100,"ed":104,"text":"Usus@@1@@ est utilitatis actuatio. Abusus vel usus apparens@@2@@, vel usus, quo utile interit@@3@@. Cumque cognosci possit ex utili perfectio eius, cui prodest, §. 336, 100, utile et illud, cui prodesse potest, connexa sunt, eorumque nexus nexus utilitatis@@4@@ dici potest.","glosses":["der Gebrauch, Nutzen","Missbrauch","Verbrauch","Zusammenhang der Nutzbarkeiten"],"marks":["*","**","***","****"]},
 {"num":339,"section":"parsi-capiii-secvi","aa":100,"ed":null,"text":"Si quis utatur utili, actuatur per illud alterius perfectio, §. 338, 100, et utile per usum fit causa perfectionis illius, cui prodest, §. 307. Et hic nexus causalis dici potest nexus usuum@@1@@. Quo quis utitur, est illud utile, §. 336, 57, omnino inutili nemo utitur, §. 338, 58, quoddam tamen utile caret usu, §. 59, hinc aliquid, quo nemo utitur, nihilo minus est utile, §. 60.","glosses":["Zusammenhang der Nutzen"],"marks":["*"]},
 {"num":340,"section":"parsi-capiii-secvi","aa":100,"ed":null,"text":"Utilia uni eidemque rei cum ea connexa sunt, §. 339. Ergo omnia utilia ad unum connexa sunt inter se, §. 314. Utile A utili B essentialiter sibi subordinato, utile est et illi C, cui prodest B, §. 317.","glosses":[],"marks":[]},
 {"num":341,"section":"parsi-capiii-secvii","aa":100,"ed":null,"text":"Si quis utitur vel abutitur aliquo ad bonum sibi visum actuandum: ipsum bonum agenti visum finis@@1@@, cf. §. 248, causae finis, quibus ad finem uti vel abuti potest, media@@2@@ (destinata, finita, cf. §. 248, remedia), finisque repraesentatio intentio@@3@@ dicitur. Iam finis est principium usus vel abusus, §. 338, 307, hinc causa finalis, §. 338, 307.","glosses":["Zweck","Mittel","Absicht"],"marks":["*","**","***"]},
 {"num":342,"section":"parsi-capiii-secvii","aa":100,"ed":null,"text":"Intentionis rationes in intendente vocantur causae impulsivae@@1@@. Finis est effectus actionis et mediorum, quibus agens utitur vel abutitur, §. 341, 319. Hinc finis plenus est aequalis actioni et mediis. Media et actio sunt aequalia (proportionata) fini pleno, §. 331. Captatio occasionis, §. 323, et impedimentorum remotio, §. 221, sunt media, §. 341.","glosses":["Trieb oder bewegende Ursachen"],"marks":["*"],"aaEnd":101},
 {"num":343,"section":"parsi-capiii-secvii","aa":101,"ed":106,"text":"Nexus causalis mediorum et finium finalis@@1@@ est, omnes cofines connectuntur inter se, §. 314, 341. Finis finium essentialiter sibi subordinatorum est et finis mediorum, §. 317, 341. Finis primus, seu cui cofines omnes subordinantur, ultimus seu scopus@@2@@ dicitur, et hic est vel simpliciter ultimus, vel talis secundum quid in data finium subordinatione, §. 28, reliqui intermedii@@3@@.","glosses":["Zusammenhang der Mittel und Zwecke","Endzweck","Mittel-Zwecke"],"marks":["*","**","***"]},
 {"num":344,"section":"parsi-capiii-secvii","aa":101,"ed":null,"text":"Si ens concipitur, ut determinabile, materia, cf. §. 295, 296, ex qua@@1@@, in ipso determinationis actu materia circa quam (obiectum, subiectum occupationis)@@2@@, facta determinatione materia in qua, et haec cum materia ex qua subiectum vocatur.","glosses":["der Stoff, der Zeug","der Gegenstand"],"marks":["*","**"]},
 {"num":345,"section":"parsi-capiii-secvii","aa":101,"ed":107,"text":"Materia et forma cum actualis determinationis rationem contineant, §. 344, 40, causae sunt, §. 307. Illa materialis, haec formalis. Concausae materiales et formales sunt inter se connexae, §. 314, earumque nexus cum suis principiatis, §. 307, et inter se, §. 314, ille subiectivus dici potest, hic formalis (essentialis).","glosses":[],"marks":[]},
 {"num":346,"section":"parsi-capiii-secvii","aa":101,"ed":null,"text":"Exemplar@@1@@ est, cui simile intenditus, et causa impulsiva cum sit, §. 342, est causa, §. 307, quae exemplaris dicitur, eiusque causatum exemplatum@@2@@ (ectypon, copia) vocatur. Exemplar, quod non habet aliud, est archetypon@@3@@ (originale). Exemplar et exemplatum et coexemplaria connectuntur nexu causali. §. 313, qui nexus exemplaris est (typicus).","glosses":["das Muster","der Abdruck","das Urbild"],"marks":["*","**","***"],"aaEnd":102},
 {"num":347,"section":"parsi-capiii-secviii","aa":102,"ed":108,"text":"Medium cognoscendae alterius exsistentiae signum@@1@@ est, signi finis signatum@@2@@. Hinc signum est signati principium cognoscendi, §. 311, et nexus inter signum et signatum significativus@@3@@ est, signoque tributus significatus@@4@@ dicitur (vis, potestas).","glosses":["das Zeichen","das bezeichnete","der Zusammenhang der Zeichen","die Bedeutung"],"marks":["*","**","***","****"]},
 {"num":348,"section":"parsi-capiii-secviii","aa":102,"ed":null,"text":"Signatum actuale, §. 347, vel praesens est, tunc signum dicitur demonstrativum@@1@@; vel praeteritum, tunc signum dicitur mnemonicum@@2@@ (rememorativum, μνημοσυνον); vel futurum, §. 298, tunc signum dicitur prognosticon.","glosses":["ein Anzeigungs-Zeichen","ein Erinnerungs-Zeichen"],"marks":["*","*"]},
 {"num":349,"section":"parsi-capiii-secviii","aa":102,"ed":109,"text":"Scientia signorum est (semiotica, semiologia philosophica, symbolice) characteristica@@1@@, eaque, I. heuristica@@2@@, de inveniendis signis tam primitivis@@3@@, quae non habent signa pro partibus, quam derivativis@@4@@, quae ex signis sunt composita. Horum modus compositionis essentiae signati si sit similior, sunt ea essentialia@@5@@. Heuristica signorum derivativorum est combinatoria@@6@@, et II. hermeneutica@@7@@, de cognoscendis signorum signatis. Haec hermeneutica universalis est@@8@@. Characteristica prognosticorum est mantica@@9@@.","glosses":["die allgemeine Zeichen-Kunst","die erfindende","einfache","zusammen gesetzte Zeichen","wesentliche Zeichen","die verbindende","die deutende","die allgemeine Auslegungs-Kunst","die Kunst der Vorbedeutungen"],"marks":["*","**","***","****","*****","******","*******","********","*********"]},
 {"num":350,"section":"parsi-capiii-secviii","aa":102,"ed":110,"text":"Signum repraesentationis est terminus (cf. §. 248, symbolum). Termini per vocem humanam usitatiores sunt vocabula@@1@@. Series vocabulorum repraesentationes connexas significantium est oratio (latius dicta)@@2@@. Complexus vocabulorum in certa regione maiori usitatiorum est lingua particularis@@3@@. Lingua in certa minori regione usitatior, a se ipsa, uti in aliis minoribus regionibus usitatior est, differens idioma est@@4@@. Idioma perfectius est dialectus. Termini, ductus oculis observandi, sunt characteres strictius dicti@@5@@, cf. §. 67. Hi vel vocabulorum, nominales@@6@@, vel rerum signandarum vocabulis immediati, reales@@7@@, qui si aliam rem significent, quam cui simillimi sunt, sunt hieroglyphici, societatum insignia@@8@@, si in omni lingua particulari legi possunt, eorum complexus est lingua universalis@@9@@.","glosses":["Wort","Rede","besondre Sprache","Mund-Art","Züge","Wort-","Sach-Charactere","Siegel, Pettschaft, Wapen","die allgemeine Sprache"],"marks":["*","**","***","****","*****","******","*******","********","*********"],"aaEnd":103},
 {"num":351,"section":"parsii-proleg","aa":103,"ed":null,"text":"Cosmologia generalis est scientia praedicatorum mundi generalium, eaque vel ex experientia propius, empirica, vel ex notione mundi, rationalis.","glosses":[],"marks":[]},
 {"num":352,"section":"parsii-proleg","aa":103,"ed":111,"text":"Cosmologia principia psychologiae, theologiarum, physicae, teleologiae, philosophiae practicae prima continens, refertur, §. 2, cum ratione, ad metaphysicam, §. 1.","glosses":[],"marks":[]},
 {"num":353,"section":"parsii-proleg","aa":103,"ed":null,"text":"Cosmologia mundi 1) notionem, 2) partes, 3) perfectionem docet.","glosses":[],"marks":[]},
 {"num":354,"section":"parsii-capi-seci","aa":103,"ed":null,"text":"Mundus@@1@@ (cf. §. 91, 403, 434, universum, παν) est series (multitudo, totum) actualium finitorum, quae non est pars alterius.","glosses":["die ganze Welt"],"marks":["*"]},
 {"num":355,"section":"parsii-capi-seci","aa":103,"ed":null,"text":"Hic mundus exsistit. Ergo mundus est in se possibilis, §. 57, 18.","glosses":[],"marks":[],"aaEnd":104},
 {"num":356,"section":"parsii-capi-seci","aa":104,"ed":null,"text":"In hoc mundo sunt actualia extra se posita, hinc nexus universalis actualis, §. 279, 306.","glosses":[],"marks":[]},
 {"num":357,"section":"parsii-capi-seci","aa":104,"ed":112,"text":"In omni mundo sunt partes actuales, §. 354, 155, hae singulae connectuntur cum toto, §. 14, 157, hinc singulae connectuntur cum singulis, §. 33. Ergo in omni mundo nexus est partium et harmonia universalis, §. 48, i.e. in mundo non datur insula. Aliter: partes mundi vel sunt extra se invicem posita actualia, et connectuntur singula cum singulis, §. 279, 306, vel sunt eius determinationes internae non positae extra se invicem, §. 10, 37, et connectuntur singulae cum singulis, §. 49. Ουκ εστιν επεισοδιωδησ εστιν ωσπερ στρατευμα.","glosses":[],"marks":[]},
 {"num":358,"section":"parsii-capi-seci","aa":104,"ed":null,"text":"In hoc mundo exsistit nexus effectivus (regnum potentiae), §. 335, utilitatis, §. 338, usuum, §. 339, finalis (regnum sapientiae), §. 343, subiectivus et formalis, §. 345, exemplaris, §. 346, significativus, §. 347. Hinc nexus eiusmodi sunt in mundo possibiles, §. 57.","glosses":[],"marks":[]},
 {"num":359,"section":"parsii-capi-seci","aa":104,"ed":null,"text":"Omnis mundus cum sit ens, §. 355, 62, erit unum, §. 73 (§. 354, 155), verum, §. 90 (§. 357, 355, 354, 92). Hinc in omni mundo est ordo, §. 89, et regulae communes, §. 86. Mundus fabulosus non est mundus, §. 120.","glosses":[],"marks":[]},
 {"num":360,"section":"parsii-capi-seci","aa":104,"ed":113,"text":"Omnis mundus est perfectus, §. 99, 359, et bonus. §. 100.","glosses":[],"marks":[]},
 {"num":361,"section":"parsii-capi-seci","aa":104,"ed":null,"text":"Partes omnis mundi singulae sunt entia contingentia, §. 354, 257. Hinc earum exsistentia modus est, §. 134. Iam exsistentia singularum mundi partium simul sumptarum est exsistentia mundi, §. 155. Ergo mundi exsistentia modus est. et omnis mundus est ens contingens, §. 111. Aliter: Pone quendam mundum esse ens necessarium, omnes eius determinationes internae erunt absolute necessariae, nec hinc ulla pars istius mundi habebit modos, §. 108, 157, nec erit ens contingens, §. 134, sed omnis pars illius mundi erit ens necessarium, §. 109, hinc infinitum, §. 258, q.a., §. 354.","glosses":[],"marks":[]},
 {"num":362,"section":"parsii-capi-seci","aa":104,"ed":null,"text":"Omnis mundus est unum, §. 359, modos tamen habet, §. 361, 112, hinc determinationes in se separabiles, §. 72, 65, hinc unitatem hypotheticam, §. 76, et intrinsecus contingentem, §. 115.","glosses":[],"marks":[]},
 {"num":363,"section":"parsii-capi-seci","aa":104,"ed":114,"text":"Nullius mundi partium coniunctio est absolute necessaria, §. 362, 102, est tamen coordinatio, §. 78. Ergo in omni mundo est ordo in se contingens, §. 117, hinc et veritas intrinsecus contingens, §. 119.","glosses":[],"marks":[]},
 {"num":364,"section":"parsii-capi-seci","aa":104,"ed":null,"text":"Omnes partes mundi reales, §. 136, cum consentiant ad gradum realitatis mundo ipsarum tribuendum, §. 248, 140, ita tamen, ut in se possint etiam non consentire, aut non tantum consentire, utpote entia contingentia, §. 354, 257: in omni mundo est perfectio in se contingens, §. 122.","glosses":[],"marks":[],"aaEnd":105},
 {"num":365,"section":"parsii-capi-seci","aa":105,"ed":null,"text":"Omnis mundus est absolute et interne mutabilis, §. 361, 133.","glosses":[],"marks":[]},
 {"num":366,"section":"parsii-capi-seci","aa":105,"ed":null,"text":"In omni mundo sunt realitates absolute necessariae, §. 359, 360, hinc bonum metaphysicum, §. 147, et in se contingentes, §. 362-364, hinc bonum physicum late dictum, §. 147.","glosses":[],"marks":[]},
 {"num":367,"section":"parsii-capi-seci","aa":105,"ed":115,"text":"Hic mundus est unum, §. 359, in se contingenter, §. 362. Est in hoc mundo ordo, §. 359, et veritas intrinsecus contingentes, §. 363, est et perfectio et bonitas intrinsecus contingens, §. 364, bonum metaphysicum et physicum late dictum, §. 366, et est hic mundus absolute, est interne mutabilis, §. 365, 154.","glosses":[],"marks":[]},
 {"num":368,"section":"parsii-capi-seci","aa":105,"ed":null,"text":"Mundus minimus esset totum paucissimorum minimorum actualium, §. 161, 354, hinc quo plura, quo maiora finita pro partibus habet, hoc fit maior, §. 160, donec sit maximus plurimorum maximorum in finitis aggregatum, §. 161.","glosses":[],"marks":[]},
 {"num":369,"section":"parsii-capi-seci","aa":105,"ed":null,"text":"Status mundi@@1@@ est totum omnium statuum in partibus eius simultaneorum. Iam hic mundus habet partes, in quibus coexsistunt fixa cum mutabilibus, §. 367. Ergo hic mundus habet statum, §. 205.","glosses":["der Zustand einer ganzen Welt"],"marks":["*"]},
 {"num":370,"section":"parsii-capi-seci","aa":105,"ed":null,"text":"Omnis et huius mundi exsistentia modus est, §. 361, 134, hinc potest abesse et adesse salva mundi essentia, §. 65. Cumque sit absolute mutabilis omnis et huius mundi actualitas, §. 133, omnis mundi initium et finis est absolute possibilis, §. 301, 65.","glosses":[],"marks":[]},
 {"num":371,"section":"parsii-capi-seci","aa":105,"ed":116,"text":"Mundus non potest oriri, nisi ex nihilo. Ponatur enim aliquis mundus ita oriri, ut tamen iam aliqua pars eius ipsi praeexstiterit: quoniam et quamdiu haec pars eius exstitit, fuit ex parte exsistens, uti semper erit, si exstiterit, non vero non exsistens, hinc post partem praeexsistentem oriri visus non oritur: §. 227, cum nondum ortus esset talis mundus, non tamen fuit amplius mere possibilis, dum totum exsistentis partis esset, adeoque iam, qua exsistentiam, determinatus, §. 54. Ergo mundus non oriens ex nihilo non oritur, §. 228. Sic et mundus non annihilatus non interit, dum superstite parte manet ex parte exsistens, uti semper fuit, si exstitit, hinc non mutatur in non exsistens, §. 227. Ergo mundus non potest interire, nisi per annihilationem, §. 228.","glosses":[],"marks":[],"aaEnd":106},
 {"num":372,"section":"parsii-capi-seci","aa":106,"ed":null,"text":"Omnis et hic mundus est ens finitum, §. 255, 361, hinc possibilis eius cognitio philosophica et mathematica, §. 249. Omnis mundus et hic habet malum metaphysicum, §. 250, et contingens, s. physicum late dictum, imperfectionem in se contingentem absolute possibilem, §. 263, partim bonus, partim malus, §. 264.","glosses":[],"marks":[]},
 {"num":373,"section":"parsii-capi-seci","aa":106,"ed":117,"text":"Omnes mundi sunt et enti infinito, et sibi invicem, et cuilibet partium suarum partialiter similes, §. 265, 267, sed impossibiles sunt plures extra se invicem actuales totaliter iidem, §. 269, diversi, §. 268, congruentes, §. 270, similes, §. 271, aequales, §. 272.","glosses":[],"marks":[]},
 {"num":374,"section":"parsii-capi-seci","aa":106,"ed":null,"text":"Cum partes mundi vel sint simultanea, vel successiva, §. 238, 354, si extra se invicem ponantur, connectentur in mundo aut per tempus, aut per spatium, aut per utrumque, §. 239, 306.","glosses":[],"marks":[]},
 {"num":375,"section":"parsii-capi-seci","aa":106,"ed":null,"text":"Omnis mundus est ens ab alio, §. 361, seu dependens, §. 308, et hic mundus habet causam efficientem extra se positam, eiusque effectus est, §. 334, testans de causa, §. 333.","glosses":[],"marks":[]},
 {"num":376,"section":"parsii-capi-seci","aa":106,"ed":null,"text":"Omnis mundi partes sunt actualia, §. 354, hinc singulae in suo mundo, adeoque partes huius mundi in hoc mundo habent veritatem, §. 90, et certitudinem, §. 93, ut determinationes internas, §. 37, 93, determinatas, §. 54.","glosses":[],"marks":[]},
 {"num":377,"section":"parsii-capi-seci","aa":106,"ed":118,"text":"Finita, quae non absolute solum, nec hypothetice tantum in qualicumque nexu, sed etiam in universali nexu alicuius mundi possibilia sunt, possibilia@@1@@ illius mundi vocantur. Hinc possibilia huius mundi sunt, quae in universali eius nexu spectata tamen sunt hypothetice possibilia, hinc maiorem possibilitatis gradum habent, §. 165, 246.","glosses":["das Mögliche einer gewissen ganzen Welt"],"marks":["*"]},
 {"num":378,"section":"parsii-capi-seci","aa":106,"ed":null,"text":"Si vel unica pars huius mundi esset alia, quam est, mundus hic non esset totaliter idem, qui est, §. 155, 267. Iam omnes partes huius universi possunt esse aliae, quam sunt, § 354, 260. Ergo possibiles sunt mundi partim ab hoc diversi, §. 38, partim iidem cum eo, §. 265, i.e. plures, §. 74.","glosses":[],"marks":[]},
 {"num":379,"section":"parsii-capi-seci","aa":106,"ed":null,"text":"Hic mundus unice singularis est, §. 77. Pone enim plures esse, constituerent cum hoc multitudinem seu seriem, §. 74. Hinc hic non esset mundus, §. 354, aut omnes isti mundi partes huius, tantum unici, §. 354, 77.","glosses":[],"marks":[],"aaEnd":107},
 {"num":380,"section":"parsii-capi-secii","aa":107,"ed":119,"text":"Progressus (regressus) in infinitum@@1@@ esset series entium contingentium extra se invicem positorum, quorum unum est alterius causa secundum quid, sine causa simpliciter tali. In quo progressu in infinitum causatum sumitur causa sui, esset ille curvilineus@@2@@ (circularis): in quo causatum non sumitur causa sui, esset ille rectilineus@@3@@.","glosses":["der Fort- oder Rückgang in das Unendliche","dergleichen Fortgang im Kreise","der grade Fort- oder Rückgang"],"marks":["*","**","**"]},
 {"num":381,"section":"parsii-capi-secii","aa":107,"ed":120,"text":"Progressus in infinitum, quantuscumque poneretur, esset ens contingens, §. 380, 155, hinc haberet causam efficientem extra se positam, §. 334. Haec non posset esse ens contingens, dum enim illud iterum esset ens ab alio, §. 308, non esset causa progressus in infinitum, nisi secundum quid talis, §. 28. Ergo non extra progressum ipsum posita, sed pars eius, §. 155, 380. Ergo causa efficiens progressus in infinitum deberet esse ens necessarium, §. 109, et independens, §. 310. Quocumque modo hoc potest exsistere, eo modo exsistit, §. 259. At potest exsistere, licet non sit causatum alterius extra se positi, §. 310. Ergo nec est causatum alterius extra se positi, adeoque causa effectuum suorum simpliciter talis, §. 28. Hinc progressus in infinitum, qui deberet esse sine causa simpliciter tali, §. 380, et tamen eam habere, est impossibilis, §. 7, nec in hoc, nec in ullo mundo ponendus, §. 354, 58.","glosses":[],"marks":[]},
 {"num":382,"section":"parsii-capi-secii","aa":107,"ed":null,"text":"Fatum@@1@@ est necessitas eventuum in mundo. Fatum ex necessitate mundi absoluta esset spinosisticum, non ens, §. 361, 105, nec in hoc, nec in ullo mundo ponendum, §. 354, 58.","glosses":["das Schicksal, Verhängniss"],"marks":["*"]},
 {"num":383,"section":"parsii-capi-secii","aa":107,"ed":null,"text":"Eventus in mundo, cuius ignoratur ratio sufficiens, casus@@1@@ est. Casus, cuius nec est ratio sufficiens, purus@@2@@ esset, impossibilis, §. 22, nec in hoc, nec in ullo mundo ponendus, §. 354, 58.","glosses":["ein Zufall, ein ungefähr","ein blinder Zufall"],"marks":["*","**"],"aaEnd":108},
 {"num":384,"section":"parsii-capi-secii","aa":108,"ed":121,"text":"Eventus ordinarius@@1@@ est, cuius exsistentia determinatur secundum certi alicuius ordinis regulas: extraordinarius@@2@@ est non ordinarius. Extraordinarius absolute@@3@@ esset, cuius exsistentia secundum nullas ullius ordinis regulas determinaretur; relative@@4@@ talis est, qui non fit per regulas dati certi alicuius ordinis. Extraordinarius ob confusionem inordinatus@@5@@ est.","glosses":["eine ordentliche","ausserordentliche","ganz und völlig ausserordentliche","gewisser maassen ausserordentliche","unordentliche Begebenheit"],"marks":["*","**","***","****","*****"]},
 {"num":385,"section":"parsii-capi-secii","aa":108,"ed":null,"text":"Absolute extraordinarium non esset verum, §. 384, 89, hinc impossibile, §. 90, 62, nec in hoc, nec in ullo mundo ponendum, §. 354, 58.","glosses":[],"marks":[]},
 {"num":386,"section":"parsii-capi-secii","aa":108,"ed":null,"text":"Eventus sine ulla ratione sufficiente proxima esset saltus absolutus@@1@@. Eventus sine ratione sufficiente proxima ordinaria est saltus respectivus@@2@@","glosses":["das völlig durch einen Sprung geschähe","wobei gewisser maassen ein Sprung statt hat"],"marks":["*","**"]},
 {"num":387,"section":"parsii-capi-secii","aa":108,"ed":null,"text":"Quod exsisteret sine ratione sufficiente ulla proxima, §. 27, exsisteret per casum purum, §. 22, 383, hinc saltus absolutus est impossibilis, §. 386, 284, nec in hoc, nec in ullo mundo ponendus, §. 354, 58. Respectivus etiam omnis, si non inordinati quid est, est tamen aliquid extraordinarii, §. 384.","glosses":[],"marks":[]},
 {"num":388,"section":"parsii-capi-secii","aa":108,"ed":122,"text":"Mundus nec est substantia infinita, §. 372, 248, nec determinatio eius interna, §. 365, 252, hinc nec essentia entis infiniti, §. 40, nec attributum, nec modus, §. 50, nec modificatio, §. 209. Hinc omnis mundus extra substantiam infinitam ponendus est, adeoque hic etiam mundus exsistit extra ens infinitum, quod ideo vocatur ens extramundanum@@1@@, ens extra hunc mundum actuale.","glosses":["das Wesen ausser der Welt"],"marks":["*"]},
 {"num":389,"section":"parsii-capi-secii","aa":108,"ed":null,"text":"Omnis, hinc et hic, mundus, aut est substantia, aut accidens, §. 191. Si hic mundus substantia fuerit, extra substantiam infinitam subsistit, §. 388, ut adeo infinita substantia non sit unica substantia, §. 77.","glosses":[],"marks":[],"aaEnd":109},
 {"num":390,"section":"parsii-capi-secii","aa":109,"ed":null,"text":"Si hic mundus fuerit accidens, non tamen est accidens substantiae infinitae, alias non exstiturus extra suum substantiale, §. 196, 388, nec exsistere potest, nisi in substantia, aut substantiis, §. 194. Ergo si hic mundus sit accidens, infinita substantia nec tunc est unica substantia, §. 77, 389. Iam alteruter casus est necessarius, §. 191, 10. Ergo substantia infinita non est substantia unica.","glosses":[],"marks":[]},
 {"num":391,"section":"parsii-capi-secii","aa":109,"ed":123,"text":"Vis infinita non est unica vis, §. 390, 198, in omni et hoc mundo sunt vires finitae, §. 390, 388.","glosses":[],"marks":[]},
 {"num":392,"section":"parsii-capii-seci","aa":109,"ed":null,"text":"Omnis mundus aut est ens simplex, aut compositum, §. 224, hic est ens compositum. Qui hunc mundum se putat ens simplex est egoista.","glosses":[],"marks":[]},
 {"num":393,"section":"parsii-capii-seci","aa":109,"ed":124,"text":"Mundi compositi partes singulae et simul sumptae non possunt esse accidentia. Cum enim exsistere talis mundus non posset, nisi in substantiis, §. 155, 191, nec posset tamen infinitae inhaerere, §. 388, nec unicae finitae, §. 224, 194, requireret plures substantias finitas, quibus inhaereret, §. 77. At hae constituerent seriem finitorum actualium, quae si non esset pars mundi ex meris accidentibus compositi, cum ipso tamen constitueret seriem finitorum actualium ipso maiorem, §. 160, hinc ipse non esset mundus, §. 354. Si series illa, quam substantiae finitae constituerent, esset pars eius mundi, non esset ille ex meris accidentibus compositus, §. 155. Hinc impossibilis est mundus ex meris accidentibus compositus, §. 61, 62. Omnis mundus compositus est compositum strictius dictum, §. 225. Omnis mundus aut est substantia, §. 389, 392, aut compositum strictius dictum.","glosses":[],"marks":[]},
 {"num":394,"section":"parsii-capii-seci","aa":109,"ed":null,"text":"Partes mundi compositi sunt vel substantiales, vel accidentales, §. 393, et illae quidem monades, §. 235. Hinc omnis mundus compositus, et hic monadibus constat, §. 392. Unde denuo patet, nullum mundum oriri posse, nisi ex nihilo, §. 236, nec interire, nisi per annihilationem, §. 237, 393.","glosses":[],"marks":[]},
 {"num":395,"section":"parsii-capii-seci","aa":109,"ed":null,"text":"Hic mundus compositum strictius dictum, §. 393, monadibus constat, nec est in eo quicquam substantiale, praeter monades, §. 394. Qui negat exsistentiam monadum est materialista universalis. Qui negat exsistentiam monadum universi, e.g. huius, partium est materialista cosmologicus (cf. §. 757).","glosses":[],"marks":[],"aaEnd":110},
 {"num":396,"section":"parsii-capii-seci","aa":110,"ed":125,"text":"Monades omnis, hinc et huius, compositi mundi sunt possibilia, §. 8, rationalia, §. 24, entia, §. 63, una, §. 73, vera, §. 90, obiective certa, §. 93, perfecta, §. 99, bona, §. 100, entia contingentia, §. 257, mutabilia, §. 133, realia, §. 136, universaliter connexa, §. 357, sunt vi praeditae, immo vires, etiam strictius dictae, §. 199, habent statum internum, §. 206, et externum, §. 207, modificabiles, §. 209, non extensae, nec spatium replentes singulae, at aggregatae, §. 242, nec habent magnitudinem quantitativam, §. 243, indivisibiles, §. 244, finitae, §. 354, hinc habent certum virium limitem, §. 249, malum metaphysicum, §. 250, partialiter sibi similes, §. 265, 268, at partialiter etiam tam dissimiles, quam inaequales, §. 273, singulae non admittentes figuram, ita tamen, ut totum earum admittat figuram, §. 280.","glosses":[],"marks":[]},
 {"num":397,"section":"parsii-capii-seci","aa":110,"ed":null,"text":"Monades omnis, hinc et huius, compositi mundi, cum sint actuales extra se invicem positae, §. 354, 224, aut erunt entia simultanea, aut successiva, aut utraque, §. 238, hinc singulares habent positum, §. 148, aut in simultaneis, locum, aut in successivis, aetatem, aut utrumque, §. 281, licet singulae locum non repleant, §. 396.","glosses":[],"marks":[]},
 {"num":398,"section":"parsii-capii-seci","aa":110,"ed":126,"text":"Monadum omnis, hinc et huius, universi finitarum, §. 354, quaelibet extra reliquas, si subsistere ponatur, substitura, §. 192, non potest cum ulla altera esse in eodem totaliter loco, §. 282. Substantia, in cuius loco nequit esse alia extra eam posita, est impenetrabilis@@1@@ (solida). Ergo omnis substantia, hinc et monades, tam huius, quam omnis compositi mundi, sunt impenetrabiles, §. 230.","glosses":["undurchdringlich"],"marks":["*"]},
 {"num":399,"section":"parsii-capii-seci","aa":110,"ed":27,"text":"Monades huius et omnis compositi, hinc extensi, mundi, §. 241, 393, sunt puncta, §. 286, sed neutiquam mathematica, in quibus nihil, praeter non extensionem, ponitur, §. 396-398, nec iuxta se positae congruunt aut coincidunt, §. 70, 396, sed positis earum coexsistentibus pluribus, quia quaevis impenetrabilis est, §. 398, ponuntur simultanea extra se invicem certo quodam ordine, §. 396, 78, hinc in earum aggregato est spatium, §. 239. Ergo omne aggregatum monadum huius et omnis compositi mundi extensum est, §. 241. Punctum mathematicum, abstractum possibile, §. 149, si fingatur exsistere, zenonicum est punctum, ens fictum, §. 62. Punctum physicum si dicas actuale et praeter simplicitatem omnimode determinatum, quaedam monades huius universi sunt puncta physica, nempe quarum ex aggregato extensum.","glosses":[],"marks":[]},
 {"num":400,"section":"parsii-capii-seci","aa":110,"ed":null,"text":"Omnes compositi, hinc et huius, mundi monades sunt in universali nexu, §. 357, hinc singulae singularum aut rationes sunt aut rationata, aut utrumque, §. 14, 48. Ex rationato cognosci potest ratio, §. 29. Ergo ex quavis omnis compositi, hinc et huius, mundi monade singulae mundi, ad quem pertinet, partes cognosci possunt, §. 14, i.e. singulae omnis, hinc et huius, compositi mundi monades sunt vires, §. 199, repraesentativae sui universi (sunt specula eius activa, §. 210, indivisibilia, §. 244, microcosmi, mundi in compendio, suique mundi concentrationes, seu habent vim, praeditae sunt vi repraesentativa sui universi).","glosses":[],"marks":[],"aaEnd":111},
 {"num":401,"section":"parsii-capii-seci","aa":111,"ed":128,"text":"Monades mundum suum repraesentantes, §. 400, aut sibi eum repraesentant, suae perceptionis, saltim ex parte, consciae, aut minus, §. 10. Hinc et monades huius universi mundum hunc aut obscure tantum repraesentant, aut clare, saltim ex parte. Illae sunt monades nudae@@1@@ (sopitae).","glosses":["im tiefen Schlaf liegende Monaden"],"marks":["*"]},
 {"num":402,"section":"parsii-capii-seci","aa":111,"ed":null,"text":"Monades clare mundum repraesentantes aut sibi eum distincte, saltim ex parte, repraesentant, aut minus, §. 10. Priores intelligunt, §. 69. Ergo facultatem habent distincte cognoscendi, §. 216, i.e. intellectum@@1@@ (strictius dictum, cf. §. 519). Substantia intellectualis@@2@@, i.e. intellectu praedita, est spiritus@@3@@ (intelligentia, persona). Ergo monades huius universi intellectuales sunt spiritus, §. 230. Solos in hoc mundo spiritus admittens est idealista.","glosses":["Verstand","das mit Verstand begabt","ein Geist"],"marks":["*","**","***"]},
 {"num":403,"section":"parsii-capii-seci","aa":111,"ed":null,"text":"Nexus spirituum alicuius mundi inter se est pneumaticus@@1@@. Iam in omni et hoc mundo, cui spiritus insunt, singulis singuli connectuntur. Ergo in hoc et omni mundo, cui spiritus insunt, est nexus pneumaticus universalis, §. 357 (mundus, cf. §. 354, pneumaticus, intellectualis, moralis, cf. §. 723, regnum gratiae).","glosses":["Verbindung der Geister"],"marks":["*"]},
 {"num":404,"section":"parsii-capii-seci","aa":111,"ed":129,"text":"Omnis substantia monas est, §. 234. Omnis spiritus est substantia, §. 402. Ergo monas est et ens simplex, §. 230.","glosses":[],"marks":[]},
 {"num":405,"section":"parsii-capii-seci","aa":111,"ed":null,"text":"Omnes omnis et huius mundi, cui spiritus insunt, spiritus sunt monades, §. 404, vires repraesentativae mundi sui ex parte saltim distincte, §. 402, non extensi, nec singuli spatium replentes, nec habent magnitudinem quantitativam, indivisibiles, finiti, certo tantum virium gradu praediti, malo metaphysico obnoxii, partialiter sibi similes, sed et singuli partialiter dissimiles et inaequales, nec singuli figuram agnoscentes, §. 396, unicus omnium perfectissimus est, §. 77, 185.","glosses":[],"marks":[],"aaEnd":112},
 {"num":406,"section":"parsii-capii-secii","aa":112,"ed":null,"text":"Totum monadum est monadatum. Ergo mundus hic et omnis compositus est monadatum, §. 394.","glosses":[],"marks":[]},
 {"num":407,"section":"parsii-capii-secii","aa":112,"ed":130,"text":"Monades in mundo composito aut partes etiam eius pro monadatis suis habent aut minus, §. 10, 406. In utroque casu monadatum eiusmodi erit extensum, §. 396, partium impenetrabilium, §. 398, partialiter dissimilium, §. 396, i.e. partialiter heterogeneum (difforme, dissimilare), hinc non erit extensum totaliter homogeneum (uniforme, similare), i.e. partium totaliter similium, §. 271.","glosses":[],"marks":[]},
 {"num":408,"section":"parsii-capii-secii","aa":112,"ed":null,"text":"Monades huius mundi simultaneae locum, successivae sibi mutuo determinant aetatem, §. 281, 85, hinc in se mutuo influunt, §. 211, in conflictu positae, §. 213. Ergo est in hoc mundo influxus et conflictus universalis, §. 48, 306 (bellum omnium contra omnia, concordia discors, discordia concors, §. 364).","glosses":[],"marks":[]},
 {"num":409,"section":"parsii-capii-secii","aa":112,"ed":null,"text":"Monadum in hoc mundo quaedam in se remotius influunt mutuo, § 408, 27, quaedam propius, sibi praesentes, §. 223, et quia saltus absolutus in mundo impossibilis est, §. 387, quaedam proxime, se contingentes, §. 223.","glosses":[],"marks":[]},
 {"num":410,"section":"parsii-capii-secii","aa":112,"ed":131,"text":"Quia omnes monades huius mundi in se mutuo influunt, §. 408, non est earundem actio transiens seu influxus sine reactione, §. 213.","glosses":[],"marks":[]},
 {"num":411,"section":"parsii-capii-secii","aa":112,"ed":null,"text":"Actio transiens seu influxus partium mundi in alias extra ipsas est aut simplex aut compositus, §. 215. Simplex est etiam minimus, §. 247, 214. Huic respondet reactio, aut minima, aut maior, §. 160, 161. Si minima est, est influxui aequalis, §. 70. Si maior ponatur reactio, id, quo excedit influxum reactio, ponit reactionem influentis, §. 410, hinc influxus eius non erit simplex, §. 215, quod contra hypothesin. Ergo influxui simplici respondet aequalis reactio, §. 70.","glosses":[],"marks":[]},
 {"num":412,"section":"parsii-capii-secii","aa":112,"ed":null,"text":"Influxus compositus partium mundi in alias extra ipsas est totum plurium simplicium influxuum, §. 215, 214. Cuivis ex his respondet reactio aequalis, §. 411. Iam si addas aequalibus aequalia, summae sunt aequales, §. 70. Ergo omni influxui composito partium mundi respondet aequalis reactio. Hinc reactio partium mundi omnis in alias extra ipsas est influxui seu actioni transeunti aequalis, §. 411.","glosses":[],"marks":[]},
 {"num":413,"section":"parsii-capii-secii","aa":112,"ed":132,"text":"Vires vivae monadum in mundo per contactum mutuum inter se confligentium sunt aequales, §. 412, 331, et quia eaedem non possunt rationes proximae contradictoriorum esse, §. 140, 36, proxime locum, §. 408, 409, hinc coniunctionem sibi mutuo determinantes, §. 281, 85, non continent rationem separationis mutuae proximam, §. 72. Hinc, nisi accedat vis tertia, contingunt se inseparabiliter, §. 386, unum constituentes, §. 73, unitae, §. 79.","glosses":[],"marks":[],"aaEnd":113},
 {"num":414,"section":"parsii-capii-secii","aa":113,"ed":null,"text":"Ita se mutuo contingentia, ut non nisi per vim tertiam separari possint, cohaerent@@1@@. Ergo monades mundi se mutuo contingentes cohaerent, §. 413. Nullus contactus sine cohaesione est. Ergo quaedam monades huius mundi cohaerent, §. 409, unum constituentes, §. 413, extensum, §. 407.","glosses":["hangen an einander"],"marks":["*"]},
 {"num":415,"section":"parsii-capii-secii","aa":113,"ed":133,"text":"Nulla mutatio fit in mundo composito sine motu. Sit enim A mutandum ex B in non-B. Coexstiterat cum simultaneis suis extra illud positis, ut B, nunc coexsistet, ut non-B, hinc diversam ad ea relationem, §. 37, 38, positum, §. 85, et locum nanciscetur, §. 281, et fiet motus, §. 283, 125. Quoties talis mutatio, talis in mundo composito motus fit, status mutati, et universi, cuius pars est, partim idem est cum praecedentibus, §. 265, partim diversus, §. 125. Hinc sicuti certus aliquis motus fuit, quatenus status novus a pristino differt; ita, quatenus status idem mansit, haec duratio status, est in mundo composito simul duratio loci, §. 299, certi motus absentia, quies, §. 183, certique motus impedimentum fuit, §. 221, et resistentia, §. 222.","glosses":[],"marks":[]},
 {"num":416,"section":"parsii-capii-secii","aa":113,"ed":null,"text":"Monades in universo constituentes extensum, §. 414, semper agunt, §. 216, 285, vi sua, §. 400, repraesentantes universi sui singulos status, et suos, etiam futuros, §. 298, quatenus hi iidem sunt cum antecedentibus perdurantes, certum motum impediente, certo motui resistente, §. 415, 210, quatenus autem hi diversi sunt ab antecedentibus, certum alium motum efficiente, s. movente, §. 415, 210. Praedicatorum singulis partibus convenientium aggregatum toti tribuitur, §. 155. Hinc monades quaedam huius universi constituunt extensum, cui vis inertiae tribuatur, §. 294, hinc materiam, §. 295. Materia nec huius universi, nec ullius ulla potest esse totaliter homogenea, §. 407.","glosses":[],"marks":[]},
 {"num":417,"section":"parsii-capii-secii","aa":113,"ed":134,"text":"Monades huius universi materiam constituentes, non eam exhibent primam ex significatu §. 295, et mere passivam, sed materiam, cui vis motrix tribuatur, §. 416, secundam, et corpus physicum, §. 296. Si moveatur una pars huius mundi, mutatur eius relatio ad reliquas simultaneas singulas, §. 283, 281, hinc non est motus in mundo particularis@@1@@, id est, cuiusdam mundi partis, sine universali, §. 283. Hinc in hoc mundo omnis materia est in motu, §. 415, et quies eius non est, nisi respectiva@@2@@, i.e. absentia determinati alicuius motus, §. 283, quae si tanta fuerit, ut observetur nullus quiescentis motus, erit motus evanescens@@3@@. Nulla in mundo quies absoluta, absentia omnis motus.","glosses":["eine besondre Bewegung","Ruhe von einer gewissen Bewegung, oder in Absicht auf eine gewisse Bewegung","eine unmerklich werdende, oder verschwindende Bewegung"],"marks":["*","**","***"],"aaEnd":114},
 {"num":418,"section":"parsii-capii-secii","aa":114,"ed":135,"text":"Extensum, aggregatum monadum, quarum singulae sunt impenetrabiles, iam hinc resistet motui suum locum occupaturorum extra ipsum positorum, §. 398, 222, iam hinc exseret vim inertiae, §. 294. Extensum, aggregatum monadum, quarum nulla vis est ulli alteri extra se positae totaliter aequalis, quarum nullum totum ulli alteri extra prius posito monadato, qua vires, totaliter aequale est, §. 272, 406, numquam est in totali aequilibrio@@1@@, aequalitate virium in confligentibus, et iam hinc exseret vim motricem, §. 294. Tale autem extensum est omne monadatum in hoc mundo, §. 414, 396. Ergo monadata in hoc mundo ob unam eandemque vim suarum monadum repraesentativam, §. 400, quatenus ea in impenetrabilibus rationem durantis loci, quietis, certique motus absentis continet, vim inertiae, quatenus eadem in numquam totaliter aequilibrantibus, mutationis loci, motusque certi rationem continet, vim motricem prodent, materia, §. 416, et corpora physica, §. 417. Quae duae vires tantum abest, ut ita sint oppositae sibi invicem, ut posita una diverso respectu non possit simul in eodem subiecto poni altera, §. 87, ut potius in respectu ad diversos motus sint simul in quocumque huius mundi extenso, §. 417, eademque vis dato extenso tributa respectu dati motus motrix, respectu motus huic oppositi sit vis inertiae, et v.v., §. 415.","glosses":["Gleichgewicht der Kräfte"],"marks":["*"]},
 {"num":419,"section":"parsii-capii-secii","aa":114,"ed":136,"text":"Cum corporibus tribuantur vires, §. 296, sunt composita strictius dicta, §. 225, 198, hinc modus compositionis est ipsorum essentia, §. 226, monadibus constant, §. 235, habent magnitudinem quantitativam, §. 243.","glosses":[],"marks":[]},
 {"num":420,"section":"parsii-capii-secii","aa":114,"ed":null,"text":"Corpora habent partes extra partes, §. 296, 224. Partes corporum extra se invicem actuales primae elementa@@1@@ vocantur.","glosses":["die allerersten Grund-Theile"],"marks":["*"]},
 {"num":421,"section":"parsii-capii-secii","aa":114,"ed":null,"text":"Elementa aut sunt partes corporum absolute primae, i.e. quae non habent ipsae iterum partes extra partes, aut relative tales, ultra quas in attentione compositionis progredi non placet, §. 420. Illae sunt entia simplicia seu monades, §. 419, 224.","glosses":[],"marks":[]},
 {"num":422,"section":"parsii-capii-secii","aa":114,"ed":137,"text":"Immaterialevocatur, quod non est materia, quod est materia, materiale vocatur. Elementa corporum absolute talia sunt immaterialia, §. 421, 295. Incorporeum est, quod non est corpus, quod est, corporeum. Iam omne corporeum est materiale, §. 296. Ergo elementa corporum absolute talia sunt incorporea, hinc singula non sunt corpora, §. 296.","glosses":[],"marks":[],"aaEnd":115},
 {"num":423,"section":"parsii-capii-secii","aa":115,"ed":null,"text":"Philosophia respective primum pro absolute primo habens philosophia pigrorum dicitur, quae cum falsa sit, elementa relative talia, §. 421, materialia et corporea, §. 422, non habenda sunt pro elementis absolute talibus, immaterialibus et incorporeis, §. 422. Hinc haec commodius elementa simpliciter, illa dicuntur materiae primae@@1@@, cf. §. 295.","glosses":["ein allererster Grund-Stoff"],"marks":["*"]},
 {"num":424,"section":"parsii-capii-secii","aa":115,"ed":null,"text":"Atomus@@1@@ dicitur ens per se indivisibile. Omnis monas est indivisibilis per se, §. 244. Hinc omnis monas est atomus. Ergo elementa sunt atomi, §. 423, hinc atomi naturae dicuntur.","glosses":["das an und vor sich untheilbare"],"marks":["*"]},
 {"num":425,"section":"parsii-capii-secii","aa":115,"ed":138,"text":"Observabilia@@1@@ (phaenomena) dicimus, quae per sensus possumus cognoscere (confusius). Corpora minora nobis non observabilia corpuscula vocantur. Philosophia phaenomena corporum ex corpusculis explicans corpuscularis est.","glosses":["das wahrzunehmende"],"marks":["*"]},
 {"num":426,"section":"parsii-capii-secii","aa":115,"ed":null,"text":"Corpuscula vel alia iterum corpuscula pro partibus habent, vel minus, §. 10, 155. Haec primitiva@@1@@ dicuntur, illa derivativa@@2@@.","glosses":["die ersten","zusammengesetztere"],"marks":["*","**"]},
 {"num":427,"section":"parsii-capii-secii","aa":115,"ed":139,"text":"Omnem materiam, qualis est in hoc mundo, constituunt elementa, §. 418, 419. Hinc magnitudo quantitativa ipsi tribuenda, §. 419, 423, est multitudo elementorum ad certam materiam constituendam unitorum, §. 159, 413. Hinc elementa partes certae materiae cum ea, tamquam monadato suo, sunt in eodem loco, §. 155, 406. Ergo si locus eorum ita mutetur, ut non sint cum materia, quam ante constituerant, in eodem loco, non manent partes illius materiae, §. 155. Iam vero omnis relationis mutatio est in ente in se spectato possibilis, §. 133. Ergo omnis loci mutatio est in omnibus elementis in se spectatis possibilis, §. 281, 85. Ergo et ille motus, quo cessant esse partes materiae, cuius partes fuerant, §. 283. Si ita moveantur, materia dividitur, §. 244, 162. Ergo omnis materia, qualis in mundo, est divisibilis, saltim in et per se, §. 18.","glosses":[],"marks":[]},
 {"num":428,"section":"parsii-capii-secii","aa":115,"ed":null,"text":"Si materia in mundo dicatur divisibilis in infinitum: id vel intelligitur absolute, ipsi non esse partes indivisibiles, et est falsum, §. 424, 419, vel respective, nobis in ea dividenda non observabiles partes esse, nisi iterum divisibiles, §. 248, et est verum materiam esse in indefinitum divisibilem, §. 425.","glosses":[],"marks":[],"aaEnd":116},
 {"num":429,"section":"parsii-capii-secii","aa":116,"ed":null,"text":"Atomus materialis esset corpusculum per se indivisibile, quod nihil est, §. 427, 425. Philosophia igitur atomistica, phaenomena corporum ex atomis materialibus explicans, fallitur.","glosses":[],"marks":[]},
 {"num":430,"section":"parsii-capii-seciii","aa":116,"ed":140,"text":"Natura (cf. §. 431, 466) entis est complexus earum eius determinationum internarum, quae mutationum eius, aut in genere accidentium ipsi inhaerentium sunt principia. Hinc ad naturam entis pertinent 1) essentialia eius, §. 39, 2) essentia, §. 40, 3) facultates, 4) receptivitates, §. 216, 5) vires, quibus instructum est, omnes, §. 197. Initium naturae est origo@@1@@, duratio vita@@2@@, finis mors@@3@@, cf. §. 556.","glosses":["Erzeugung","Leben","Tod"],"marks":["*","**","***"]},
 {"num":431,"section":"parsii-capii-seciii","aa":116,"ed":null,"text":"Natura corporum est modus compositionis eorum, §. 419, cum omni facultate, receptivitate, vi inertiae et motrice, qua pollent, §. 296, 430. Nonnumquam etiam natura simpliciter dicitur, cf. §. 430, 466.","glosses":[],"marks":[]},
 {"num":432,"section":"parsii-capii-seciii","aa":116,"ed":null,"text":"Cum in mundo sit universalis veritas, §. 363, 90, omnes eius mutationes habent normas communes, §. 86, 89, secundum quas natura partium eius determinatur, §. 431, hinc et motus corporum in mundo, §. 283, quarum superiores leges@@1@@, inferiores regulae motus@@2@@ dicuntur.","glosses":["gemeine","besondre Gesetze der Bewegung"],"marks":["*","**"]},
 {"num":433,"section":"parsii-capii-seciii","aa":116,"ed":141,"text":"Machina est compositum stricte dictum secundum leges motus mobile. Ergo omne corpus in mundo est machina, §. 419, 432. Nec datur in mundo machina, nisi ens contingens, §. 361. Machinae natura per leges motus determinata mechanismus est. At, quicquid non est compositum, non est machina, hinc nulla monas est machina, §. 230.","glosses":[],"marks":[],"aaEnd":117},
 {"num":434,"section":"parsii-capii-seciii","aa":117,"ed":null,"text":"Nexus machinarum est mechanicus, hinc nexus corporum in mundo est mechanicus (mundus, cf. §. 354, corporeus, materialis, regnum naturae), §. 433. At, in quo mundo sunt spiritus et corpora, in eo connexa sunt etiam corpora cum spiritibus, §. 357, hinc in mundo, in quo sunt spiritus et corpora, est nexus 1) corporum inter se, 2) spirituum inter se, §. 403, 3) corporum et spirituum mutuus, pneumatico-mechanicus et mechanico-pneumaticus (harmonia regni naturae et gratiae).","glosses":[],"marks":[]},
 {"num":435,"section":"parsii-capii-seciii","aa":117,"ed":142,"text":"Philosophia mechanica est phaenomena corporum ex eorum mechanismo explicans. Fatum ex mechanismo corporum est physicomechanicum (physicum aut mechanicum simpliciter), at si quis eventus mundi per illud determinetur, est in se contingens , §. 361, 354, non nisi hypothetice necessarius, §. 382, 105.","glosses":[],"marks":[]},
 {"num":436,"section":"parsii-capiii-seci","aa":117,"ed":null,"text":"Mundus perfectissimus est, in quo plurimarum partium maximae, et maximarum plurimae partes in mundo compossibiles tantum ad unum consentiunt, quantum in mundo fieri potest. Hinc mundus perfectissimus habet perfectionem maxime compositam, cuique mundo non nisi simplex convenit perfectio, non est perfectissimus, §. 185.","glosses":[],"marks":[]},
 {"num":437,"section":"parsii-capiii-seci","aa":117,"ed":143,"text":"Posito mundo perfectissimo ponitur summa, quae in mundo possibilis est, perfectio, §. 436. Hinc mundus perfectissimus est etiam mundorum possibilium omnium optimus, §. 187. Iam mundi partes sunt actualia, §. 354, haec vel simultanea, vel successiva, §. 306. Ergo mundus perfectissimus tot 1) simultanea, tot 2) successiva complectitur, et 3) tanta, quot et quanta in mundo sunt optimo compossibilia, i.e. 1) extensive, 2) protensive, 3) intensive, mundorum est optimus maximus, §. 436, 368.","glosses":[],"marks":[],"aaEnd":118},
 {"num":438,"section":"parsii-capiii-seci","aa":118,"ed":null,"text":"Si vel duo tantum contingentia extra se posita sunt in mundo compossibilia, vel ut simultanea, vel ut successiva, quorum unius perfectio vel nihil, vel non tantum alterius perfectioni deroget, quantum perfectioni totius addat, mundus egoisticus, qualem egoista hunc ponit, non est perfectissimus. Si vel unica tantum monas non intellectualis in se possibilis et cum spiritibus in mundo compossibilis est, cuius perfectio aut nihil, aut non tantum perfectioni spirituum deroget, quantum perfectioni totius addat, mundus idealisticus, qualem idealista hunc ponit, non est perfectissimus, §. 437.","glosses":[],"marks":[]},
 {"num":439,"section":"parsii-capiii-seci","aa":118,"ed":null,"text":"Materialista negat in hoc mundo dari monada, §. 395, hinc mundum sibi format impossibilem, §. 394, ergo mundus nec ullus, nec perfectissimus est, qualem materialista fingit hunc esse, materialisticus, §. 436.","glosses":[],"marks":[]},
 {"num":440,"section":"parsii-capiii-seci","aa":118,"ed":144,"text":"Perfectissimusetiam mundus finitus est, §. 372, et omnes eius, etiam perfectissimae, partes finitae, §. 354, 257. Ergo nec ipse, nec quicquam in eodem est infinitum realiter, §. 248. Non possunt tamen solum et ipse, et multae eius partes multis rationibus mathematice infinita esse, sed est ipse etiam omnibus, qui aut nequeunt, aut quibus non placet contingentis maximi determinare limites, extensionis, protensionis, intensionis infinitae mathematice talis, s. intensive, extensive, protensive indefinitus, §. 248, 437.","glosses":[],"marks":[]},
 {"num":441,"section":"parsii-capiii-seci","aa":118,"ed":null,"text":"In mundo perfectissimo est maximus, qui in mundo possibilis, nexus universalis, §. 437, 94, harmonia et consensus, §. 436, 357.","glosses":[],"marks":[]},
 {"num":442,"section":"parsii-capiii-seci","aa":118,"ed":null,"text":"Cum omnis mundus sit perfectus, §. 360, imperfectissimus est, in quo minima, quae in mundo esse potest, perfectio, consensus paucissimorum minimorum ad unum minimum minimus, §. 354, 185, hinc simplex, §. 96, sine exceptionibus, §. 97. Mundus imperfectissimus est minimus, §. 368.","glosses":[],"marks":[]},
 {"num":443,"section":"parsii-capiii-seci","aa":118,"ed":145,"text":"Etiamsi mundus perfectissimus ponatur mundorum optimus, §. 437, non tamen ideo ponitur summum bonum, s. optimum metaphysicum, etiamsi ponantur in eo maximae plurimae realitates, quae in ullo mundo sunt compossibiles, non tamen absolute plurimae maximae, §. 190, multo minus absolute necessariae, quoniam singularum exsistentia modus est, §. 361. Etiamsi mundo perfectissimo tribuatur maximus realitatis in universo quodam obtinendae gradus, ille tamen in ente contingenti non nisi limes erit, §. 248, 250, a realiter infiniti gradu realitatis absolute maximo, necessario, immutabili, §. 251, probe diversus, §. 38.","glosses":[],"marks":[],"aaEnd":119},
 {"num":444,"section":"parsii-capiii-seci","aa":119,"ed":null,"text":"In omni perfectione est ordo, §. 95. Hinc in mundo perfectissimo maximus est ordo, qui in mundo possibilis, §. 437, 175. Ergo plurimae regulae perfectionis communes, e.g. Quo plura, quo maiora, quo spatiosiora, §. 280, quo diuturniora, §. 299, ceteris paribus, hoc melius, §. 437, 187, et ordo maxime compositus, §. 183, ita tamen, ut inferiores superioresque regulae tandem ad unam omnes ex una summa perfectionis regula, eademque fortissima, cognosci possint, §. 182, 185.","glosses":[],"marks":[]},
 {"num":445,"section":"parsii-capiii-seci","aa":119,"ed":146,"text":"In mundo perfectissimo cum plurimae sint perfectionis regulae, §. 444, possunt etiam esse exceptiones admodum multae, §. 97, 372, modo maximum non tollant consensum, §. 440, hinc sint, quae possunt, ceteris paribus, paucissimae, §. 161, minimae, §. 186.","glosses":[],"marks":[]},
 {"num":446,"section":"parsii-capiii-seci","aa":119,"ed":null,"text":"Si in mundo perfectissimo collidantur ratio perfectionis sufficiens et insufficiens, fit exceptio ab insufficienti: si collidantur fecundior et minus fecunda, fit exceptio a minus fecunda; si gravior et minus gravis, fit exceptio a minus gravi; si ulterior et propior ulteriori subordinata, fit exceptio a propiori; si secundum quid sufficiens et simpliciter talis, fit exceptio a sufficiente secundum quid; si inferior et superior, fit exceptio ab inferiori. Quaecumquae tandem regula perfectionis in mundo perfectissimo collidatur cum summa, ab ea excipitur, §. 186, 445.","glosses":[],"marks":[]},
 {"num":447,"section":"parsii-capiii-seci","aa":119,"ed":147,"text":"De mundo perfectissimo non valent solum §. 361-376, 354, 436, sed etiam absunt ab eodem longissime, quae abesse ab omni mundo docent §. 380-388, 247, 354. e.g. Tantum abest ab eo fatum spinosisticum, §. 382, ut ipsi potius indefinita extensive, intensive et protensive tribuenda sit contingentia et mutabilitas, §. 440, 437, etiam hypothetica, §. 104, 127.","glosses":[],"marks":[],"aaEnd":120},
 {"num":448,"section":"parsii-capiii-secii","aa":120,"ed":148,"text":"Cum in hoc mundo sit harmonia, §. 356, sit influxus universalis, §. 408, aut erit hic ubique realis, aut ubique idealis, aut aliquando realis, aliquando idealis, §. 212. Harmonia monadum mundi in se mutuo influentium est substantiarum mundanarum commercium@@1@@. Ergo substantiae omnis et huius mundi sunt in universali commercio, §. 357. Sententiae, huic explicando aptae quae videntur, systemata explicandi commercii inter substantias mundi@@2@@ dicuntur, eaque si explicando omni omnium commercio adhibeantur, universalia@@3@@, cf. §. 761 (generalia). Mutationes partium mundi in commercio positarum, quarum in una parte commercii evenientium cognosci potest ratio sufficiens ex vi alterius partis commercii, sunt harmonicae@@4@@. Influxus omnium substantiarum mundi in se invicem idealis est harmonia praestabilita universalis@@5@@, cf. §. 462, eamque ponens in hoc mundo, est harmonista universalis, cuius systema vocatur systema harmoniae praestabilitae universalis@@6@@.","glosses":["die Verbindung des in einer ganzen Welt vor sich bestehenden","Meinungen von der Art und Weise solcher Verbindung","allgemeine","übereinstimmende Veränderungen","die allgemeine vorherbestimmte Übereinstimmung","die Meinung der allgemeinen vorherbestimmten Übereinstimmung"],"marks":["*","**","***","****","*****","******"]},
 {"num":449,"section":"parsii-capiii-secii","aa":120,"ed":149,"text":"Systema harmoniae praestabilitae universalis non tollit influxum substantiarum huius mundi in se invicem, sed eum ponit, §. 448, non tollit unam mundi substantiam pati ab altera, §. 448, 212, sed quamlibet tamen mutationem suam, quam ab altera substantia huius mundi patitur, vi sua producere ponit, §. 210, non tollit partium huius mundi conflictum mutuum, §. 213, facultatem receptivitatemque actionum transeuntium, §. 217, multo minus influxum substantiae infinitae, receptivitatemque illius influxus in finitis, §. 448, non solum non tollit agere posse spiritus in corpora, et corpora in spiritus, sed ponit etiam in hoc mundo corpora et spiritus in se mutuo influere, §. 408, 434, seque posse mutuo contingere, §. 223, 409.","glosses":[],"marks":[]},
 {"num":450,"section":"parsii-capiii-secii","aa":120,"ed":null,"text":"Influxus realis substantiae mundi partis in aliam mundi partem est physicus. Hinc influxus physicus universalis est universalis substantiarum in mundo harmonia, qua una in alteram realiter influit, eumque ponens in hoc mundo est influxionista universalis. Huius systema est systema influxus physici universalis.","glosses":[],"marks":[]},
 {"num":451,"section":"parsii-capiii-secii","aa":120,"ed":150,"text":"Systema influxus physici universalis non tollit harmoniam substantiarum mundi mutuam eamque universalem, §. 450, 48, sed praestabilitam, §. 448. Non omnis, qui ponit substantias huius mundi in se mutuo influere, inter se confligere, a se invicem pati, et utrumque posse corpora respectu spirituum, spiritus respectu corporum, immo se posse mutuo contingere, est influxionista universalis, §. 449, 450. Influxionista universalis 1) negat ullam substantiam huius mundi, quando patitur ab alia substantia huius mundi, agere et passiones suas vi sua producere, §. 450, 212, 2) ponit realiter passiones unius substantiae huius mundi produci ab altera substantia huius mundi in eam influente, §. 450. Hinc per systema influxus physici universalis nulla substantia, pars mundi, in ullis suis mutationibus harmonicis agit vi propria, §. 448. Iam vero omnes mutationes substantiae mundanae possunt ex vi cuiuscumque alius monados ad eundem mundum pertinentis sufficientur cognosci, §. 354, 400. Ergo omnes sunt harmonicae, §. 448, et hinc in nullis suis mutationibus ulla substantia mundana agit, ex systemate influxus physici universalis, in omnibus realiter patiens ab aliis substantiis mundanis, quae tamen ob eandem rationem prorsus non agerent, §. 210, hinc nec vires essent, §. 197, q.c., §. 199.","glosses":[],"marks":[],"aaEnd":121},
 {"num":452,"section":"parsii-capiii-secii","aa":121,"ed":151,"text":"Qui ponit in omnes substantias huius mundi pati visas ab aliis huius mundi substantiis, et realiter quidem patientes, ex ipsius sententia, solam realiter influere substantiam infinitam, est occasionalista (assistentianus) universalis, eiusque systema est systema causarum occasionalium universale@@1@@ (Cartesianum, s. Malebranchianum potius assistentiae), contradicens §. 400, 408, hinc falsum. Idem patet inde, quod per occasionalismum nulla mutatio harmonica in substantia ulla mundana est ipsius, sed tantum substantiae infinitae actio, §. 448. Hinc etiam hoc systema omnem in finitis tollit vim et energian, §. 451.","glosses":["die Meinung der allgemeinen sogenannten nur gelegentlichen Ursachen"],"marks":["*"]},
 {"num":453,"section":"parsii-capiii-secii","aa":121,"ed":null,"text":"Systema causarum occasionalium, nisi harmoniam, influxum tamen mutuum substantiarum huius mundi universalem verum tollit, §. 452, 448, hunc physicum, §. 450, et idealem, §. 212 (nisi sic dicas imaginarium apparentem, §. 12), illam praestabilitam, §. 448. Non omnis, qui ponit substantiam infinitam in omnes finitarum substantiarum passiones realiter influere, nec omnis ille, qui substantiam infinitam solam in eas realiter influere ponit, est occasionalista universalis, sed qui ponit 1) reales esse passiones substantiarum finitarum omnes, 2) a solo influxu substantiae infinitae dependere, §. 452.","glosses":[],"marks":[]},
 {"num":454,"section":"parsii-capiii-secii","aa":121,"ed":152,"text":"Systemata harmoniae praestabilitae et influxus physici universalium in hoc sunt similia, §. 70, ut 1) nec influxum mutuum substantiarum huius mundi, nec harmoniam, nec influxum substantiae infinitae in easdem realem tollant universales, §. 448, 450, 2) passiones substantiarum huius mundi ponant esse actiones alicuius substantiae finitae; in eo sunt dissimilia, ut posterius excludat ab actione patientem substantiam, prius non excludat, §. 449, 451.","glosses":[],"marks":[]},
 {"num":455,"section":"parsii-capiii-secii","aa":121,"ed":null,"text":"Systema harmoniae praestabilitae et causarum occasionalium universalia in eo sunt similia, ut tollant influxum realem substantiae huius mundi in aliam, eiusdem partem, §. 70, in eo sunt dissimilia, §. 70, ut prius ideales ponat passiones quasdam earum, quas posterius reales ponit, §. 449, 453.","glosses":[],"marks":[]},
 {"num":456,"section":"parsii-capiii-secii","aa":121,"ed":null,"text":"Systema influxus physici et causarum occasionalium universalia in eo sunt similia, ut passiones unius in hoc mundo substantiae ab altera eiusdem mundi parte utrumque ponat reales; in eo sunt dissimilia, §. 70, ut prius influere solam substantiam infinitam in eas tollat, ponat posterius, §. 451, 452.","glosses":[],"marks":[]},
 {"num":457,"section":"parsii-capiii-secii","aa":121,"ed":153,"text":"Systemata explicandi substantiarum mundanarum commercium universalia, si singula singularum mundi substantiarum commercia simili modo explicant, simplicia@@1@@ dicuntur. Ergo systema harmoniae praestabilitae, influxus physici et causarum occasionalium universalia sunt systemata simplicia, §. 448, 456. Systemata universalia composita@@2@@ sunt, quae quaedam quarundam substantiarum mundi commercia diverso modo, quam alia, explicant.","glosses":["die allgemeine Meinungen von der Art und Weise der Verbindung des vor sich bestehenden in einer ganzen Welt sind entweder einfach","oder zusammengesetzt"],"marks":["*","**"],"aaEnd":122},
 {"num":458,"section":"parsii-capiii-secii","aa":122,"ed":null,"text":"Praeter harmoniae praestabilitae, influxus physici, et causarum occasionalium systemata universalia, quartum aliquod simplex universale, §. 457, non est possibile, §. 448, 452, infinita seu potius indefinita possunt esse composita, §. 457, 248.","glosses":[],"marks":[]},
 {"num":459,"section":"parsii-capiii-secii","aa":122,"ed":154,"text":"Per harmoniam praestabilitam, influxum plurium substantiarum mundi in commercio positarum idealem in se invicem maior nexus actuatur, quam per influxum earundem physicum, §. 167. Nam in influxu physico passio realiter patientis non habet rationem sufficientem in patientis viribus, §. 450, 212. In harmonia praestabilita habet passio patientis substantiae rationem sufficientem 1) in ipsius viribus, 2) in idealiter influente substantia, §. 449. Hinc substantia influens in harmonia praestabilita est aeque fecunda, ac in influxu physico, substantia vero patiens est in harmonia praestabilita fecundior, quam in influxu physico, §. 166.","glosses":[],"marks":[]},
 {"num":460,"section":"parsii-capiii-secii","aa":122,"ed":null,"text":"Per influxum substantiae infinitae soli tributum in substantias in commercio positas realiter patientes, quicquid patiuntur, substantia patiens non est fecundior, quam per influxum physicum, §. 453, altera autem pars commercii finita adhuc minus fecunda, §. 453, 166. Ergo per harmoniam praestabilitam coniunctam cum concursu substantiae infinitae maior nexus actuatur in substantiis in commercio positis, quam per influxum soli infinitae substantiae tributum, §. 167.","glosses":[],"marks":[]},
 {"num":461,"section":"parsii-capiii-secii","aa":122,"ed":155,"text":"In mundo perfectissimo est nexus possibilium in mundo maximus, §. 441. Ergo substantiae, quae et quot possunt in eo, connectuntur per harmoniam praestabilitam coniunctam cum concursu substantiae infinitae, §. 460, 459.","glosses":[],"marks":[]},
 {"num":462,"section":"parsii-capiii-secii","aa":122,"ed":null,"text":"Si harmonia praestabilita universalis coniuncta cum concursu substantiae infinitae est in mundo perfectissimo possibilis, est ille, qualem harmonista universalis hunc ponit esse, §. 448, 461, nec est, qualemcumque systema quoddam compositum adoptaturus concipiat, §. 451, omnis contra particularis harmonia praestabilita@@1@@, i.e. quarundam mundi partium, in eodem admittenda est, §. 154.","glosses":["besondre vorherbestimmte Übereinstimmung"],"marks":["*"],"aaEnd":123},
 {"num":463,"section":"parsii-capiii-secii","aa":123,"ed":156,"text":"Cum harmoniae praestabilitae universalis condicio, sine qua non, sit possibilitas eius in mundo perfectissimo, haec demonstranda est harmoniam praestabilitam demonstraturo per §. 462. Alias ita patet: ex quavis cuiusvis mundi monade singulae mundi, ad quem pertinet, partes cognosci possunt, §. 400, ergo et singulae mutationes mundanae, §. 354, 155. Tales autem sunt omnes passiones cuiusvis monadis mundanae, quam ab alia sui mundi monade patitur, §. 210. Monas autem patiens est vis, §. 199. Ergo ipsa illa monas ab alia monade mundana patiens est ratio huius passionis suae, et singularum eius partium, §. 354, 155, hinc ratio huius suae passionis sufficiens, §. 14, 21, adeoque data passio ipsius simul est patientis actio, §. 210. Ergo passiones omnes monadum cuiusvis mundi, quas ab aliis monadibus mundanis patiuntur, sunt tantum ideales, §. 212. Ergo talis etiam semper influxus monadis mundanae in aliam, numquam realis, numquam physicus, §. 450. Hinc in hoc etiam mundo omnes eius substantiae sunt tantum per harmoniam praestabilitam in commercio universali, §. 448, nullae umquam per influxum physicum. Systema harmoniae praestabilitae universalis est vera sententia, ergo et omnis particularis harmonia praestabilita vera est, §. 462, omnis et universalis et particularis influxus physicus, et eius systema, §. 450, et systema causarum occasionalium, §. 452, falsa sunt.","glosses":[],"marks":[]},
 {"num":464,"section":"parsii-capiii-secii","aa":123,"ed":157,"text":"In mundo perfectissimo nexus est, qui in mundo possibilis, maximus, §. 441. Ergo si sunt in mundo perfectissimo corpora et spiritus, §. 438, est nexus mechanicus, pneumaticus, et pneumaticomechanicus in eodem maximus, §. 441 (maxima regni naturae et gratiae harmonia, §. 434, 403, praestabilita, §. 463).","glosses":[],"marks":[]},
 {"num":465,"section":"parsii-capiii-secii","aa":123,"ed":null,"text":"Dualista est, qui ponit hunc mundum constare spiritibus et corporibus extra se. Hinc mundus perfectissimus non egoisticus, non idealisticus, §. 438, est, qualem hunc dualista concipit, §. 439.","glosses":[],"marks":[],"aaEnd":124},
 {"num":466,"section":"parsii-capiii-seciii","aa":124,"ed":null,"text":"Complexus naturarum in singulis et simul sumptis partibus mundi est natura universa (naturata, cf. §. 859). Hinc natura huius et perfectissimi universi est aggregatum seu complexus omnium essentialium, essentiarum, facultatum, receptivitatum, virium, quibus omnes eius partes, monades, elementa, spiritus, materiae, corpora instructa sunt, §. 430, hinc omnis omnium in eo corporum modus compositionis, vis inertiae, vis motrix, et mechanismus est pars naturae universae, §. 431, 433.","glosses":[],"marks":[]},
 {"num":467,"section":"parsii-capiii-seciii","aa":124,"ed":158,"text":"Essentia mundi eiusque compositi modus compositionis, §. 226, cum essentiis singularum eius partium, non est, nisi pars, satis parva, §. 161, naturae universae, §. 466, 155.","glosses":[],"marks":[]},
 {"num":468,"section":"parsii-capiii-seciii","aa":124,"ed":null,"text":"Natura universa habet partes internas mutabiles, §. 466, easque perfectissimi mundi natura universa plurimas, §. 437. Hinc natura universa cuiusvis mundi est ens contingens, §. 131, et finitum, §. 255, et perfectissimi quidem mundi natura universa habet contingentiam mathematice ter infinitam, §. 447.","glosses":[],"marks":[]},
 {"num":469,"section":"parsii-capiii-seciii","aa":124,"ed":159,"text":"Eventus ab ullius entis contingentis natura actuandus est naturalis supernaturali contradistinctus, cf. §. 474. At eventus a determinata determinati entis contingentis natura actuandus est naturalis, praeternaturali, cf. §. 474, contradistinctus. Quicquid ab alicuius natura actuari potest, est ipsi physice possibile, quicquid non potest, est ipsi physice impossibile. Quaedam in se possibilia non tamen a quavis natura actuari possunt, §. 15, 430, ergo multis possunt esse physice impossibilia. Non omne physice nonnullis impossibile est et absolute tale. Physice alicui contingenti impossibilia sunt talia aut in quocumque eius natura spectetur statu, naturaliter impossibilia simpliciter (mere, omnino, prorsus), aut tunc demum, si in certo statu spectetur eius natura, naturaliter impossibilia secundum quid (pro nunc et sic). Impossibilitas naturalis simpliciter talis realitatum est impotentia mere naturalis. Non omnis impossibilitas naturalis est impotentia mere naturalis aut absoluta impossibilitas, §. 467. Oppositum physice impossibilis est physice necessarium, physice possibilis physice contingens. Non omne physice necessarium est absolute necessarium, §. 102. Quaedam in se contingentia possunt multis esse physice necessaria, §. 104. Physice necessaria vel sunt simpliciter, vel secundum quid talia.","glosses":[],"marks":[]},
 {"num":470,"section":"parsii-capiii-seciii","aa":124,"ed":160,"text":"Naturale certo corpori est a determinata eius natura actuandum, certo mundo corporeo est, quod per naturam corporum certi mundi universam actuandum, §. 466. Naturale certo spiritui contingenti est per determinatam eius naturam actuandum. Naturale certo mundo pneumatico est, quod per naturam spirituum certi mundi universam actuandum est, §. 469.","glosses":[],"marks":[]},
 {"num":471,"section":"parsii-capiii-seciii","aa":124,"ed":null,"text":"Successio naturalium in mundo est cursus naturae. Hinc cursus naturae opponitur successioni vel supernaturalium, vel praeternaturalium, §. 469, et vel in aliquo corpore, vel in toto aliquo mundo corporeo, vel in spiritu aliquo, vel in toto aliquo mundo pneumatico, vel in universa natura spectatur, §. 470, 466.","glosses":[],"marks":[]},
 {"num":472,"section":"parsii-capiii-seciii","aa":124,"ed":161,"text":"Ordo naturalium in mundo est ordo naturae, isque vel supernaturalium, vel praeternaturalium opponitur coniunctioni, et vel in certo tantum corpore, vel mundo corporeo, vel spiritu, vel mundo pneumatico spectatur, §. 469, 470, vel in universa natura, §. 466. Horum ordinum singuli normas suas communes habent, §. 86. Ergo sunt in hoc mundo normae naturalis ordinis leges regulaeque communes, §. 432, diversae, §. 38, at similes, §. 70. Complexus legum similium ius@@1@@ est, cf. §. 971 (latius dictum). Legum ordinis naturae complexus ius naturae latissimum est, huius partes sunt leges regulaeque motus, §. 432, legesque naturae spirituum.","glosses":["ein Recht"],"marks":["*"],"aaEnd":125},
 {"num":473,"section":"parsii-capiii-seciii","aa":125,"ed":null,"text":"Naturale si sequatur naturale, evenit secundum cursum naturae, idque secundum cursum naturae vel certi corporis, vel certi nexus in certo mundo materialis, vel certi spiritus, vel certi nexus in certo mundo pneumatici etiam §. 471, vel saltim secundum cursum naturae universae, §. 466, si succedat, vel coexsistat naturali, evenit secundum ordinem naturae, idque secundum ordinem naturae vel certi corporis, vel certi nexus in certo mundo materialis, vel certi spiritus, vel certi nexus in certo mundo pneumatici etiam, §. 472, vel saltim secundum ordinem naturae universae, §. 466. Ergo naturale succedens et coexsistens naturalibus actuatur secundum leges naturales, §. 472. Naturale certo corpori, aut certo nexui in mundo materiali secundum leges regulasque motus per mechanismum corporum actuatur, §. 433, hinc explicari potest mechanice, §. 435, 433.","glosses":[],"marks":[]},
 {"num":474,"section":"parsii-capiii-seciiii","aa":125,"ed":null,"text":"Eventus mundi a nullius entis contingentis natura actuatus supernaturalis est. Eventus a determinata certi entis contingentis, in quo evenit, natura non actuatus, respectu illius entis praeternaturalis est. Hinc supernaturalia sunt praeternaturalia respectu naturae universae; et praeternaturalia respectu naturae universae sunt supernaturalia, §. 466. Eventus supernaturalis, qua spectatur ut extraordinarius, est miraculum@@1@@. Hinc miraculum est praeternaturale respectu naturae universae. Omne miraculum est supernaturale, sed non omne supernaturale refertur ad miracula.","glosses":["ein Wunder, Wunderwerk"],"marks":["*"]},
 {"num":475,"section":"parsii-capiii-seciiii","aa":125,"ed":null,"text":"Supernaturalia et miracula sunt naturalium, et naturaliter ordinariorum opposita, §. 81, 474. Iam naturalia et naturaliter ordinaria in omni mundo sunt contingentia, §. 354, 257. Ergo supernaturalia et miracula sunt possibilia, §. 101.","glosses":[],"marks":[]},
 {"num":476,"section":"parsii-capiii-seciiii","aa":125,"ed":163,"text":"Quae per naturam entis contingentis in mundo actuantur, non sunt supernaturalia, nec miracula, §. 474. Hinc per naturam spiritus, qui pars mundi est, actuata non sunt supernaturalia, non miracula, §. 354, 257.","glosses":[],"marks":[],"aaEnd":126},
 {"num":477,"section":"parsii-capiii-seciiii","aa":126,"ed":null,"text":"Actiones spirituum finitorum in alias mundi partes, per determinatam naturam patientium non actuatae, hinc respectu patientium praeternaturales, §. 474, et extraordinariae, §. 472, 384, non sunt tamen supernaturales, nec miracula, §. 474. Hinc si dicuntur miracula comparativa@@1@@, miracula comparativa non sunt miracula, quae illis contradistinguenda rigorosa@@2@@ vocantur. Si tales actiones supra naturam ponantur, id tantum de certa certi corporis mundive corporei natura concedi potest, §. 470.","glosses":["Vergleichungs-Weise","nach der Strenge sogenannte Wunder"],"marks":["*","**"]},
 {"num":478,"section":"parsii-capiii-seciiii","aa":126,"ed":164,"text":"Cuius causam naturalem nos non novimus, eventus extraordinarius est prodigium@@1@@ (signum, cf. §. 347, ostentum, portentum). Prodigia sunt vel miracula rigorosa, §. 474, 477, vel naturales eventus, miracula quoad nos@@2@@.","glosses":["ein geschehendes Zeichen","Wunder nach der Fassung des Wahrnehmenden"],"marks":["*","**"]},
 {"num":479,"section":"parsii-capiii-seciiii","aa":126,"ed":null,"text":"Supernaturalia et miracula cum per universam naturam non actuentur, §. 474, 466, et sint tamen entia contingentia, §. 474, 354, hinc effectus, §. 334, quando exsistunt, habent causam efficientem ens extramundanum, §. 388, de quo testantur, §. 333.","glosses":[],"marks":[]},
 {"num":480,"section":"parsii-capiii-seciiii","aa":126,"ed":165,"text":"Contra cursum naturae evenit eventus non naturalis naturalibus succedens, §. 471, 473. Iam supernaturale et miraculum non est eventus naturalis, §. 474, 469. Ergo supernaturale et miraculum fit contra cursum naturae naturalibus succedens, et quidem contra cursum naturae universae, §. 471. Praeternaturale certo corpori, aut certo mundo corporeo, certo spiritui, aut certo mundo pneumatico fit contra cursum naturae aliquem tantum, §. 474, 471. Hinc non omne contra qualemcumque cursum naturae eveniens est supernaturale, vel miraculum, §. 474.","glosses":[],"marks":[]},
 {"num":481,"section":"parsii-capiii-seciiii","aa":126,"ed":null,"text":"Supernaturalia et miracula non sunt absolute extraordinaria, §. 475, 385, nec contra ordinem mundi omnem, §. 359, 7, nec tamen sunt naturaliter ordinaria, §. 472, 474. Cumque eventus non naturalis naturalibus coexsistens vel succedens evenit contra ordinem naturae, supernaturalia et miracula sunt contra omnem ordinem naturae universae. Ergo non eveniunt secundum normas certi ordinis naturae communes, §. 472. Ergo sunt relative ad ordinem naturae extraordinaria, §. 384. Supernaturalia et miracula sunt extraordinaria respectu ordinis naturae universae, §. 472. Praeternaturale est extraordinarium respectu certi corporis, aut mundi corporei, certi spiritus, aut nexus pneumatici, et ordinis naturae in iisdem determinati, §. 474, 472, ita, ut contra hunc eveniat, §. 384. Ergo non omne extraordinarium respectu qualiscumque ordinis naturae, non omne, quod est contra qualemcumque naturae ordinem, est supernaturale, multo minus miraculum, §. 474.","glosses":[],"marks":[],"aaEnd":127},
 {"num":482,"section":"parsii-capiii-secv","aa":127,"ed":null,"text":"Lex ordinis in mundo perfectissimo, §. 84, eaque una ex superioribus, §. 182, haec est: Optimum compossibilium in mundo perfectissimo coniungatur optimo, §. 444. Haec lex dicitur lex optimi in mundo, cf. §. 822, cui subordinatur lex optimi in natura: optimum naturalium in mundo perfectissimo coniungatur optimo, §. 469, 444.","glosses":[],"marks":[]},
 {"num":483,"section":"parsii-capiii-secv","aa":127,"ed":null,"text":"Pone in mundo perfectissimo eventum naturalem, hinc secundum ordinem naturae eventurum, §. 473, reliquis compossibilem. Pone sub iisdem circumstantiis eventum supernaturalem, hinc contra omnem ordinem naturae eventurum, §. 481, reliquis compossibilem, sed naturali meliorem. Cum oppositi, naturalis et supernaturalis, e.g. miraculosus, eventus simul exsistere nequeant, §. 81, in hoc casu regulae ordinis naturae universae, et superior regula perfectionis, §. 482, collidentur, §. 97.","glosses":[],"marks":[]},
 {"num":484,"section":"parsii-capiii-secv","aa":127,"ed":167,"text":"Regulae ordinis naturae, et peculiaris, et universae, cum in mundo perfectissimo sint inferiores et subordinatae legi optimi in mundo, §. 182, 482, in casu per §. 483 posito fiet exceptio a legibus ordinis naturae, §. 446, et fiet supernaturale quid, immo miraculum, §. 483, ordini mundi perfectissimi summo convenientissime, §. 444.","glosses":[],"marks":[]},
 {"num":485,"section":"parsii-capiii-secv","aa":127,"ed":null,"text":"Supernaturalia et miracula per saltum absolutum essent impossibilia, §. 387, hinc supernaturalia nulla, miracula nulla fiunt per saltum absolutum, §. 475. Cum tamen eventuum in mundo naturaliter ordinaria ratio sufficiens proxima sit natura cuiusdam entis contingentis, §. 472, 469, quando eveniunt supernaturalia et miracula, eveniunt per saltum respectivum, §. 474, 386.","glosses":[],"marks":[]},
 {"num":486,"section":"parsii-capiii-secv","aa":127,"ed":null,"text":"Supernaturalia et miracula in mundo corporeo evenientia mechanice explicari non possunt, §. 435, 433, multo minus pneumatica, in mundo pneumatico (regno gratiae) evenientia, §. 433, 403.","glosses":[],"marks":[]},
 {"num":487,"section":"parsii-capiii-secv","aa":127,"ed":168,"text":"Si pro eventu naturali in mundo ponatur supernaturalis et miraculosus, non est mundus totaliter idem, qui esset, si naturalis eventus pars eius esset, §. 267, 155. Ergo posito supernaturali et miraculo in mundo, pro effectu naturali, ponitur status mundi supernaturali dato, vel miraculo coexsistens partialiter alius, quam esset supernaturali vel miraculo non patrato, §. 378, 369.","glosses":[],"marks":[],"aaEnd":128},
 {"num":488,"section":"parsii-capiii-secv","aa":128,"ed":null,"text":"Nihil prorsus sterile, §. 23, hinc nullum supernaturale, nullum miraculum est sine corollario, seu rationato, posito hoc, ponitur iterum aliquid, §. 14, hinc eius denuo rationatum, §. 23, et sic porro. Ergo omnis supernaturalis, omnis miraculi ponuntur consectaria in indefinitum, §. 248, per status mundi post eventum supernaturalem, post miraculum successivos, §. 30, 369.","glosses":[],"marks":[]},
 {"num":489,"section":"parsii-capiii-secv","aa":128,"ed":169,"text":"Si pro eventu supernaturali, pro miraculo positus in mundo fuisset in casu §. 487, 488 memorato eventus naturalis, habuisset et hic sua rationata in indefinitum per omnes mundi status succedentes ipsi, §. 23, 369, sed consectaria effectus naturalis et supernaturalis vel miraculosi non possunt esse totaliter eadem, §. 267, 38. Ergo posito supernaturali, posito miraculo in mundo pro effectu naturali omnes mundi status eventui supernaturali, vel miraculo succedentes sunt partialiter alii, quam fuissent dato supernaturali, vel miraculo non patrato, §. 369.","glosses":[],"marks":[]},
 {"num":490,"section":"parsii-capiii-secv","aa":128,"ed":null,"text":"In systemate occasionalismi omnis passio substantiae finitae supernaturalis est, §. 474, 453, licet quaedam concipi possit, quae non sit miraculum, quatenus spectatur, ut ordinaria, §. 384.","glosses":[],"marks":[]},
 {"num":491,"section":"parsii-capiii-secv","aa":128,"ed":null,"text":"Supernaturale et miraculum cum sit actio, §. 474, 323, erit vel simplex, vel compositum, §. 215, et hoc quidem vel ens simultaneum, vel ens successivum, vel utrumque, §. 238. Tam simplex, quam compositum, modo ens simultaneum, evenit in instanti, destitutum prioribus posterioribusque partibus, §. 300.","glosses":[],"marks":[]},
 {"num":492,"section":"parsii-capiii-secv","aa":128,"ed":null,"text":"Quo fecundius, quo nobilius supernaturale et miraculum, §. 166, hoc maius est, §. 491, 214, hinc maximum erit fecundissimum, nobilissimum, et maxime compositum, §. 214, 215.","glosses":[],"marks":[]},
 {"num":493,"section":"parsii-capiii-secv","aa":128,"ed":170,"text":"Naturalista latius dictus, cf. §. 999, est, qui in hoc mundo supernaturales omnes eventus tollit. Ergo tollit miraculorum in hoc mundo exsistentiam, §. 474, si id facit, ob negatam eorundem possibilitatem, errat, §. 475.","glosses":[],"marks":[]},
 {"num":494,"section":"parsii-capiii-secv","aa":128,"ed":null,"text":"Posita natura huius mundi, uti est, extensionis intensionis protensionis mathematice infinitae, §. 440, 466, est et infinitae eiusmodi contingentiae, §. 468, 361, nec potest exsistere, nisi ut effectus causae extramundanae, de qua testatur, §. 375, sicut supernaturalia et miracula, quando exsistunt, §. 479. Hinc limites suae theoriae de natura huius mundi universa non confundens cum limitibus dictae naturae ipsius, nec inde secure concludens ex sua tantum ignorantia causae naturalis ad hanc omnino negandam: non est ideo iam iniurius in causam universae naturae supernaturalibus et miraculis communem, §. 375, 479, neque naturalista, §. 493.","glosses":[],"marks":[],"aaEnd":129},
 {"num":495,"section":"parsii-capiii-secv","aa":129,"ed":171,"text":"Pone eventum naturalem et supernaturalem in mundo perfectissimo sub iisdem circumstantiis reliquis mundi partibus compossibilem, sed, qua consectaria, aequaliter bonos. Naturalis aeque satisfaciet legi optimi in mundo ac supernaturalis, §. 482, simulque regulis perfectionis, quas ordo naturae praescribit, §. 472, hinc pluribus, quam supernaturalis, §. 481. In hoc ergo casu non fiet supernaturale quid, vel miraculum in mundo perfectissimo, §. 482, 445.","glosses":[],"marks":[]},
 {"num":496,"section":"parsii-capiii-secv","aa":129,"ed":null,"text":"Cum natura etiam perfectissimi mundi universa sit finita, §. 468, non est principium omnium accidentium, quae mundo optimo inhaerere possunt, sufficiens, §. 430, 259. Pone ergo eventum reliquis in mundo optimo compossibilem optimis optimum, sed naturaliter et ordinario non actuandum, pone eundem supernaturaliter et extraordinario actuari posse; fiet in hoc etiam casu, ut §. 484, supernaturale quid, immo miraculum ordini mundi perfectissimi convenientissime, §. 482, 444.","glosses":[],"marks":[]},
 {"num":497,"section":"parsii-capiii-secv","aa":129,"ed":172,"text":"Quot et quanta possunt in mundo optimo optima evenire naturaliter, et ordinario fiunt in eodem naturaliter, §. 495. Quot et quanta aut prorsus non possunt in eodem, aut non aeque bene evenire naturaliter et ordinario, fiunt in eodem optima supernaturaliter et miraculose, §. 484, 496. Priora miracula dici possunt miracula supplentia@@1@@, posteriora emendantia@@2@@. Par est ratio supernaturalium.","glosses":["ergänzende","ausbessernde Wunder"],"marks":["*","**"]},
 {"num":498,"section":"parsii-capiii-secv","aa":129,"ed":null,"text":"Numerus supernaturalium et miraculorum in mundo perfectissimo tantus est, quantus possibilium eius numerus, quae naturaliter et secundum ordinem naturae aeque bene actuari nequeunt, §. 159, 497, nec maior, nec minor, §. 160.","glosses":[],"marks":[]},
 {"num":499,"section":"parsii-capiii-secv","aa":129,"ed":null,"text":"Si quis umquam supernaturalis eventus in mundo optimo melior est, quam naturalis, qua consectaria etiam, si quis umquam eventus possibilis mundi optimi est naturaliter per naturam universam impossibilis: mundus perfectissimus non est, qualem hunc naturalista significatu generaliori statuit, §. 498, 493.","glosses":[],"marks":[],"aaEnd":130},
 {"num":500,"section":"parsii-capiii-secv","aa":130,"ed":173,"text":"Non omnis, qui quaedam praeternaturalia, §. 474, spirituum finitorum effectus extraordinarios, §. 476, miracula comparativa, §. 477, prodigia et miracula quoad nos, §. 478, contra cursum naturae, §. 480, et ordinem aliquem evenientia, §. 481, negat esse miracula in hoc mundo, §. 474, est naturalista significatu generaliori talis, §. 493.","glosses":[],"marks":[]},
 {"num":501,"section":"parsiii-proleg","aa":130,"ed":null,"text":"Psychologia est scientia praedicatorum animae generalium.","glosses":[],"marks":[]},
 {"num":502,"section":"parsiii-proleg","aa":130,"ed":null,"text":"Psychologia principia theologiarum, aestheticae, logicae, practicarum scientiarum prima continens, cum ratione, §. 501, refertur, §. 2, ad metaphysicam, §. 1.","glosses":[],"marks":[]},
 {"num":503,"section":"parsiii-proleg","aa":130,"ed":null,"text":"Psychologia asserta sua 1) ex experientia propius, empirica, 2) ex notione animae longiori ratiociniorum serie deducit, rationalis.","glosses":[],"marks":[],"aaEnd":131},
 {"num":700,"section":"parsiii-capi-secxviiii","aa":131,"ed":271,"text":"Mutor, §. 505-699, interne, §. 126. Ergo sum ens finitum, §. 254, et contingens, §. 257. Ergo exsistentia mea modus est, §. 134, adeoque status mei omnes sunt in se contingentes, §. 205, 108. Ergo etiam mutationes eorum omnium, §. 124, 125. Ergo omnes actiones meae, omnes passiones sunt in se contingentes, §. 210. Hinc et omnes actiones meae futurae, §. 298. Hinc nullae actiones meae, nullae passiones sunt absolute vel intrinsecus necessariae, §. 105.","glosses":[],"marks":[]},
 {"num":701,"section":"parsiii-capi-secxviiii","aa":131,"ed":null,"text":"Necessitatio@@1@@ (coactio) est mutatio alicuius ex contingenti in necessarium, hinc est vel activa@@2@@ necessitantis, quod non est proprie, nisi substantia, §. 198, vel passiva@@3@@ necessitati, quae tribuitur tum accidentibus, vel actioni vel passioni, quae mutantur ex contingentibus in necessaria, tum substantiae, cui eiusmodi necessitata accidentia insunt.","glosses":["die Nöthigung","die vorgenommene","die gelittene"],"marks":["*","**","***"]},
 {"num":702,"section":"parsiii-capi-secxviiii","aa":131,"ed":272,"text":"Necessitatio (coactio) absoluta@@1@@ foret, quae in se contingens mutaret in absolute necessarium. Iam nihil potest mutari in absolute necessarium, §. 130. Ergo nec ulla actio, ergo nec ulla mea actio. Ergo absoluta necessitatio ullius actionis meae est impossibilis, §. 7. Omnes actiones meae sunt manentque semper, in ipso actu, et post eum in se contingentes, hinc et oppositum earum in se possibile, §. 700, 104.","glosses":["an und vor sich nothwendig machen, eine unbedingte Nöthigung"],"marks":["*"]},
 {"num":703,"section":"parsiii-capi-secxviiii","aa":131,"ed":null,"text":"Oppositi multarum actionum mearum admodum magna est possibilitas hypothetica, §. 168. Hinc multarum mearum actionum admodum magna est contingentia, etiam hypothetica, §. 188, 700. Hinc futurae sunt futura admodum contingentia, §. 298.","glosses":[],"marks":[]},
 {"num":704,"section":"parsiii-capi-secxviiii","aa":131,"ed":null,"text":"Actio a sufficienti principio, quod agenti internum est, dependens est spontanea@@1@@. Unde spontaneitas tribuitur, 1) actioni, quae a principio sufficienti, quod agenti internum est, dependet, 2) substantiae eiusmodi actiones patranti. Iam omnis actio proprie talis a principio, quod agenti internum est, dependet, §. 210, 37. Ergo omnis actio proprie talis est spontanea. Quoniam tamen mutationes ex actionibus passionibusque compositae nonnumquam a potiori denominantur actiones, quatenus passiones sunt, concipiuntur, ut non spontaneae, §. 210.","glosses":["eine selbstthätige Handlung"],"marks":["*"]},
 {"num":705,"section":"parsiii-capi-secxviiii","aa":131,"ed":273,"text":"Multae actiones meae, immo omnes proprie dictae, hinc et actiones animae meae sunt spontaneae, adeoque vere tam illis, quam animae meae tribuitur spontaneitas, §. 704. Si automaton dicatur se ipsum mutans, anima erit automaton.","glosses":[],"marks":[]},
 {"num":706,"section":"parsiii-capi-secxviiii","aa":131,"ed":null,"text":"Spontaneitas minima est, si principium agenti intrinsecum ad unam tantum minimam actionem sufficit, §. 704, 161. Ad quo plures ergo, ad quo maiores actiones principium agenti intrinsecum sufficit, hoc maior est eius spontaneitas, donec sit maxima in eo agente, in quo ad plurimas maximas actiones sufficit. Animae meae admodum magna convenit spontaneitas, §. 705.","glosses":[],"marks":[],"aaEnd":132},
 {"num":707,"section":"parsiii-capi-secxviiii","aa":132,"ed":274,"text":"Necessitatio externa@@1@@ (coactio ab extra) est dependens a vi extra substantiam necessitatam exsistente, estque vel idealis, vel realis, §. 701, 212. Actio externe realiter necessitata non esset spontanea, nec proprie actio, §. 704, sed realis passio, §. 210. Necessitatio externa realis est necessitatio (coactio) externa simpliciter talis@@2@@. Ergo actiones necessitatione externa simpliciter tali coactae essent passiones reales. Substantia et actiones, quae non absolute necessitantur, sunt liberae (cf. §. 719) a coactione absoluta@@3@@. Substantia et actiones, quae non necessitantur coactione externa simpliciter tali, sunt liberae a coactione externa simpliciter tali@@4@@. Ergo omnes meae mutationes sunt liberae a coactione absoluta, §. 702, omnes actiones meae, omnes actiones animae meae spontaneae, i.e. omnes actiones proprie dictae, §. 704, et anima mea, quatenus sponte agit, sunt liberae a coactione externa simpliciter tali.","glosses":["die äussre Nöthigung","die äussre schlechterdings so genannte Nöthigung","Kraft und Handlung sind frei von unbedingter Nöthigung","Kraft und Handlung sind frei von äussrer schlechterdings so genannter Nöthigung"],"marks":["*","**","***","****"]},
 {"num":708,"section":"parsiii-capi-secxx","aa":132,"ed":275,"text":"Actiones mihi physice possibiles sunt in potestate mea positae@@1@@, realitates mihi physice impossibiles sunt extra potestatem meam positae@@2@@. Ergo est actio quaedam vel simpliciter tantum, vel etiam secundum quid in potestate mea posita, est quaedam vel simpliciter etiam, vel tantum secundum quid extra meam potestatem, §. 469. Actionum in potestate alicuius agentis positarum oppositum aut est etiam in potestate eiusdem agentis positum, aut extra eandem, §. 9, et utrumque denuo vel simpliciter, vel secundum quid, §. 469. Quae ipsae cum suis oppositis, simpliciter saltim, sunt in potestate alicuius positae, sunt ipsi liberae (cf. §. 719) ratione exsecutionis@@3@@, quarum oppositum simpliciter supra potestatem alicuius positum est, sunt ipsi mere naturales. Actio libera ratione exsecutionis, cuius opposito aequalis respectu certi agentis est physica possibilitas, est physice ipsi indifferens@@4@@ (indifferens, qua exercitium actus).","glosses":["Handlungen stehn","stehn nicht in meiner Gewalt","bei denen Thun und Lassen in meiner Gewalt steht","gleich leicht und schwer ist"],"marks":["*","**","***","****"]},
 {"num":709,"section":"parsiii-capi-secxx","aa":132,"ed":276,"text":"Actiones mere naturales sunt naturaliter necessariae. Unde actiones liberae ratione exsecutionis his contradistinctae physice contingentes sunt, §. 708, 469. Hinc futurae nonnumquam futura contingentia@@1@@ simpliciter vocantur.","glosses":["das Zufällig-künftige"],"marks":["*"],"aaEnd":133},
 {"num":710,"section":"parsiii-capi-secxx","aa":133,"ed":277,"text":"Interna necessitatio@@1@@ (coactio) est, quae dependet a determinatione substantiae necessitatae interna, et tribuitur substantiis et earum actionibus, 1) dum actiones substantiarum putantur a sola earundem essentia necessitari, absoluta@@2@@ (essentialis). Eiusmodi necessitatio, dum actiones mutaret in absolute necessarias, §. 702, 107, omnino impossibilis est, §. 702. 2) dum per substantiae naturam quaedam actiones ex physice alias contingentibus mutantur in physice necessarias illi naturae vel simpliciter vel secundum quid tales, §. 469, physica (naturalis). Hinc actiones mere naturales possunt dici necessitatae coactione interna physica, §. 709, 708. Actiones et substantiae neutro ex his significatu interne coactae sunt liberae (cf. §. 719) a necessitatione interna tam absoluta, quam physica@@3@@. Iam vero actiones liberae ratione exsecutionis, et substantiae, quae et quatenus actiones eiusmodi patrant, neutro ex his significatu sunt interne coactae, §. 709, 708, ergo sunt liberae a coactione interna tam absoluta, quam physica.","glosses":["die innre Nöthigung","die wesentliche","frei von der innern so wohl wesentlichen als natürlichen Nöthigung"],"marks":["*","**","***"]},
 {"num":711,"section":"parsiii-capi-secxx","aa":133,"ed":null,"text":"Multae meae actiones, multae actiones animae meae spontaneae sunt liberae ratione exsecutionis, §. 708. Ergo et ipsis et animae, quatenus eas patrat, convenit libertas a coactione externa simpliciter tali, §. 707, et interna, tam absoluta, quam physica, §. 710.","glosses":[],"marks":[]},
 {"num":712,"section":"parsiii-capi-secxx","aa":133,"ed":278,"text":"Lubitus@@1@@ est cognitio, qua substantia pollet, ex qua secundum leges appetitionis aversationisque cognosci potest, cur sic non aliter se determinet circa actionem liberam ratione exsecutionis. At hoc cognosci potest ex praevisione, praesagio, voluptate vel taedio, §. 665, stimulis et motivis, §. 677, 690. Ergo praevisio, praesagium, voluptas vel taedium, stimuli et motiva, quae cognoscuntur a certa substantia, lubitum eius constituunt. Si substantia circa actionem liberam ratione exsecutionis ita vim suam determinat, sicut ex lubitu eius cognosci potest, appetit vel aversatur pro lubitu@@2@@. Qui ergo aut non praevisum, aut id, quod prorsus non praesagierat, ullo nisu suo exstiturum, aut nec placens, nec displicens, sine ullis stimulis, ullis motivis appeteret, vel aversaretur, non appeteret, non aversaretur pro lubitu. Multa appeto, multa aversor pro lubito meo. Ergo habeo facultatem appetendi et aversandi pro lubitu meo, i.e. arbitrium@@3@@. Actiones, quas per arbitrium determinare est in potestate alicuius substantiae positum, ipsi sunt arbitrariae@@4@@. Multae actiones meae sunt arbitrariae.","glosses":["das Belieben","nach Belieben begehren oder abgeneigt sein","Willkür","willkürlich"],"marks":["*","**","***","****"],"aaEnd":134},
 {"num":713,"section":"parsiii-capi-secxx","aa":134,"ed":279,"text":"Lubenter appeto vel aversor@@1@@ 1) quicquid appeto vel aversor pro lubitu, et tunc nihil appeto, nihil aversor illubenter s. invitus@@2@@, §. 712, 665, 2) si lubitus aut merum taedium, aut puram voluptatem, aut ingens superpondium contineat: tunc invitus (illubenter, contra lubitum) appeto vel aversor, ubi non est admodum magnum in lubitu superpondium: seu, ubi ad oppositum eius, quod appeto vel aversor, multa etiam et magna videntur impellere. Ultimo significatu invitus, tamen appeto vel aversor pro lubitu, eoque significatu invita actio tamen est arbitraria, §. 712.","glosses":["ich begehre oder verwerfe gern","ungern"],"marks":["*","**"]},
 {"num":714,"section":"parsiii-capi-secxx","aa":134,"ed":null,"text":"Cum coactio significatu stricto @@1@@, cf. §. 701, sit productio actionis invitae: actio coacta seu invita per coactionem simpliciter sumptam externam @@2@@ esset, quam nullo pro lubitu, contra omnem lubitum, per coactionem externam simpliciter sumptam patrarem, sed haec non esset actio proprie dicta, §. 707. Si quid invitus ago pro lubitu ex §. 713, superpondium eius, quod appeto vel aversor, aut ut a me productum consideratur, et me ipse coegisse @@3@@ dicor, aut ut ab alio extra me, §. 22, et actio dicitur invita seu coacta per coactionem externam secundum quid @@4@@ (mixta, sc. ex arbitraria, et invita per coactionem simpliciter sumptam externam).","glosses":["Zwang in engerer Bedeutung","eine von aussen schlechterdings erzwungene Handlung","ich zwinge mich selbst zu etwas","eine von aussen gewisser Maassen erzwungene Handlung"],"marks":["a","b","c","d"],"aaEnd":135},
 {"num":715,"section":"parsiii-capi-secxx","aa":135,"ed":280,"text":"Actiones invitae, ad quas me cogere dicor ipse, aut externe cogi secundum quid ab aliis, fiunt pro lubitu meo, §. 714, hinc sunt arbitrariae, §. 712, et necessitatae vocantur, quatenus, ut minus necessariae, concipiuntur, si vel ipse, vel alia non produxissent, quod eas produxit, superpondium, §. 701, 188.","glosses":[],"marks":[]},
 {"num":716,"section":"parsiii-capi-secxx","aa":135,"ed":null,"text":"Actiones invitae per ignorantiam aut errorem@@1@@ appellantur, quas non patrassem pro lubitu, nisi aliquid ignorassem vel errassem; quae cum tamen fiant pro lubitu, sunt etiam arbitrariae, §. 712.","glosses":["aus Unwissenheit oder Irrthum ungern vorgenommene Handlungen"],"marks":["*"]},
 {"num":717,"section":"parsiii-capi-secxx","aa":135,"ed":null,"text":"Arbitrium minimum esset, pro minimo lubitu unicam tantum actionem determinans, §. 161. Quo ergo maiori pro lubitu, quo plures, quo maiores actiones determinat, hoc maius est, §. 160, donec sit maximum, maximas plurimas actiones ex maximo lubitu determinans, §. 161, 712.","glosses":[],"marks":[]},
 {"num":718,"section":"parsiii-capi-secxx","aa":135,"ed":281,"text":"Cum arbitrium sit facultas appetendi aversandive pro lubitu suo, §. 712, substantia arbitrio praedita, aut tantum facultatem appetendi aversandive sensitive habebit, aut tantum volendi nolendive pro lubitu, aut facultatem volendi nolendive et sensitive appetendi aversandive pro lubitu suo, §. 676, 689.","glosses":[],"marks":[],"aaEnd":136},
 {"num":719,"section":"parsiii-capi-secxxi","aa":136,"ed":null,"text":"Facultas appetendi aversandive pro lubitu suo sensitive, est arbitrium sensitivum@@1@@, facultas volendi nolendive pro lubitu suo est (liberum arbitrium) libertas@@2@@, cf. §. 707, 708, 710 (moralis, simpliciter sic dicta). Libertas pure volendi nolendive est libertas pura@@3@@. Ergo substantia arbitrio praedita aut illud sensitivum tantum habebit, aut libertatem tantum puram, aut eandem arbitrio sensitivo mixtam, §. 718. Actiones, ad quas per libertatem se determinare est in potestate alicuius substantiae positum, liberae@@4@@ sunt, et ipsa substantia, quae et quatenus actiones liberas patrare potest, est libera@@5@@.","glosses":["das sinnliche Willkür","Freiheit","reine Freiheit","freie Handlungen","Dinge, oder Kräfte, die frei vor sich bestehn"],"marks":["*","**","***","*","**"]},
 {"num":720,"section":"parsiii-capi-secxxi","aa":136,"ed":282,"text":"Multa appeto aversorque sensitive pro lubitu meo. Ergo habeo arbitrium sensitivum, §. 216, 719. Multa volo noloque pro lubitu meo. Ergo habeo libertatem, §. 216, 719. Multae actiones meae, multae actiones animae meae, et anima in multis actionibus suis, sunt liberae. Omnibus meis volitionibus nolitionibusque sensitivi quid admixtum est, §. 692. Hinc non convenit mihi pura libertas, in liberrimis meis actionibus arbitrio sensitivo mixta mea est libertas, §. 719. Tam arbitrium sensitivum, quam liberum actuantur per vim animae repraesentativam universi pro positu corporis mei in eodem, §. 712, 667.","glosses":[],"marks":[]},
 {"num":721,"section":"parsiii-capi-secxxi","aa":136,"ed":null,"text":"Actiones voluntariae@@1@@ dicuntur 1) quaecumque per facultatem appetitivam superiorem determinantur, tunc involuntariae@@2@@ sunt, quae per facultatem appetitivam superiorem non determinantur. Et hoc significatu omnes actiones voluntariae sunt liberae, non omnes actiones liberae sunt voluntariae, §. 719. Pone enim, me me ipsum determinare per arbitrium sensitivum, ubi me determinare per libertatem fuit in potestate mea positum, erit eiusmodi actio involuntaria, tamen libera, §. 719.","glosses":["Handlungen des Willens, die mit Willen geschehn","die nicht des Willens sind, oder nicht mit Willen geschehn"],"marks":["*","**"]},
 {"num":722,"section":"parsiii-capi-secxxi","aa":136,"ed":283,"text":"Actiones voluntariae@@1@@ dicuntur 2) quaecumque per facultatem appetitivam superiorem nullo modo inviti determinantur. Tunc involuntariae@@2@@ sunt, quas invitus volo. Hoc significatu voluntariae involuntariaeque omnes sunt liberae actiones, §. 719. Sed non omnes liberae actiones sunt vel voluntariae, vel involuntariae hoc significatu, §. 721.","glosses":["freiwillige Handlungen","Handlungen, die ich ungern will"],"marks":["*","**"]},
 {"num":723,"section":"parsiii-capi-secxxi","aa":136,"ed":284,"text":"Cum libertate propius connexum est morale late dictum @@1@@, cf. §. 787. Hinc determinationes liberae sunt morales @@2@@, habitus actionum liberarum morales @@3@@, leges determinationum moralium morales @@4@@, philosophia et theologia eas docens moralis, status ex iis resultans moralis @@5@@ est. Hinc moraliter possibile est 1) quod non, nisi per libertatem, s. in substantia libera, qua tali, fieri potest, latius @@6@@, 2) quod non, nisi per libertatem legibus moralibus conformiter determinatam, fieri potest, strictius, s. licitum @@7@@. Moraliter impossibile est 1) quod ob solam libertatem in substantia libera fieri non potest, latius @@8@@, 2) per libertatem legibus moralibus conformiter determinandam impossibile, strictius s. illicitum @@9@@. Moraliter necessarium est, cuius oppositum est moraliter impossibile, ergo 1) cuius oppositum non, nisi per libertatem, s. in substantia, quatenus est libera, est impossibile, latius @@10@@, 2) cuius oppositum est illicitum, strictius @@11@@. Necessitatio moralis est obligatio @@12@@. Obligatio ad actionem invitam erit coactio moralis @@13@@.","glosses":["sittlich in weiterer Bedeutung","sittliche Bestimmungen","Fertigkeiten","Gesetze","der sittliche Zustand","sittlich möglich in weiterer","in engerer Bedeutung, erlaubt","sittlich unmöglich in weiterer","in engerer Bedeutung, unerlaubt","sittlich nothwendig in weiterer","in engerer Bedeutung","Verbindung, Verpflichtung","sittlicher Zwang"],"marks":["a","b","c","d","e","f","g","h","i","k","l","m","n"],"aaEnd":137},
 {"num":724,"section":"parsiii-capi-secxxi","aa":137,"ed":285,"text":"Necessitas moralis neutro significatu esse potest, ubi non est libertas, §. 723, ergo non tollit libertatem, nec eius oppositum est, §. 81, sed rationatum seu consectarium, §. 14. Hinc actiones moraliter necessariae, necessitatae, et coactae non possunt solum esse liberae, sed et sunt tales necessario, §. 723. Immo posita lege morali universalissima@@1@@, i.e. omnes omnium substantiarum liberarum liberas actiones determinante, cf. §. 822, omnes actiones liberae sunt moraliter necessariae, aut illicitae, §. 723.","glosses":["das allgemeinste sittliche Gesetze"],"marks":["*"]},
 {"num":725,"section":"parsiii-capi-secxxi","aa":137,"ed":null,"text":"Libertas minima est unicam tantum volitionem nolitionemve pro lubitu minimo actuans, quo ergo plures, quo maiores, quo maiori pro lubitu actuat, hoc maior est, donec sit maxima maximas plurimas volitiones nolitionesve summo pro lubitu actuans, §. 719. Quo ergo distinctiori pro lubitu aliquid volo nolove, hoc id volo nolove liberius. Ergo quo magis motivorum meorum mihi sum conscius, hoc liberius volo, §. 712. Liberrime volens nolensve distinctissime volendi nolendive motiva ut perspiciat, quandocumque vult, vel non vult, est moraliter necessarium, §. 723.","glosses":[],"marks":[]},
 {"num":726,"section":"parsiii-capi-secxxi","aa":137,"ed":286,"text":"Arbitrii haec lex est: Ex liberis ratione exsecutionis, quod libet, appeto, quod libet, aversor. Hinc libertatis regula: Ex liberis ratione exsecutionis, quod libet, volo, quod libet, nolo. Actiones meae liberae, dum pro lubitu determinantur, non necessitantur per causas suas impulsivas, stimulos aut motiva coactione physica, non externa, §. 707, sunt enim stimuli et motiva repraesentationes meae, §. 677, 690. Hinc determinationes meae internae, §. 37. Nec necessitantur actiones meae liberae per causas suas impulsivas coactione interna physica, dum sunt manentque positis motivis liberae ratione exsecutionis, §. 711, 710. Immo, motiva et stimuli accurate loquendo ne agunt quidem in animam, hinc nec eam cogunt, §. 714, nec necessitant moraliter, §. 723, 701, dum non sunt, nisi animae meae accidentia, §. 505.","glosses":[],"marks":[],"aaEnd":138},
 {"num":727,"section":"parsiii-capi-secxxi","aa":138,"ed":null,"text":"Si me dicar cogere, in potestate mea positum est, me ad id, ad quod me cogo, per libertatem determinare, unde cogo me libere, §. 714, 719. Si cogar ab alio externe secundum quid, determinor pro lubitu, qui, ut ab alio extra me posito productus, concipitur, §. 714. Quod si tunc in potestate mea positum fuit, me ad id, ad quod cogor externe secundum quid, per libertatem determinare, eiusmodi actio tamen est libera, §. 719. Multae meae actiones, ad quas me cogo, aut cogor externe secundum quid, sunt liberae.","glosses":[],"marks":[]},
 {"num":728,"section":"parsiii-capi-secxxi","aa":138,"ed":287,"text":"Coactiones externae secundum quid erunt l) productiones stimulorum ex placentibus, illecebrae@@1@@, 2) ex displicentibus, minae@@2@@, 3) motivorum ex placentibus, suasiones@@3@@, 4) ex displicentibus, dissuasiones@@4@@, 5) ipsa actuatio displicentium continuanda, donec de secuto ad invitam actionem superpondio certus esse queat cogens, extorsio@@5@@, §. 714. Multae actiones meae, licet ad eas minis et illecebris, suasionibus, dissuasionibusque, et ipsis extorsionibus cogar, tamen sunt liberae, §. 727.","glosses":["Reizungen, locken","Drohen","Anrathen","Abrathen","die Erpressung"],"marks":["*","**","***","*","**"]},
 {"num":729,"section":"parsiii-capi-secxxi","aa":138,"ed":null,"text":"Per systema harmoniae praestabilitae tolluntur omnes actiones animae invitae per coactionem externam simpliciter sumptam ab ullo finito producendae, §. 714, 449, et in coactis per vim externam secundum quid ipse ille lubitus, ex quo oriuntur, ab alio extra animam finito realiter productus tollitur, §. 727, 449, et quatenus per istud systema, anima, ut numquam, ita in nullis actionibus suis liberis, ab ullo finito patitur realiter, totalis hoc sensu ab omni totoque mundo animae adscribitur independentia, §. 354, 307.","glosses":[],"marks":[]},
 {"num":730,"section":"parsiii-capi-secxxi","aa":138,"ed":288,"text":"Volitiones nolitionesque meae liberae dicuntur actus animae eliciti, reliquarum facultatum actiones liberae actus imperati, et quatenus a libertate animae pendent, ipsi in eas imperium adscribitur. Hinc animae in semet ipsam@@1@@ imperium est facultas pro distincto lubitu nunc huius, nunc illius facultatis actiones producendi, nunc earum producendi oppositum. Quo maior ergo libertas, hoc maius liberi in se est imperium, §. 725. Insignis imperii in se ipsum defectus est servitus moralis significatu lato@@2@@. Ad augendum in se imperium faciens est (ingenuum) liberale@@3@@, servitutem promovens moralem est servile@@4@@.","glosses":["die Herrschaft der Seele über sich selbst","die innre Knechtschaft der Seelen überhaupt","frei, dem knechtischen entgegen gesetzt","knechtisch"],"marks":["*","**","***","*"]},
 {"num":731,"section":"parsiii-capi-secxxi","aa":138,"ed":null,"text":"Actiones animae non, nisi per plures actus intermedios, a libertate si pendeant, ipsi indirecte (mediate) subsunt@@1@@, directe@@2@@ (immediate) autem, quas per libertatem ago vel omitto sine observabilibus pluribus intermediis actibus aliis. Actiones, quae libertati vel maxime per indirectum subsunt, tamen sunt liberae, §. 719.","glosses":["Handlungen, die der Freiheit mittelbar","die ihr unmittelbar unterworfen"],"marks":["*","**"],"aaEnd":139},
 {"num":732,"section":"parsiii-capi-secxxi","aa":139,"ed":289,"text":"Determinata facultatum appetitivarum inter se in certo subiecto proportio est eiusdem indoles@@1@@, vel erecta@@2@@, habitualiter dominantibus superioribus, vel abiecta@@3@@, habitualiter dominantibus inferioribus, quarum maxima passio dominans@@4@@ vocatur. Cumque certa earum proportio ad certum appetibilium aversabiliumve genus facilius feratur, varia hinc temperamentorum animae@@5@@ genera constituuntur. Ergo temperamentum animae multum mutari potest ac saepius exercitiis et consuetudine, §. 650, 577.","glosses":["die Gemüths-Art","eine edle","eine niedrige","der Hang","Mischung der Gemüths-Neigungen"],"marks":["*","**","***","*","**"]},
 {"num":733,"section":"parsiii-capi-secxxii","aa":139,"ed":289,"text":"Multi motus corporis mei ab arbitrio meo pendent, §. 14. Ab arbitrio, cuius mihi sum conscius, pendentes motus corporis arbitrarii@@1@@, §. 712, dicuntur, et arbitrarii a facultate superiore pendentes sunt voluntarii@@2@@, §. 721. Regimen animae in corpus@@3@@ est dependentia motuum huius ab arbitrio illius. Hinc anima mea habet regimen in corpus meum.","glosses":["willkürliche","freiwillige Bewegungen des Leibes","die Herrschaft der Seelen über ihren Leib"],"marks":["*","**","***"]},
 {"num":734,"section":"parsiii-capi-secxxii","aa":139,"ed":null,"text":"In motibus corporis mei arbitrariis et voluntariis ex anima potest sufficienter cognosci, cur eventus in corpore contingat, hoc non alio tempore et loco, §. 733. Ergo anima agit in corpus, §. 210, et in illud influit, §. 211.","glosses":[],"marks":[]},
 {"num":735,"section":"parsiii-capi-secxxii","aa":139,"ed":null,"text":"In affectibus animae conformis illis coexsistit in corpore motus, qui ex iisdem cum sufficienter cognosci queat, novum influxus animae in corpus argumentum dat, §. 734.","glosses":[],"marks":[]},
 {"num":736,"section":"parsiii-capi-secxxii","aa":139,"ed":null,"text":"In sensationibus externis ex vi corporis potest sufficienter cognosci, cur in anima fiat certa mutatio. Ergo corpus agit in animam, §. 210, in eamque influit, §. 211. Ergo est inter animam meam et corpus meum influxus mutuus, §. 734, 735, mutua harmonia, §. 14, et commercium, §. 448.","glosses":[],"marks":[],"aaEnd":140},
 {"num":737,"section":"parsiii-capi-secxxii","aa":140,"ed":291,"text":"Motus arbitrarios corporis per vim corpori propriam sufficienter determinari, sufficienterque determinari sensationes per vim animae propriam non experior. Qui ergo maiorem hanc assumit: ›quicquid non experior, non exsistit‹, inde concludet: ›Ergo motus corporis arbitrarii per vim corpori propriam, et sensationes externae per vim animae propriam non sufficienter determinantur. Hinc corpus in animam, anima in corpus realiter influit, §. 212, influxu physico, §. 450 (per exp.).‹ Hanc si conclusionem pro sensatione habet, inde fallaciae sensuum ipsius oriuntur, sumpta maiore falsa, §. 548, per vitium subreptionis, §. 546.","glosses":[],"marks":[]},
 {"num":738,"section":"parsiii-capi-secxxii","aa":140,"ed":292,"text":"Mutationes corporis ex anima, et animae ex corpore pendentes sunt harmonicae, §. 448. In mutationibus harmonicis animae et corporis mutationi corporis coexsistit, vel succedit mutatio animae, mutationi animae coexsistit, vel succedit mutatio corporis, §. 733-736. Qui ergo hanc maiorem assumit: ›Quae sibi coexsistunt vel succedunt, eorum unum in alterum realiter influit‹, hinc concludet: ›ergo corpus in animam in mutationibus harmonicis, anima in corpus realiter influit (per exp.)‹. Quam si conclusionem habet pro sensatione, hinc oriuntur fallaciae sensuum ipsius, §. 548, per vitium subreptionis, §. 546.","glosses":[],"marks":[]},
 {"num":739,"section":"parsiii-capi-secxxii","aa":140,"ed":null,"text":"Anima mea et corpus meum me unum constituunt. Ergo sunt inter se unita, §. 73, 79. Commercium eorum, quatenus per illud unus homo perdurat, est unio, §. 205, quae quatenus est admodum magna, §. 734-736, et quanta non est inter animam meam et ullum aliud corpus, §. 508, est artissima.","glosses":[],"marks":[]},
 {"num":740,"section":"parsiii-capii-seci","aa":140,"ed":293,"text":"Anima humana@@1@@ est anima, quae cum corpore humano in artissimo est commercio. Cumque anima cum corpore, quocum est in artissimo commercio, constituat animal@@2@@: anima humana cum corpore, quocum est in artissimo commercio, constituit animal, quod hominem@@3@@ dicimus.","glosses":["eine menschliche Seele","ein Thier","einen Menschen"],"marks":["*","**","***"]},
 {"num":741,"section":"parsiii-capii-seci","aa":140,"ed":null,"text":"Anima humana sibi corpus suum repraesentat pro arbitrio, §. 740. Ergo agit, §. 210, movet etiam corpus suum, §. 740, 734. Ergo appetit et aversatur, §. 712. Ergo agit et est vis repraesentativa corporis sui, §. 210. Corpus humanum est materia, §. 296, hinc divisibile, §. 427, adeoque interne mutabile, §. 244, adeoque ens finitum, §. 255, actuale, pars mundi, §. 354. Ex positu corporis humani in universo cognosci potest, cur anima humana obscure, clare, distincte repraesentet haec, non alia, §. 740, 736. Ergo anima humana@@1@@ est vis repraesentativa universi pro positu corporis humani in eodem, §. 513, 155.","glosses":["die menschliche Seele"],"marks":["*"],"aaEnd":141},
 {"num":742,"section":"parsiii-capii-seci","aa":141,"ed":294,"text":"Ad cogitationem requiritur 1) perceptio rei, 2) notarum ad eam distinguendam sufficientium, §. 524, 3) ipsa eius distinctio, §. 67. Est autem accidens cogitatio, §. 191. Ergo non potest exsistere, nisi in substantia, vel substantiarum aggregato, §. 194. Substantiarum aggregatum, ex cuius partium mutationibus vel accidentibus collectis, quarum nulla iam esset cogitatio, demum resultaret cogitatio in toto, esset materia cogitans. Haec in mundo esset aggregatum substantiarum finitarum, §. 354, quarum una plus conferret ad cogitandum, quam reliquae, §. 272, a quibus auxilia pateretur, §. 210, 321. Sed haec patietur, non nisi idealiter, §. 451, 463. Ergo in mundo in omni materia cogitante esset una substantia, in cuius unica vi omnia ad cogitationem requisita a finitis praestanda rationem sufficientem haberent, §. 210, 212, et tamen 1) haec substantia dati aggregati dominans numquam cogitaret per se, quod contra §. 30, 220, 2) omnia ad cogitationem requisita, a finitis praestanda, haberent rationem sufficientem in data substantia dominante, per demonstrata, simulque non, nisi per aggregatum substantiarum demum actuanda essent, i.e. non, nisi in plurium substantiarum finitarum vi rationem sufficientem haberent, §. 210, q.a., §. 7. Materia cogitans est in mundo impossibilis. Quicquid cogitare potest, aut est substantia, monas, §. 234, aut totum, cuius substantia, quae cogitare potest, pars sit. Ergo omnis anima est substantia, monas, §. 504. Quicquid intelligere potest, potest cogitare, §. 69. Ergo quicquid intelligere potest, aut est substantia, monas, spiritus, §. 402, aut totum, cuius spiritus pars est. Totum spirituum est (persona moralis) corpus mysticum. Anima intellectualis est spiritus, §. 504, cf. §. 402, 296. Anima humana est substantia, §. 740. Ergo monas, spiritus, §. 741.","glosses":[],"marks":[]},
 {"num":743,"section":"parsiii-capii-seci","aa":141,"ed":296,"text":"Anima humana subsistit per se, §. 742, 192. Ergo non est phaenomenon substantiatum, §. 193. Cum tamen repraesentet pro positu corporis humani in universo, quod est in perpetuo motu, §. 417, 296, hinc semper positum suum mutat, §. 283, 281, repraesentationes eius semper mutantur, §. 512. Quae cum sint determinationes animae humanae internae, §. 37, 741, anima humana est interne mutabilis substantia, hinc contingens, §. 202, et finita, §. 255. Omnem animam humanam finitam esse et contingentem substantiam ita quoque patet: anima humana repraesentat pro positu corporis, §. 741. Ergo quaedam distincte, quaedam minus distincte percipit, §. 512. Iam vero distincte quid concipere est realitas, §. 515, 531. Ergo anima humana habet gradum realitatis non maximum, §. 161, hinc limitem, §. 248. Ergo finita et contingens est, §. 257, substantia, §. 742.","glosses":[],"marks":[],"aaEnd":142},
 {"num":744,"section":"parsiii-capii-seci","aa":142,"ed":null,"text":"Anima humana cognoscit, appetit et aversatur, §. 741. Hae sunt actiones partialiter diversae, §. 267. Ergo anima humana habet diversas partialiter facultates, §. 216, quae non stricte vires dicuntur, §. 197, 59, per unicam potius animae vim repraesentativam stricte dictam concipiuntur, §. 521-720, nec sunt extra se invicem positae, dum accidentia, §. 191, non sint extra suam substantiam, §. 194, nec dicuntur accurate in se invicem agere, dum actio non sit proprie nisi substantiae, §. 210, multo minus in se invicem influere, §. 211.","glosses":[],"marks":[]},
 {"num":745,"section":"parsiii-capii-seci","aa":142,"ed":297,"text":"Anima humana monas, §. 742, contingens, §. 743, non potest oriri, nisi ex nihilo, §. 236, non potest interire, nisi per annihilationem, §. 237, non extensa est, nec spatium replet, §. 241, i.e. non est in loco repletive, §. 241. Coexsistens tamen simultaneis extra eam positis, est in spatio, §. 239, et loco, §. 281, ita, ut alia extra eam posita ipsi sint propiora, alia remotiora, §. 288, 282. Complexus simultaneorum animae humanae propiorum si sedes@@1@@ eius dicatur: corpus humanum prae aliis corporibus, et quaedam eius partes prae aliis membris sunt sedes animae, §. 409.","glosses":["der Sitz der menschlichen Seele"],"marks":["*"]},
 {"num":746,"section":"parsiii-capii-seci","aa":142,"ed":null,"text":"Anima humana non habet magnitudinem quantitativam, §. 744, 243, et est indivisibilis, §. 244. Interitus per divisionem est corruptio physica@@1@@. Ergo corruptio physica est animae humanae in se impossibilis, §. 15, 745, i.e. anima humana est absolute incorruptibilis physice@@2@@.","glosses":["das Zergehn","unzergänglich, unauflöslich, unverweslich, unzerstörbar"],"marks":["*","**"]},
 {"num":747,"section":"parsiii-capii-seci","aa":142,"ed":298,"text":"Anima humana non admittit quidem triplicem dimensionem extensorum, §. 290, 745, possibilis tamen eius cognitio philosophica et mathematica, sicut humani corporis, §. 743, 249. Homo constat anima et corpore finitis, §. 741, 743, hinc interne mutabilis, §. 740, est ens finitum et contingens, §. 202, 257. Ergo possibilis est hominis cognitio philosophica, et mathematica, §. 249, i.e. anthropologia philosophica, et mathematica s. anthropometria, sicut empirica per experientiam. Complexus regularum in cognoscendo homine observandarum est anthropognosia.","glosses":[],"marks":[]},
 {"num":748,"section":"parsiii-capii-seci","aa":142,"ed":null,"text":"Mutato ente finito in infinitum, infinitum oriretur, §. 125, 227, nec aeternum esset, §. 302, quod absolute impossibile, §. 252. Mutatio hominis in ens infinitum est apotheosis@@1@@, ergo apotheosis est absolute impossibilis.","glosses":["Vergötterung"],"marks":["*"],"aaEnd":143},
 {"num":749,"section":"parsiii-capii-seci","aa":143,"ed":null,"text":"Animarum humanarum vel duarum tantum similitudo et aequalitas totalis est impossibilis, §. 271, 272. Ergo totalis convenientia seu identitas sensuum, imaginationum, praevisionum, iudiciorum, gustuum, taediorum, voluptatum, stimulorum, motivorum, errorum, appetitionum, aversationum, volitionum, nolitionum in pluribus hominibus, vel paucissimis, est chimaera, §. 590.","glosses":[],"marks":[]},
 {"num":750,"section":"parsiii-capii-seci","aa":143,"ed":299,"text":"Anima humana corpus suum movet, §. 740, 734. Ergo habet facultatem movendi quid extra se positum, i.e. locomotivam, §. 216, quae ut reliquae facultates animae, §. 744, actuatur per vim eius repraesentativam universi pro positu corporis, §. 741, 417.","glosses":[],"marks":[]},
 {"num":751,"section":"parsiii-capii-seci","aa":143,"ed":null,"text":"Anima humana sibi quasdam huius universi partes, ut singulares, repraesentat, §. 740, 736, ergo ut omnimode determinatas, §. 148. Ad omnimodam determinationem partium huius mundi nexus earundem cum singulis reliquis pertinet, §. 357. Ergo anima humana sibi quaedam repraesentat, ut connexa cum singulis mundi partibus. Iam vero unum cognosci non potest, ut connexum cum altero, nisi cognoscatur alterum quomodocumque, §. 14. Ergo anima humana singulas huius universi partes percipit, ergo et singulos huius universi status percipit, §. 369.","glosses":[],"marks":[]},
 {"num":752,"section":"parsiii-capii-seci","aa":143,"ed":300,"text":"Anima humana pro positu corporis sui repraesentat sibi statum mundi praesentem, i.e. sentit, §. 534, 751, praeteritum, i.e. imaginatur, §. 557, futurum, i.e. praevidet, §. 595. Sensationes animae humanae sunt repraesentationes singularum mundi partium sibi simultanearum, minus vel magis distinctae, confusae, vel obscurae, prout obiecta earum se ad corpus humanum habent, §. 751. Imaginationes animae humanae sunt repraesentationes singularum mundi partium praeteritarum, quae animam sentientem antecesserunt, s. ante illum sensationis actum exstiterunt; et hae quoque imaginationes sunt distinctae, confusae, obscurae, magis vel minus, prout obiecta earundem se ad corpus humanum habuerunt, §. 751. Praevisiones animae humanae sunt repraesentationes singularum mundi partium futurarum, post sentientis animae actum exstiturarum, minus vel magis distinctae, confusae, obscurae, prout obiecta earundem se ad corpus humanum habitura sunt, §. 751.","glosses":[],"marks":[]},
 {"num":753,"section":"parsiii-capii-seci","aa":143,"ed":null,"text":"Eodem modo, quo §. 752 de sensatione e.c. evicit eam esse in omni anima humana, ostendi id potest de reliquis animae actibus per experientiam in anima humana deprehendendis, per psychologiam empiricam enumeratis, §. 576 seqqu.","glosses":[],"marks":[],"aaEnd":144},
 {"num":754,"section":"parsiii-capii-seci","aa":144,"ed":null,"text":"Anima humana pro positu corporis sui distincte repraesentat, §. 741. Ergo intelligit, §. 402, et est spiritus, §. 742, 216. Hinc denuo patet, omnes animas humanas esse inaequales et unam omnium perfectissimam, §. 405. Anima humana est spiritus finitus, §. 743, pars huius mundi, §. 355.","glosses":[],"marks":[]},
 {"num":755,"section":"parsiii-capii-seci","aa":144,"ed":301,"text":"Omnis spiritus est substantia, §. 402. Ergo vis, §. 199, hinc quorundam accidentium inhaerentiae ratio sufficiens, §. 197, adeoque agens, §. 210. Cumque sit substantia intellectualis, §. 402, quasdam distinctas repraesentationes actuandi facultatem habet, §. 216. Ergo ad eas vim suam determinandi, §. 210, hinc appetendi, §. 663. Quicquid appetit, eius oppositum aversatur, hinc spiritus habet facultatem aversandi, §. 663. Appetitiones aversationesque spiritus sunt eius determinationes internae, §. 37. Ergo sunt cum reliquis eius determinationibus internis in universali nexu, §. 49. Ergo etiam cum reliqua ipsius cognitione, quae determinatio interna est, §. 37, adeoque fiunt pro lubitu spiritus, §. 712. Ergo spiritus habet arbitrium, §. 712, cumque lubitus ipsius possit distinctus esse, §. 402, liberum seu libertatem, §. 719.","glosses":[],"marks":[]},
 {"num":756,"section":"parsiii-capii-seci","aa":144,"ed":302,"text":"Anima humana spiritus est, §. 754. Ergo habet libertatem, §. 755. Cumque spiritualitas, intellectualitas, personalitas, §. 641, 754, libertas, simplicitas absoluta, §. 744, et incorruptibilitas ipsi conveniant absolute necessario, §. 746, non sunt eius modi, §. 108, hinc aut essentialia, aut attributa, quia sunt determinationes internae, §. 37, 52. Una eorum sublata tolleretur anima humana, §. 63. Hinc anima humana, quae prorsus nequeat distincte quid concipere, nec ex distincto se lubitu determinare, amittens omnem personalitatem et libertatem, constans pluribus viribus, ut partibus extra se invicem ponendis, et corrumpenda physice sunt chimaerae, §. 590.","glosses":[],"marks":[]},
 {"num":757,"section":"parsiii-capii-seci","aa":144,"ed":null,"text":"Anima humana est immaterialis et incorporea, §. 744, 422. Qui negat animam humanam esse immaterialem substantiam, est materialista significatu psychologico, cf. §. 395, et fallitur, sive eam pro mero corporis accidente habeat, §. 742, sive pro atomo materiali, §. 429, sive pro quocumque corpusculo subtilissimo, §. 426. Materialista universalis est etiam significatu psychologico talis, §. 395, sed non omnis animam humanam materialem substantiam putans materialista necessario universalis est, §. 395.","glosses":[],"marks":[]},
 {"num":758,"section":"parsiii-capii-seci","aa":144,"ed":303,"text":"Vis repraesentativa universi pro positu corporis humani in eodem, cum hinc pendentibus ipsius modis, est complexus determinationum animae internarum, quae mutationum eius et inhaerentium ipsi accidentium principia sunt, §. 751-755. Ergo vis eadem cum determinationibus suis ex positu corporis pendentibus est natura animae humanae, §. 430. Hinc quicquid per hanc vim secundum leges regulasque singularum facultatum determinatam actuatur in anima humana, est naturale animae humanae, §. 470, quatenus contradistinguitur supernaturali, §. 469. Hoc significatu actiones etiam liberae et morales animae sunt naturales, §. 756, 755, licet non sint mere naturales, §. 709. Praeter hunc proprium significatum naturae in anima humana, et hinc naturalis in eadem, sunt alii improprii, et synecdochici, nunc ex confusione partis cum toto male orti, nunc inde quod ex peculiari modo, modificatione, vel statu naturae in anima humana conceptibilibus peculiare nomen inhaesit, et tunc reliquis naturalibus peculiari nomine destitutis, tale adeptis si contradistinguenda fuerunt, nomen generis remansit in significatu strictiori. Sic e.g. connata nonnumquam naturalia dicuntur contradistincta acquisitis, naturalia contradistinguuntur artificialibus, socialibus, arbitrariis, per consuetudinem demum impetratis, e.c. cf. §. 710.","glosses":[],"marks":[],"aaEnd":145},
 {"num":759,"section":"parsiii-capii-seci","aa":145,"ed":304,"text":"Quae in anima humana sibi succedunt naturalia animae humanae secundum leges vi ipsius praescriptas, fiunt respectu animae humanae secundum cursum naturae, §. 758, 471, et cum iis, quae coexsistunt in anima humana secundum easdem leges, contingunt secundum ordinem naturae respectu animae humanae, §. 473. Praeternaturalia, quae per vim ipsius repraesentativam pro positu corporis sui, secundum leges regulasque facultatum ipsius, non actuantur, quae si nec actuentur per naturam universam, sunt supernaturalia, §. 474.","glosses":[],"marks":[]},
 {"num":760,"section":"parsiii-capii-seci","aa":145,"ed":null,"text":"Anima humana mundi optimi est in nexu universali pneumatico, et pneumatico-mechanico maximo, §. 464, 754. Ergo connectitur cum singulis optimi mundi spiritibus et corporibus, §. 48, at inaequaliter, §. 272. Ergo cum uno corpore, cum uno spiritu maxime, §. 161.","glosses":[],"marks":[],"aaEnd":146},
 {"num":761,"section":"parsiii-capii-secii","aa":146,"ed":305,"text":"Systemata psychologica sunt sententiae, quae videntur ad explicandum animae et corporis in homine commercium aptae. Ergo systemata psychologica sunt systemata particularia, §. 462, vel simplicia, vel composita, §. 457. Illorum nullum possibile, praeter systema harmoniae praestabilitae, influxus physici, et causarum occasionalium forsitan psychologicum, §. 458.","glosses":[],"marks":[]},
 {"num":762,"section":"parsiii-capii-secii","aa":146,"ed":null,"text":"Posito uno ex systematis generalibus simplicibus, ponitur etiam unum ex psychologicis simplicibus, §. 761, 457. Ergo demonstrata harmonia praestabilita universali, §. 463, demonstrata simul est harmonia praestabilita psychologica. Posito tamen uno ex systematis psychologicis simplicibus non necessario unum aut simillimum ex generalibus ponendam est, §. 761, 457. Si anima et corpus humanum possunt per harmoniam praestabilitam in artissimo esse commercio, connectuntur etiam per harmoniam praestabilitam in mundo optimo, §. 461, ita, ut influxus physicus aut systema causarum occasionalium non admittenda sint, nisi ubi impossibile per harmoniam praestabilitam commercium, §. 462.","glosses":[],"marks":[]},
 {"num":763,"section":"parsiii-capii-secii","aa":146,"ed":306,"text":"Systema influxus physici psychologicum, quia simplex est, ponit omnes omnium animarum corporumque humanorum mutationes harmonicas contingere per influxum physicum, §. 457. Ergo si vel unica mutatio unius animae vel corporis humani harmonica, probari potest possibilis per harmoniam praestabilitam in mundo optimo: systema influxus physici in mundo optimo locum habere amplius defendi nequit, §. 762. Systema harmoniae praestabilitae psychologicum, quia simplex est, ponit omnes omnium animarum corporumque humanorum mutationes harmonicas contingere per harmoniam praestabilitam, easdem per solam vim infinitam contingere ponit ob eandem rationem systema causarum occasionalium psychologicum, §. 457. Ergo si vel una unius animae vel corporis humani mutatio harmonica impossibilis esset in optimo mundo per harmoniam praestabilitam: systema eius psychologicum locum habere in mundo optimo amplius defendi non posset. Si vel una unius animae vel corporis humani mutatio harmonica per harmoniam praestabilitam aut influxum physicum possibilis est in mundo optimo: nec systema causarum occasionalium amplius locum habere in mundo optimo defendi potest, §. 762, 460. Systema influxus physici psychologicum non magis, quam systema harmoniae praestabilitae et causarum occasionalium, patet per experientiam, §. 737, 738.","glosses":[],"marks":[]},
 {"num":764,"section":"parsiii-capii-secii","aa":146,"ed":307,"text":"Systema influxus physici psychologicum ponit animam humanam in corpus suum, corpus humanum in animam suam in mutationibus harmonicis influere realiter, §. 761, 450. Hinc per systema influxus physici psychologicum 1) in nullis mutationibus harmonicis, in corpore humano contingentibus, corpus agit vi propria, §. 212. Iam vero omnes mutationes corporis humani, ut partis mundi, quem anima repraesentat, possunt ex vi animae sufficienter cognosci, §. 354, 751. Ergo omnes sunt harmonicae, §. 448, et in nullis suis mutationibus corpus agit, secundum systema influxus physici psychologicum, vi propria, in omnibus realiter patiens ab anima. Si numquam agit corpus, nec reagit, §. 213. Ergo per systema influxus physici est in mundo actio transiens animae in corpus humanum sine reactione, quotiescumque anima in corpus suam agit, quod vel semel fieret contra §. 410.","glosses":[],"marks":[],"aaEnd":147},
 {"num":765,"section":"parsiii-capii-secii","aa":147,"ed":308,"text":"Per systema influxus physici psychologicum ponitur 2) corpus humanum in animam suam influere realiter, quotiescumque contingit in anima humana mutatio, quae ex vi corporis sufficienter cognosci potest, §. 764, 448. Ergo in mutationibus harmonicis, in anima obviis, per systema influxus physici psychologicum, realiter influit corpus, quod tamen in nullis suis mutationibus umquam agere per idem systema ponendum est, §. 764. Per systema influxus physici sentiendo anima prorsus non agit, §. 212, cum tamen vi sua propria sibi repraesentet statum mundi praesentem non minus, quam reliquos, §. 751.","glosses":[],"marks":[]},
 {"num":766,"section":"parsiii-capii-secii","aa":147,"ed":null,"text":"Corpus humanum constat elementis, §. 420, monadibus, repraesentantibus mundum suum, ex quibus singulis singulae eius partes cognosci possunt, §. 400, hinc et singulae mutationes animae, partes mundi, §. 354. Ergo omnis actio animae est mutatio harmonica, §. 448, 22. Iam omnis animae volitio et nolitio est actio eius, §. 210, 690. Ergo omnis animae humanae volitio et nolitio est mutatio harmonica eiusdem. Iam per systema influxus physici psychologicum anima humana in mutationibus suis harmonicis nullis agit vi propria, sed realiter patitur a corpore. Ergo per systema influxus physici anima in omnibus suis volitionibus nolitionibusque, nil quicquam agens, patitur a corpore, quod contra libertatem, §. 755.","glosses":[],"marks":[]},
 {"num":767,"section":"parsiii-capii-secii","aa":147,"ed":309,"text":"Per systema causarum occasionalium psychologicum 1) corpus humanum non agit in ullis suis mutationibus harmonicis, sed ens infinitum, §. 761, 452, unde eodem modo, quo §. 764 ostendebatur, patet, per systema assistentiae corpus in nullis suis mutationibus agere, sed solum ens infinitum. 2) Per idem systema anima humana non agit in mutationibus suis harmonicis, sed ens infinitum solum, §. 761, 452, unde eodem modo, quo §. 766 ostendebatur, patet, per systema assistentiae psychologicum animam humanam in nullis volitionibus nolitionibusque suis quicquam agere, et tantum realiter pati in iis ab ente infinito, quod itidem contra libertatem, §. 755.","glosses":[],"marks":[]},
 {"num":768,"section":"parsiii-capii-secii","aa":147,"ed":310,"text":"Per systema harmoniae praestabilitae psychologicum utraque pars commercii in se occurrentes mutationes harmonicas actuat vi propria ab altera parte idealiter patiens, §. 761, 448, hinc per systema harmoniae praestabilitae psychologicum ponuntur 1) motus arbitrarii corporis non minus, quam mere naturales ac vitales, per mechanismum ipsius et corporum illud circumdantium sufficienter determinari, 2) sensationes animae per ipsius vim repraesentativam non minus, quam liberrimas ipsius quasvis cogitationes, determinari sufficienter, §. 758, 433.","glosses":[],"marks":[]},
 {"num":769,"section":"parsiii-capii-secii","aa":147,"ed":null,"text":"Pone harmonistam psychologicum rationem daturum mutationis alicuius harmonicae in homine, eamque petentem 1) ex vi ipsius illius partis commercii, in qua mutatio harmonica observatur, 2) ax altera parte commercii, quam ipse supponit idealiter influere, 3) ex vi infinita, quam statuit concurrere, pone, inquam, eum falli, certissime veram rationem dedit, §. 448, 450, falsam licet per hypothesin addiderit. Pone in eodem casu influxionistam aut occasionalistam falli, magnam ille verae rationis partem non praeteriit solum, sed et negavit, §. 450, 452.","glosses":[],"marks":[],"aaEnd":148},
 {"num":770,"section":"parsiii-capii-seciii","aa":148,"ed":null,"text":"Dum homo concipitur, anima in artissimo commercio futura cum eius corpore, quale in his terris hominibus est, aut iam praeexstitit, aut in ipsa conceptione, aut paullo post eam exsistere demum incipit. Qui primum ponit, praeexsistentianus@@1@@ vocatur.","glosses":["ein Freund des Vorherdaseins"],"marks":["*"]},
 {"num":771,"section":"parsiii-capii-seciii","aa":148,"ed":311,"text":"In ipsa conceptione, aut paullo post eam, incipere demum exsistentiam animae humanae qui ponunt, aut eam ex parentibus oriri volunt et traduciani@@1@@ vocantur, aut eam admittunt tunc primum exsistentem ex nihilo, et dicuntur induciani@@2@@ (infusiani, coexsistentiani).","glosses":["ein Freund des Ursprungs durch den Übergang","ein Freund der augenblicklichen Schöpfung"],"marks":["*","**"]},
 {"num":772,"section":"parsiii-capii-seciii","aa":148,"ed":null,"text":"Qui animam humanam ponit actuatam ex nihilo, creatianus@@1@@ appellatur. Hinc inducianus est creatianus, §. 771. Praeexsistentianus potest esse creatianus, §. 770. Traducianus non est creatianus, et v.v., §. 771. Traduciani sive ex parentum anima, ut flammulam ex flammula, sive ex eorundem corpore, derivent oriundam animam, aut oriri animam novam admittere tenentur ex parte parentum simplici, aut ex composita, §. 224. Si prius: anima non oritur, sed praeexsistit, §. 227; si posterius: anima nova non erit monas, sed compositum stricte dictum, §. 225, quod contra §. 756, 757. Anima non potest oriri, nisi ex nihilo, §. 745. Ergo non oritur ex parentibus, §. 228.","glosses":["ein Freund der unmittelbaren Schöpfung"],"marks":["*"]},
 {"num":773,"section":"parsiii-capii-seciii","aa":148,"ed":312,"text":"Propagatio animarum humanarum per traducem@@1@@ si dicatur unitio aliarum aliarumque semper animarum humanarum cum corpore, quale in his terris hominibus est, per continuam parentum subolisque successionem in mundo, qua genus humanum, quale in his terris est, ita propagetur, ut animae cum corporibus prolis transeant et traducantur ex corporibus parentum in sua loca propria, magis seorsim ubi habitent, potest concipi, 1) ut ortum animae simul involvat, i.e. ut anima interveniente conceptionis actu cum corpore, quale in his terris homini est, in artissimum ventura commercium simul statuatur oriri, idque iterum vel ex parentibus, de quo §. 772, vel a parentibus, sumendo deum posse determinatam vim animae humanae indere, qua non nisi suae speciei aliqua individua possit ex nihilo producere, concurrente ipsius vi creatrice realitates plurimas in anima oriunda praestante, non nisi limitatis admodum aliquibus realitatibus ab anima parentum proficiscentibus. Hanc sententiam ponens dici potest concreatianus@@2@@.","glosses":["die Fortpflanzung menschlicher Seelen durch den Übergang","ein Freund der mitgetheilten Schöpfers-Kraft"],"marks":["*","**"],"aaEnd":149},
 {"num":774,"section":"parsiii-capii-seciii","aa":149,"ed":313,"text":"Propagatio animarum humanarum per traducem potest concipi, 2) ut ortum animae non involvat, sed praeexsistens anima statuatur iam exstitisse ante intervenientem conceptionis actum in artissimo commercio cum parte seminis, aut accuratius animalculo spermatico, et sic retro, per plures generationes, sensim aucta et evoluta, ipsius animae vi repraesentativa, prout paullatim propius propiusque transformationi suae magnae et incrementis factum est corpus animalculi spermatici electi, quod in maius theatrum prodiret, §. 773.","glosses":[],"marks":[]},
 {"num":775,"section":"parsiii-capii-seciii","aa":149,"ed":null,"text":"Ortus animae et propagatio animae per traducem possunt distingui, §. 773, 771. Ortum etiam animae per traducem qui ponunt ex parentibus, distingui possunt ab iis, qui eundem ponunt a parentibus derivandum, §. 773, 772. Ergo non omnis, traducem quomodocumque intellectum admittens, materialismi psychologici reus est, §. 772, 757.","glosses":[],"marks":[],"aaEnd":150},
 {"num":776,"section":"parsiii-capii-seciiii","aa":150,"ed":null,"text":"Quamdiu vel unica minima mutatio enti naturalis, vel generatim unicum minimum accidens enti naturaliter inhaeret, durat eius natura, §. 469, 29, et ens vivit, §. 430. Quod si omnes mutationes enti naturales, vel generatim omnia ipsi naturaliter inhaerentia accidentia finiuntur s. cessant, finitur eius natura, §. 469, 23, et ens moritur, §. 430. Ergo vita corporis humani@@1@@, s. duratio naturae eius, qua pollet, ut corpus humanum, continuatur, superstite vel unico minimo motu vitali vel arbitrario, ipsi, qua corpus humanum est, naturali, §. 733, 740. Mors corporis humani@@2@@, s. finis eius naturae, qua pollet, ut corpus humanum, est omnimoda motuum vitalium et arbitrariorum cessatio. Ergo mors definita §. 556 est mors corporis humani.","glosses":["das Leben","der Tod des menschlichen Leibes"],"marks":["*","**"]},
 {"num":777,"section":"parsiii-capii-seciiii","aa":150,"ed":315,"text":"Animal cum sit compositum ex anima et corpore, cum quo illa est in artissimo commercio, §. 740, natura eius est composita ex natura corporis et animae in commercio artissimo positorum, §. 430. Hinc quaedam mutationes harmonicae animae corporisque in artissimo commercio positorum dum exsistunt, vivit animal@@1@@. Cessatio omnium actionum harmonicarum animae et corporis in artissimo commercio positorum, est mors animalis@@2@@. Iam per mortem corporis cessant omnes harmonicae mutationes animae et corporis morientis in artissimo commercio positorum, §. 776, 448. Ergo mors corporis est etiam mors animalis, mors corporis humani mors hominis, §. 740. Ergo mors §. 556 definita est mors hominis, §. 776.","glosses":["lebt","stirbt das Thier"],"marks":["*","**"]},
 {"num":778,"section":"parsiii-capii-seciiii","aa":150,"ed":316,"text":"Mors animalis vel absoluta@@1@@ est, cessatio omnium cum omni corpore animali mutationum animae harmonicarum, vel respectiva@@2@@ tantum (transformatio et metamorphosis animalis), cessatio mutationum harmonicarum animae cum aliquo certo tantum corpore, quocum in artissimo fuerat commercio. Mors hominis vel absoluta est, vel respectiva tantum, i.e. moriente corpore, quale in his terris hominibus esse experimur, aut omne animae humanae cum aliquo corpore cessat commercium artissimum, aut venit cum alio in novum eiusmodi commercium, §. 776, 777.","glosses":["der schlechterdings","der nur verhältnissweise so genannte Tod des Thieres"],"marks":["*","**"]},
 {"num":779,"section":"parsiii-capii-seciiii","aa":150,"ed":null,"text":"Cum quotidie quaedam partes corporis humani cessent esse cum anima in artissimo commercio, quaedam in illud veniant, patet, quo sensu dici possit homo quotidie mori, quotidie reviviscere, §. 777. Sententia, qua mors hominis nil, nisi transformatio animalis, esse ponitur, vocatur exsilium mortis@@1@@ (absolutae).","glosses":["der aufgehobne Tod"],"marks":["*"]},
 {"num":780,"section":"parsiii-capii-seciiii","aa":150,"ed":317,"text":"Vita animae humanae@@1@@ s. naturae eius duratio, continuatur, dum vel unicum minimum superstes est accidens ipsi qua est anima humana naturale, §. 776. Iam autem, dum durat anima humana, in eadem est perceptio s. repraesentatio status mundi et sui praeteriti, praesentis et futuri, §. 742, 400, quae pro positu certi corporis possit esse distincta, §. 741, accidens, §. 191, ipsi naturale, §. 758. Ergo anima humana, dum exsistit, vivit. Mors animae humanae@@2@@ s. finis naturae eius est simul exsistentiae. Iam omnis animae humanae exsistentia, natura, vita est in se contingens, §. 743, 430. Ergo mors animae humanae est in se possibilis, §. 81, 104.","glosses":["das Leben","der Tod der menschlichen Seele"],"marks":["*","**"],"aaEnd":151},
 {"num":781,"section":"parsiii-capii-seciiii","aa":151,"ed":null,"text":"Mortale@@1@@ est, quod potest mori, et possibilitas moriendi est mortalitas@@2@@. Quod non potest mori, est immortale@@3@@, et impossibilitas moriendi est immortalitas @@4@@. Mortalitas et immortalitas sunt vel absolutae, vel hypotheticae, §. 15, 16. Non absoluta solum, sed et hypothetica satis magna mortalitas corpori humano et homini competit. §. 777, 168, animae non nisi absoluta, et hypothetica annihilandae, §. 745, 780. Immortalitas animae non quidem absoluta tribui potest, §. 780, quia tamen sexcentis modis, quibus corpus mori potest, non mori potest indestructibilis, §. 746, admodum magna ipsi convenit immortalitas hypothetica. Nulla substantia huius mundi, §. 354, 358, annihilatur, §. 227, 228. Ergo anima humana moriente corpore, duale in his terris homines habent, superstes vivit immortaliter, §. 780, 742. Thnetopsychitae @@5@@ animam humanam mori cum corpore ponentes errant.","glosses":["sterblich","Sterblichkeit","unsterblich","Unsterblichkeit","Freunde des Seelen-Todes"],"marks":["*","**","***","a","b"],"aaEnd":152},
 {"num":782,"section":"parsiii-capii-secv","aa":152,"ed":319,"text":"Anima humana post mortem (corporis et hominis, quales in his terris experimur) servat spiritualitatem, libertatem, personalitatem, §. 781, 756. Servatam memoriam sui intellectualem si dixeris immortalitatem, hoc etiam significatu anima humana immortalis est, §. 781, 641. Qua usum, aut perceptiones eius totales per longius tempus non nisi sensitivae sunt, aut mox intellectuales nanciscitur. Prius ponentes sunt hypnopsychitae@@1@@, qui si negent umquam animam post mortem huius corporis intelligere, psychopannychitae@@2@@ sunt. Anima humana ante mortem non nihil clare distincteve cognoverat, §. 754. Haec realitas, §. 520, numquam omnino sterilis, §. 517, qua realitas est, non, nisi realitates, habet in indefinitum consectaria, §. 140, et est in indefinitum in universali nexu cum animae spiritualitate, intellectu, ratione, denuo realitatibus, §. 531, 49, quae non, nisi realitates, habent, qua tales, consectaria in indefinitum, §. 23, 140. Hinc nexus inter cognitionem huius vitae claram distinctamve et spiritualitatem, intellectum, rationem animae, est denuo realitas consectaria realia habens in indefinitum, §. 140. Naturalia autem horum omnium consectaria realia non possunt in indefinitum augeri, §. 23, 162, citra perceptiones distinctas, §. 631, ratiocinia, §. 642, volitiones nolitionesve, §. 665, 690. Hinc anima humana post mortem servans suam naturam, §. 780, 781, naturaliter, tandem saltim, vitam etiam intellectualem actionibus spiritualibus exserit, §. 639, et errant psychopannychitae.","glosses":["Vertheidiger des Seelen-Schlafes","der ewigen Nacht"],"marks":["*","**"]},
 {"num":783,"section":"parsiii-capii-secv","aa":152,"ed":null,"text":"Anima humana post mortem intelligens, aut personalitatem etiam in tantum exserit, ut distincte recordetur status sui in hac vita, aut minus, §. 782. Posterius ponentes dici possunt patroni lethaei poculi@@1@@. Prius est naturalius, §. 583, 561.","glosses":["Freunde des Bechers der Vergessenheit"],"marks":["*"]},
 {"num":784,"section":"parsiii-capii-secv","aa":152,"ed":320,"text":"Status animae humanae post mortem potest considerari, 1) posita hominis morte absoluta, §. 778. Tunc ponitur anima humana post mortem omni corpore destituta, seu nullum corpus esse, cum quo in artissimum denuo venerit commercium, §. 742, 740. 2) posita morte hominis respectiva tantum, ut cum novo corpore in artissimum iterum missae commercium, §. 778. Initium novi cum novo corpore commercii artissimi palingenesia@@1@@ (regeneratio, metensomatosis et metempsychosis latius sumpta) dicitur. Hanc ponentes vel simul lethaeo patrocinantur poculo, novumque corpus ponunt, qualia in his terris nota sunt, vel neutrum ex his cum illa ponunt. Priores defendunt metempsychosin strictius dictam et crassam@@2@@ improbabiliter, §. 783.","glosses":["der Tausch des Leibes gegen einen andern","die grobe Seelenwanderung"],"marks":["**","**"],"aaEnd":153},
 {"num":785,"section":"parsiii-capii-secv","aa":153,"ed":321,"text":"Anima humana durans post mortem corporis, quod in his terris habuit, §. 781, singulas adhuc partes huius universi repraesentat, §. 752, 780, ergo et eiusdem corpora, §. 155. Corpora ipsi simultanea in eam agunt, ab eadem patiuntur, ipsa a corporibus sibi simultaneis patitur, in ea influit, §. 408, sed non in duo ex illis aequaliter influit, nec a duobus ex illis aequaliter patitur, §. 272. Ergo unum corpus est, quocum anima humana post mortem corporis durans in artissimum venit commercium, §. 448, 739. Hinc si anima eiusmodi separata dicatur, intelligendum id est respective ad corpus, quale hominibus in his esse terris experimur, et mors hominis non est, nisi transformatio animalis, §. 779, et palingenesia, quae tamen cum metempsychosi crassa male confunderetur, §. 784.","glosses":[],"marks":[]},
 {"num":786,"section":"parsiii-capii-secv","aa":153,"ed":null,"text":"Anima humana post mortem corporis huius durans est cum alio in artissimo commercio, §. 785. Novum illud corpus in diversis suis statibus huic corpori, nunc minus, nunc magis erit congruens, §. 270, 265. Ergo aliquis ipsius status erit, in quo corpori. quod in hac vita fuerat in artissimo cum anima commercio, congruentissimum erit, §. 161, hinc idem, §. 70.","glosses":[],"marks":[]},
 {"num":787,"section":"parsiii-capii-secv","aa":153,"ed":322,"text":"Sicut perfectio spiritus finiti 1) vel absolute necessaria est, vel contingens, §. 147, 2) vel naturalis, vel supernaturalis, §. 496, 3) vel interna, vel externa, §. 98, 4) vel moralis late dicta, vel minus, §. 723: ita et bona spiritui, quibus illa positis ponitur, §. 100, sunt 1) vel metaphysica, vel contingentia, §. 147, 2) vel naturalia, vel supernaturalia, §. 469, 3) vel domestica, vel adventicia, §. 660, 4) vel moralia late dicta, vel minus talia, § 723. Moralia late dicta spiritui dato cum eius libertate propius connectuntur, vel ut rationes, §. 14, a priori, §. 24, et ut antecedentia certi eiusdem status, vel ut rationata, §. 14, a posteriori, §. 24, et ut consectaria certi eiusdem status, §. 596, vel utrimque, §. 24. Quae pendent a data libertate propius, stricte moralia@@1@@ dicuntur et non numquam simpliciter. Hinc bona spiritui propius ex eius libertate pendentia sunt stricte moralia@@2@@, et perfectio his positis ponenda beatitudo@@3@@. Complexus perfectionum spiritui convenientium est felicitas@@4@@. Complementum beatitudinis ad felicitatem finiti spiritus est prosperitas@@5@@, et bona, quibus positis ponitur, sunt prospera@@6@@ (physica stricte dicta). Felicitas spiritus finiti est complexus prosperitatis et beatitudinis.","glosses":["sittlich in engerer Bedeutung","sittliche Güter in engrer Bedeutung","Seligkeit","Glückseligkeit","gutes Glück, Wohlfart","Glücks-Güter"],"marks":["*","**","***","a","b","c"],"aaEnd":154},
 {"num":788,"section":"parsiii-capii-secv","aa":154,"ed":323,"text":"Mala spiritus ab eius libertate propius pendentia sunt stricte moralia@@1@@, §. 787 (mala culpae, peccata), mala late moralia@@2@@ spiritui sunt cum eius libertate propius connexa. Imperfectio ex his est corruptio moralis late@@3@@, ex illis stricte dicta@@4@@. Complexus imperfectionum spiritui convenientium est infelicitas@@5@@. Complementum corruptionis stricte moralis ad infelicitatem finiti spiritus est miseria@@6@@, et mala, quibus positis ponitur, sunt damna late dicta@@7@@ (mala physica stricte dicta). Infelicitas est complexus miseriae corruptionisque moralis.","glosses":["das sittlich Böse in engrer","in weitrer Bedeutung","das sittliche Verderben in weiter","in engerer Bedeutung, oder Unseligkeit","Unglückseligkeit","Elend","Widerwärtigkeiten, Leiden, ein schmerzendes Übel"],"marks":["*","**","***","a","b","c","d"]},
 {"num":789,"section":"parsiii-capii-secv","aa":154,"ed":324,"text":"Anima humana in hac vita@@1@@, i.e. dum vivit in commercio artissimo cum corpore, quale hominibus in his terris esse experimur, mutatur continuo, §. 418, 754. Harum mutationum nulla est obiective indifferens absolute, §. 654. Omnes ergo vel bonae vel malae sunt, vel utrumque. Quae mutationes animae bonae malaeque simul sunt, uti sunt omnes, §. 264, eae vel bonae malaeque simul sunt aequaliter, vel inaequaliter, §. 70. Magis bonae, quam malae plus ponunt felicitatis, quam infelicitatis, magis malae, quam bonae plus ponunt infelicitatis, quam felicitatis, adeoque a potiori denominandae priores bonae, posteriores malae sunt, §. 787, 788.","glosses":["in diesem Leben"],"marks":["*"]},
 {"num":790,"section":"parsiii-capii-secv","aa":154,"ed":null,"text":"Pone rem tantum totaliter malam, quantum est bona, non haberet ea summum realitatis gradum, §. 246, 248. Ergo esset ens finitum, §. 248, hinc contingens, §. 257, adeoque oppositum eius esset possibile, §. 101, cumque ipsius exsistentia esset contingens, §. 109, oppositi eius exsistentia esset possibilis, §. 101. At oppositum rei eiusmodi non posset, nisi extra eam, exsistere, §. 81, 7, et esset bonum et malum ipsi rei positae totaliter aequale, §. 81, 267. Ergo possibilia forent duo extra se invicem actualia totaliter aequalia, quod contra §. 272. Ergo res, quae tantum totaliter bona esset, quantum mala, non potest exsistere. Ergo nec dantur mutationes animae humanae, nisi vel bonae, vel malae. Ergo omnis anima humana in hac vita vel felix est, vel infelix, §. 789.","glosses":[],"marks":[]},
 {"num":791,"section":"parsiii-capii-secv","aa":154,"ed":325,"text":"Anima humana durans post mortem corporis continuo mutari pergit, §. 781, 782. Ergo quovis durationis ipsius momento augetur eiusdem felicitas, vel infelicitas, §. 790, 162. Ergo anima humana durans post mortem corporis, aut maiori fruetur, quam in hac vita, felicitate, et est beata@@1@@, aut maiori laborabit infelicitate, et est damnata@@2@@. Beatitudo, quam anima post hanc vitam semel ingressa ponitur, aut coexsistet animae, dum durat, aut succedet eidem aliquando damnatio. Damnatio, quam anima post hanc vitam semel ingressa ponitur, aut coexsistet animae, dum durat, aut succedet eidem aliquando beatitudo, §. 790, 789. Prius in utroque casu naturalius est, §. 139, 140.","glosses":["eine selige","verdammte Seele"],"marks":["*","**"],"aaEnd":155},
 {"num":792,"section":"parsiii-capii-secvi","aa":155,"ed":null,"text":"Omnis anima cum sit id in ente, quod sibi alicuius esse potest conscium, §. 504, habet facultatem cognoscitivam, §. 519, eamque vel inferiorem tantum, vel etiam superiorem, §. 520, 524. Prior erit anima mere sensitiva@@1@@. Animal, quod animam habet mere sensitivam, brutum@@2@@ est; cuius anima spiritus est, est animal rationale@@3@@. Ergo homo est animal rationale, §. 754, 740.","glosses":["eine bloss sinnliche Seele","das Vieh","ein vernünftiges Thier"],"marks":["*","**","***"]},
 {"num":793,"section":"parsiii-capii-secvi","aa":155,"ed":326,"text":"Animae brutorum sunt cum corpore animali in artissimo commercio, §. 740, hinc corpus suum clare obscureque repraesentant, §. 792, 736. Ergo sunt vires repraesentativae universi pro positu corporis brutorum in eodem, §. 741, hinc substantiae, §. 198, monades, §. 234, entia simplicia, §. 230, non habent partes extra partes, §. 224, finitae, §. 202, 792, indivisibiles, §. 244, hinc physice incorruptibiles, §. 746, immateriales et incorporeae, §. 422, sensatione, imaginatione, praevisione et reliquis sine distincta cognitione actuandis per vim repraesentativam universi pro positu corporis facultatibus instructae, §. 792, hinc appetitu et aversatione sensitivis, §. 667, et arbitrio, §. 718, instinctibus, fugis, et stimulis impellendae, §. 677, etiam ad affectus, §. 678.","glosses":[],"marks":[]},
 {"num":794,"section":"parsiii-capii-secvi","aa":155,"ed":327,"text":"Cum quaestionibus: an bruta habeant animam, an rationalem, facilioribus, §. 792, 793, ne confundantur: 1) an omnia in his terris phaenomena, praeter humanum, corpora destituantur anima, §. 504, 2) an quaedam eorum sint sedes animae rationalis, §. 745, 3) an omnia, quae sunt corpora animalia, vel iam nunc aliquo rationis usu gaudentis, vel tandem gavisurae, §. 782, 639.","glosses":[],"marks":[]},
 {"num":795,"section":"parsiii-capii-secvi","aa":155,"ed":null,"text":"Animae brutorum destituuntur intellectu, §. 792. Ergo non sunt spiritus, §. 402, carent personalitate, §. 641, ratione, §. 640, voluntate, noluntate, §. 690, et libertate §. 719, nec sunt immortales, ut animae humanae, §. 781-784, nec felicitatis nec infelicitatis aut nunc, aut olim capaces, §. 787, 788.","glosses":[],"marks":[],"aaEnd":156},
 {"num":796,"section":"parsiii-capii-secvii","aa":156,"ed":null,"text":"Spiritus maiori intellectus gradu essentiali praediti, quam qui est hominis, sunt superiores@@1@@, minori, inferiores@@2@@. Sunt utrique finiti, vel felices, vel infelices, §. 790, illi agathodaemones@@3@@ (calodaemones), hi cacodaemones@@4@@.","glosses":["höhere","niedrigere","gute","böse Geister"],"marks":["*","**","***","****"]},
 {"num":797,"section":"parsiii-capii-secvii","aa":156,"ed":328,"text":"Omnis spiritus finitus, sive superior fuerit homine, sive inferior, actualis habet corpus, quocum est in artissimo commercio, §. 785, 796, vel ad certum extra se centrum constanter gravitans, vel minus. Prior est incola certi corporis in universo totalis, eiusque vel fixi, vel vagi, e.c.","glosses":[],"marks":[]},
 {"num":798,"section":"parsiii-capii-secvii","aa":156,"ed":null,"text":"Quemcumque spiritus superior finitus habuerit gradum intellectus, non tamen habet maximum, §. 248, hinc non omnia distinctissime repraesentat, §. 637, sed ita, ut ex corpore eius cognosci possit, cur haec, non alia, purius, profundius, distinctius, confuse, obscure repraesentet, §. 797, 512. Ergo spiritus finitus omnis habet facultatem cognoscitivam inferiorem, §. 520.","glosses":[],"marks":[]},
 {"num":799,"section":"parsiii-capii-secvii","aa":156,"ed":329,"text":"Nullus finitus spiritus sive superior homine fuerit, sive inferior, potest physice corrumpi, §. 746; hinc dissoluto vel maxime aliquo ex ipsius corporibus, tamen superstes erit, nisi annihiletur, §. 745, dum durat, servat personalitatem, crescente potius, quam decrescente, aut omnino cessante intellectus, rationis, libertatis usu, §. 782, et naturalius ipsi est, praeteriti status sui distincte meminisse, quam lethaeum poculum, §. 783. Ergo omnis spiritus finitus est natura sua, i.e. per vim ipsius repraesentativam universi, §. 782, immortalis, ut anima humana, §. 781, 783, naturalius in beatitudine vel damnatione, quam semel ingressus est, §. 787, 791, dum durat, perdurans, quam ut semel insigniter beatus damnetur, aut v.v., §. 791.","glosses":[],"marks":[],"aaEnd":157},
 {"num":800,"section":"parsiiii-proleg","aa":157,"ed":null,"text":"Theologia naturalis est scientia de deo, quatenus sine fide cognosci potest.","glosses":[],"marks":[]},
 {"num":801,"section":"parsiiii-proleg","aa":157,"ed":null,"text":"Theologia naturalis prima philosophiae practicae, teleologiae et theologiae revelatae principia continet. Ergo refertur, §. 2, cum ratione ad metaphysicam, §. 1.","glosses":[],"marks":[]},
 {"num":802,"section":"parsiiii-proleg","aa":157,"ed":null,"text":"Theologia naturalis 1) conceptum dei, 2) operationes eius considerat.","glosses":[],"marks":[]},
 {"num":803,"section":"parsiiii-capi-seci","aa":157,"ed":null,"text":"Ens perfectissimum@@1@@ est, cui summa in entibus est perfectio: i.e. in quo tot, tanta, tantum in tot et tanta consentiunt, quot, quanta, quantum in plurima et maxima possibilium in ullo ente consentire possunt, §. 185. Est ergo in ente perfectissimo quaedam pluralitas absolute necessario, §. 74.","glosses":["das vollkommenste"],"marks":["*"]},
 {"num":804,"section":"parsiiii-capi-seci","aa":157,"ed":null,"text":"Praedicata entis perfectissimi dicuntur eius perfectiones. In ente perfectissimo tot sunt perfectiones plurimum consentientes, quot in ente simul esse possunt, quot sunt compossibiles, §. 803.","glosses":[],"marks":[]},
 {"num":805,"section":"parsiiii-capi-seci","aa":157,"ed":null,"text":"Omnis entis perfectissimi perfectio tanta est, quanta ullo in ente esse potest, §. 803, 804.","glosses":[],"marks":[]},
 {"num":806,"section":"parsiiii-capi-seci","aa":157,"ed":331,"text":"Ens perfectissimum est ens reale, §. 803, 135. Ergo illi convenit realitas tanta, quanta in ente esse potest. Ens perfectissimum est realissimum, §. 805, 804, in quo plurimae maximae realitates, summum bonum et optimum metaphysice, §. 190.","glosses":[],"marks":[]},
 {"num":807,"section":"parsiiii-capi-seci","aa":157,"ed":null,"text":"Omnes realitates sunt vere positiva, nec ulla negatio est realitas, §. 36. Ergo si vel maxime coniungantur in ente omnes, numquam ex iis orietur contradictio, §. 13. Ergo omnes realitates sunt in ente compossibiles. Iam ens perfectissimum est entium realissimum, §. 806. Ergo enti perfectissimo convenit omnitudo realitatum, earumque, quae ullo in ente esse possunt, maximarum, §. 805, 190.","glosses":[],"marks":[],"aaEnd":158},
 {"num":808,"section":"parsiiii-capi-seci","aa":158,"ed":null,"text":"Posita realitate tollitur negatio, §. 36. Iam in ente perfectissimo ponendae realitates omnes, §. 807. Ergo tollendae omnes negationes.","glosses":[],"marks":[]},
 {"num":809,"section":"parsiiii-capi-seci","aa":158,"ed":332,"text":"In omni impossibili aliquid simul ponendum et tollendum est, §. 7. Id vel negatio, vel realitas, §. 36, 9. Realitas in ente perfectissimo nulla tollenda est, §. 807. Negatio in ente perfectissimo nulla ponenda est, §. 808. Ergo nihil in ente perfectissimo simul tollendum est, et ponendum. Ens perfectissimum est possibile, §. 8.","glosses":[],"marks":[]},
 {"num":810,"section":"parsiiii-capi-seci","aa":158,"ed":null,"text":"Exsistentia est realitas cum essentia et reliquis realitatibus compossibilis, §. 66, 807. Ergo ens perfectissimum habet exsistentiam, §. 807.","glosses":[],"marks":[]},
 {"num":811,"section":"parsiiii-capi-seci","aa":158,"ed":null,"text":"Deus@@1@@ est ens perfectissimum. Ergo deus actualis est, §. 810, 55.","glosses":["Gott"],"marks":["*"]},
 {"num":812,"section":"parsiiii-capi-seci","aa":158,"ed":null,"text":"Dei praedicata perfectiones sunt, §. 811, 804, omnes realitates maximae, §. 807. Ipsa eius possibilitas est maxima, 1) interna et absoluta, §. 165, dum in eodem plurima maxima sunt compossibilia, §. 805, 807, 2) externa et hypothetica, dum fecundissimae gravissimaeque in eodem rationes in omni mundorum omnium possibilium nexu rationata habent, quae extra deum esse possunt, fecundissima, gravissima, §. 168.","glosses":[],"marks":[]},
 {"num":813,"section":"parsiiii-capi-seci","aa":158,"ed":333,"text":"In deo nullae sunt negationes, §. 808, ergo nec negationes stricte dictae, nec privationes, §. 137, nec malum metaphysicum, nec contingens, §. 146, nec physicum, nec morale quocumque significatu, §. 788.","glosses":[],"marks":[]},
 {"num":814,"section":"parsiiii-capi-seci","aa":158,"ed":null,"text":"In conceptu dei notae non solum totaliter negativae impossibiles, §. 525, sed et partialiter tales vere, §. 813, 808, licet nobis multa in ipso maxime realia negativa esse videantur, §. 12, quia partim negationes affirmativis terminis exprimimus, partim negationem negationis affirmare non satis meminimus, §. 36, 81.","glosses":[],"marks":[]},
 {"num":815,"section":"parsiiii-capi-seci","aa":158,"ed":null,"text":"Perfectiones dei vel sunt in eodem absolutae, vel respectivae, et in his quaedam relativae, §. 37: aut possunt a nobis repraesentari sine actionis nota, quiescentes@@1@@, aut non possunt, operativae@@2@@.","glosses":["ruhende","wirksame Vollkommenheiten"],"marks":["*","**"],"aaEnd":159},
 {"num":816,"section":"parsiiii-capi-seci","aa":159,"ed":334,"text":"Perfectio dei interna, ex qua reliquae tandem omnes internae possunt ita deduci, ut ipsa postea nequeat a vitaturis circulum ex alia perfectione dei interna deduci, est conceptus dei primus, §. 40, 39. Iam ex infinitis dei perfectionibus talis reliquarum deductio est possibilis, §. 24, 49, dum quaelibet est ratio maxima, §. 812, 166, et sufficientissima, §. 169, hinc et ultima simpliciter, §. 170, maxima essentia, §. 171. Ergo infiniti sunt conceptus de deo primi, quorum tamen quilibet pro essentia sumptus est essentia dei unica, §. 40, 77.","glosses":[],"marks":[]},
 {"num":817,"section":"parsiiii-capi-seci","aa":159,"ed":null,"text":"Licet in deo sit nexus maximus, §. 808, 167, et maxime universalis, §. 172, ita ut in eodem ex omnibus omnia verissime, §. 876: tamen ex una perfectione dei facilius a nobis reliquae eius perfectiones cognoscuntur, quam ex alia, §. 527. Ergo eam pro essentia sumere praestat, ex qua facillime reliquas deducere speramus, §. 816. Tantum abest, ut omnis pluralitas in deo sit impossibilis, ut potius in ipsa eius essentia et per eandem quaedam absolute necessario ponatur pluralitas, §. 812, 816.","glosses":[],"marks":[]},
 {"num":818,"section":"parsiiii-capi-seci","aa":159,"ed":null,"text":"Deus praeter essentiam, quamcumque sumpseris, §. 817, determinatus est, qua reliquas etiam perfectiones internas, §. 816, tantum, quantum potest quicquam, qua interna, determinari, §. 812. Ergo deus actualis est, §. 54.","glosses":[],"marks":[]},
 {"num":819,"section":"parsiiii-capi-seci","aa":159,"ed":335,"text":"Deus, qua exsistentiam, determinatus est, §. 818, 811. Ergo deus est ens, §. 61, 57, nec negativum, nec privativum non ens, §. 7, 54.","glosses":[],"marks":[]},
 {"num":820,"section":"parsiiii-capi-seci","aa":159,"ed":null,"text":"A posse dei ad esse eiusdem valet consequentia, i.e. exsistentia eius per essentiam ipsius sufficienter determinatur, §. 809-811, et quidem maxima, §. 805, complexus plurimarum maximarum affectionum in ullo ente compossibilium, s. maximae essentiae, §. 816, quamcumque sumpseris, §. 817, complementum, §. 55, aeternum, §. 302.","glosses":[],"marks":[],"aaEnd":160},
 {"num":821,"section":"parsiiii-capi-seci","aa":160,"ed":null,"text":"Deo convenit unitas, §. 819, 73, maxima, §. 812, inseparabilitas plurimarum maximarum realitatum, §. 173, hinc patet, 1) qui possit eminenter dici perfecta unitas, quae exempli loco esse potest, quomodo et maxime steriles visae in dei perfectionibus sint tamen eiusdem essentia, §. 816, 2) posita summa dei unitate, non tantum non tolli, sed etiam poni quandam inseparabilium in eodem pluralitatem, §. 74.","glosses":[],"marks":[]},
 {"num":822,"section":"parsiiii-capi-seci","aa":160,"ed":336,"text":"Deo convenit veritas transcendentalis, §. 819, 90, maxima, §. 812, summus perfectionum ipsius ordo, §. 175, 89, summa possibilitas, §. 812, summus nexus, §. 817, summa cum fortissimis regulis convenientia, §. 179, 184, qualis lex optimi generatim: optimum iungatur optimo, §. 482, 187, et optimi in entibus: optimum compossibilium in ente perfectissimo coniungatur optimo, §. 803.","glosses":[],"marks":[]},
 {"num":823,"section":"parsiiii-capi-seci","aa":160,"ed":null,"text":"Deus non actualis esset ens omnibus realitatibus gaudens, cui quaedam tamen deesset, §. 66, 812, determinatus, qua omnes perfectiones internas, quantum ens, qua interna, determinari potest, §. 818, et tamen, qua aliquas, non ita determinatus, §. 54. Ergo oppositum exsistentiae divinae est in se impossibile, §. 15. Exsistentia dei est absolute necessaria, §. 102. Deus est ens necessarium, §. 109, cuius summa exsistentia, §. 820, est eiusdem essentia, §. 819, salva tamen §. 817.","glosses":[],"marks":[]},
 {"num":824,"section":"parsiiii-capi-seci","aa":160,"ed":null,"text":"Si deus non actualis esset, falsum esset principium contradictionis, §. 823, 7, primum et formae et materiae principium in omnibus demonstrationibus nostris. Ergo licet multae scientiae possint demonstrari complete citra ullam praemissam theologicam, §. 1-800: non tamen essent, aut ipsae, aut earum obiecta, e.g. §. 61, 354, 504, immo ne possibilia quidem essent, §. 8, nisi deus actualis esset.","glosses":[],"marks":[]},
 {"num":825,"section":"parsiiii-capi-seci","aa":160,"ed":337,"text":"Deus est ens necessarium, §. 823, 824. In ente necessario non sunt modi, §. 111. Ergo in deo non sunt modi, s. accidentia praedicabilia.","glosses":[],"marks":[],"aaEnd":161},
 {"num":826,"section":"parsiiii-capi-seci","aa":161,"ed":null,"text":"Si quid in ente necessario deprehendimus, quod repraesentatis in ente contingenti partialiter simile, partialiter diversum ab iis est, discrimina tamen non satis intelligimus, nec nomen ipsi peculiare invenimus: illud dicimus eius, quod in ente contingenti simile notavimus, analogon, deoque tribuitur per analogiam, si realitates in eius conceptu regnare videntur, per eminentiam@@1@@ (excellentiam), si negationes, per reductionem@@2@@ (via negationis).","glosses":["in unendlich-ausnehmender","in geläuterter Bedeutung"],"marks":["*","**"]},
 {"num":827,"section":"parsiiii-capi-seci","aa":161,"ed":338,"text":"Si in ente necessario quaedam deprehendimus, quae hypothetice necessaria esse est absolute necessarium, quatenus, qua hypotheticam necessitatem, modis similia sunt, §. 108, dicuntur modorum analoga@@1@@, §. 826, quatenus ea in deo exsistere hypothetice necessaria absolute necessarium est per essentiam, §. 823, 54, attributa sunt, §. 107. Hinc attributa divina possunt dividi in similiora attributis finitorum, et modis finitorum. Ultima etiam vera sunt attributa, cum ratio sufficiens in essentia dei sit; 1) exsistentiae eorundem, quatenus contradistinguitur indeterminationi, §. 54. Ens contingens potest esse, qua multa, indeterminatum, §. 34, 134. Ens necessarium, qua nulla, et quidem per essentiam, §. 820. 2) durationis, aeternitatis, et immutabilitatis eorum, quae sunt semel in deo. In contingentibus entibus essentialis limes est ratio sufficiens, cur debeant continuo mutari, dum exsistunt, interne. In ente necessario essentialis infinitudo est ratio sufficiens oppositi: 3) cur alia loco horum, ab aeterno in aeternum in deo exsistere potuissent, et hinc, 4) cur horum, non aliorum exsistentia sic, non aliter, determinata sit, non nisi per hypotheticam necessitatem, §. 102.","glosses":["das den Zufälligkeiten ähnliche"],"marks":["*"]},
 {"num":828,"section":"parsiiii-capi-seci","aa":161,"ed":null,"text":"Sanctitas@@1@@ est realitas entis, qua plures illius imperfectiones vere tales tolluntur, hinc sanctissimum@@2@@ est, cuius realitate omnes eius imperfectiones tolluntur. Iam per omnitudinem realitatum maximarum in deo omnes in eodem imperfectiones tolluntur, §. 142, 808. Ergo deus est sanctissimus.","glosses":["Heiligkeit","das Allerheiligste"],"marks":["*","**"]},
 {"num":829,"section":"parsiiii-capi-seci","aa":161,"ed":339,"text":"In deo nulla est imperfectio, §. 828. Ergo nec essentialis, nec accidentalis, nec interna, nec externa, §. 121, 808. Idem patet ex §. 813.","glosses":[],"marks":[],"aaEnd":162},
 {"num":830,"section":"parsiiii-capi-seci","aa":162,"ed":null,"text":"In deo est ratio sufficiens, cur ipsi inexsistant ipsius perfectiones, §. 822, 823. Ergo vis stricte dicta, §. 197. Hinc deus est substantia, §. 199.","glosses":[],"marks":[]},
 {"num":831,"section":"parsiiii-capi-seci","aa":162,"ed":null,"text":"Deus habet vim, §. 830, maximam, §. 812. Ergo plurimis maximis actuandis accidentibus sufficientem, §. 203.","glosses":[],"marks":[]},
 {"num":832,"section":"parsiiii-capi-seci","aa":162,"ed":null,"text":"Accidentia non exsistunt extra suas substantias, §. 194. Ergo vis actuandis plurimis maximis accidentibus sufficiens sufficit actuandis plurimis substantiis. Ergo omnibus, §. 191, 247. Vis alicui actuando sufficiens est potentia@@1@@. Hinc omnipotentia@@2@@ est vis actuandis omnibus sufficiens. Deus est omnipotens, §. 831.","glosses":["Gewalt","Allgewaltigkeit"],"marks":["*","**"]},
 {"num":833,"section":"parsiiii-capi-seci","aa":162,"ed":340,"text":"Absolute impossibilia nihil sunt, §. 7. Ergo qui posset absolute impossibilia, nihil posset, §. 469. Deus potest omnia, §. 832. Ergo dei omnipotentia non extenditur ad absolute impossibilia. Impossibile alicui est, ad quod actuandum vires eius non sufficiunt, §. 469. Hoc significatu deo nulla res impossibilis. Omnis res ergo nobis et omni finito impossibilis deo possibilis est, §. 832.","glosses":[],"marks":[]},
 {"num":834,"section":"parsiiii-capi-seci","aa":162,"ed":null,"text":"Miracula sunt possibilia, §. 475. Dei vis ad omnia possibilia actuanda sufficit, §. 832. Ergo deus potest patrare miracula rigorosa, §. 477, 833.","glosses":[],"marks":[]},
 {"num":835,"section":"parsiiii-capi-seci","aa":162,"ed":null,"text":"Deus potest actuare omnes mundos possibiles, §. 832. Ergo et optimum, §. 436, et imperfectissimum sine exceptionibus, §. 442.","glosses":[],"marks":[]},
 {"num":836,"section":"parsiiii-capi-seci","aa":162,"ed":null,"text":"Deus est substantia, §. 830, nec habet modos, §. 825. Ergo est substantia necessaria, §. 202, nec statum internum habet, §. 206, nec modificabilis est, §. 209. Unde denuo patet, mundum esse non posse modificationem dei, §. 388.","glosses":[],"marks":[]},
 {"num":837,"section":"parsiiii-capi-seci","aa":162,"ed":341,"text":"Ortus et interitus omnis, ortus ex nihilo et annihilatio substantiae necessariae sunt absolute impossibiles; deus est substantia necessaria, §. 836. Ergo ortus et interitus omnis in deo est absolute impossibilis, §. 227, 228.","glosses":[],"marks":[]},
 {"num":838,"section":"parsiiii-capi-seci","aa":162,"ed":null,"text":"Omnis substantia monas est, §. 234. Deus est substantia, §. 830. Ergo monas est, et ens simplex, §. 230. Posita summa dei simplicitate, tollitur quidem eum ulla ratione compositum esse partibus extra partes, §. 224, non autem tollitur diversitas plurium in deo, §. 817, realissima, §. 807, quia etiam in finitis falsum est, omnia realiter diversa esse extra se invicem posita, §. 755.","glosses":[],"marks":[],"aaEnd":163},
 {"num":839,"section":"parsiiii-capi-seci","aa":163,"ed":null,"text":"Deus est ens necessarium, §. 823, 824. Omnis entis necessarii determinationes sunt absolute et interne immutabiles, §. 132. Ergo deus absolute et interne est immutabilis, §. 126, 127. Idem sic patet: si deus absolute et interne mutabilis esset, saltim quaedam eius perfectio interna posset post aliam exsistere, §. 124. Hinc illius, quae ante eam exsistere potuisset, posset tolli exsistentia. Haec est realitas deo interna, §. 37. Ergo quaedam ex realitatibus dei possent separari ab aliis, §. 72, quod contra summam dei unitatem, §. 821.","glosses":[],"marks":[]},
 {"num":840,"section":"parsiiii-capi-seci","aa":163,"ed":342,"text":"Si deus esset compositus, esset extensus, §. 241, ipsique vis inertiae tribuenda esset, §. 832, 294. Hinc esset materia, §. 295. Ergo divisibilis, §. 427, adeoque interne mutabilis, §. 244, 126, quod contra §. 839. Ergo deus est ens simplex, §. 224. Cumque sit substantia, §. 830, est monas, §. 230. Denuo patet, errare materialistas universales, §. 395.","glosses":[],"marks":[]},
 {"num":841,"section":"parsiiii-capi-seci","aa":163,"ed":null,"text":"In deo non sunt simultanea extra se invicem posita, partes ipsius, §. 840, hinc nec spatium, §. 239. Ergo deus non est extensus, nec eo significatu spatium replet, quo extensa illud replere dicuntur, §. 241.","glosses":[],"marks":[]},
 {"num":842,"section":"parsiiii-capi-seci","aa":163,"ed":null,"text":"Deus non habet magnitudinem quantitativam, §. 838, 243, licet sit ens maximum, §. 161, plurimarum maximarum realitatum, §. 807, 812. Denuo patet, deum esse indivisibilem et absolute quidem, §. 244.","glosses":[],"marks":[]},
 {"num":843,"section":"parsiiii-capi-seci","aa":163,"ed":343,"text":"Omnitudo realitatum, quae esse possunt, maximarum est gradus realitatis maximus, §. 247, 248. Hic deo enti realissimo convenit, §. 807, 812. Ergo deus est ens infinitum reale, §. 248. Idem patet ex eo, quod deus ens necessarium, §. 823, 258.","glosses":[],"marks":[]},
 {"num":844,"section":"parsiiii-capi-seci","aa":163,"ed":null,"text":"Omnes dei perfectiones habent gradum realitatis suae, quem in ente habere possunt, maximum, §. 812. Hinc et ipsae omnes sunt infinitae, §. 248. Ad summam cuiusvis harum perfectionum realitatem pertinet consensus in ente perfectissimo, §. 139, 140. Ergo in quo una infinita realitas, in eo omnes, in quo omnes, in eo summae, §. 843. Ergo in quo est una realitas infinita, deus est, §. 811. Hinc colligi potest, qua ratione plures perfectiones dei possint, nunc hae, nunc illae, ceu conceptus primi, sumi, §. 816, et cur nequeat extra deum aeque potens, ac ipse, auctor mali admitti. Manichaeismus est sententia aeque potentem deo auctorem mali ponens exsistere, et error est.","glosses":[],"marks":[],"aaEnd":164},
 {"num":845,"section":"parsiiii-capi-seci","aa":164,"ed":null,"text":"Deus est actu, quicquid esse potest, qua perfectiones internas, §. 843, 259. Denuo patet, deum esse interne immutabilem, §. 252, et ens necessarium, modo caveatur circulus, §. 843, 256.","glosses":[],"marks":[]},
 {"num":846,"section":"parsiiii-capi-seci","aa":164,"ed":344,"text":"Plures dii sunt impossibiles. Dum enim essent plures, partim essent diversi, §. 74, hinc esset in uno, quod non esset in altero, §. 38. Hoc aut esset realitas, aut negatio, §. 36. Si realitas esset, ille, cui deesset, non foret deus, §. 807. Si negatio esset, ille, cui inesset, non foret deus, §. 808. Si poneretur una realitas esse in uno, sed alia aequipollens in alio, in neutro esset omnitudo realitatum, hinc neuter esset deus, §. 807. Cum ergo deus, quem hucusque meditati sumus, §. 811-845, ita sit summe unum omnium realitatum maximarum absolute inseparabilium, §. 821, ut aliud unum alterumve ab hoc diversum non sit, nec esse possit, quod deum esse necessarium esse, hucusque vidimus, §. 811-845, deus, quem hucusque meditati sumus, deus est unicus, §. 77. Polytheismus@@1@@ est sententia plures deos ponens, et error est. Nos potius vere in deo summam unicitatem veneramur, qua ens maximum, §. 842, ab omnibus, etiam maximis in suo genere, e.g. natura mundi optimi universa, et spiritu finitorum maximo, per plurimas maximas differentias, §. 844, distinguitur, §. 173. Haec differentia maxima extenditur ad ipsas relationes ita, ut talis et tanta relatio inter rem, quae deus hucusque consideratus non est, et tertiam intercedere nequeat, qualis et quanta inter hunc deum, et datam rem tertiam, §. 812, 817. Hac summa unicitate dei tollitur quidem aequalitas ullius rei, quae non est deus, etiamsi alias maxima, cum eodem, et similitudo non solum paene totalis, sed etiam tollens infinitam dissimilitudinem inter deum et alia omnia ponendam, §. 844, non vero tollitur pluralitas maximorum intra deum et horum summe eorundem infinita simul differentia respectiva, §. 37, 174, sed potius ponitur in infinitis characteribus, deum a rebus omnibus quid distinguat, §. 67.","glosses":["die Vielgötterei"],"marks":["*"]},
 {"num":847,"section":"parsiiii-capi-seci","aa":164,"ed":null,"text":"Denuo patet dei simplicitas. Si enim deus compositus foret, eius partes essent substantiae extra se positae, §. 225, 282. Harum unica tantum esset substantia infinita, §. 846. Ergo reliquae finitae, §. 77, 248. Hinc in deo ponendae essent quaedam imperfectiones absolute necessariae, §. 250, 155. Quod contra §. 828.","glosses":[],"marks":[]},
 {"num":848,"section":"parsiiii-capi-seci","aa":164,"ed":346,"text":"Deus non habet figuram, §. 280, 847. Anthropomorphismus crassior est error deo figuram e.g. humanam tribuentium, subtilior est error, qui deo imperfectiones rerum finitarum e.g. hominum tribuit, §. 828.","glosses":[],"marks":[],"aaEnd":165},
 {"num":849,"section":"parsiiii-capi-seci","aa":165,"ed":null,"text":"In deo non sunt successiva, §. 839, 124. Ergo nec est in deo tempus, §. 239. Non est in tempore ita, ut partem successivorum constituat, §. 124, 837. Dumque ortus et interitus ipsi sunt absolute impossibiles, §. 837, habet durationem, §. 299, maximam, §. 812, solam realiter infinitam, §. 844, 846, hinc aeternus est, §. 302, et omni tempori coexsistens sempiternus, §. 303, fuit, est, erit, §. 298. Deus exsistit.","glosses":[],"marks":[]},
 {"num":850,"section":"parsiiii-capi-seci","aa":165,"ed":null,"text":"Si ponatur ens contingens aeternum, aeternitas eius multum ab aeternitate dei differt, §. 67. 1) Duratio eius continuis modificationum successionibus est obnoxia, §. 209, 836, 2) aeternitas eius non habet quidem fines protensionis, at ideo tamen nondum realiter infinita dici potest, §. 259, 849, 3) aeternitas eius esset tempus sine initio et fine, unde posset infinitum dici, at mathematice, non ideo realiter, §. 248, 849, quia, ens successivum, §. 238, numquam est actu, quicquid esse potest, qua determinationes internas, §. 259.","glosses":[],"marks":[]},
 {"num":851,"section":"parsiiii-capi-seci","aa":165,"ed":347,"text":"Deus est ens necessarium, §. 823, 824, et infinitum, §. 843. Hinc est ens a se et independens, §. 310. Exsistit, §. 849, ita, ut non sit causatum extra ipsum positi alterius, causa effectuum suorum simpliciter talis, §. 318. Omnes dei perfectiones sunt realiter infinita, §. 844, hinc nulla perfectio dei est causatum extra deum positi, nec esse potest, §. 381, 248, 310. At passio esset praedicatum dei, quod esset causatum alicuius extra deum positi, §. 210. Ergo deus est omnino impassibilis, a nulla re extra se posita patitur, nec idealiter, nec realiter, §. 212, nec quicquam extra eum positum in eum agit, §. 210, ergo nec reagit, §. 213. Omnis dei actio in universum est sine reactione, tam ideali, quam reali, §. 212.","glosses":[],"marks":[]},
 {"num":852,"section":"parsiiii-capi-seci","aa":165,"ed":null,"text":"Imagines@@1@@ sunt 1) signa figurae alterius. Iam deus non habet figuram, §. 848. Ergo imagines dei hoc significatu sunt impossibiles, §. 347. 2) alteri in notabili gradu similia. Cum omne ens deo in aliquo gradu sit simile, §. 265, omne perfectius ens erit imago dei, §. 70, 811, quoque erit perfectius, hoc erit deo similius, hoc ergo maior imago dei, §. 265, 160.","glosses":["Bilder und Gleichnisse"],"marks":["*"],"aaEnd":166},
 {"num":853,"section":"parsiiii-capi-seci","aa":166,"ed":348,"text":"Mundus est totum actualium finitorum, §. 354. Deus non est totum actualium finitorum, §. 844. Ergo deus non est mundus: nec hic, nec ullus mundus deus est. Idem patet ex §. 361, 823, ex §. 365, 839, ex §. 370, 837, ex §. 388, 843.","glosses":[],"marks":[]},
 {"num":854,"section":"parsiiii-capi-seci","aa":166,"ed":null,"text":"Hic mundus habet causam efficientem extramundanam, §. 375, 388, eamque substantiam necessariam, §. 381, 319. Ergo substantia necessaria est possibilis, §. 333, 69. Si substantia necessaria est possibilis, est actualis, §. 109, et sempiterna, §. 302. Ergo substantia necessaria exsistit. Deus est substantia necessaria, §. 836. Ergo deus exsistit.","glosses":[],"marks":[]},
 {"num":855,"section":"parsiiii-capi-seci","aa":166,"ed":null,"text":"Deus est ens extramundanum, §. 843, 388, mundusque nec essentiale, nec essentia, nec attributum, nec modus, nec modificatio, nec accidens dei, §. 843. Deus non est substantia unica, §. 391. Spinozismus theologicus est sententia tollens deum ens extramundanum, et error est.","glosses":[],"marks":[]},
 {"num":856,"section":"parsiiii-capi-seci","aa":166,"ed":349,"text":"Sicut exsistentiam dei §. 811 probat a priori, sic §. 854 eandem sistit evictam a posteriori, uterque independenter a propositionibus, quas egoismus, §. 392, idealismus, §. 402, et materialismus tollunt, §. 395. Ergo convincendis de exsistentia dei egoistis, idealistis, materialistis, etiam qua talibus, adhiberi possunt.","glosses":[],"marks":[]},
 {"num":857,"section":"parsiiii-capi-seci","aa":166,"ed":null,"text":"Deus non est materia, §. 295, 841, ergo est immaterialis, §. 422. Deus non est corpus, §. 296. Ergo est incorporeus, §. 422. Ergo est incorruptibilis physice, §. 746. Idem patet ex §. 837.","glosses":[],"marks":[]},
 {"num":858,"section":"parsiiii-capi-seci","aa":166,"ed":null,"text":"Mundus perfectissimus est in finitis imago dei maxima, §. 436, 852, in mundo substantiae, §. 400, 857, in substantiis spiritus, §. 402, 531, in spiritibus intellectu maximo gaudentes, §. 637, et in intellectu maximo gaudentibus felicissimi, §. 787, a malo quocumque, praesertim morali, remotissimi, §. 788, 813, sanctissimi, §. 828.","glosses":[],"marks":[],"aaEnd":167},
 {"num":859,"section":"parsiiii-capi-seci","aa":167,"ed":350,"text":"Natura dei (naturans, cf. §. 466) est complexus perfectionum ipsius internarum, §. 430, quibus est causa effectuum suorum simpliciter talis et impassibilis, §. 851. Ergo quicquid est absolute possibile, deo est physice possibile, §. 833, nihilque deo physice impossibile, quod non esset in se impossibile, §. 469, 833, unde deo nihil physice necessarium, quod non simul absolute necessarium foret, absolute contingentia sunt etiam deo physice contingentia, §. 469, 104, non praeternaturales solum omnes, sed et supernaturales eventus mundi, §. 474, 475.","glosses":[],"marks":[]},
 {"num":860,"section":"parsiiii-capi-seci","aa":167,"ed":null,"text":"Si naturalista significatu generaliori supernaturales eventus in hoc mundo negat omnes, ob negatam eorundem hypotheticam possibilitatem errat. Cum enim miracula etiam in nexu cum deo extra eadem ponendo, §. 855, 474, sint possibilia, §. 834, habent etiam possibilitatem extrinsecam, §. 16, 859.","glosses":[],"marks":[]},
 {"num":861,"section":"parsiiii-capi-seci","aa":167,"ed":351,"text":"Gradui realitatis in deo, et omnibus eius perfectionibus homogeneus est impossibilis, §. 843, 844, dum deo et omnibus eius perfectionibus unicitas convenit, §. 846, 844. Ex quantitate itaque homogenea pro una assumpta non potest gradus realitatis in deo et omnibus eius perfectionibus obvius intelligi. Ergo nec deum, nec ullam eius perfectionem possumus metiri, §. 291. Quod metiri non possumus, immensum@@1@@ est. Ergo deus et omnes eius perfectiones sunt immensa. Quam immensitatem et hinc intelligimus, quia mensus tot claras perceptiones habeat oportet, quot partes, gradus, vel varia, sunt in eo, quod vere metitur. Hinc deum vere mensus aut quicquam deo interni deberet habere claras perceptiones realiter infinitas, quae non cadunt in ullum intellectum finitum, §. 844.","glosses":["unermesslich"],"marks":["*"],"aaEnd":168},
 {"num":862,"section":"parsiiii-capi-seci","aa":168,"ed":352,"text":"Deus est in se conceptibilis, §. 632, 809, et homini, §. 804-1000, et multis modis recte, immo realiter, definiri potest, §. 816. Comprehensibile@@1@@ dicitur, cuius possibilis est plena cognitio@@2@@, i.e. omnem ignorantiam excludens, hinc historica, philosophica, mathematica completa. Incomprehensibile alicui@@3@@ est, ad cuius plenam cognitionem acquirendam vires illius non sufficiunt, et quo magis huic ab illius cognitione plena abesse necessarium est, hoc ipsi datum est incomprehensibilius. Quo quid maius est, hoc difficilior vel impossibilior eius est cognoscenti finito comprehensio, §. 160, 527, hinc maximum finitis omnibus maxime incomprehensibile est, §. 261. Deismus est sententia nihil paene de deo conceptibile esse ponens, nisi eius forsan exsistentiam, et error est, licet deus et omnia in eo nobis, et finitis omnibus maxime sint incomprehensibilia, §. 861, 806.","glosses":["fasslich, ergründlich, erforschlich, erschöpflich","völlige, gänzliche Kenntniss","einem unfasslich, unergründlich, unerforschlich, unerschöpflich"],"marks":["*","**","***"]},
 {"num":863,"section":"parsiiii-capi-secii","aa":168,"ed":null,"text":"Distincta cognitio est realitas, §. 531. In deo sunt omnes realitates, §. 807. Ergo deus distincte cognoscit. Ergo habet intellectum, est substantia intellectualis, §. 830, spiritus, §. 402.","glosses":[],"marks":[]},
 {"num":864,"section":"parsiiii-capi-secii","aa":168,"ed":null,"text":"In deo sunt omnes realitates maximae, §. 812. Quo plura, quo distinctius cognoscuntur, hoc distincta cognitio maior est, §. 634. Ergo distinctissima erit cognitio distincta omnium, §. 161. Iam omnium distincta cognitio est possibilis, §. 632. Ergo in deo est cognitio omnium distincta, eademque distinctissima.","glosses":[],"marks":[]},
 {"num":865,"section":"parsiiii-capi-secii","aa":168,"ed":353,"text":"Intellectus dei summus est, §. 863, 812, et immutabilis, §. 839. Ergo in eo non sunt praeviae sequentesque cogitationes, §. 125. Summus est, dum plurimorum, maximorum, plurimas, clarissimas notas, fortissimis in sociis diversissimisque, repraesentat. Ergo dei intellectus profundissimus, patentissimus, purissimus est, §. 637.","glosses":[],"marks":[]},
 {"num":866,"section":"parsiiii-capi-secii","aa":168,"ed":null,"text":"Deus semet ipsum, quam fieri potest, plenissime cognoscit, §. 865. Cognitio de deo est theologia significatu latiori, theologia, qua deus seipsum cognoscit, exemplaris (αρχετυποσ) est, quatenus illi similes theologiae finitorum intendendae sunt, §. 346.","glosses":[],"marks":[],"aaEnd":169},
 {"num":867,"section":"parsiiii-capi-secii","aa":169,"ed":null,"text":"Deus omnia repraesentans omnes mundos possibiles sibi repraesentat, §. 864. Haec est perfectio dei interna, §. 37, eiusdem essentia, §. 816.","glosses":[],"marks":[]},
 {"num":868,"section":"parsiiii-capi-secii","aa":169,"ed":null,"text":"Deus omnes omnium finitorum essentias distinctissime cognoscit, §. 864. Quatenus ergo essentiae rerum in intellectu dei repraesentantur, ab eo dependent, §. 14, in eodem aeternae, §. 849.","glosses":[],"marks":[]},
 {"num":869,"section":"parsiiii-capi-secii","aa":169,"ed":354,"text":"Deus omnes mundos possibiles sibi repraesentat distinctissime, §. 867. Ergo et optimum, §. 436, et imperfectissimum, §. 442, et hunc. Mundus, quatenus sensitive repraesentatur, sensibilis@@1@@ (adspectabilis), quatenus distincte cognoscitur, intelligibilis@@2@@ est. Deus mundum hunc intelligibilem distinctissime cognoscit. Ergo omnes huius mundi monades, omnes eiusdem animas distinctissime cognoscit, §. 864. Distinctissima animae humanae cognitione pollens est scrutator cordium@@3@@. Ergo deus est scrutator cordium, §. 740, et singulae monados, singulae animae repraesentationem mundi sensibilis perspicit, §. 400, 741, et multo quidem perfectius, ac data monas, data anima semet ipsam novit, suamque mundi repraesentationem, §. 864.","glosses":["die Welt, als ein Schauspiel der Sinnlichkeit","die Welt, als ein Gegenstand des Verstandes","Herzens-Prüfer"],"marks":["*","**","***"]},
 {"num":870,"section":"parsiiii-capi-secii","aa":169,"ed":null,"text":"In deo non est cognitio sensitiva, §. 864, 521. Ergo non habet facultates cognoscitivas inferiores, §. 520, nihil ipsi obscurum, nihil confusum, hinc nullam rem alia clarius cognoscit, §. 528, nec attendit, nec abstrahit, §. 529, nec reflectit, nec comparat, §. 626.","glosses":[],"marks":[]},
 {"num":871,"section":"parsiiii-capi-secii","aa":169,"ed":355,"text":"Cum deus signata omnia distinctissime cognoscat, habet omnium intuitum, §. 620, 864. Omnia etiam signa cognoscit, et omnem animarum in mundo cognitionem symbolicam, §. 864, 869. Nec tamen signorum umquam maior vel minor in ipso est perceptio, quam signatorum, §. 870, utraque semper maxima, §. 864.","glosses":[],"marks":[],"aaEnd":170},
 {"num":872,"section":"parsiiii-capi-secii","aa":170,"ed":null,"text":"Deus omnem nexum distinctissime sibi repraesentat, §. 864. Ergo habet summam rationem, §. 640. Summa eius ratio est, dum est intellectus summus, hinc immutabilis, sine omni ratiociniorum successione, §. 865, maximum plurimorum nexum perspiciens, §. 645.","glosses":[],"marks":[]},
 {"num":873,"section":"parsiiii-capi-secii","aa":170,"ed":356,"text":"Cognitio dei est summae extensionis et maiestatis, exactissima, §. 864, et ordinatissima, §. 822, citra omnem ignorantiam et errorem, angustias et levitatem, in qua nihil tumultuarii, §. 515, clarissima, distinctissima, veritatis omnis, hinc certissima, in qua nihil obscuri, nihil confusi, nihil inadaequati, nihil incompleti, nihil impuri, nihil superficiarii, probabilis, dubii, vel improbabilis, nihil mortui inertis et speculativi, §. 669, 671. Distinctissime cognoscit omnia principia certa, omnia eorum principiata, omnem principiorum principiatorumque nexum, §. 864, 872, ergo cognitio ipsius est summa scientia. Deus distinctissime cognoscit omnes animarum ignorantias, errores, cognitionis angustias, exilitates, quicquid in eiusmodi cognitione crassi et tumultuarii, noctis, confusionis, inadaequationis, incompletionis, impuritatis, omnes animarum certitudines morales, probabilitates, dubia, improbabilitates, opiniones, argumenta, scrupulos, inertes et mortuas speculationes, §. 869.","glosses":[],"marks":[]},
 {"num":874,"section":"parsiiii-capi-secii","aa":170,"ed":null,"text":"Deus scit, §. 873, I) omnes omnium determinationes, quatenus illa, ut mere possibilia, spectantur. Haec est scientia simplicis intelligentiae@@1@@.","glosses":["die Wissenschaft des Möglichen"],"marks":["*"]},
 {"num":875,"section":"parsiiii-capi-secii","aa":170,"ed":null,"text":"Deus scit, §. 873, II) omnes determinationes actualium, 1) huius mundi, scientia libera (visionis)@@1@@, α) praeterita recordatione divina@@2@@,β) praesentia, scientia visionis@@3@@,γ) futura, praescientia@@4@@. Socinianismus philosophicus est sententia tollens praescientiam divinam futurorum contingentium, et error est.","glosses":["die freie Wissenschaft","das Angedenken","Sehn","Vorhersehung Gottes"],"marks":["*","**","***","****"]},
 {"num":876,"section":"parsiiii-capi-secii","aa":170,"ed":357,"text":"Deus scit omnes determinationes actualium 2) alterius mundi, quam hic, scientia media@@1@@. Pro quovis eventu huius mundi exsistere posset alius, §. 363, 324. Quivis autem haberet sua consectaria in indefinitum per omnes status mundi secuturos partialiter diversa, §. 488. Ergo si vel pro uno tantum eventu huius mundi exstitisset alius, mundus hic esset per omnes status illi eventui successivos, immo antecedentes etiam, §. 357, 278, partialiter alius, quam est. Ergo quicquid loco cuiusvis eventus in hoc mundo exsistere potuisset cum omnibus suis consectariis, deus scit, scientia media, §. 378.","glosses":["die mittlere Wissenschaft Gottes, oder dessen Einsicht bloss möglicher Welten"],"marks":["*"],"aaEnd":171},
 {"num":877,"section":"parsiiii-capi-secii","aa":171,"ed":null,"text":"Deus sibi status praesentis mundi semper distinctissime conscius est, §. 875. Ergo numquam dormit, §. 556. Idem patet ex §. 870. Non sentit, ut nos, §. 870, 544, sed per eminentiam scientia visionis, §. 875, vigilans, §. 552, 826.","glosses":[],"marks":[]},
 {"num":878,"section":"parsiiii-capi-secii","aa":171,"ed":358,"text":"Aeternum deus sibi rem futuram repraesentavit, quantum potest, §. 875, 843. Ergo dum illa fit in mundo praesens, nihil ad cognitionem dei accedit, §. 161, quamquam ipsa ex obiecto praescientiae mutetur in obiectum visionis, §. 125. Aeternum deus sibi rem praeteritam repraesentabit, quantum potest, §. 875, 843. Ergo dum praesens fiet praeterita, ipsa quidem ex obiecto visionis mutabitur in obiectum recordationis, nihil autem de cognitione dei decedet, §. 161. Deus omnes huius mundi successivos status aeternum intuetur, §. 875, unde cogitari potest cognitionis divinae interna immutabilitas, §. 839.","glosses":[],"marks":[]},
 {"num":879,"section":"parsiiii-capi-secii","aa":171,"ed":null,"text":"Qui errare non potest, infallibilis@@1@@ est. Ergo deus est infallibilis, §. 873. Minima infallibilitas est, si cui unicum tantum minimum verum cum falso confundere est minime impossibile; quo ergo plura, quo maiora quis vera cum falsis confundere nescit, quo maior talis confusionis impossibilitas, hoc magis est infallibilis. Dum ergo deo maximam infallibilitatem tribuimus, §. 812, eum veneramur, plurimas maximas veritates cum ullo falso confundere absolute nescium.","glosses":["unfehlbar, unbetrieglich"],"marks":["*"]},
 {"num":880,"section":"parsiiii-capi-secii","aa":171,"ed":359,"text":"Certitudo minima est minime clara unius minimae veritatis cognitio, §. 161. Quo clarius, quo plures, quo maiores veritates cognoscuntur, hoc maior erit certitudo, §. 160. Dum ergo deo summam tribuimus certitudinem subiectivam, §. 873, 812, eum veneramur plurimas maximas veritates distinctissime cognoscentem. Idem deus est obiective certissimus, §. 93, 812, dum summa eius veritas est, §. 822, et exsistentia per essentiam ipsius et exsistentiam cuiuslibet finiti demonstrabilis, §. 856.","glosses":[],"marks":[]},
 {"num":881,"section":"parsiiii-capi-secii","aa":171,"ed":null,"text":"Scientia dei libera est perfectio eius respectiva, §. 875, 815. Cumque absolute necessarium est eam esse verissimam, §. 879, mundum hunc deo sistit exsistentem in et per se contingenter, §. 361, hinc eam non, nisi hypothetice, necessariam esse est absolute necessarium, §. 102. Ergo scientia dei libera est analogon modi, §. 827.","glosses":[],"marks":[]},
 {"num":882,"section":"parsiiii-capi-secii","aa":171,"ed":360,"text":"Sapientia nexus finalis generatim@@1@@ est perspicientia, et quidem finium sapientia speciatim@@2@@, remediorum prudentia@@3@@. Hinc deus est omnisapientissimus, §. 872, dum omnisapientissimum dicimus, veneramur 1) omnes fines, 2) omnia remedia, 3) omnes eorundem nexus possibiles, §. 343, 4) qua omnes qualitates, 5) omnes quantitates, 6) in maximo nexu possibili, 7) certissime ardentissimeque perspicientem, §. 880, 873.","glosses":["Weisheit überhaupt","insonderheit","Klugheit"],"marks":["*","**","**"],"aaEnd":172},
 {"num":883,"section":"parsiiii-capi-secii","aa":172,"ed":null,"text":"Deus omnes fines scit, hinc et optimos, et pessimos, quis ex iis possit esse remedium alterius, hinc omnem omnium finium subordinationem possibilem, omnem etiam coordinationem, §. 315, omnes scopos secundum quid, et simpliciter ultimum, §. 343, secundum omnem ipsorum bonitatem, et bonitatis gradum, omnem cum remediis nexum possibilem, ita ut ipsi quidem numquam ullus videatur alius, quam est, §. 879, ut tamen simul cognoscat, quomodo videatur quisque finis omnibus et singulis animabus eum cognoscentibus, §. 869. Ergo deus de finibus optimis optime novit, quod sint optimi, §. 882.","glosses":[],"marks":[],"aaEnd":173},
 {"num":884,"section":"parsiiii-capi-secii","aa":173,"ed":null,"text":"Deus novit omnia remedia, hinc et optima, §. 882, quibus positis ponitur summa perfectio, §. 187. Iam positis remediis ponitur finis, §. 326, 341. Ergo remedia optima fini optimo subordinantur. Deus novit ea, quatenus optimo fini subordinantur, quomodo, et in quantum subordinentur, §. 883.","glosses":[],"marks":[],"aaEnd":174},
 {"num":885,"section":"parsiiii-capi-secii","aa":174,"ed":361,"text":"Remedium certum@@1@@ est, quod re vera tale est ac tantum, quale quantumque cognoscitur, hinc opponitur apparenti, quod videtur solum, et aut prorsus non est, aut non est tantum, quantum videtur, et incerto, cuius vera bonitas, gradusve bonitatis non liquet. Remedia optima sunt certissima, et quatenus non sunt apparentia, et quatenus deus certissimus est, et de bonitate, et de gradu bonitatis eorundem, §. 882, nihilo tamen minus omnes de iisdem dubitationes animarum possibiles perspiciens, §. 869, 873.","glosses":["ein gewisses Mittel"],"marks":["*"]},
 {"num":886,"section":"parsiiii-capi-secii","aa":174,"ed":null,"text":"Quo fecundius remedium est, hoc maior illo posito ponitur perfectio, §. 166, 341. Ergo media fecundissima sunt optima, et vice versa, §. 187. Deus novit remedia fecundissima, §. 884, quantumque quodlibet fecunditatis habeat, §. 882, quantumque cuilibet fecunditatis a datis animabus adscribatur, §. 873.","glosses":[],"marks":[]},
 {"num":887,"section":"parsiiii-capi-secii","aa":174,"ed":362,"text":"Remedia optima sunt completa, §. 886, ad finem optimum, §. 884. Ergo non sunt incompleta, §. 81. Si abundantia forent, quaedam haberent ad finem nihil facientia. Ergo bonum non actuantia, §. 341, neque tamen prorsus sterilia, §. 23. Hinc mala, §. 146. Ergo remedia optima sunt fini optimo adaequata. Deus novit remedia fini optimo adaequata, §. 884. Remedia certa et adaequata sunt finem ex asse consequentia@@1@@. Deus novit remedia finem optimum ex asse consequentia, §. 885.","glosses":["den Zweck völlig erreichen"],"marks":["*"],"aaEnd":175},
 {"num":888,"section":"parsiiii-capi-secii","aa":175,"ed":null,"text":"Actuatio finis per remedia, quae eum ex asse consequuntur, paucissima est via brevissima@@1@@. Usus mediorum optimorum semper est via brevissima. Tunc enim actuatur finis per remedia eum ex asse consequentia, §. 887, quorum singula sunt fecundissima, §. 886, nullum abundans, §. 887. Erunt hinc, quae esse possunt, paucissima, §. 161. Deus omnem novit viam brevissimam, §. 887.","glosses":["der kürzeste Weg"],"marks":["*"]},
 {"num":889,"section":"parsiiii-capi-secii","aa":175,"ed":null,"text":"Omniscientia@@1@@ est scientia omnium. Deus est omniscientissimus, §. 873. Cum eum talem dicimus, veneramur, qualem §. 863-888 exhibent.","glosses":["Allwissenheit"],"marks":["*"],"aaEnd":177},
 {"num":890,"section":"parsiiii-capi-seciii","aa":177,"ed":null,"text":"Deus omnes omnium perfectiones imperfectionesve intuetur distinctissime, §. 889, 871. Quicquid in deo est, maxima est ratio, §. 23, 812. Hinc intuitus perfectionum imperfectionumve in eodem maxime vivus est, §. 669, 873. Ergo deo complacentia et displicentia convenit, §. 655, summa, §. 812.","glosses":[],"marks":[]},
 {"num":891,"section":"parsiiii-capi-seciii","aa":177,"ed":null,"text":"Complacentia et displicentia dei non sunt, nisi verissimae, §. 880, distinctissimae, §. 870, rationalissimae, §. 822, numquam est totaliter indifferens, §. 653, nec umquam partialiter erga ullam rem, §. 654, nec voluptatem, nec taedium, §. 656, nec appetitum, nec aversationem sensitiva habet, nec instinctus, nec fugas, §. 677, nec affectus, §. 678, nec voluptates, nec taedia apparentia, § 655.","glosses":[],"marks":[]},
 {"num":892,"section":"parsiiii-capi-seciii","aa":177,"ed":364,"text":"Cum deus se, ut bonum tantum, ut optimum sanctissimum intueatur distinctissime, §. 866, 828, purissimam ex se voluptatem haurit, §. 661. Haec summa dei acquiescentia in se ipso, §. 682. Theologia exemplaris est suavissima, §. 866. Deus ex nulla re merum taedium habet, §. 891, 661. Displicentia eius et complacentia omnis est immutabilis, §. 839. Hinc nescit voluptates et taedia transitoria, §. 662, nihil ipsi molestum, §. 658. Nec summa eius displicentia summam voluptatem obscurat ullo modo, §. 870, nec quicquam extra ipsum in eo potest voluptatem aut taedium ullum actuare, §. 851.","glosses":[],"marks":[]},
 {"num":893,"section":"parsiiii-capi-seciii","aa":177,"ed":null,"text":"In deo est scientia libera huius mundi, cum tamen et nullius, et alius esse possit, §. 881. Non tamen exsistit in deo huius mundi scientia libera, nisi vi dei, §. 851, 197. Ergo vim suam determinavit deus ad scientiam liberam non nullius, non alius, sed huius mundi actuandam. Ergo deus appetit et aversatur, §. 663. Iam non appetit, non aversatur sensitive, §. 891. Sequitur tamen appetitio eius et aversatio cognitionem, §. 668, 822. Ergo vult et non vult, habet voluntatem et noluntatem, §. 689, summam, §. 812, i.e. summam omniscientiam perfectissime sequentem, §. 668, 889.","glosses":[],"marks":[]},
 {"num":894,"section":"parsiiii-capi-seciii","aa":177,"ed":365,"text":"Voluntas noluntasve cognitionem intellectus mathematicam sequens, s. appetens pro gradu bonitatis in appetendis distincte cognito, aversata pro gradu imperfectionis in aversandis distincte cognito, est proportionalis intellectui@@1@@, qui si rem tam bonam malamve sistat, ac est, est voluntas noluntasve proportionalis obiectis@@2@@. Ergo voluntati noluntatique divinae convenit proportionalitas, §. 893, summa, §. 812, dum distinctissimam summe et infallibilem graduum perfectionis et imperfectionis cognitionem sequitur, §. 879, 883.","glosses":["Wollen und Nicht-Wollen, so der Einsicht des Verstandes","so den Gegenständen angemessen"],"marks":["*","**"],"aaEnd":178},
 {"num":895,"section":"parsiiii-capi-seciii","aa":178,"ed":null,"text":"Deus, dum vult, §. 393, agit, §. 210. Actiones dei omnes a sufficienti principio interno agenti deo dependere possunt, §. 833, et dependent, §. 851. Ergo actionibus divinis ipsique deo convenit spontaneitas, §. 704, eaque summa, §. 872, dum ad plurimas maximas actiones sufficit, §. 706, 832. Dei actiones maxime spontaneae erunt aut immanentes, aut transeuntes, §. 211.","glosses":[],"marks":[]},
 {"num":896,"section":"parsiiii-capi-seciii","aa":178,"ed":366,"text":"Deus est liber a coactione interna absoluta, §. 710, 702, et physica, §. 710, 859, et externa tam ideali, quam reali, §. 707, 851, adeoque etiam morali, §. 723, motivorum, §. 726, ad actiones invitas per violentiam secundum quid, §. 714, ab illecebris, minis, suasionibus, dissuasionibus, extorsionibus, §. 728.","glosses":[],"marks":[]},
 {"num":897,"section":"parsiiii-capi-seciii","aa":178,"ed":null,"text":"Omnes actiones sunt in potestate dei positae, §. 708, 859. Si ergo quaedam actio et opposita ipsi actio quaecumque est possibilis in se utraque, §. 15, i.e. si quaedam actio est contingens in se, §. 104, hinc et oppositam contingentem in se actionem habet, §. 104, utraque est in potestate dei posita. Ergo omnes actiones in se contingentes sunt deo liberae ratione exsecutionis et indifferentes qua exercitium actus, §. 708, quia respectu dei possibilitas utriusque physica summa est, §. 844. Hinc actuatio huius universi, aut nullius, aut alius, fuit deo libera ratione exsecutionis, §. 835. Indifferens fuit, qua exercitium actus, tam ergo mundum optimum, quam erga imperfectissimum, idemque est, et erit. §. 849.","glosses":[],"marks":[]},
 {"num":898,"section":"parsiiii-capi-seciii","aa":178,"ed":367,"text":"Cum deus se in agendo determinet pro lubitu, §. 893, 712, eoque distincto, §. 893, habet libertatem, §. 719, eamque summam, §. 812, i.e. maximas plurimas actiones distinctissimo pro lubitu actuantem, §. 725. fatalismus, sententia libertatem divinam tollens, error est.","glosses":[],"marks":[]},
 {"num":899,"section":"parsiiii-capi-seciii","aa":178,"ed":null,"text":"Deus vult liberrime, §. 898. Ergo bonum, §. 719, 665. Deus aversatur liberrime, §. 898. Ergo malum, §. 719, 665. Volitio s. amor boni, odium s. nolitio mali in deo infinita sunt, §. 844, 1) extensive, dum amat omne bonum, odit omne malum, §. 898, 889, 2) protensive, dum aeterna sunt, §. 849, et 3) intensive, dum proportionalissima, §. 894. Volitio nolitiove divina extensive infinita, quia non esse potest in deo scientia mortua et mere speculativa, §. 873, fertur in obiecta 1) simplicis intelligentiae, universalia, quae nobis notiones exhibent, et quicquid in iis est boni malive, erga quod deus non potest esse totaliter indifferens, §. 891, 2) scientiae mediae, actualia universi alterius, 3) scientiae liberae, §. 874-876. Voluntas dei, quatenus obiecta scientiae liberae, s. actualia huius universi appetit, consequens@@1@@, quatenus fertur in universalia et actualia alterius universi, antecedens@@2@@ dicitur, per reductionem, §. 826, 695, illa efficiens, §. 671, utraque efficax, antecedens etiam, non tantum, quia seria, sed etiam, quia est in motivis decreti, §. 675.","glosses":["der nachfolgende","der vorhergehende Wille Gottes"],"marks":["*","**"],"aaEnd":179},
 {"num":900,"section":"parsiiii-capi-seciii","aa":179,"ed":368,"text":"Voluntas est imperscrutabilis@@1@@, cuius causae impulsivae sunt incomprehensibiles. Iam causae impulsivae voluntatis divinae sunt distinctissimus ipsius lubitus, §. 898, hinc deo interna perfectio, §. 37, nobis incomprehensibilis, §. 862. Qui quaedam dei motiva in aliquo distinctionis gradu concipit, non perscrutatur voluntatem divinam, §. 862. Hinc nec intendens aliquam motivorum divinorum intellectionem voluntatem dei fingit sibi perscrutabilem, §. 664. Quo plures causae impulsivae certae voluntatis, quo minus plene possunt cognosci, hoc est voluntas imperscrutabilior, §. 160. Hinc cum voluntas dei nobis imperscrutabilis maxime, §. 812, dicitur, cogitamus 1) plurima ipsius motiva plene non cognosci, 2) plurimum abesse quodvis eorum a comprehensione nostra, §. 862, 898.","glosses":["ein unausforschlicher Wille"],"marks":["*"],"aaEnd":181},
 {"num":901,"section":"parsiiii-capi-seciii","aa":181,"ed":369,"text":"Actionis liberae conformitas cum ratione sua, hinc lege, §. 83, morali, §. 723, est eiusdem rectitudo@@1@@, quatenus ergo omnes actiones dei liberrimae, §. 898, 725, summam conformitatem habent, §. 176, cum lege optimi, §. 822, morali, §. 723: Optimum libere iungatur optimo, sunt rectissimae. Summa voluntati divinae rectitudo convenit, §. 899, sanctitas, §. 828, moralis, §. 723.","glosses":["Richtigkeit einer Handlung, oder Gesetzmäßigkeit"],"marks":["*"]},
 {"num":902,"section":"parsiiii-capi-seciii","aa":181,"ed":null,"text":"Actiones dei liberrimae non sunt absolute necessariae, dum earum oppositum est in se possibile. §. 102. Omnes actiones dei transeuntes in mundum, §. 854, 211, habent oppositum in se possibile, §. 361. Hinc nullae earum sunt absolute necessariae. Cumque omnium liberrimarum dei actionum oppositum possit per omnipotentiam dei actuari, §. 897, nulla earum, nec adeo ulla dei actio in mundum est ipsi physice necessaria, §. 470, 859, adeoque nec ulla moraliter necessaria eo sensu, ac si per libertatem oppositum ullius deo redderetur physice impossibile, §. 723. Cum tamen summa dei libertas se semper rectissime determinet, §. 901, dum sunt omnes eius actiones moraliter sanctissimae, sunt moraliter necessariae, §. 723, 724.","glosses":[],"marks":[]},
 {"num":903,"section":"parsiiii-capi-seciii","aa":181,"ed":370,"text":"Bonitas@@1@@ (benignitas) est determinatio voluntatis ad faciendum alteri bene. Beneficium@@2@@ est actio alteri utilior ex bonitate profecta. Bonitas minima esset minima voluntatis propensio s. dispositio unius minimi boni in unicum minimum i.e. minime dignum conferendi, §. 161. Quo ergo magis, quo plura, quo maiora, beneficia, in quo plures, quo digniores, conferre appetit bonitas, hoc maior est, §. 160. Beneficium est maius bonum. §. 336, 187.","glosses":["Gütigkeit","Wohlthat"],"marks":["*","**"]},
 {"num":904,"section":"parsiiii-capi-seciii","aa":181,"ed":null,"text":"Deus vult beneficia aliis conferenda, §. 903, 899. Ergo benignus est, §. 903, summe, §. 812. Dum benignissimum dicimus deum, veneramur infinite amantem et aeterne, §. 899, et immutabiliter, §. 839, plurima, maxima beneficia plurimis, dignissimis conferre. §. 903.","glosses":[],"marks":[]},
 {"num":905,"section":"parsiiii-capi-seciii","aa":181,"ed":null,"text":"Amor hominum philanthropia@@1@@ est, amorem amati mutuum proportionatum volens zelotypia@@2@@ est, qui cum misericordia, favore, benevolentia, clementia universales in deo sunt et maximi, §. 684, 904. Cumque constans amor intensus sit fidelitas@@3@@, deus aeternum amans infinite summe fidelis est, §. 904, 812.","glosses":["Menschen-Liebe","Liebes-Eifer","Treue"],"marks":["*","**","***"],"aaEnd":182},
 {"num":906,"section":"parsiiii-capi-seciii","aa":182,"ed":371,"text":"Bonitas erga personas s. spiritus proportionalis est iustitia@@1@@, cf. E. §. 317. Iustitia minima esset minima bonitas minimam, minime claram, minime certam, minime vivam cognitionem mathematicam sequens, §. 903, 161. Quo ergo 1) intensius amat, 2) quo plura, 3) quo maiora, 4) in quo plures beneficia conferre pro gradu perfectionis imperfectionisve in spiritu cognito, 5) quo clarius, 6) quo certius, 7) quo ardentius gradus ille cognitus est, hoc maior est iustitia, §. 903, 160. Deus iustus est, §. 904, 894, summe, §. 812. Dum deum iustissimum dicimus, veneramur summam eius bonitatem, §. 904, proportionalissimam, §. 894, pro distinctissima, et infallibili, et maxime viva cognitione graduum perfectionis imperfectionisve in singulis spiritibus obviae plurima maxima plurimis beneficia conferre paratissimam.","glosses":["Gerechtigkeit"],"marks":["*"]},
 {"num":907,"section":"parsiiii-capi-seciii","aa":182,"ed":null,"text":"Praemium@@1@@ (remuneratio) est bonum contingens personae ob bonum morale collatum. Iustitia in conferendis praemiis est remuneratoria@@2@@, quam in deo summam veneramur, §. 906, 812, dum pro omnibus etiam minimis bonis moralibus omnium spirituum, proportionalissima praemia conferre paratissimam suspicimus.","glosses":["eine Belohnung, Lohn","Belohnungs-Gerechtigkeit"],"marks":["*","**"],"aaEnd":183},
 {"num":908,"section":"parsiiii-capi-seciii","aa":183,"ed":372,"text":"Poena@@1@@ est malum contingens personae ob malum morale illatum. Tam poenae, quam praemia quaedam possunt sufficienter concipi ex essentia peccati et natura peccantis, aut ex essentia boni moralis et natura bene agentis, et erunt naturalia. Quaedam praemia non possunt sufficienter concipi, nisi ex arbitrio ea conferentis alterius, et sunt arbitraria@@2@@. Quaedam poenae non possunt sufficienter concipi, nisi ex arbitrio punientis alterius, et sunt arbitrariae@@3@@.","glosses":["Strafe","willkürliche Belohnungen","Strafen"],"marks":["*","**","***"]},
 {"num":909,"section":"parsiiii-capi-seciii","aa":183,"ed":373,"text":"In quo sunt mala moralia, peccator@@1@@ est. In quo quaedam mala moralia non sunt, respectu eorum est innocens latius dictus@@2@@ (insons), cf. E. §. 319. Peccator, ceteris paribus, non tam bonus est, quam innocens, §. 187. Ergo nec tantum amatus a bonitate proportionalissima, §. 906. Ergo quaedam beneficia deus vult innocenti conferre, quae non vult conferre peccatori, §. 904. Erga haec peccatori non conferenda beneficia deus non est indifferens, §. 891, hinc ea pro distinctissimo lubitu aversatur peccatori conferre, §. 898, 669. Ergo beneficiorum eiusmodi vult oppositum, §. 663, 690. Beneficiorum opposita mala sunt, §. 81, 903, eaque contingentia, §. 146. Ergo deus vult quaedam mala contingentia ob mala moralia peccatori inferenda, i.e. poenas, §. 908.","glosses":["ein Sünder","der Unschuldige in weiterer Bedeutung"],"marks":["*","**"]},
 {"num":910,"section":"parsiiii-capi-seciii","aa":183,"ed":null,"text":"Iustitia in inferendis poenis punitiva@@1@@ est (vindicativa, ultrix, vindicatrix, nemesis), iustitia punitiva deo convenit, §. 909, eaque summa, §. 812, dum ad omnia peccatorum omnium peccata proportionalissime punienda est paratissima, §. 906. Dippelianismus philosophicus sententia, iustitiam dei punitivam tollens, error est.","glosses":["die Straf-Gerechtigkeit"],"marks":["*"],"aaEnd":184},
 {"num":911,"section":"parsiiii-capi-seciii","aa":184,"ed":null,"text":"Oppositum praemii naturalis poena naturalis est, oppositum praemii arbitrarii poena est arbitraria, §. 908. Ergo iustitia dei remunerativa dispensante praemia arbitraria, iustitia vindicativa poenas irrogat arbitrarias, §. 907, 909. Ipsae poenae naturales respectu eius, sine cuius arbitrio natura peccantis non haberet rationem sufficientem, sunt arbitrariae, §. 908. Par ratio praemiorum naturalium.","glosses":[],"marks":[],"aaEnd":185},
 {"num":912,"section":"parsiiii-capi-seciii","aa":185,"ed":374,"text":"Complexus causarum extra spiritum positarum ad prosperitatem eius miseriamve concurrentium est fortuna bona et mala@@1@@, per fortunam actuata sunt fortuita@@2@@, eaque contingentia, §. 146, 787. Eiusmodi bona collata spiritui ob bona moralia praemia sunt, §. 907, nec sufficienter cognoscenda, nisi ex arbitrio dei, §. 854, arbitraria sunt, §. 908. Mala fortuita spiritui illata sunt infortunia@@3@@. Infortunia spiritui ob mala moralia illata poenae sunt, nec cognoscenda, nisi ex arbitrio dei, sufficienter, §. 854, poenae sunt arbitrariae, §. 908.","glosses":["gutes und böses Glück","Glücks-Fälle","Unglücks-Fälle"],"marks":["*","**","***"]},
 {"num":913,"section":"parsiiii-capi-seciii","aa":185,"ed":null,"text":"Praemia et poenae miraculosae et supernaturales in se sunt possibiles, §. 475, et hypothetice, §. 860, omnipotentiae divinae, §. 833, 834, sunt arbitrariae, §. 908, 898, non tamen solae, §. 911, 912.","glosses":[],"marks":[]},
 {"num":914,"section":"parsiiii-capi-seciii","aa":185,"ed":375,"text":"Eventus, quicquid in eo est realis et positivi, materiale remotum@@1@@, omnimoda determinatio materiale proximum@@2@@, et quicquid in finitis est eidem negativi, formale@@3@@ eventus dicitur. Hinc mala, adeoque et poenae, §. 908, aut spectantur materialiter formaliterque simul, et sunt, ut finita omnia, partim bona, partim mala praecise s. formaliter sumpta, §. 264, amantur a deo, quatenus sunt bona, odit ea deus, quatenus sunt mala, infinite, §. 899, aut spectantur tantum materialiter, qua materiale remotum, et sunt positiva et realia, tantum obiectum amoris divini, §. 899, aut formaliter tantum, et non sunt, nisi aut negationes stricte dictae, aut privationes, §. 137, et sunt tantum obiectum odii divini, §. 899, aut qua materiale proximum et formale.","glosses":["das bejahende","die gänzliche Bestimmung","der mangelhafte Schranken einer Begebenheit"],"marks":["*","**","***"],"aaEnd":186},
 {"num":915,"section":"parsiiii-capi-seciii","aa":186,"ed":null,"text":"Deus vult iustitia punitiva, §. 910, materiale poenae remotum, et quicquid est in proximo realitatis, non vero formale, §. 914. Iam vero contingere easdem huic peccatori, non alii, sed ei, cui sunt proportionalissimae, est realitas, §. 36, 909. Hanc ergo deus vult, §. 899. Hinc et diiudicanda distinctio malorum contingentium, §. 146, adeoque tam poenarum, §. 908, quam peccatorum, §. 788, in privativa et positiva, §. 525.","glosses":[],"marks":[]},
 {"num":916,"section":"parsiiii-capi-seciii","aa":186,"ed":376,"text":"Longanimitas@@1@@ (patientia iudicis) est iustitia non nisi optima visa occasione puniens. Deus optimas omnium poenarum opportunitates infallibiliter sciens, §. 889, 879, hoc etiam materiale proximum cuiusvis poenae, dum realitas est, §. 36, volet proportionalissime, §. 894, 914. Hinc summe est longanimis.","glosses":["Langmuth, und richterliche Geduld"],"marks":["*"]},
 {"num":917,"section":"parsiiii-capi-seciii","aa":186,"ed":null,"text":"Impartialitas est aversio a decidendo ex apparentibus stimulis. In deo ne stimuli quidem, §. 898, multo minus apparentes possibiles sunt, §. 889, 12, dumque tam ipsos, quam decretum ex iis aversetur sanctissima ipsius voluntas, §. 902, est impartialissimus.","glosses":[],"marks":[],"aaEnd":187},
 {"num":918,"section":"parsiiii-capi-seciii","aa":187,"ed":null,"text":"Impartialis iustitia est aequitas@@1@@. Deus iustissimus, §. 906, et impartialissimus, §. 917, est aequissimus.","glosses":["Billigkeit"],"marks":["*"]},
 {"num":919,"section":"parsiiii-capi-seciii","aa":187,"ed":377,"text":"Sinceritas@@1@@ est bonitas in mente sua significanda, et haec est in deo, §. 904, summa, §. 812, dum omnibus, quibus, et tantum, quantum significare mentem suam summa sapientia suadet, signis aptissimis significare paratissimus est, §. 884-888.","glosses":["Aufrichtigkeit"],"marks":["*"],"aaEnd":188},
 {"num":920,"section":"parsiiii-capi-seciii","aa":188,"ed":null,"text":"Veracitas@@1@@ est sinceritas in oratione. Sapientia ergo divina iudicante optimum per orationem mentem divinam significare, deus est veracissimus. §. 919.","glosses":["Wahrhaftigkeit"],"marks":["*"]},
 {"num":921,"section":"parsiiii-capi-seciii","aa":188,"ed":null,"text":"Minima minimae naturae duratio vita foret minima. Quo maioris naturae, quo maior est duratio, hoc maior est vita, donec sit maxima summa perfectissimae naturae duratio, §. 430, 161. Deo summa vita tribuenda est, §. 859, 850.","glosses":[],"marks":[],"aaEnd":189},
 {"num":922,"section":"parsiiii-capi-seciii","aa":189,"ed":null,"text":"Cum dei vita maxima sit absolute necessaria, §. 921, quia est ipsius essentia, §. 816, et exsistentia, §. 823, 780, non deus immortalis solum est, sed et solus habet immortalitatem absolutam, §. 781.","glosses":[],"marks":[]},
 {"num":923,"section":"parsiiii-capi-seciii","aa":189,"ed":378,"text":"Cum summa perfectione metaphysica et physica in deo coniungitur summa perfectio moralis, §. 806, 859, per summam eius rectitudinem, §. 901, quarum distinctissime sibi conscius, §. 866, summa inde voluptate fruens, §. 892, est beatissimus, §. 787.","glosses":[],"marks":[]},
 {"num":924,"section":"parsiiii-capi-seciii","aa":189,"ed":null,"text":"Deus felix est, §. 923, 787, summe, §. 812, dum 1) omnis ab eo corruptio moralis et miseria non abest solum, §. 813, sed nec esse quidem in eodem potest, physice, §. 859, vel moraliter, §. 902, 2) independenter et a se, §. 851, 3) sine omni mutatione tam ipsorum bonorum, quam intuitus eorundem est felicissimus, §. 839.","glosses":[],"marks":[]},
 {"num":925,"section":"parsiiii-capi-seciii","aa":189,"ed":null,"text":"Ens alio perfectius est illo superius@@1@@. Deus est spiritus supremus, §. 889, 796, ens supramundanum@@2@@, quatenus maiorem perfectionem habet, quam totus aliquis mundus, isque vel optimus, §. 361, 843. Cumque plura entia perfectissima extra se posita sint impossibilia, §. 846, deus est ens absolute summum.","glosses":["etwas höheres","etwas über die Welt erhabenes"],"marks":["*","**"],"aaEnd":190},
 {"num":926,"section":"parsiiii-capii-seci","aa":190,"ed":null,"text":"Causa efficiens actuat effectum, §. 319, 210. Deus est causa efficiens huius universi, §. 854. Ergo deus actuavit hoc universum, aut ab aeterno, i.e. ita, ut mundus hic non habuerit initium, aut in tempore s. non ab aeterno, §. 10, in neutro casu pars mundi mundo praeexstitit, §. 371, 394. Ergo in utroque casu mundus est actuatus ex nihilo, §. 228, et deus est, qui eum actuavit ex nihilo, §. 854. Actuare quid ex nihilo est creare@@1@@. Ergo deus est creator huius universi.","glosses":["erschaffen"],"marks":["*"]},
 {"num":927,"section":"parsiiii-capii-seci","aa":190,"ed":380,"text":"Creatio per emanationem@@1@@ esset actuatio universi ex dei essentia, eiusmodi creatione 1) mundus non actuaretur ex nihilo, §. 926. Essentia enim dei est ens necessarium, §. 109, 816. Quod contra §. 926. 2) aut tota dei essentia, aut pars eius mutari posset in universum, §. 370, quod contra §. 839. 3) pars dei esset extra deum posita, §. 388, deusque compositus, §. 225, quod contra §. 838. Pluribus adhuc modis patet, creationem per emanationem esse impossibilem, §. 7.","glosses":["die Schöpfung durch einen Ausfluss"],"marks":["*"]},
 {"num":928,"section":"parsiiii-capii-seci","aa":190,"ed":null,"text":"Omnes monades huius universi sunt entia finita, §. 396, hinc omnes entia ab alio, §. 308, nec possunt ullae actuari, nisi ex nihilo, §. 229, 236. Ergo omnes monades huius universi sunt creatae, §. 926. Ens quod non potest exsistere, nisi per creationem, est creatura@@1@@. Ergo omnes huius universi monades sunt creaturae, et quidem dei, §. 381, 854. Quicquid est in hoc universo substantiale, dei creatura est, §. 396.","glosses":["ein Geschöpf"],"marks":["*"]},
 {"num":929,"section":"parsiiii-capii-seci","aa":190,"ed":381,"text":"Omnis spiritus huius universi, §. 404, omnes animae humanae, §. 744, 741, omnia elementa huius mundi sunt dei creaturae, §. 928, 423, actuatae singulae creatione simultanea, §. 238, et instantanea, §. 299, 228. Iam corpora huius mundi sunt aggregata elementorum, §. 155, 420, hinc quicquid in corporibus est substantiale, quotquot habent partes per se subsistentes, sunt dei creaturae, §. 928.","glosses":[],"marks":[]},
 {"num":930,"section":"parsiiii-capii-seci","aa":190,"ed":null,"text":"Quod non potest exsistere, nisi ut causatum alterius, nec potest durare, nisi ut causatum alterius, §. 299. Hinc mundus et omnes eius partes non possunt durare, nisi ut entia ab alio, §. 928, 375. Ergo creatio independentem in creaturis durationem actuans est impossibilis, nec obiectum omnipotentiae divinae, §. 833. Creatio huius universi est possibilis, §. 926, 57. Ergo per creationem huius universi non actuata est independens in ipso duratio.","glosses":[],"marks":[],"aaEnd":191},
 {"num":931,"section":"parsiiii-capii-seci","aa":191,"ed":null,"text":"Quicquid non pertinet ad mundi partiumque ipsius substantialium exsistentiam, non est creatum, §. 926. Iam vero essentiae creaturarum, hinc et malum metaphysicum earundem, §. 146, non pertinent ad earundem exsistentiam, §. 132, 134, hinc nec essentiae, nec mala creaturarum metaphysica, sunt creata, nisi creatas dici velis omnes creaturae actualis determinationes, contra notionem §. 926.","glosses":[],"marks":[]},
 {"num":932,"section":"parsiiii-capii-seci","aa":191,"ed":382,"text":"Non exsistere hoc universum, non exsistere ullum universum, est in se possibile, §. 370, 361. Omnia in se possibilia, sunt et deo possibilia, §. 859. Hinc deus potuit, qua omnipotentiam, non creare universum, creare aliud, quam hoc, quo exsistente, hoc non exstitisset, §. 379, 926. Creavit tamen hoc impassibilis, §. 851, per summam spontaneitatem, §. 895, creatione libera ratione exsecutionis, §. 897. Ergo liberrime, §. 898.","glosses":[],"marks":[]},
 {"num":933,"section":"parsiiii-capii-seci","aa":191,"ed":null,"text":"Deus hunc mundum creavit liberrime, §. 932. Ergo eum creare voluit, §. 893, voluit efficienter, §. 671, hinc et plene, quia infallibilis est, §. 879, adeoque ex motivis completis consequenter. Ergo deus hunc mundum creare decrevit, §. 695, et omni quidem significatu efficaciter, §. 675.","glosses":[],"marks":[]},
 {"num":934,"section":"parsiiii-capii-seci","aa":191,"ed":383,"text":"Deus creationem huius mundi decrevit, §. 933, voluntate proportionalissima, §. 894. Hinc decrevit huius mundi exsistentiam, pro gradu bonitatis in eadem cognito, §. 926. Alius mundi exsistentiam non decrevit voluntate proportionalissima, §. 379. Ergo tantam bonitatem in exsistentia ullius alius mundi deus non cognovit, quantam in exsistentia huius mundi cognovit, §. 70. Iam cognitio dei est distinctissima et maxime infallibilis, §. 879. Ergo praelati huius et electi prae reliquis omnibus mundi exsistentia, §. 697, est, quae mundi esse potest, optima, §. 187.","glosses":[],"marks":[]},
 {"num":935,"section":"parsiiii-capii-seci","aa":191,"ed":null,"text":"Posita huius mundi exsistentia, ponitur summa, quae in mundo esse potest, perfectio, §. 187, 934. In quo mundo ponitur summa, quae in mundo esse potest, perfectio, est ille perfectissimus, §. 185. Ergo mundus hic est omnium possibilium perfectissimus.","glosses":[],"marks":[]},
 {"num":936,"section":"parsiiii-capii-seci","aa":191,"ed":null,"text":"In hoc mundo sunt maximarum plurimae, plurimarum maximae partes, quae in mundo esse possunt, consensus tantus, quantus in mundo esse potest, §. 436, 935. Hinc mundus est extensive, protensive et intensive mundorum maximus, §. 437, realiter quidem finitus, ita tamen, ut multis modis infinitus dici possit, §. 440, optimus, §. 443, in eodem maximus nexus universalis, §. 441, ordo, §. 444, et maxima, quae esse potest, harmonia, §. 462.","glosses":[],"marks":[],"aaEnd":192},
 {"num":937,"section":"parsiiii-capii-seci","aa":192,"ed":384,"text":"Pone mundum huic mundo perfectione totaliter aequalem, esset extra eundem ponendus, alias pars huius mundi foret, §. 354, 155. Perfectio huius mundi non potest extra eundem esse, nec perfectio prorsus aequaliter perfecti posset extra ipsum esse, §. 194. Si ergo talis mundus esset possibilis, duae perfectiones extra se invicem totaliter aequales essent possibiles, quod contra §. 272. Ergo mundus perfectissimus est unicus, §. 77.","glosses":[],"marks":[]},
 {"num":938,"section":"parsiiii-capii-seci","aa":192,"ed":null,"text":"De eo, quod hic mundus sit optimus, possumus certi esse, §. 935, 936. Ergo haec doctrina non est hypothesis philosophica. Qui demonstrationem eius a posteriori poscunt, aut intelligunt, per demonstrationem a posteriori, eam, quae in praemissis suis habet iudicium intuitivum, et habent eam, §. 933, cuius praemissas ingreditur: hic mundus exsistit, iudicium intuitivum, aut postulant discrepantiam huius et deterioris mundi experiri, hinc extra hunc mundum poni, §. 548, mirabilem ecstasin, §. 552.","glosses":[],"marks":[]},
 {"num":939,"section":"parsiiii-capii-seci","aa":192,"ed":null,"text":"Quicquid deus creavit, creare voluit, §. 932. Iam vero malorum contingentium et moralium in specie formale prorsus non voluit, §. 914. Ergo nec idem creare voluit, §. 926. Deus non est creator ullius mali contingentis, hinc nec ullius mali moralis formaliter spectati.","glosses":[],"marks":[]},
 {"num":940,"section":"parsiiii-capii-seci","aa":192,"ed":385,"text":"Auctor@@1@@ est causa liberae actionis, et tam actio, quam eius causata sunt effectus auctoris, s. facta@@2@@. Iam deus mundum creavit liberrime, §. 932. Ergo deus est creationis et huius mundi auctor. Deus non est auctor, nisi eorum, quae vult, §. 719, 891. Iam formale nullius mali contingentis, nullius peccati deus vult, §. 914. Ergo nullius mali contingentis, nullius peccati formaliter spectati deus auctor est. Causa moralis stricte dicta@@3@@ est auctor per liberam alterius determinationem, qualis illiciens, minatus, suadens, dissuadens, extorquens, §. 728. Iam causa moralis stricte dicta auctor est. Ergo deus nec est causa moralis stricte dicta ullius peccati et mali contingentis formaliter spectati.","glosses":["Urheber","sittliche Thaten","ein sittlicher Urheber"],"marks":["*","**","***"]},
 {"num":941,"section":"parsiiii-capii-seci","aa":192,"ed":null,"text":"Ad malum morale formaliter spectatum causas impulsivas actuans est tentator ad malum@@1@@. Deus si causas impulsivas ad malum morale formaliter spectatum actuaret, fieret eiusdem causa moralis stricte dicta. Ergo deus numquam est tentator ad malum, §. 940.","glosses":["ein Versucher zum Bösen"],"marks":["*"],"aaEnd":193},
 {"num":942,"section":"parsiiii-capii-secii","aa":193,"ed":null,"text":"Agnitio perfectionis maioris in aliquo est honor@@1@@. Honor maior est gloria@@2@@, cf. §. 684. Gloria dei ergo est maior cognitio summarum ipsius perfectionum. Quo plures, quo magis, ergo quo clarius, quo certius, quo ardentius, quo verius, quo plures, quo maiores alicuius perfectiones cognoscunt, hoc maior est gloria, §. 160. Hinc summa dei gloria est clarissima, verissima, certissima, ardentissima plurimarum maximarum ipsius perfectionum in plurimis cognitio, §. 161. Gloria dei est bonum, §. 866.","glosses":["Ehre","Preis"],"marks":["*","**"]},
 {"num":943,"section":"parsiiii-capii-secii","aa":193,"ed":null,"text":"Per hunc mundum possunt perfectiones dei summae clarius, verius, certius, ardentius cognosci, §. 333, 375. Ergo hic mundus ad gloriam dei utilis est eandem ex eo cognoscere valentibus, §. 336. Haec utilitas creatione et ipsius mundi et omnium in eodem spirituum actuata est, §. 926. Ergo creator universi utitur eodem ad suam gloriam, quam distinctissime bonam cognoscit, §. 889, 942, actuandam. Ergo deus in creando finem habuit, §. 341.","glosses":[],"marks":[]},
 {"num":944,"section":"parsiiii-capii-secii","aa":193,"ed":387,"text":"Deus mundum creavit secundum summam ipsius scientiam nexus finalis, §. 943, hinc sapientissime, §. 882. Hinc optimos optimi mundi in creando eodem fines omnes in perfectissima subordinatione et coordinatione, §. 883, remedia eorum optima, §. 884, certissima, §. 885, fecundissima, §. 886, eosque ex asse consequentia, §. 887, via brevissima, §. 888, scivit, et actuavit, §. 894. Denno patet, deum nullum malum contingens formaliter spectatum creasse, §. 146, 914.","glosses":[],"marks":[]},
 {"num":945,"section":"parsiiii-capii-secii","aa":193,"ed":null,"text":"Finis dei non fuit in creando mundo perfectio quaedam ipsi interna. Per mundum enim ullam earum aut actuari, aut augeri impossibile est, §. 851, deus autem non vult impossibilia, §. 891, 893. Iam quicquid est, praeter deum, mundus est, aut pars mundi, §. 846, 354. Ergo finis dei in creando mundo fuit perfectio creaturarum, §. 928.","glosses":[],"marks":[],"aaEnd":194},
 {"num":946,"section":"parsiiii-capii-secii","aa":194,"ed":388,"text":"Finis dei in creando universo fuit perfectio creaturarum tanta, quanta in mundo optimo possibilis, §. 945, 944. Ergo omnes rerum utilitates creatarum, §. 336, omnes earundem usus, §. 338, fines dei sunt, §. 944. Scientia finium in creaturis divinorum est teleologia, tam physica, corporum, quam pneumatica, fines spirituum exhibens.","glosses":[],"marks":[]},
 {"num":947,"section":"parsiiii-capii-secii","aa":194,"ed":null,"text":"Bona spiritus determinatio ex motivis gloriae divinae est illustratio gloriae divinae (cultus dei)@@1@@. Gloria dei et illustratio eius sunt religio. Iam gloria dei utilis est ad cultum eius, §. 336, 712. Gloria et cultus ad religionem, §. 336. Ergo fines creationis fuerunt cultus dei et religio, §. 942, 946.","glosses":["Verherrlichung Gottes, Gottesdienst"],"marks":["*"]},
 {"num":948,"section":"parsiiii-capii-secii","aa":194,"ed":null,"text":"Prosperitas et beatitudo seu felicitas spirituum utilis est ad gloriam dei, §. 787, 942, illustrationem eius et religionem, §. 947, 336. Ergo prosperitas et beatitudo seu felicitas spirituum tanta, quanta in mundo optimo possibilis, finis fuit creationis, §. 946, 942.","glosses":[],"marks":[]},
 {"num":949,"section":"parsiiii-capii-secii","aa":194,"ed":389,"text":"Omnes creaturae, sive spectentur ut media, sive ut fines, utiles sunt ad dei gloriam, haec ad illustrationem gloriae divinae, §. 943, 947, hinc omnes confines religionis in creatione ipsi subordinantur, §. 315, 947. Ergo religio est finis creationis ultimus, §. 343.","glosses":[],"marks":[],"aaEnd":195},
 {"num":950,"section":"parsiiii-capii-seciii","aa":195,"ed":null,"text":"Hic mundus durat, §. 299, at nullo momento independenter, §. 930. Ergo non potest durare, nisi ut causatum extra se positi vel uno momento, §. 307. Ergo vis extramundana operatur durationem eius in quovis durationis momento, §. 210. Haec deus est, §. 855, 839. Ergo deus operatur quovis durationis momento durationem universi. Actuatio durationis est conservatio@@1@@. Ergo deus est conservator huius universi.","glosses":["die Erhaltung"],"marks":["*"]},
 {"num":951,"section":"parsiiii-capii-seciii","aa":195,"ed":null,"text":"Conservatio est influxus dei continuus, §. 950, 895, isque realis, §. 212, quia exsistentia sua nullius finiti effectus esse potest, §. 308. Idem est creatio, §. 926. Unde conservatio non male dicitur continuata creatio.","glosses":[],"marks":[]},
 {"num":952,"section":"parsiiii-capii-seciii","aa":195,"ed":390,"text":"Quae non creata sunt, non conservantur, §. 950, 926. Ergo nec essentiae rerum, nec malum finitorum metaphysicum, §. 931, nec formale mali contingentis, nec malum morale formaliter spectatum a deo conservatur, §. 939.","glosses":[],"marks":[]},
 {"num":953,"section":"parsiiii-capii-seciii","aa":195,"ed":null,"text":"Quicquid exsistere non potest, nisi per creationem, non potest durare, nisi per conservationem, §. 950, 926. Iam omnes huius mundi monades, et quicquid est in eodem substantiale, dei creatura est. Ergo omnes mundi monades, et quicquid est in mundo hoc substantiale, conservatur a deo quovis momento durationis suae, §. 928.","glosses":[],"marks":[]},
 {"num":954,"section":"parsiiii-capii-seciii","aa":195,"ed":391,"text":"Cum causae efficientes, praeter deum, omnes substantiae huius mundi, §. 319, 846, deo subordinentur, §. 928, est ille causa efficiens simpliciter prima, reliquae omnes secundae, §. 315, 28. Iam omnes finitarum substantiarum actiones sunt simul passiones ab aliis substantiis finitis in eas influentibus, § 451. Ergo deus concurrit, ut causa efficiens, ad omnes substantiarum finitarum actiones mediate, §. 314, 320. Quoniam vero simul omnes finitarum substantiarum, passiones ab aliis substantiis finitis sunt ipsarum actiones, §. 463, non tunc solum ubi agere potissimum concipiuntur, sed et tunc, ubi notantur pati, deus eo, ipso momento, quo mutantur, rationem huius mutationis ipsarum sufficientem, vim earundem, conservando actuans, §. 953, ad omnes substantiarum finitarum actiones, ut causa efficiens, concurrit immediate, §. 320, ad exsistentiam enim substantiae finitae praesentem pertinet eius actio, §. 210, 55.","glosses":[],"marks":[],"aaEnd":196},
 {"num":955,"section":"parsiiii-capii-seciii","aa":196,"ed":null,"text":"Concursus dei immediatus est eiusdem praesentia, §. 223. Ergo deus substantiis huius mundi omnibus proxime praesens, §. 954. Quod omnibus et singulis alicuius partibus substantialibus proxime praesens est, ipsi illi rei intime praesens@@1@@ dicitur. Iam omnibus corporum partibus substantialibus in hoc universo deus proxime praesens est, §. 421. Ergo deus omnibus in hoc universo corporibus intime praesens est.","glosses":["auf das genaueste gegenwärtig"],"marks":["*"]},
 {"num":956,"section":"parsiiii-capii-seciii","aa":196,"ed":null,"text":"Deus omni huius mundi monadi proxime, omni corpori praesens est intime, §. 955, idque quovis momento, et qua omnes creaturarum actiones, §. 954. Ergo deus est omnipraesentissimus.","glosses":[],"marks":[]},
 {"num":957,"section":"parsiiii-capii-seciii","aa":196,"ed":392,"text":"Ubicumque deus est, ibi totus est, et indivisus, §. 842. Ergo et qua substantiam et essentiam, §. 830. 816. Ergo deus omnibus huius mundi monadibus et corporibus, qua substantiam et essentiam, praesens est, §. 955.","glosses":[],"marks":[]},
 {"num":958,"section":"parsiiii-capii-seciii","aa":196,"ed":null,"text":"Conservatio virium huius universi quarumcumque, in ipso earundem actu, est concursus dei physicus, isque, quia et quatenus ad singulas singularum substantiarum actiones extenditur, generalis@@1@@ (universalis) dicitur.","glosses":["die allgemeine Mitwirkung Gottes"],"marks":["*"]},
 {"num":959,"section":"parsiiii-capii-seciii","aa":196,"ed":null,"text":"Concursus dei omnis est liberrimus, §. 932. Ergo si concurreret ad formale ullius actionis malae, fieret eiusdem auctor, §. 940. Ergo ad omnes actiones physice et moraliter malas concurrit, qua materiale, §. 958, non vero, qua formale, §. 940.","glosses":[],"marks":[],"aaEnd":197},
 {"num":960,"section":"parsiiii-capii-seciii","aa":197,"ed":null,"text":"Concursus causae moralis stricte dictae est moralis@@1@@. Deus motiva cultus sui actuat, §. 947. Ergo ad quasdam actiones in hoc universo concurrit moraliter, §. 940. Concursus dei moralis ad generalem accedens specialis@@2@@ est. Ergo deus ad quasdam in hoc universo actiones concurrit specialiter.","glosses":["die sittliche","die besondre Mitwirkung"],"marks":["*","**"]},
 {"num":961,"section":"parsiiii-capii-seciii","aa":197,"ed":393,"text":"Deus non est tentator ad malum, §. 941. Ergo ad formale nullarum actionum moraliter malarum concurrit moraliter, §. 940. Ergo nec specialiter, §. 960.","glosses":[],"marks":[]},
 {"num":962,"section":"parsiiii-capii-seciii","aa":197,"ed":null,"text":"Concursus dei supernaturalis ad specialem accedens est specialissimus@@1@@, et in se possibilis, §. 475, et hypothetice, §. 860, et in hoc mundo actualis, quotiescumque quaedam actio in eodem per specialem dei concursum aeque bene actuari non potest, §. 498, 935.","glosses":["die besonderste Mitwirkung Gottes"],"marks":["*"]},
 {"num":963,"section":"parsiiii-capii-seciii","aa":197,"ed":394,"text":"Gubernatio@@1@@ est actio, qua media successive plura ad ulteriorem aliquem finem actuantur. Quo ergo meliora, quo optimorum, hinc et via brevissima finem consequentium, §. 888, plura media, quo meliores, quo ulteriores ad fines actuantur, hoc est gubernatio perfectior, §. 185. Quos deus in creando fines habuit, habet et actuat conservando, §. 951, 944. Dum ergo summum eum universi gubernatorem veneramur, colimus optima, et viis brevissimis procedentium plurima media, ad optimos fines et tandem ad ultimum huius universi scopum ducentia, momento quovis actuantem. Dum deus gubernando 1) viribus (hinc et actionibus, §. 331) rei creatae certum limitem constituit, determinare strictius@@2@@, 2) finibus suis subordinat actionem rei creatae ad eosdem ab hac non susceptam, dirigere strictius@@3@@ dicitur.","glosses":["die Führung","Maass und Schranken setzen","lenken in engerer Bedeutung"],"marks":["*","**","***"]},
 {"num":964,"section":"parsiiii-capii-seciii","aa":197,"ed":null,"text":"Primum peccatum lapsus@@1@@ dicitur, et potentia labendi labilitas@@2@@, haec est vel absoluta, vel hypothetica, §. 15, 16. Oppositum labilitatis hypotheticae est confirmatio in bono@@3@@.","glosses":["der Fall","dessen Möglichkeit","Bestätigung im Guten"],"marks":["*","**","***"],"aaEnd":198},
 {"num":965,"section":"parsiiii-capii-seciii","aa":198,"ed":395,"text":"Absoluta labilitas pertinet ad spiritus finiti essentiam, §. 40, 964, hinc est in eodem absolute necessario, §. 106, malum metaphysicum, §. 146, quae non concreata spiritui ulli, §. 931, cuius oppositum nulli creaturae concreari potuit, §. 833. Spiritus labens agit, §. 964, 788. Ergo deus ad lapsus materiale concurrit, §. 918, ad formale vero nec physice, nec moraliter, §. 909, 911. Ergo nec fit auctor lapsus formaliter spectati, nec causa moralis stricte dicta §. 940.","glosses":[],"marks":[]},
 {"num":966,"section":"parsiiii-capii-seciii","aa":198,"ed":null,"text":"Lapsus est in se contingens, §. 964, dum est mutatio finiti, §. 361. Ergo oppositum lapsus est in se possibile, §. 104. Ergo impedimentum lapsus est in se possibile, §. 221. Ergo deus omnem lapsum impedire potuit, §. 833.","glosses":[],"marks":[]},
 {"num":967,"section":"parsiiii-capii-seciii","aa":198,"ed":null,"text":"Impeditio moralis@@1@@ est actuatio motivorum ad oppositum alicuius mutationis. Deus motiva spiritibus ad felicitatem ipsorum actuavit plurima, §. 948. Felicitas spiritus est oppositum lapsus eius, §. 81, 787. Ergo deus omnem lapsum impedit moraliter.","glosses":["sittliche Verhinderung"],"marks":["*"]},
 {"num":968,"section":"parsiiii-capii-seciii","aa":198,"ed":396,"text":"Impeditio, quae non moralis est, physica dicitur. Lapsus est peccatum, §. 964, ergo actio moralis, §. 788, ergo libera ratione exsecutionis, §. 719, 722, hinc physice contingens, §. 709. Ergo praeter libertatem lapsi et motiva illius, §. 967, multa alia possibilia erant, quibus positis lapsus non secutus esset, qui secutus est, §. 378, impedimenta lapsus physica, §. 81, 221. Ergo deus lapsum etiam physice impedire potuit, §. 833.","glosses":[],"marks":[]},
 {"num":969,"section":"parsiiii-capii-seciii","aa":198,"ed":null,"text":"Omne peccatum deus impedit moraliter, §. 967, impedire physice potest per omnipotentiam, §. 968. Non omne tamen physice impedit. Non impeditio est permissio@@1@@. Ergo est vel physica. §. 968, vel moralis, §. 967.","glosses":["Zulassung"],"marks":["*"]},
 {"num":970,"section":"parsiiii-capii-seciii","aa":198,"ed":null,"text":"Deus nullum lapsum, §. 967, nullum peccatum, permittit moraliter, §. 969. Quaedam tamen peccata in hoc mundo permittit physice. Pone et haec physice impediri, non esset hic mundus, in quo physice impedirentur, sed alius, §. 378, minus bonus, §. 937. Ergo deus quaedam in hoc mundo peccata physice permittit, quia mundus, in quo permittuntur physice, est medium religionis optimum, §. 949, 935.","glosses":[],"marks":[],"aaEnd":199},
 {"num":971,"section":"parsiiii-capii-seciii","aa":199,"ed":null,"text":"Ius (pro qualitate personae sumptum) significatu latiori@@1@@ est facultas moralis; quique ius habet decernendi de aliqua re, quicquid placuerit, plenus eius dominus@@2@@ est. Plenum dominium in personas est potestas plena@@3@@.","glosses":["Recht in weiter Bedeutung","völlig Herr davon","völlige Herrschaft"],"marks":["*","**","***"]},
 {"num":972,"section":"parsiiii-capii-seciii","aa":199,"ed":397,"text":"Deus ius habet ad actiones suas rectissimas, §. 901, 971. In iis est decretum de mundo et singulis eius creaturis, §. 934. Ergo deus plenus mundi et omnium in eodem creaturarum dominus est. Ergo in spiritus huius mundi plenam potestatem habet, §. 971.","glosses":[],"marks":[]},
 {"num":973,"section":"parsiiii-capii-seciii","aa":199,"ed":null,"text":"Qui plenam in spiritum potestatem habet, ius habet ipsum obligandi, quomodocumque placuerit. Qui ius habet spiritum aliquem obligandi, quomodocumque placuerit, habet ius illi leges ferendi. Auctor enim obligationis, quam lex enuntiat, legem ferre@@1@@ dicitur. Ius leges ferendi habens, legislator@@2@@ est. Ergo deus omnium spirituum huius mundi legislator est, §. 971, 972.","glosses":["Gesetze geben","der Gesetzgeber"],"marks":["*","**"]},
 {"num":974,"section":"parsiiii-capii-seciii","aa":199,"ed":398,"text":"Qui solus in plures spiritus summam potentiam et potestatem habet, est eorum monarcha, qui plenam, est eorum despotes. Iam deus solus in omnes spiritus creatos summam potentiam, §. 832, et potestatem, eamque plenam habet, §. 971. Ergo summa ipsius est et maxima monarchia despotica, cuius omnes spiritus creati sunt subditi, §. 844.","glosses":[],"marks":[]},
 {"num":975,"section":"parsiiii-capii-seciii","aa":199,"ed":null,"text":"Providentia dei@@1@@ est actio, qua tantum cuivis rei creatae bonorum largitur, quantum summa bonitas potest. Ergo conservando, §. 950, concurrendo, §. 954, gubernando, §. 963, malum moraliter impediendo, §. 967, nec physice permittendo, nisi quod impedire finibus ipsius detraheret, §. 970, civitatique suae leges optimas ferendo, §. 973, 974, deus exercet providentiam, §. 903-920, per causas impulsivas ad beatitatem, verticordiam@@2@@, per fortuita, fortunam sanctam@@3@@, per bona cuiusvis naturae insita, almam naturam. Epicureismus, sententia providentiam dei tollens, error est, §. 515.","glosses":["die Vorsehung Gottes","deren herzlenkende Kraft","das heilige, das göttliche in dem, was man Glück nennt"],"marks":["*","**","***"],"aaEnd":201},
 {"num":976,"section":"parsiiii-capii-seciiii","aa":201,"ed":399,"text":"Decretum de exsistentia mundi est in deo liberrimum, §. 933, hinc distinctissimam omnium mundi huius partium omnisque boni et mali in iisdem accuratissimam cognitionem sequens, §. 889, immutabile, §. 839, aeternum, §. 849, et irresistibile, §. 844, 222. Quod humano modo sic potest concipi: Propositum, προθεσισ: Complexus optimorum extra deum compossibilium exsistat, §. 822, 901. Praevisio, προγνωσισ: Hic mundus optimus est complexus extra deum compossibilium optimorum, §. 935. Decretum, προορισμοσ: Hic mundus optimus exsistat.","glosses":[],"marks":[]},
 {"num":977,"section":"parsiiii-capii-seciiii","aa":201,"ed":null,"text":"Plures mundi, quam hic, plura finita, quam quae partes huius mundi sunt, non exsistunt, §. 379, nec deus plura de contingentibus decrevit, quam decreto de exsistentia huius mundi comprehensa, §. 976. Illud ergo, qua ad omnes huius universi realitates extenditur, universale, qua est, quod plura non sunt, vocatur unicum, §. 77.","glosses":[],"marks":[]},
 {"num":978,"section":"parsiiii-capii-seciiii","aa":201,"ed":null,"text":"Particularia dei decreta@@1@@ vel sunt partes decreti universalis et unici, §. 977, vel essent primitiva@@2@@, aut opposita illi aut saltim non comprehensa sub universali. Talia non sunt in deo, §. 976.","glosses":["besondre Rathschlüsse Gottes","ursprüngliche"],"marks":["*","**"]},
 {"num":979,"section":"parsiiii-capii-seciiii","aa":201,"ed":400,"text":"Decreta dei omnia sunt actus voluntatis proportionalissimae obiectis, §. 894, perfectissime sequentis scientiam gradus perfectionis vel imperfectionis in obiecto vel appetendo, vel aversando, §. 976. Idem et sic patet: Pone in aliquo decreto dei praevisam obiecti perfectionem imperfectionemve prorsus non fuisse motivum: aut eam deus ignoravit, quod contra §. 875, aut ab eadem abstraxit, quod contra §. 870, aut fuit eiusmodi cognitio distinctissima, sed mortua, quod contra §. 890.","glosses":[],"marks":[],"aaEnd":202},
 {"num":980,"section":"parsiiii-capii-seciiii","aa":202,"ed":null,"text":"Decretum dei absolutum@@1@@ si dicitur, cuius motivum nec praevisa obiecti perfectio, nec imperfectio fuit, hypotheticum@@2@@ contra, quod praevisam obiecti perfectionem imperfectionemve sequitur; nulla dei de contingentibus decreta sunt absoluta, omnia hypothetica, §. 979. Absolutismus theologicus est sententia decreta dei de contingentibus absoluta ponens, et error est, §. 515.","glosses":["der unbedingte","der bedingte Rathschluss Gottes"],"marks":["*","**"],"aaEnd":203},
 {"num":981,"section":"parsiiii-capii-seciiii","aa":203,"ed":401,"text":"Decretum de felicitate alicuius spiritus aeterna praedestinatio est strictius dicta@@1@@, cum latius@@2@@ sit decretum de futuro. Decretum de infelicitate alicuius spiritus aeterna est reprobatio@@3@@, utrumque hypotheticum, §. 980. praedestinatianismus, s. absolutismus in concipienda praedestinatione strictius dicta, error est, §. 515.","glosses":["die Gnadenwahl","die Vorherbestimmung","die Verwerfung"],"marks":["*","**","***"]},
 {"num":982,"section":"parsiiii-capii-secv","aa":203,"ed":null,"text":"Revelatio latius dicta@@1@@, cf. §. 986, 989, est significatio mentis divinae creaturis a deo facta. Ergo revelatione divina docentur creaturae cognitionem volitionemque divinam, numquam omnem, §. 862, sed tantam semper, quanta placuerit providentiae, §. 975.","glosses":["die Offenbarung in weiterer Bedeutung"],"marks":["*"]},
 {"num":983,"section":"parsiiii-capii-secv","aa":203,"ed":null,"text":"Deus est auctor naturae universae, §. 940, 466. Quicquid ergo per naturam suam ex natura universa de dei mente cognoscit creatura, cognoscit per revelationem divinam, §. 982, quae naturalis est, §. 469. Talis theologia naturalis est, §. 800.","glosses":[],"marks":[]},
 {"num":984,"section":"parsiiii-capii-secv","aa":203,"ed":402,"text":"Omnia finita sunt media cognoscendae mentis divinae, §. 858, 880, vires repraesentativae huius universi omnes significant creatorem suum, §. 929, optimum, sapientissimum, §. 933. Ipsa anima est vis repraesentativa dei sui, §. 741, 744.","glosses":[],"marks":[],"aaEnd":204},
 {"num":985,"section":"parsiiii-capii-secv","aa":204,"ed":null,"text":"Per animam ipsam, per singulas, quibus praesens est, monades, hinc et per singula corpora, et sensus, animae mens divina revelatur naturaliter, §. 984, per usus singulorum, fines dei, §. 946, per cognitionem optimi voluntas eius, §. 894.","glosses":[],"marks":[]},
 {"num":986,"section":"parsiiii-capii-secv","aa":204,"ed":null,"text":"Revelatio strictius dicta@@1@@, cf. §. 982, 989, est supernaturalis revelatio divina hominibus per orationem facta, concursus ad religionem specialissimus, et in se possibilis, et hypothetice, et in hoc mundo actualis, quotiescumque religio per revelationem naturalem solam aeque bene actuari non potest, §. 962, 949.","glosses":["die Offenbarung in enger Bedeutung"],"marks":["*"]},
 {"num":987,"section":"parsiiii-capii-secv","aa":204,"ed":403,"text":"Pone in hoc mundo revelationem naturalem tantum certis individuis, e.g. hominibus faciendam; pone sub iisdem circumstantiis revelationem iisdem individuis supernaturaliter faciendam mere naturali uberiorem, nobiliorem, clariorem, veriorem, certiorem, ardentiorem, §. 669, contingere potest revelatio stricte dicta ordini huius mundi convenientissime, §. 484, et in eodem exsistit, §. 986.","glosses":[],"marks":[]},
 {"num":988,"section":"parsiiii-capii-secv","aa":204,"ed":null,"text":"Pone aliquam mentis divinae significationem in hoc mundo ad religionem admodum bonam, §. 947, sed naturaliter non actuandam, cum tamen possit actuari supernaturaliter; fiet in hoc mundo revelatio stricte dicta, §. 496, 987.","glosses":[],"marks":[]},
 {"num":989,"section":"parsiiii-capii-secv","aa":204,"ed":null,"text":"Revelatio stricte dicta naturaliter creaturis incognoscibilium, est revelatio strictissime dicta@@1@@, cf. §. 982, 986. Quaecumque ergo cognitio mentis divinae in hoc mundo ad religionem admodum bona certis creaturis est naturaliter incognoscibilis, actuatur in eodem per revelationem strictissime dictam, §. 988.","glosses":["die Offenbarung in engerer Bedeutung"],"marks":["*"]},
 {"num":990,"section":"parsiiii-capii-secv","aa":204,"ed":404,"text":"Si quid pro revelatione dei stricte dicta habetur, neque tamen magis gloriam dei et religionem promovet, nec uberiorem, nec nobiliorem, nec clariorem, nec veriorem, nec certiorem, nec ardentiorem dei cognitionem suppeditat, quam naturalis, non est revelatio dei stricte dicta, §. 986, 495.","glosses":[],"marks":[]},
 {"num":991,"section":"parsiiii-capii-secv","aa":204,"ed":null,"text":"In mente dei nulla est contradictio, §. 822. Ergo quicquid revelationi naturali vere contradicit, non est revelatio dei stricte dicta, §. 983, 986, nec strictissime, §. 989.","glosses":[],"marks":[],"aaEnd":205},
 {"num":992,"section":"parsiiii-capii-secv","aa":205,"ed":null,"text":"Revelatio dei stricte et strictissime dicta non contradicit naturali, §. 991, hinc nec rationi obiective sumptae, quatenus a sana ratione humana subiective sumpta cognoscitur, §. 646, 984.","glosses":[],"marks":[]},
 {"num":993,"section":"parsiiii-capii-secv","aa":205,"ed":null,"text":"Fides sacra obiective sumpta@@1@@ est complexus revelationi stricte dictae credendorum, uti habita revelationi stricte dictae fides, est sacra subiective sumpta@@2@@. Ergo non sola naturaliter prorsus creaturis incognoscibilia pertinent ad sacram fidem, §. 989, 986.","glosses":["der Inhalt des heiligen Glaubens","der heilige Glaube"],"marks":["*","**"]},
 {"num":994,"section":"parsiiii-capii-secv","aa":205,"ed":405,"text":"Fides sacra, obiective sumpta, quatenus ab homine per fidem subiective sumptam creditur, non contradicit rationi obiective sumptae, quatenus a sana ratione humana subiective sumpta cognoscitur, §. 992, 993.","glosses":[],"marks":[]},
 {"num":995,"section":"parsiiii-capii-secv","aa":205,"ed":null,"text":"Revelatio stricte dicta significat summe possibilia, §. 986, 822. Iam quae contra rationem sunt, sunt impossibilia, §. 643. Ergo nec revelatio dei stricte dicta, nec strictissima, §. 989, nec fides sacra obiective sumpta contra rationem sunt. Quae vero contra rationem sunt, nec sunt revelatio dei stricte, nec strictissime dicta, nec fides sacra obiective sumpta.","glosses":[],"marks":[]},
 {"num":996,"section":"parsiiii-capii-secv","aa":205,"ed":null,"text":"Mysteria sacra@@1@@ sunt supra creaturarum rationem posita in fide sacra obiective sumpta. In omni revelatione strictissime dicta sunt mysteria, §. 989, 644. Ergo non repugnant revelationi stricte dictae, §. 989, nec sunt contra rationem, §. 643.","glosses":["heilige Geheimnisse"],"marks":["*"]},
 {"num":997,"section":"parsiiii-capii-secv","aa":205,"ed":406,"text":"In omni sua revelatione deus est maxime sincerus, §. 919, hinc sapientia ipsius orationem aptissimum signum significandae mentis divinae hominibus iudicante, eamque supernaturaliter actuatam, est in revelatione stricte dicta veracissimus, §. 920.","glosses":[],"marks":[]},
 {"num":998,"section":"parsiiii-capii-secv","aa":205,"ed":null,"text":"In revelatione stricte et strictissime sumpta deus testis est, §. 986, 946, maxime sincerus et dexterrimus, §. 997, 889, hinc fide dignissimus, cuius revelatio stricte dicta summam dat fidei certitudinem.","glosses":[],"marks":[]},
 {"num":999,"section":"parsiiii-capii-secv","aa":205,"ed":null,"text":"Naturalista significatu strictiori (cf. §. 493) est negans in hoc mundo revelationem dei stricte dictam. Atheus (theoreticus), negans dei exsistentiam, errat, §. 811, 854. Naturalismus significatu neutro ponit atheismum necessario, §. 493.","glosses":[],"marks":[],"aaEnd":206},
 {"num":1000,"section":"parsiiii-capii-secv","aa":206,"ed":null,"text":"Naturalista significatu strictiori, negans revelationem stricte dictam in hoc mundo exsistere, quia 1) est eventus supernaturalis, §. 986, hinc ipsi videtur impossibilis, errat, §. 860, 2) fidem sacram putat esse contra rationem, hinc impossibilem, errat, §. 995, 3) negat providentiam in genus humanum, et errat, §. 975, sua culpa, §. 982, 986, ignarus dei benignissimi, §. 903, Cuius semper honos, nomen, laudesque manebunt.","glosses":[],"marks":[]},
];

